package com.osrstcg.interop;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.osrstcg.catalog.CardDefinition;
import com.osrstcg.state.CardCollectionKey;
import com.osrstcg.state.CloudSidebarCollectionStats;
import com.osrstcg.state.PackCardResult;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class TcgPublicStatsCalculatorTest
{
	@Test
	public void localOverviewCountsRollPoolUniquesAndScore()
	{
		CardDefinition goblin = card("Goblin", 10L, 20L);
		CardDefinition dragon = card("Dragon", 40L, 80L);
		Map<CardCollectionKey, Integer> owned = new HashMap<>();
		owned.put(new CardCollectionKey("Goblin", false), 2);

		CloudSidebarCollectionStats stats = TcgPublicStatsCalculator.computeLocalOverview(
			owned, List.of(goblin, dragon), List.of(goblin, dragon));

		assertEquals(1, stats.getUniqueOwned());
		assertEquals(0, stats.getUniqueFoilOwned());
		assertEquals(2, stats.getTotalCardsOwned());
		assertEquals(0L, stats.getFoilOwned());
		assertEquals(2, stats.getTotalCardPool());
		assertEquals(10L, stats.getCollectionScore());
		assertEquals(50.0d, stats.getCompletionPct(), 0.0001d);
	}

	@Test
	public void localOverviewUsesFoilScoreWhenAFoilCopyIsOwned()
	{
		CardDefinition goblin = card("Goblin", 10L, 20L);
		Map<CardCollectionKey, Integer> owned = new HashMap<>();
		owned.put(new CardCollectionKey("Goblin", false), 1);
		owned.put(new CardCollectionKey("Goblin", true), 1);

		CloudSidebarCollectionStats stats = TcgPublicStatsCalculator.computeLocalOverview(
			owned, List.of(goblin), List.of(goblin));

		assertEquals(1, stats.getUniqueOwned());
		assertEquals(1, stats.getUniqueFoilOwned());
		assertEquals(2, stats.getTotalCardsOwned());
		assertEquals(1L, stats.getFoilOwned());
		assertEquals(20L, stats.getCollectionScore());
	}

	@Test
	public void resolveOverviewPrefersSnapshotCloudStats()
	{
		CloudSidebarCollectionStats cloud = new CloudSidebarCollectionStats(
			5, 2, 9, 3L, 10, 50.0d, 20.0d, 100L);
		com.osrstcg.ui.layout.PackCloseSnapshot snap = new com.osrstcg.ui.layout.PackCloseSnapshot(
			Map.of(), null, 0L, 0L, cloud);

		CloudSidebarCollectionStats resolved = TcgPublicStatsCalculator.resolveOverview(
			snap, List.of(), List.of());
		assertEquals(cloud, resolved);
	}

	@Test
	public void optimisticPackPullIncrementsUniqueAndScoreForNewName()
	{
		CloudSidebarCollectionStats base = new CloudSidebarCollectionStats(
			1, 0, 2, 0L, 10, 10.0d, 0.0d, 10L);
		Map<CardCollectionKey, Integer> ownedBefore = new HashMap<>();
		ownedBefore.put(new CardCollectionKey("Goblin", false), 2);
		PackCardResult pull = new PackCardResult(
			"Dragon", true, "id-1", "Rare", 50L, null, null, null, null, null, null, null,
			null, null, null, null);

		CloudSidebarCollectionStats next = CloudSidebarCollectionStats.withOptimisticPackPulls(
			base, ownedBefore, List.of(pull));

		assertEquals(2, next.getUniqueOwned());
		assertEquals(1, next.getUniqueFoilOwned());
		assertEquals(3, next.getTotalCardsOwned());
		assertEquals(1L, next.getFoilOwned());
		assertEquals(60L, next.getCollectionScore());
		assertTrue(next.getCompletionPct() > base.getCompletionPct());
	}

	@Test
	public void countsAgreeIgnoresScoreDrift()
	{
		CloudSidebarCollectionStats server = new CloudSidebarCollectionStats(
			2, 1, 4, 1L, 10, 20.0d, 10.0d, 99L);
		CloudSidebarCollectionStats local = new CloudSidebarCollectionStats(
			2, 1, 4, 1L, 10, 20.01d, 10.0d, 100L);
		assertTrue(CloudSidebarCollectionStats.countsAgree(server, local));
	}

	private static CardDefinition card(String name, long score, long foilScore)
	{
		CardDefinition def = new CardDefinition();
		def.setName(name);
		def.setScore(score);
		def.setFoilScore(foilScore);
		return def;
	}
}

package com.osrstcg.cloud.catalog;

import com.google.gson.JsonParser;
import com.osrstcg.state.PackCardResult;
import org.junit.Assert;
import org.junit.Test;

public class PackPullParserTest
{
	@Test
	public void parseCard_readsCustomExamineWithNewlines()
	{
		PackCardResult pull = PackPullParser.parseCard(new JsonParser().parse("{"
			+ "\"cardName\":\"Abyssal whip\","
			+ "\"foil\":true,"
			+ "\"instanceId\":\"id-1\","
			+ "\"tierLabel\":\"Rare\","
			+ "\"score\":100,"
			+ "\"foilImagePath\":\"/api/v1/artwork/files/xyz?token=t\","
			+ "\"artistName\":\"Ada\","
			+ "\"artistColor\":\"#FFFFFF\","
			+ "\"artistUrl\":\"https://example.com\","
			+ "\"examine\":\"Custom line\\nSecond line\""
			+ "}").getAsJsonObject());

		Assert.assertNotNull(pull);
		Assert.assertEquals("Custom line\nSecond line", pull.getExamine());
		Assert.assertEquals("/api/v1/artwork/files/xyz?token=t", pull.getFoilImagePath());
		Assert.assertEquals("Ada", pull.getArtistName());
	}

	@Test
	public void parseCard_omitsBlankExamine()
	{
		PackCardResult pull = PackPullParser.parseCard(new JsonParser().parse("{"
			+ "\"cardName\":\"Abyssal whip\","
			+ "\"foil\":true,"
			+ "\"instanceId\":\"id-2\","
			+ "\"foilImagePath\":\"/api/v1/artwork/files/xyz\","
			+ "\"examine\":\"   \""
			+ "}").getAsJsonObject());

		Assert.assertNotNull(pull);
		Assert.assertNull(pull.getExamine());
	}

	@Test
	public void parseCard_nonFoilHasNoExamineField()
	{
		PackCardResult pull = PackPullParser.parseCard(new JsonParser().parse("{"
			+ "\"cardName\":\"Abyssal whip\","
			+ "\"foil\":false,"
			+ "\"instanceId\":\"id-3\""
			+ "}").getAsJsonObject());

		Assert.assertNotNull(pull);
		Assert.assertNull(pull.getExamine());
		Assert.assertNull(pull.getFoilImagePath());
	}

	@Test
	public void parseCard_readsDisplayNameSeparateFromCardName()
	{
		PackCardResult pull = PackPullParser.parseCard(new JsonParser().parse("{"
			+ "\"cardName\":\"npc:6616\","
			+ "\"name\":\"Scorpia's offspring\","
			+ "\"foil\":false,"
			+ "\"instanceId\":\"id-npc\","
			+ "\"tierLabel\":\"Rare\","
			+ "\"score\":100"
			+ "}").getAsJsonObject());

		Assert.assertNotNull(pull);
		Assert.assertEquals("npc:6616", pull.getCardName());
		Assert.assertEquals("Scorpia's offspring", pull.getDisplayName());
	}

	@Test
	public void parseCard_omitsBlankDisplayName()
	{
		PackCardResult pull = PackPullParser.parseCard(new JsonParser().parse("{"
			+ "\"cardName\":\"Abyssal whip\","
			+ "\"name\":\"   \","
			+ "\"foil\":false,"
			+ "\"instanceId\":\"id-4\""
			+ "}").getAsJsonObject());

		Assert.assertNotNull(pull);
		Assert.assertEquals("Abyssal whip", pull.getCardName());
		Assert.assertNull(pull.getDisplayName());
	}
}

package com.osrstcg.cloud.catalog;

import com.google.gson.JsonParser;
import com.osrstcg.catalog.CardDefinition;
import com.osrstcg.state.PackCardResult;
import com.osrstcg.util.CardDisplayNames;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class LiveCardsCatalogParserDisplayNameTest
{
	@Test
	public void collidingNpcKeepsIdentityNameAndFriendlyDisplayName()
	{
		List<CardDefinition> cards = LiveCardsCatalogParser.parse(new JsonParser().parse("{"
			+ "\"items\":[{\"id\":391,\"name\":\"Manta ray\",\"tcg\":{\"score\":1,\"tierLabel\":\"Common\"}}],"
			+ "\"npcs\":[{\"id\":15220,\"name\":\"Manta ray\",\"tcg\":{\"score\":10,\"tierLabel\":\"Rare\"}}]"
			+ "}").getAsJsonObject());

		CardDefinition npc = cards.stream()
			.filter(c -> "npc:15220".equals(c.getName()))
			.findFirst()
			.orElse(null);
		Assert.assertNotNull(npc);
		Assert.assertEquals("npc:15220", npc.getName());
		Assert.assertEquals("Manta ray", npc.getDisplayName());
		Assert.assertEquals(Long.valueOf(15220L), npc.getId());
	}

	@Test
	public void titleForPullPrefersApiDisplayNameOverNpcIdentity()
	{
		CardDefinition catalog = new CardDefinition();
		catalog.setName("npc:6616");
		catalog.setDisplayName("Scorpia's offspring");

		PackCardResult pull = new PackCardResult(
			"npc:6616",
			false,
			"id-1",
			"Rare",
			100L,
			null,
			null,
			null,
			null,
			null,
			null,
			null,
			null,
			null,
			null,
			"Scorpia's offspring");

		Assert.assertEquals("Scorpia's offspring", CardDisplayNames.titleForPull(pull, catalog));
		Assert.assertEquals("Scorpia's offspring", CardDisplayNames.titleForDefinition(catalog, pull));
	}

	@Test
	public void titleFallsBackToCatalogDisplayWhenPullOmitsName()
	{
		CardDefinition catalog = new CardDefinition();
		catalog.setName("npc:6616");
		catalog.setDisplayName("Scorpia's offspring");

		PackCardResult pull = new PackCardResult("npc:6616", false);
		Assert.assertEquals("Scorpia's offspring", CardDisplayNames.titleForPull(pull, catalog));
	}
}

package com.osrstcg.cloud.attest;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

import java.io.IOException;
import org.junit.Test;

public class CreditAttestPosterIdentityTest
{
	@Test
	public void assertPostIdentityAllowsTeardownWhenLiveUnset() throws Exception
	{
		CreditAttestPoster.assertPostIdentity(42L, -1L, true);
	}

	@Test
	public void assertPostIdentityRejectsLiveAccountSwitch()
	{
		try
		{
			CreditAttestPoster.assertPostIdentity(42L, 99L, true);
			fail("expected IOException");
		}
		catch (IOException ex)
		{
			assertEquals("Account changed during credit attest flush", ex.getMessage());
		}
	}

	@Test
	public void assertPostIdentityRejectsUnboundTokens()
	{
		try
		{
			CreditAttestPoster.assertPostIdentity(42L, -1L, false);
			fail("expected IOException");
		}
		catch (IOException ex)
		{
			assertEquals("Tokens not bound to credit attest account", ex.getMessage());
		}
	}

	@Test
	public void assertPostIdentityRejectsMissingBoundHash()
	{
		try
		{
			CreditAttestPoster.assertPostIdentity(-1L, -1L, true);
			fail("expected IOException");
		}
		catch (IOException ex)
		{
			assertEquals("Missing account hash for credit attest flush", ex.getMessage());
		}
	}
}

package com.osrstcg.cloud.attest;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import org.junit.Test;

public class CreditAttestCoalescerTest
{
	private static final long HOUR = CreditAttestCoalescer.HOUR_MS;
	/** Fixed base inside an hour (not near a boundary). */
	private static final long T0 = 1_700_000_000_000L;

	@Test
	public void sameSkillSameHourMergesXp()
	{
		List<JsonObject> raw = List.of(
			xp("WOODCUTTING", 1000L, T0),
			xp("WOODCUTTING", 2500L, T0 + 60_000L)
		);
		List<JsonObject> out = CreditAttestCoalescer.coalesce(raw);
		assertEquals(1, out.size());
		JsonObject event = out.get(0);
		assertEquals(CreditAttestCoalescer.TYPE_XP_CHUNK, event.get("type").getAsString());
		assertEquals(3500L, event.getAsJsonObject("evidence").get("xpDelta").getAsLong());
		assertEquals(T0 + 60_000L, event.get("at").getAsLong());
	}

	@Test
	public void sameSkillAcrossHourBoundarySplitsXp()
	{
		long hourEnd = (T0 / HOUR) * HOUR + HOUR;
		List<JsonObject> raw = List.of(
			xp("WOODCUTTING", 1000L, hourEnd - 1L),
			xp("WOODCUTTING", 2000L, hourEnd),
			xp("WOODCUTTING", 3000L, hourEnd + 1L)
		);
		List<JsonObject> out = CreditAttestCoalescer.coalesce(raw);
		assertEquals(2, out.size());

		List<JsonObject> sorted = new ArrayList<>(out);
		sorted.sort(Comparator.comparingLong(e -> e.get("at").getAsLong()));

		assertEquals(1000L, sorted.get(0).getAsJsonObject("evidence").get("xpDelta").getAsLong());
		assertEquals(hourEnd - 1L, sorted.get(0).get("at").getAsLong());

		assertEquals(5000L, sorted.get(1).getAsJsonObject("evidence").get("xpDelta").getAsLong());
		assertEquals(hourEnd + 1L, sorted.get(1).get("at").getAsLong());
	}

	@Test
	public void combatSkillXpDropped()
	{
		List<JsonObject> raw = List.of(
			xp("ATTACK", 5000L, T0),
			xp("WOODCUTTING", 1000L, T0)
		);
		List<JsonObject> out = CreditAttestCoalescer.coalesce(raw);
		assertEquals(1, out.size());
		assertEquals("WOODCUTTING", out.get(0).getAsJsonObject("evidence").get("skill").getAsString());
	}

	@Test
	public void sameNpcSameHourStacksKills()
	{
		List<JsonObject> raw = List.of(
			kill(42, "Goblin", 2, 3, T0),
			kill(42, "Goblin", 2, 2, T0 + 30_000L)
		);
		List<JsonObject> out = CreditAttestCoalescer.coalesce(raw);
		assertEquals(1, out.size());
		assertEquals(5, out.get(0).getAsJsonObject("evidence").get("amount").getAsInt());
		assertEquals(T0 + 30_000L, out.get(0).get("at").getAsLong());
	}

	@Test
	public void sameNpcDifferentHoursSplitKills()
	{
		long hourEnd = (T0 / HOUR) * HOUR + HOUR;
		List<JsonObject> raw = List.of(
			kill(42, "Goblin", 2, 1, hourEnd - 1L),
			kill(42, "Goblin", 2, 1, hourEnd)
		);
		List<JsonObject> out = CreditAttestCoalescer.coalesce(raw);
		assertEquals(2, out.size());
		for (JsonObject event : out)
		{
			assertEquals(CreditAttestCoalescer.TYPE_NPC_KILL, event.get("type").getAsString());
			assertEquals(1, event.getAsJsonObject("evidence").get("amount").getAsInt());
		}
	}

	@Test
	public void epochHourMatchesHourMsDivision()
	{
		assertEquals(T0 / HOUR, CreditAttestCoalescer.epochHour(T0));
		assertEquals(0L, CreditAttestCoalescer.epochHour(-5L));
		assertTrue(CreditAttestCoalescer.epochHour(HOUR) > CreditAttestCoalescer.epochHour(HOUR - 1L));
	}

	private static JsonObject xp(String skill, long xpDelta, long at)
	{
		JsonObject evidence = new JsonObject();
		evidence.addProperty("skill", skill);
		evidence.addProperty("xpDelta", xpDelta);
		JsonObject event = new JsonObject();
		event.addProperty("type", CreditAttestCoalescer.TYPE_XP_CHUNK);
		event.add("evidence", evidence);
		event.addProperty("at", at);
		return event;
	}

	private static JsonObject kill(int npcId, String npcName, int combatLevel, int amount, long at)
	{
		JsonObject evidence = new JsonObject();
		evidence.addProperty("npcId", npcId);
		evidence.addProperty("npcName", npcName);
		evidence.addProperty("combatLevel", combatLevel);
		evidence.addProperty("amount", amount);
		JsonObject event = new JsonObject();
		event.addProperty("type", CreditAttestCoalescer.TYPE_NPC_KILL);
		event.add("evidence", evidence);
		event.addProperty("at", at);
		return event;
	}
}

package com.osrstcg.cloud.attest;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Test;

public class AttestRateCapNotifierTest
{
	@Test
	public void pauseMessageUsesCeiledMinutes()
	{
		assertEquals(0L, AttestRateCapNotifier.rateCapPauseMinutes(0L));
		assertEquals(1L, AttestRateCapNotifier.rateCapPauseMinutes(1L));
		assertEquals(1L, AttestRateCapNotifier.rateCapPauseMinutes(60_000L));
		assertEquals(2L, AttestRateCapNotifier.rateCapPauseMinutes(60_001L));
		assertEquals(31L, AttestRateCapNotifier.rateCapPauseMinutes(1_843_200L));
		assertEquals(
			"Hourly cap reached. Credit gains paused for 31 minutes.",
			AttestRateCapNotifier.playerFacingRateCapPauseMessage(1_843_200L));
	}

	@Test
	public void rateCapAfterMsPrefersPauseMessageOverRejectReasons()
	{
		AtomicReference<String> chat = new AtomicReference<>();
		AttestRateCapNotifier notifier = new AttestRateCapNotifier(chat::set);

		JsonObject response = new JsonObject();
		response.addProperty("rateCapAfterMs", 120_000L);
		JsonArray rejected = new JsonArray();
		JsonObject row = new JsonObject();
		row.addProperty("reason", "rate_cap_skill");
		rejected.add(row);
		response.add("rejected", rejected);

		notifier.onAttestResponse(response, 1_000L);
		assertEquals(
			"Hourly cap reached. Credit gains paused for 2 minutes.",
			chat.get());
	}

	@Test
	public void rejectOnlyUsesHourlyMessage()
	{
		AtomicReference<String> chat = new AtomicReference<>();
		AttestRateCapNotifier notifier = new AttestRateCapNotifier(chat::set);

		JsonObject response = new JsonObject();
		JsonArray rejected = new JsonArray();
		JsonObject row = new JsonObject();
		row.addProperty("reason", "rate_cap_global");
		rejected.add(row);
		response.add("rejected", rejected);

		notifier.onAttestResponse(response, 1_000L);
		assertEquals(
			"Credit rate limit hit - try again later.",
			chat.get());
	}

	@Test
	public void throttleSuppressesSecondWarnWithinWindow()
	{
		List<String> chats = new ArrayList<>();
		AttestRateCapNotifier notifier = new AttestRateCapNotifier(chats::add);

		JsonObject response = new JsonObject();
		response.addProperty("rateCapAfterMs", 60_000L);

		notifier.onAttestResponse(response, 1_000L);
		notifier.onAttestResponse(response, 1_000L + AttestRateCapNotifier.RATE_CAP_THROTTLE_MS - 1L);
		assertEquals(1, chats.size());

		notifier.onAttestResponse(response, 1_000L + AttestRateCapNotifier.RATE_CAP_THROTTLE_MS);
		assertEquals(2, chats.size());
	}

	@Test
	public void parseRateCapAfterMs()
	{
		assertEquals(0L, CreditAttestQueue.parseRateCapAfterMs(null));
		assertEquals(0L, CreditAttestQueue.parseRateCapAfterMs(new JsonObject()));

		JsonObject zero = new JsonObject();
		zero.addProperty("rateCapAfterMs", 0);
		assertEquals(0L, CreditAttestQueue.parseRateCapAfterMs(zero));

		JsonObject positive = new JsonObject();
		positive.addProperty("rateCapAfterMs", 1_843_200L);
		assertEquals(1_843_200L, CreditAttestQueue.parseRateCapAfterMs(positive));
	}

	@Test
	public void isRateCapActiveUsesDeadline()
	{
		assertFalse(new DeadlineProbe(0L).isRateCapActive(100L));
		assertTrue(new DeadlineProbe(200L).isRateCapActive(100L));
		assertFalse(new DeadlineProbe(200L).isRateCapActive(200L));
		assertFalse(new DeadlineProbe(200L).isRateCapActive(201L));
	}

	@Test
	public void enqueueOptimisticCreditsFrozenWhileRateCapActive()
	{
		assertEquals(0L, CreditAttestQueue.enqueueOptimisticCredits(250L, true));
		assertEquals(250L, CreditAttestQueue.enqueueOptimisticCredits(250L, false));
		assertEquals(0L, CreditAttestQueue.enqueueOptimisticCredits(0L, false));
	}

	/** Tiny stand-in for deadline comparisons without constructing the full queue. */
	private static final class DeadlineProbe
	{
		private final long until;

		DeadlineProbe(long until)
		{
			this.until = until;
		}

		boolean isRateCapActive(long nowMs)
		{
			return until > 0L && nowMs < until;
		}
	}
}

package com.osrstcg.cloud.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class CloudTokenStoreBindingTest
{
	@Test
	public void isBoundToRequiresExactMatch()
	{
		assertTrue(CloudTokenStore.isBoundTo(42L, 42L));
		assertFalse(CloudTokenStore.isBoundTo(42L, 99L));
		assertFalse(CloudTokenStore.isBoundTo(-1L, 42L));
		assertFalse(CloudTokenStore.isBoundTo(42L, -1L));
	}

	@Test
	public void parseBoundAccountHashHandlesMissingAndInvalid()
	{
		assertEquals(12345L, CloudTokenStore.parseBoundAccountHash("12345"));
		assertEquals(-1L, CloudTokenStore.parseBoundAccountHash(null));
		assertEquals(-1L, CloudTokenStore.parseBoundAccountHash(""));
		assertEquals(-1L, CloudTokenStore.parseBoundAccountHash("  "));
		assertEquals(-1L, CloudTokenStore.parseBoundAccountHash("not-a-number"));
	}

	@Test
	public void shouldClearWhenRefreshExistsButNotBoundToLiveAccount()
	{
		assertTrue(CloudTokenStore.shouldClearForAccount(1L, true, 2L));
		assertTrue(CloudTokenStore.shouldClearForAccount(-1L, true, 2L));
		assertFalse(CloudTokenStore.shouldClearForAccount(2L, true, 2L));
		assertFalse(CloudTokenStore.shouldClearForAccount(1L, false, 2L));
		assertFalse(CloudTokenStore.shouldClearForAccount(1L, true, -1L));
	}
}

package com.osrstcg.cloud.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstcg.cloud.session.CloudSessionFileStore.SessionData;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class CloudSessionFileStoreTest
{
	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	@Test
	public void saveLoadRoundTrip() throws Exception
	{
		CloudSessionFileStore store = newStore();
		SessionData data = session("access-a", "refresh-a", "acct-1", "ok");

		store.save(42L, data);
		SessionData loaded = store.load(42L);

		assertNotNull(loaded);
		assertEquals("access-a", loaded.accessToken);
		assertEquals("refresh-a", loaded.refreshToken);
		assertEquals("acct-1", loaded.accountId);
		assertEquals("ok", loaded.status);
		assertEquals(42L, loaded.boundAccountHash);
		assertTrue(Files.isRegularFile(store.sessionFile(42L)));
	}

	@Test
	public void accountsAreIsolated() throws Exception
	{
		CloudSessionFileStore store = newStore();
		store.save(1L, session("a1", "r1", null, null));
		store.save(2L, session("a2", "r2", null, null));

		assertEquals("a1", store.load(1L).accessToken);
		assertEquals("a2", store.load(2L).accessToken);
		assertFalse(store.sessionFile(1L).equals(store.sessionFile(2L)));
	}

	@Test
	public void deleteRemovesSessionFile() throws Exception
	{
		CloudSessionFileStore store = newStore();
		store.save(7L, session("a", "r", null, null));
		assertTrue(Files.isRegularFile(store.sessionFile(7L)));

		store.delete(7L);
		assertNull(store.load(7L));
		assertFalse(Files.isRegularFile(store.sessionFile(7L)));
	}

	@Test
	public void deleteAccountDirWipesFolder() throws Exception
	{
		CloudSessionFileStore store = newStore();
		store.save(9L, session("a", "r", null, null));
		Path dir = store.accountDir(9L);
		Files.writeString(dir.resolve("tcg.save"), "blob");
		assertTrue(Files.isDirectory(dir));

		store.deleteAccountDir(9L);
		assertFalse(Files.exists(dir));
		assertNull(store.load(9L));
	}

	@Test
	public void loadReturnsNullForMissingOrInvalid() throws Exception
	{
		CloudSessionFileStore store = newStore();
		assertNull(store.load(99L));
		assertNull(store.load(-1L));

		Path file = store.sessionFile(5L);
		Files.createDirectories(file.getParent());
		Files.writeString(file, "{not-json");
		assertNull(store.load(5L));
	}

	private CloudSessionFileStore newStore() throws Exception
	{
		return new CloudSessionFileStore(tmp.newFolder("profiles").toPath(), new Gson());
	}

	private static SessionData session(String access, String refresh, String accountId, String status)
	{
		SessionData data = new SessionData();
		data.accessToken = access;
		data.refreshToken = refresh;
		data.accountId = accountId;
		data.status = status;
		return data;
	}
}

