		assertEquals(
			"%USERNAME% opened a booster pack!\n\n**New cards**\n- **Zilyana**\n- Goblin",
			packSummaryMessage("%USERNAME%", buildSummarySections(pulls, true)));
	}

	@Test
	public void packSummaryOmitsEmptyNewCardsSection()
	{
