		21,
		16);

	private final OsrsTcgConfig config;
	private final TcgStateService stateService;
	private final CreditsRateTracker creditsRateTracker;
	private final PackCatalogService packCatalogService;
/** Cache of the last painted credits value; render()-thread only, used to skip rebuilding components when unchanged. */
	private long lastCredits = Long.MIN_VALUE;
/** Cache of the last painted credits/h value; render()-thread only. */
	private Long lastCreditsPerHour;
/** Cache of the last "show rate" config flag; render()-thread only. */
	private boolean lastShowRate;
/** Cache of the last "show infobox" config flag; render()-thread only. */
	private boolean lastShowInfobox = true;
/** Hash of the menu-entry-relevant state as of the last {@link #refreshMenuEntries()} call; render()-thread only. */
	private int lastMenuFingerprint = Integer.MIN_VALUE;
/** Wires the collaborators used to read credits/rate/catalog state and positions the overlay top-left. */
	@Inject
	CreditsInfoboxOverlay(
		OsrsTcgConfig config,
		TcgStateService stateService,
		CreditsRateTracker creditsRateTracker,
		PackCatalogService packCatalogService)
	{
		this.config = config;
		this.stateService = stateService;
		this.creditsRateTracker = creditsRateTracker;
		this.packCatalogService = packCatalogService;
		setPosition(OverlayPosition.TOP_LEFT);
		setClearChildren(false);
	}
/**
	 * Paints the credits/credits-per-hour panel, rebuilding the child components only when the
	 * displayed values changed, and refreshing the right-click menu only when its contents changed.
	 * Called on the client's rendering thread. Returns null (and clears state) while the infobox is
	 * disabled in config.
	 */
	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.creditsInfobox())
		{
			if (lastShowInfobox)
			{
				getMenuEntries().clear();
				panelComponent.getChildren().clear();
				lastShowInfobox = false;
				lastCredits = Long.MIN_VALUE;
				lastMenuFingerprint = Integer.MIN_VALUE;
			}
			return null;
		}
		lastShowInfobox = true;

		long credits = stateService.getCredits();
		boolean showRate = config.creditsPerHour();
		Long creditsPerHour = showRate ? creditsRateTracker.creditsPerHourOrNull() : null;
		int menuFingerprint = menuFingerprint(credits, showRate);
		boolean valuesChanged = credits != lastCredits
			|| showRate != lastShowRate
			|| !java.util.Objects.equals(creditsPerHour, lastCreditsPerHour);
		if (valuesChanged)
		{
			lastCredits = credits;
			lastShowRate = showRate;
			lastCreditsPerHour = creditsPerHour;
			panelComponent.getChildren().clear();
			panelComponent.getChildren().add(SplitComponent.builder()
				.orientation(ComponentOrientation.HORIZONTAL)
				.gap(new Point(4, 0))
				.first(new ImageComponent(CREDIT_ICON))
				.second(LineComponent.builder()
					.right(NumberFormatting.format(credits))
					.build())
				.build());

			if (showRate && creditsPerHour != null)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.right(NumberFormatting.format(creditsPerHour) + "/h")
					.build());
			}
		}
		if (menuFingerprint != lastMenuFingerprint)
		{
			lastMenuFingerprint = menuFingerprint;
			refreshMenuEntries();
		}

		return super.render(graphics);
	}
/** Combines credits, the rate-display flag, and each affordable visible booster into a change-detection hash. */
	private int menuFingerprint(long credits, boolean showRate)
	{
		int hash = showRate ? 1 : 0;
		hash = 31 * hash + Long.hashCode(credits);
		for (BoosterPackDefinition booster : packCatalogService.getVisibleBoosters())
		{
			if (booster == null || credits < booster.getPrice())
			{
				continue;
			}
			String target = packMenuTarget(booster);
			hash = 31 * hash + target.hashCode();
			hash = 31 * hash + Integer.hashCode(booster.getPrice());
		}
		return hash;
	}
/** Display name used as the overlay menu target for a pack. */
	public static String packMenuTarget(BoosterPackDefinition booster)
	{
		if (booster == null)
		{
			return "";
		}
		if (booster.getName() != null && !booster.getName().isBlank())
		{
			return booster.getName();
		}
		if (booster.getId() != null && !booster.getId().isBlank())
		{
			return booster.getId();
		}
		return "Pack";
	}
/** Rebuilds the overlay's right-click menu: a Reset entry when the rate is shown, and an Open entry per affordable visible booster. */
	private void refreshMenuEntries()
	{
		getMenuEntries().clear();
		if (config.creditsPerHour())
		{
			addMenuEntry(MenuAction.RUNELITE_OVERLAY, MENU_OPTION_RESET, MENU_TARGET_CREDITS_PER_HOUR);
		}
		long credits = stateService.getCredits();
		for (BoosterPackDefinition booster : packCatalogService.getVisibleBoosters())
		{
			if (booster == null || credits < booster.getPrice())
			{
				continue;
			}
			addMenuEntry(MenuAction.RUNELITE_OVERLAY, MENU_OPTION_OPEN, packMenuTarget(booster));
		}
	}
}

package com.osrstcg.overlay;

import com.osrstcg.overlay.PackRevealLayout.ViewportLayout;
import com.osrstcg.pack.PackRevealService;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
/**
 * Layout math for the card-dealing animation phase: computes where each card sits mid-flight from
 * the pile to its final grid slot, and in what draw order. Pure functions over the caller-supplied
 * elapsed time, so it carries no mutable state and is safe to call from any thread.
 */
public final class PackRevealDealLayout
{
/** Pixel offset applied per waiting card in the still-stacked pile, so later cards peek out from under earlier ones. */
	static final int DEAL_STACK_STEP = 5;
/** Not instantiable; all members are static. */
	private PackRevealDealLayout()
	{
	}
/**
	 * Computes the current on-screen rectangle for every card during the deal phase: waiting cards are
	 * stacked at the pile center with a small offset per rank, in-flight cards are eased from the pile
	 * to their destination slot, and arrived cards sit at their final grid slot.
	 */
	static List<Rectangle> layoutDealPhaseCardRects(Rectangle canvas, ViewportLayout layout, int cardCount, long elapsed)
	{
		List<Rectangle> out = new ArrayList<>(cardCount);
		if (cardCount <= 0)
		{
			return out;
		}
		long stagger = PackRevealService.PACK_DEAL_STAGGER_MS;
		long flight = PackRevealService.PACK_DEAL_FLIGHT_MS;
		List<Rectangle> slots = PackRevealLayout.layoutCardSlots(canvas, cardCount, layout);
		int cw = layout.cardW;
		int ch = layout.cardH;
		Rectangle grid = unionBounds(slots);
		int cx = grid.x + grid.width / 2;
		int cy = grid.y + grid.height / 2;
		Rectangle pileCenterRect = new Rectangle(cx - cw / 2, cy - ch / 2, cw, ch);
		for (int i = 0; i < cardCount; i++)
		{
			out.add(dealPhaseCardRect(i, elapsed, stagger, flight, slots, pileCenterRect, cw, ch, cardCount));
		}
		return out;
	}
/**
	 * Draw-order layer for card {@code i} at the given elapsed time: 0 once it has arrived (drawn first,
	 * i.e. behind), 2 while in flight (drawn on top), 1 while still waiting in the pile.
	 */
	static int dealDrawLayer(long elapsed, int i, long stagger, long flight)
	{
		long t0 = (long) i * stagger;
		long t1 = t0 + flight;
		if (elapsed >= t1)
		{
			return 0;
		}
		if (elapsed < t0)
		{
			return 1;
		}
		return 2;
	}
/** Linearly interpolates position and size between two rectangles at {@code t} (0 = from, 1 = to). */
	static Rectangle lerp(Rectangle from, Rectangle to, double t)
	{
		int x = (int) Math.round(from.x + ((to.x - from.x) * t));
		int y = (int) Math.round(from.y + ((to.y - from.y) * t));
		int w = (int) Math.round(from.width + ((to.width - from.width) * t));
		int h = (int) Math.round(from.height + ((to.height - from.height) * t));
		return new Rectangle(x, y, w, h);
	}
/** Clamps {@code v} to the [0, 1] range. */
	public static double clamp01(double v)
	{
		if (v <= 0.0d)
		{
			return 0.0d;
		}
		if (v >= 1.0d)
		{
			return 1.0d;
		}
		return v;
	}
/** Smoothstep easing (3t^2 - 2t^3) over {@code t}, clamped to [0, 1] first. */
	static double smoothStep(double t)
	{
		t = clamp01(t);
		return t * t * (3.0d - 2.0d * t);
	}
/** Bounding rectangle covering every rect in the list, or an empty rectangle at the origin if the list is null/empty. */
	static Rectangle unionBounds(List<Rectangle> rects)
	{
		if (rects == null || rects.isEmpty())
		{
			return new Rectangle();
		}
		Rectangle u = new Rectangle(rects.get(0));
		for (int i = 1; i < rects.size(); i++)
		{
			u.add(rects.get(i));
		}
		return u;
	}
/**
	 * Per-card rectangle for the deal phase: the destination slot once arrived; a pile-stack position,
	 * offset by rank among still-waiting cards, before its stagger delay elapses; otherwise an eased
	 * lerp from the pile center to the destination slot.
	 */
	private static Rectangle dealPhaseCardRect(int i, long elapsed, long stagger, long flight,
		List<Rectangle> slots, Rectangle pileCenterRect, int cw, int ch, int n)
	{
		long t0 = (long) i * stagger;
		long t1 = t0 + flight;
		Rectangle dest = slots.get(i);
		if (elapsed >= t1)
		{
			return dest;
		}
		if (elapsed < t0)
		{
			List<Integer> waiting = new ArrayList<>();
			for (int j = 0; j < n; j++)
			{
				if (elapsed < (long) j * stagger)
				{
					waiting.add(j);
				}
			}
			Collections.sort(waiting);
			int rank = waiting.indexOf(i);
			if (rank < 0)
			{
				rank = 0;
			}
			int off = rank * DEAL_STACK_STEP;
			return new Rectangle(pileCenterRect.x + off, pileCenterRect.y + off, cw, ch);
		}
		double u = clamp01((elapsed - t0) / (double) flight);
		double t = smoothStep(u);
		return lerp(pileCenterRect, dest, t);
	}
}

package com.osrstcg.overlay;

import com.osrstcg.ui.SharedCardRenderer;
import com.osrstcg.ui.card.CardColorMath;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.client.ui.FontManager;
/**
 * Stateless drawing helpers for the pack reveal overlay: the close button, glow effects, badges/labels,
 * and image/rect fitting math. Called from overlay rendering ({@code Graphics2D}) on RuneLite's overlay
 * render thread; the glow bake cache is synchronized since it may be read/written across renders.
 */
final class PackRevealDrawUtil
{
	static final int CLOSE_BUTTON_SIZE = 26;
	private static final Color CLOSE_BG_TOP = new Color(0x2E, 0x2E, 0x2E, 248);
	private static final Color CLOSE_BG_BOTTOM = new Color(0x10, 0x10, 0x10, 248);
	private static final Color CLOSE_BORDER = new Color(255, 255, 255, 42);
	private static final Color CLOSE_BORDER_HOVER = new Color(0xFF, 0xF5, 0xDC, 110);
	private static final Color CLOSE_INSET_HIGHLIGHT = new Color(255, 255, 255, 38);
	private static final Color CLOSE_ICON = new Color(0xE0, 0x4B, 0x4B);
	private static final Color CLOSE_ICON_HOVER = new Color(0xFF, 0x6B, 0x6B);
	private static final Color CLOSE_HOVER_WASH = new Color(255, 255, 255, 24);
	private static final Color CLOSE_SHADOW = new Color(0, 0, 0, 150);
	private static final int CLOSE_RADIUS = 5;

	private static final int GLOW_CACHE_MAX = 24;
	private static final int GLOW_LAYERS = 6;
	private static final float GLOW_LAYER_ALPHA = 0.58f;
	private static final float GLOW_MAX_EXPAND = 28f;
	private static final Map<String, BufferedImage> GLOW_CACHE = Collections.synchronizedMap(
		new LinkedHashMap<String, BufferedImage>(16, 0.75f, true)
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<String, BufferedImage> eldest)
			{
				return size() > GLOW_CACHE_MAX;
			}
		});
/** No instances; all members are static. */
	private PackRevealDrawUtil()
	{
	}
/** Fills {@code canvas} with a semi-transparent black wash to dim the game view behind the overlay. */
	static void drawDim(Graphics2D g, Rectangle canvas)
	{
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.55f));
		g.setColor(Color.BLACK);
		g.fillRect(canvas.x, canvas.y, canvas.width, canvas.height);
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 1.0f));
	}
/** Writes the close button's bounds (top-right corner of {@code canvas}, edge-padded) into {@code outBounds}. */
	static void layoutCloseButton(Rectangle canvas, Rectangle outBounds)
	{
		int pad = PackRevealLayout.VIEWPORT_EDGE_PAD;
		int size = CLOSE_BUTTON_SIZE;
		outBounds.setBounds(
			canvas.x + canvas.width - pad - size,
			canvas.y + pad,
			size,
			size);
	}
/** Draws the rounded close button (shadow, gradient panel, inset highlight, border, X icon) with hover styling. */
	static void drawCloseButton(Graphics2D g, Rectangle bounds, boolean hover)
	{
		if (g == null || bounds == null || bounds.width <= 0 || bounds.height <= 0)
		{
			return;
		}
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);

			float r = CLOSE_RADIUS * 2f;
			int shadowOffset = 2;
			RoundRectangle2D shadow = new RoundRectangle2D.Float(
				bounds.x + shadowOffset,
				bounds.y + shadowOffset,
				bounds.width,
				bounds.height,
				r,
				r);
			g2.setColor(CLOSE_SHADOW);
			g2.fill(shadow);

			RoundRectangle2D panel = new RoundRectangle2D.Float(
				bounds.x, bounds.y, bounds.width, bounds.height, r, r);
			g2.setPaint(new GradientPaint(
				bounds.x,
				bounds.y,
				CLOSE_BG_TOP,
				bounds.x,
				bounds.y + bounds.height,
				CLOSE_BG_BOTTOM));
			g2.fill(panel);

			if (hover)
			{
				g2.setColor(CLOSE_HOVER_WASH);
				g2.fill(panel);
			}

			g2.setColor(CLOSE_INSET_HIGHLIGHT);
			g2.setStroke(new BasicStroke(1f));
			g2.draw(new RoundRectangle2D.Float(
				bounds.x + 1f,
				bounds.y + 1f,
				bounds.width - 2f,
				Math.max(1f, bounds.height - 2f),
				Math.max(0f, r - 2f),
				Math.max(0f, r - 2f)));

			g2.setColor(hover ? CLOSE_BORDER_HOVER : CLOSE_BORDER);
			g2.setStroke(new BasicStroke(1f));
			g2.draw(panel);

			int iconPad = Math.max(7, Math.round(bounds.width * 0.30f));
			int x1 = bounds.x + iconPad;
			int y1 = bounds.y + iconPad;
			int x2 = bounds.x + bounds.width - iconPad;
			int y2 = bounds.y + bounds.height - iconPad;
			BasicStroke iconStroke = new BasicStroke(1.75f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
			g2.setStroke(iconStroke);
			g2.setColor(new Color(0, 0, 0, 120));
			g2.drawLine(x1 + 1, y1 + 1, x2 + 1, y2 + 1);
			g2.drawLine(x2 + 1, y1 + 1, x1 + 1, y2 + 1);
			g2.setColor(hover ? CLOSE_ICON_HOVER : CLOSE_ICON);
			g2.drawLine(x1, y1, x2, y2);
			g2.drawLine(x2, y1, x1, y2);
		}
		finally
		{
			g2.dispose();
		}
	}
/** Scales {@code r} uniformly by {@code scale} about its center, clamping each dimension to at least 1px. */
	static Rectangle scaleRectCentered(Rectangle r, double scale)
	{
		int nw = Math.max(1, (int) Math.round(r.width * scale));
		int nh = Math.max(1, (int) Math.round(r.height * scale));
		int nx = r.x + (r.width - nw) / 2;
		int ny = r.y + (r.height - nh) / 2;
		return new Rectangle(nx, ny, nw, nh);
	}
/** Scales {@code r}'s width by {@code scaleX} about its horizontal center; height is unchanged. */
	static Rectangle scaleRectHorizontally(Rectangle r, double scaleX)
	{
		int nw = Math.max(1, (int) Math.round(r.width * scaleX));
		int nx = r.x + (r.width - nw) / 2;
		return new Rectangle(nx, r.y, nw, r.height);
	}
/** Shrinks {@code r} by {@code inset} on all four sides, clamping each dimension to at least 1px. */
	static Rectangle uniformInset(Rectangle r, int inset)
	{
		if (inset <= 0)
		{
			return new Rectangle(r);
		}
		int nw = Math.max(1, r.width - 2 * inset);
		int nh = Math.max(1, r.height - 2 * inset);
		return new Rectangle(r.x + inset, r.y + inset, nw, nh);
	}
/** Draws a soft glow around {@code r} using the default expand/layer settings and the card's outer arc. */
	static void drawGlow(Graphics2D g, Rectangle r, Color color, float alpha)
	{
		int baseArc = SharedCardRenderer.outerArcDiameter(r.width);
		drawGlow(g, r, color, alpha, GLOW_MAX_EXPAND, GLOW_LAYERS, baseArc);
	}
/**
	 * Draws a soft glow around {@code r} by blitting a cached, pre-baked layered-rounded-rect image scaled
	 * to {@code alpha}. No-ops for a null/degenerate rect or near-zero alpha.
	 */
	static void drawGlow(Graphics2D g, Rectangle r, Color color, float alpha, float maxExpand, int layers, int baseArc)
	{
		Color glow = color == null ? Color.WHITE : color;
		float clampedAlpha = Math.max(0f, Math.min(1f, alpha));
		if (clampedAlpha <= 0.01f || r == null || r.width < 1 || r.height < 1)
		{
			return;
		}

		int expand = Math.max(1, Math.round(maxExpand));
		BufferedImage baked = cachedGlow(r.width, r.height, glow.getRGB(), expand, layers, baseArc);
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, clampedAlpha));
			g2.drawImage(baked, r.x - expand, r.y - expand, null);
		}
		finally
		{
			g2.dispose();
		}
	}
/**
	 * Returns the baked glow image for this size/color/expand/layer combination, building and caching it
	 * (LRU, capped at {@link #GLOW_CACHE_MAX}) on first use.
	 */
	private static BufferedImage cachedGlow(int width, int height, int rgb, int expand, int layers, int baseArc)
	{
		String key = width + "x" + height + '|' + rgb + '|' + expand + '|' + layers + '|' + baseArc + '|' + GLOW_LAYER_ALPHA;
		BufferedImage cached = GLOW_CACHE.get(key);
		if (cached != null)
		{
			return cached;
		}
		int imgW = Math.max(1, width + expand * 2);
		int imgH = Math.max(1, height + expand * 2);
		BufferedImage img = new BufferedImage(imgW, imgH, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g2 = img.createGraphics();
		try
		{
			Color glow = new Color(rgb, true);
			int layerCount = Math.max(1, layers);
			for (int i = layerCount; i >= 1; i--)
			{
				float t = (float) i / (float) layerCount;
				int layerExpand = Math.max(1, Math.round((1.0f - t) * expand));
				float falloff = t * t;
				float layerAlpha = falloff * GLOW_LAYER_ALPHA;
				g2.setColor(withAlpha(glow, layerAlpha));
				int arc = baseArc + 2 * layerExpand;
				g2.fillRoundRect(
					expand - layerExpand,
					expand - layerExpand,
					width + (layerExpand * 2),
					height + (layerExpand * 2),
					arc,
					arc
				);
			}
		}
		finally
		{
			g2.dispose();
		}
		GLOW_CACHE.put(key, img);
		return img;
	}
/** Returns {@code color} (or white if null) with its alpha replaced by {@code alpha}. */
	static Color withAlpha(Color color, float alpha)
	{
		return CardColorMath.withAlpha(color == null ? Color.WHITE : color, alpha);
	}
/** Returns the largest rect that fits {@code image} inside {@code bounds} preserving aspect ratio, centered. */
	static Rectangle fittedImageRect(Rectangle bounds, BufferedImage image)
	{
		if (image == null)
		{
			return new Rectangle(bounds);
		}
		int sw = image.getWidth();
		int sh = image.getHeight();
		if (sw <= 0 || sh <= 0)
		{
			return new Rectangle(bounds);
		}
		double ratio = Math.min((double) bounds.width / (double) sw, (double) bounds.height / (double) sh);
		int w = Math.max(1, (int) Math.round(sw * ratio));
		int h = Math.max(1, (int) Math.round(sh * ratio));
		int x = bounds.x + (bounds.width - w) / 2;
		int y = bounds.y + (bounds.height - h) / 2;
		return new Rectangle(x, y, w, h);
	}
/** Draws {@code image} scaled to fit within {@code bounds} preserving aspect ratio, centered. */
	static void drawImageFit(Graphics2D g, BufferedImage image, Rectangle bounds)
	{
		Rectangle r = fittedImageRect(bounds, image);
		g.drawImage(image, r.x, r.y, r.width, r.height, null);
	}
/** Draws a centered "NEW!" badge with a drop shadow above {@code cardBounds}. */
	static void drawNewBadge(Graphics2D g, Rectangle cardBounds)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setFont(FontManager.getRunescapeBoldFont());
			String text = "NEW!";
			int textX = cardBounds.x + (cardBounds.width / 2) - (g2.getFontMetrics().stringWidth(text) / 2);
			int textY = Math.max(14, cardBounds.y - 8);

			g2.setColor(new Color(0, 0, 0, 180));
			g2.drawString(text, textX + 1, textY + 1);
			g2.setColor(new Color(0xF2C94C));
			g2.drawString(text, textX, textY);
		}
		finally
		{
			g2.dispose();
		}
	}
/** Draws {@code text} centered near the top of {@code cardBounds} with a drop shadow, faded by {@code alpha}. No-op if {@code text} is null or alpha is near zero. */
	static void drawRarityLabel(Graphics2D g, Rectangle cardBounds, String text, Color color, float alpha)
	{
		float clampedAlpha = Math.max(0f, Math.min(1f, alpha));
		if (text == null || clampedAlpha <= 0.01f)
		{
			return;
		}

		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setFont(FontManager.getRunescapeBoldFont());
			FontMetrics fm = g2.getFontMetrics();
			int textX = cardBounds.x + (cardBounds.width / 2) - (fm.stringWidth(text) / 2);
			int textY = cardBounds.y + Math.max(fm.getAscent(), Math.round(cardBounds.height / 4f));

			g2.setColor(withAlpha(Color.BLACK, clampedAlpha * (180f / 255f)));
			g2.drawString(text, textX + 1, textY + 1);
			g2.setColor(withAlpha(color == null ? Color.WHITE : color, clampedAlpha));
			g2.drawString(text, textX, textY);
		}
		finally
		{
			g2.dispose();
		}
	}
}

package com.osrstcg.overlay;

import com.osrstcg.pack.PackRevealService;
import com.osrstcg.ui.SidebarRefresh;
import com.osrstcg.util.TcgPluginGameMessages;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseWheelListener;
/**
 * RuneLite mouse/keyboard listener that intercepts and consumes game input while a pack reveal is
 * active, routing clicks/keys to the reveal service and overlay instead. Callbacks run on RuneLite's
 * input handling thread, not the client thread.
 */
@Singleton
public class PackRevealInputListener implements MouseListener, KeyListener, MouseWheelListener
{
	private final PackRevealService revealService;
	private final PackRevealOverlay overlay;
	private final SidebarRefresh sidebarRefresh;
	private final ChatMessageManager chatMessageManager;
/** Wires the collaborators used to detect an active reveal, forward input to it, and refresh the sidebar after close. */
	@Inject
	public PackRevealInputListener(
		PackRevealService revealService,
		PackRevealOverlay overlay,
		SidebarRefresh sidebarRefresh,
		ChatMessageManager chatMessageManager)
	{
		this.revealService = revealService;
		this.overlay = overlay;
		this.sidebarRefresh = sidebarRefresh;
		this.chatMessageManager = chatMessageManager;
	}
/**
	 * Aborts the active reveal (no-op if none), optionally chat-announcing {@code reasonMessage} first,
	 * then refreshes the sidebar.
	 */
	private void forceCloseActiveReveal(String reasonMessage)
	{
		if (!revealService.isActive())
		{
			return;
		}
		if (reasonMessage != null && !reasonMessage.isBlank())
		{
			TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager, reasonMessage);
		}
		revealService.abortActiveReveal();
		sidebarRefresh.refreshAfterPackRevealClose();
	}
/** Consumes game input only while a pack reveal overlay is active. */
	private boolean revealBlocksGameInput()
	{
		return revealService.isActive();
	}
/** Updates the overlay's hover point from {@code e} while a reveal is active, else clears it. */
	private void syncRevealHoverCanvasFromEvent(java.awt.event.MouseEvent e)
	{
		if (e == null)
		{
			return;
		}
		if (!revealBlocksGameInput())
		{
			overlay.setRevealHoverCanvasPoint(null);
			return;
		}
		overlay.setRevealHoverCanvasPoint(e.getPoint());
	}
/** Consumes clicks while a reveal is active; otherwise passes the event through unconsumed. */
	@Override
	public MouseEvent mouseClicked(MouseEvent mouseEvent)
	{
		if (!revealBlocksGameInput() || mouseEvent == null)
		{
			return mouseEvent;
		}
		mouseEvent.consume();
		return mouseEvent;
	}
/**
	 * Syncs the hover point, then while a reveal is active: right-click pins the card info tip; left-click
	 * hits the pinned tip, the close button, or forwards to {@link PackRevealService#handleClick}, refreshing
	 * the sidebar if that ends the reveal. Consumes the event whenever a reveal is active.
	 */
	@Override
	public MouseEvent mousePressed(MouseEvent mouseEvent)
	{
		if (mouseEvent == null)
		{
			return mouseEvent;
		}
		syncRevealHoverCanvasFromEvent(mouseEvent);
		if (!revealBlocksGameInput())
		{
			return mouseEvent;
		}

		if (mouseEvent.getButton() == MouseEvent.BUTTON3)
		{
			overlay.pinCardInfoTipAt(mouseEvent.getPoint());
			mouseEvent.consume();
			return mouseEvent;
		}

		if (mouseEvent.getButton() == MouseEvent.BUTTON1)
		{
			if (overlay.isCardInfoTipPinned())
			{
				if (overlay.handlePinnedTipClick(mouseEvent.getPoint()))
				{
					mouseEvent.consume();
					return mouseEvent;
				}
			}
			if (overlay.handleCloseButtonClick(mouseEvent.getPoint()))
			{
				forceCloseActiveReveal(
					"Pack reveal closed - your cards are in your collection.");
				mouseEvent.consume();
				return mouseEvent;
			}
			revealService.handleClick(mouseEvent.getPoint(), overlay.currentPackBounds(), overlay.currentCardBounds());
			if (!revealService.isActive())
			{
				sidebarRefresh.refreshAfterPackRevealClose();
			}
		}
		mouseEvent.consume();
		return mouseEvent;
	}
/** Consumes the release while a reveal is active; otherwise passes it through unconsumed. */
	@Override
	public MouseEvent mouseReleased(MouseEvent mouseEvent)
	{
		if (!revealBlocksGameInput() || mouseEvent == null)
		{
			return mouseEvent;
		}
		mouseEvent.consume();
		return mouseEvent;
	}
/** Consumes the enter event while a reveal is active; otherwise passes it through unconsumed. */
	@Override
	public MouseEvent mouseEntered(MouseEvent mouseEvent)
	{
		if (!revealBlocksGameInput() || mouseEvent == null)
		{
			return mouseEvent;
		}
		mouseEvent.consume();
		return mouseEvent;
	}
/** Clears the overlay's hover point, then consumes the exit event while a reveal is active. */
	@Override
	public MouseEvent mouseExited(MouseEvent mouseEvent)
	{
		overlay.setRevealHoverCanvasPoint(null);
		if (!revealBlocksGameInput() || mouseEvent == null)
		{
			return mouseEvent;
		}
		mouseEvent.consume();
		return mouseEvent;
	}
/** Syncs the hover point, then consumes the drag event while a reveal is active. */
	@Override
	public MouseEvent mouseDragged(MouseEvent mouseEvent)
	{
		if (mouseEvent == null)
		{
			return mouseEvent;
		}
		syncRevealHoverCanvasFromEvent(mouseEvent);
		if (!revealBlocksGameInput())
		{
			return mouseEvent;
		}
		mouseEvent.consume();
		return mouseEvent;
	}
/** Syncs the hover point, then consumes the move event while a reveal is active. */
	@Override
	public MouseEvent mouseMoved(MouseEvent mouseEvent)
	{
		if (mouseEvent == null)
		{
			return mouseEvent;
		}
		syncRevealHoverCanvasFromEvent(mouseEvent);
		if (!revealBlocksGameInput())
		{
			return mouseEvent;
		}
		mouseEvent.consume();
		return mouseEvent;
	}
/** Syncs the hover point, then nudges the reveal's zoom level and consumes the event while a reveal is active. */
	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent event)
	{
		if (event == null)
		{
			return event;
		}
		syncRevealHoverCanvasFromEvent(event);
		if (!revealBlocksGameInput())
		{
			return event;
		}
		overlay.nudgeSessionPackZoom(event.getWheelRotation());
		event.consume();
		return event;
	}
/** Consumes typed characters while a reveal is active; otherwise leaves the event alone. */
	@Override
	public void keyTyped(KeyEvent e)
	{
		if (!revealBlocksGameInput() || e == null)
		{
			return;
		}
		e.consume();
	}
/**
	 * While a reveal is active: Escape force-closes the reveal, Space advances it (refreshing the sidebar
	 * if that ends the reveal); all other keys are simply consumed.
	 */
	@Override
	public void keyPressed(KeyEvent e)
	{
		if (!revealBlocksGameInput() || e == null)
		{
			return;
		}
		if (e.getKeyCode() == KeyEvent.VK_ESCAPE)
		{
			forceCloseActiveReveal(
				"Pack reveal closed - your cards are in your collection.");
			e.consume();
			return;
		}
		if (e.getKeyCode() == KeyEvent.VK_SPACE)
		{
			revealService.advanceFromKeyboard();
			if (!revealService.isActive())
			{
				sidebarRefresh.refreshAfterPackRevealClose();
			}
		}
		e.consume();
	}
/** Consumes the key release while a reveal is active; otherwise leaves the event alone. */
	@Override
	public void keyReleased(KeyEvent e)
	{
		if (!revealBlocksGameInput() || e == null)
		{
			return;
		}
		e.consume();
	}
}

