package com.osrstcg.cloud.trade;

import com.osrstcg.OsrsTcgConfig;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.util.Text;
/**
 * Message-row “TCG trade request” menu entries (friends / friends chat / clan).
 */
@Singleton
public class TcgTradeMenuHandler
{
/** Menu option text injected on message rows and matched back on click. */
	static final String TRADE_REQ_MENU_OPTION = "TCG trade request";

	private final Client client;
	private final TradeCloudService tradeCloudService;
	private final OsrsTcgConfig config;

	@Inject
	public TcgTradeMenuHandler(Client client, TradeCloudService tradeCloudService, OsrsTcgConfig config)
	{
		this.client = client;
		this.tradeCloudService = tradeCloudService;
		this.config = config;
	}
/**
	 * Injects a "TCG trade request" entry onto "Message" menu rows (friends / friends chat / clan). Must run
	 * on the client thread, as {@link MenuEntryAdded} handlers do.
	 */
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.friendsMenuOption())
		{
			return;
		}
		if (event == null || !"Message".equals(event.getOption()))
		{
			return;
		}
		String target = event.getTarget();
		if (target == null || target.isEmpty())
		{
			return;
		}
		String playerName = Text.removeTags(target).trim();
		if (playerName.isEmpty())
		{
			return;
		}
		client.getMenu().createMenuEntry(0)
			.setOption(TRADE_REQ_MENU_OPTION)
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> tradeCloudService.sendTradeRequest(playerName));
	}
/**
	 * Handles clicks on the injected "TCG trade request" entry, sending the trade request for the clicked
	 * player. Must run on the client thread, as {@link MenuOptionClicked} handlers do; the actual request is
	 * dispatched asynchronously by {@link TradeCloudService#sendTradeRequest(String)}.
	 */
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event == null || !TRADE_REQ_MENU_OPTION.equals(event.getMenuOption()))
		{
			return;
		}
		String target = event.getMenuTarget();
		if (target == null || target.isEmpty())
		{
			return;
		}
		String playerName = Text.removeTags(target).trim();
		if (!playerName.isEmpty())
		{
			tradeCloudService.sendTradeRequest(playerName);
		}
	}
}

package com.osrstcg.cloud.trade;

import com.google.gson.JsonObject;
import com.osrstcg.util.TcgPluginGameMessages;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.util.LinkBrowser;
import com.osrstcg.cloud.api.CloudApiClient;
import com.osrstcg.cloud.api.CloudApiException;
import com.osrstcg.cloud.api.CloudEndpoints;
import com.osrstcg.cloud.api.CloudResponseSync;
import com.osrstcg.cloud.api.JsonObjects;
import com.osrstcg.cloud.session.CloudSessionService;
/**
 * Manages player-to-player trading against the cloud API: sending trade requests and self-rescheduling
 * polling of the trade inbox, with backoff on errors. {@link #start()}/{@link #stop()} control the poll
 * loop's lifecycle (e.g. on login/logout); {@link #sendTradeRequest(String)} and the poll loop both run
 * their network calls on the injected {@link ScheduledExecutorService}, never on the client thread, and
 * notify the registered inbox listener afterward so the caller can hop back to the client thread.
 */
@Slf4j
@Singleton
public final class TradeCloudService
{
	private static final long DEFAULT_POLL_MS = 15_000L;
	private static final long BACKOFF_MAX_MS = 180_000L;
	private static final long AUTH_RETRY_MS = 60_000L;

	private final CloudApiClient api;
	private final CloudSessionService session;
	private final Client client;
	private final ChatMessageManager chatMessageManager;
	private final ScheduledExecutorService scheduler;

	private final AtomicReference<Runnable> inboxListener = new AtomicReference<>(null);
	private final AtomicBoolean running = new AtomicBoolean(false);
	private final AtomicBoolean polling = new AtomicBoolean(false);
	private final AtomicBoolean forceAgain = new AtomicBoolean(false);
	private final AtomicBoolean broadcastPendingOnLogin = new AtomicBoolean(false);
	private final AtomicLong lastRevision = new AtomicLong(-1L);
	private final AtomicLong lastGoodPollAfterMs = new AtomicLong(DEFAULT_POLL_MS);
	private final AtomicLong backoffMs = new AtomicLong(0L);
	private final Object scheduleLock = new Object();
	private ScheduledFuture<?> pollFuture;
/** Wires cloud/session collaborators and the executor used for network calls and polling. */
	@Inject
	TradeCloudService(
		CloudApiClient api,
		CloudSessionService session,
		Client client,
		ChatMessageManager chatMessageManager,
		ScheduledExecutorService scheduler)
	{
		this.api = api;
		this.session = session;
		this.client = client;
		this.chatMessageManager = chatMessageManager;
		this.scheduler = scheduler;
	}
/** Starts the inbox poll loop (idempotent) and resets revision/backoff state, forcing a login broadcast. */
	public void start()
	{
		synchronized (scheduleLock)
		{
			if (running.get())
			{
				return;
			}
			running.set(true);
			lastRevision.set(-1L);
			backoffMs.set(0L);
			lastGoodPollAfterMs.set(DEFAULT_POLL_MS);
			broadcastPendingOnLogin.set(true);
			scheduleNextLocked(0L);
		}
	}
/** Stops the inbox poll loop and cancels any scheduled poll. */
	public void stop()
	{
		synchronized (scheduleLock)
		{
			running.set(false);
			forceAgain.set(false);
			cancelScheduledLocked();
			lastRevision.set(-1L);
			backoffMs.set(0L);
			broadcastPendingOnLogin.set(false);
		}
	}
/**
	 * Requests an immediate inbox poll, bypassing the current backoff/interval. If a poll is already in
	 * flight, defers the extra poll until it finishes rather than running two concurrently.
	 */
	public void requestForcedRefresh()
	{
		synchronized (scheduleLock)
		{
			if (!running.get())
			{
				return;
			}
			if (polling.get())
			{
				forceAgain.set(true);
				return;
			}
			cancelScheduledLocked();
			scheduleNextLocked(0L);
		}
	}
/** Records the latest known trade-inbox revision, ignoring negative (unknown) values. */
	public void noteRevision(long revision)
	{
		if (revision >= 0L)
		{
			lastRevision.set(revision);
		}
	}
/** @return the last known trade-inbox revision, or -1 if none has been observed yet */
	public long getLastRevision()
	{
		return lastRevision.get();
	}
/** Registers the callback invoked after each poll/mutation that may have changed inbox state. */
	public void setInboxListener(Runnable listener)
	{
		inboxListener.set(listener);
	}
/**
	 * Creates a trade request to {@code partnerDisplayName} via the cloud API. Dispatches the (blocking)
	 * network call on the executor, so this method returns immediately; chat feedback, opening the trade
	 * web page and a forced inbox refresh happen asynchronously once the call completes.
	 */
	public void sendTradeRequest(String partnerDisplayName)
	{
		if (!session.isReady())
		{
			TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager, "Cloud offline - cannot trade.");
			return;
		}
		if (partnerDisplayName == null || partnerDisplayName.trim().isEmpty())
		{
			return;
		}
		long accountHash = client.getAccountHash();
		if (accountHash == -1L)
		{
			TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
				"Waiting for account - try again in a moment.");
			return;
		}
		final String partner = partnerDisplayName.trim();
		scheduler.execute(() ->
		{
			try
			{
				JsonObject result = api.createTrade(partner, accountHash);
				applyEconomyFieldsFromRpc(result);
				String url = JsonObjects.text(result, "url");
				TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
					"Trade request sent to " + partner
						+ (url == null || url.isEmpty() ? "." : " - finish on the website."));
				if (url != null && !url.isEmpty())
				{
					String browseUrl = CloudEndpoints.rewriteToWebBase(url);
					if (browseUrl != null && !browseUrl.isBlank())
					{
						LinkBrowser.browse(browseUrl);
					}
				}
				notifyListener();
				requestForcedRefresh();
			}
			catch (CloudApiException ex)
			{
				queueTradeFailure(ex);
			}
			catch (IllegalArgumentException ex)
			{
				TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
					"Trade failed: account hash missing - relog.");
			}
			catch (Exception ex)
			{
				log.warn("Trade create failed", ex);
				TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
					"Trade failed - cloud error.");
			}
		});
	}
/** Chats a mapped failure message for a failed trade mutation, unless the account is locked/banned/quarantined. */
	private void queueTradeFailure(CloudApiException ex)
	{
		if (ex != null && (ex.isAccountBanned() || ex.isAccountQuarantined() || session.isAccountLocked()))
		{
			return;
		}
		String mapped = TradeMutationErrors.messageFor(ex);
		TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
			mapped == null ? "Trade failed." : mapped);
	}
/** Schedules the next poll after {@code delayMs}; no-op if stopped. Caller must hold {@link #scheduleLock}. */
	private void scheduleNextLocked(long delayMs)
	{
		if (!running.get())
		{
			return;
		}
		pollFuture = scheduler.schedule(this::pollSafe, Math.max(0L, delayMs), TimeUnit.MILLISECONDS);
	}
/** Cancels any pending scheduled poll. Caller must hold {@link #scheduleLock}. */
	private void cancelScheduledLocked()
	{
		if (pollFuture != null)
		{
			pollFuture.cancel(false);
			pollFuture = null;
		}
	}
/**
	 * Poll-loop entry point: runs {@link #poll()}, computes the next delay (honoring server-suggested
	 * interval, error backoff, or a queued forced refresh), and reschedules itself. Never throws - all
	 * poll failures are caught, logged and turned into a backoff delay.
	 */
	private void pollSafe()
	{
		polling.set(true);
		long nextDelayMs = lastGoodPollAfterMs.get();
		try
		{
			nextDelayMs = poll();
			backoffMs.set(0L);
			lastGoodPollAfterMs.set(nextDelayMs <= 0L ? DEFAULT_POLL_MS : nextDelayMs);
			nextDelayMs = lastGoodPollAfterMs.get();
		}
		catch (CloudApiException ex)
		{
			nextDelayMs = delayForApiError(ex);
			log.debug("Trade inbox poll failed: {} {}", ex.getStatus(), ex.getCode());
		}
		catch (Exception e)
		{
			nextDelayMs = nextBackoffDelayMs();
			log.debug("Trade inbox poll failed", e);
		}
		finally
		{
			polling.set(false);
			synchronized (scheduleLock)
			{
				if (!running.get())
				{
					return;
				}
				if (forceAgain.compareAndSet(true, false))
				{
					scheduleNextLocked(0L);
				}
				else
				{
					scheduleNextLocked(nextDelayMs);
				}
			}
		}
	}
/**
	 * Makes one blocking call to the trade-inbox endpoint, applies any changed sidebar stats/revision, chats
	 * a ping for newly-notified (or, on first poll after login, all) pending trades, and acks notified items.
	 *
	 * @return the server-suggested delay in ms before the next poll
	 */
	private long poll() throws Exception
	{
		if (!session.isReady() || client.getAccountHash() == -1L)
		{
			return lastGoodPollAfterMs.get();
		}

		long hash = client.getAccountHash();
		long knownRevision = lastRevision.get();
		Long since = knownRevision >= 0L ? knownRevision : null;
		JsonObject response = api.getTradeInbox(hash, since);

		long pollAfterMs = JsonObjects.readLong(response, "pollAfterMs", DEFAULT_POLL_MS);

		if (!JsonObjects.readBoolean(response, "statsUnchanged")
			&& response.has("stats") && response.get("stats").isJsonObject())
		{
			JsonObject stats = response.getAsJsonObject("stats");
			session.applySidebarStats(stats);
			session.reconcileCollectionFromInbox(stats);
		}

		Double revision = JsonObjects.readNumber(response, "revision");
		if (revision != null)
		{
			lastRevision.set(Math.round(revision));
		}

		List<TradeInboxItem> inbox = api.parseInbox(response);
		boolean loginBroadcast = broadcastPendingOnLogin.compareAndSet(true, false);
		for (TradeInboxItem item : inbox)
		{
			if (loginBroadcast || !item.isNotified())
			{
				String fromLabel = item.getFromDisplayName() == null || item.getFromDisplayName().isBlank()
					? "someone"
					: item.getFromDisplayName().trim();
				TcgPluginGameMessages.queueFormattedGameMessage(chatMessageManager,
					TcgPluginGameMessages.formatPendingTradeRequest(fromLabel),
					TcgPluginGameMessages.plainPendingTradeRequest(fromLabel));
				if (!item.isNotified())
				{
					try
					{
						api.ackTradeNotify(item.getTradeId(), hash);
					}
					catch (CloudApiException ackEx)
					{
						log.debug("Trade notify ack failed: {} {}", ackEx.getCode(), ackEx.getMessage());
					}
				}
			}
		}

		notifyListener();
		return pollAfterMs;
	}
/** Applies any credits/openedPacks/totalCreditsGained/revision fields present on a trade RPC response to session state. */
	private void applyEconomyFieldsFromRpc(JsonObject response)
	{
		CloudResponseSync.applyEconomyAndRevision(response, session::applySidebarStats, this);
	}
/** Invokes the registered inbox listener, if any. */
	private void notifyListener()
	{
		Runnable listener = inboxListener.get();
		if (listener != null)
		{
			listener.run();
		}
	}
/**
	 * Chooses the next poll delay for a failed poll based on the error type: re-establishes the session and
	 * waits {@link #AUTH_RETRY_MS} on 401, exponential backoff on rate limit/server error, otherwise falls
	 * back to the last known good interval.
	 */
	private long delayForApiError(CloudApiException ex)
	{
		if (ex.isUnauthorized())
		{
			try
			{
				session.ensureSession();
			}
			catch (Exception ignored)
			{
			}
			return AUTH_RETRY_MS;
		}
		if (ex.isRateLimited() || ex.isServerError())
		{
			return nextBackoffDelayMs();
		}
		return Math.max(DEFAULT_POLL_MS, lastGoodPollAfterMs.get());
	}
/** Doubles the current backoff (starting from {@link #DEFAULT_POLL_MS}), capped at {@link #BACKOFF_MAX_MS}. */
	private long nextBackoffDelayMs()
	{
		long next = backoffMs.get();
		if (next <= 0L)
		{
			next = DEFAULT_POLL_MS;
		}
		else
		{
			next = Math.min(BACKOFF_MAX_MS, next * 2L);
		}
		backoffMs.set(next);
		return Math.max(DEFAULT_POLL_MS, next);
	}
}

package com.osrstcg.cloud.trade;

import com.osrstcg.cloud.api.CloudApiException;
/**
 * Chat-facing messages for hardened trade mutator failures ({@code accountHash} / eligibility).
 */
final class TradeMutationErrors
{
/** Static-only utility class; not instantiable. */
	private TradeMutationErrors()
	{
	}
/** @return player-facing body after {@code [OSRS TCG] }, or {@code null} to use a generic fallback */
	static String messageFor(CloudApiException ex)
	{
		if (ex == null)
		{
			return null;
		}
		String code = ex.getCode() == null ? "" : ex.getCode();
		if ("missing_account_hash".equals(code) || "invalid_account_hash".equals(code))
		{
			return "Trade failed: account hash missing - relog.";
		}
		if ("account_hash_mismatch".equals(code) || "account_hash_unbound".equals(code))
		{
			return "Trade failed: account hash mismatch - relog or re-pair.";
		}
		if ("not_trade_eligible".equals(code) || "quarantined".equals(code) || "banned".equals(code)
			|| "account_banned".equals(code))
		{
			return "Your account cannot trade right now.";
		}
		if ("partner_not_trade_eligible".equals(code))
		{
			return "That player cannot trade right now.";
		}
		if (ex.isRateLimited() || "rate_limited".equals(code))
		{
			return "Trade rate-limited - try again shortly.";
		}
		if (ex.getStatus() == 404 || "partner_not_found".equals(code))
		{
			return "Player has no public collection.";
		}
		String serverMsg = ex.getMessage();
		if (serverMsg != null && !serverMsg.isBlank() && !serverMsg.equals(code))
		{
			return "Trade failed: " + serverMsg.trim();
		}
		return null;
	}
}

package com.osrstcg.cloud.shop;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.osrstcg.catalog.BoosterPackDefinition;
import com.osrstcg.state.CardCollectionKey;
import com.osrstcg.state.CloudSidebarCollectionStats;
import com.osrstcg.state.OwnedCardInstance;
import com.osrstcg.state.PackCardResult;
import com.osrstcg.state.PackOpenResult;
import com.osrstcg.state.TcgStateService;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.util.Text;
import com.osrstcg.cloud.api.CloudApiClient;
import com.osrstcg.cloud.api.CloudApiException;
import com.osrstcg.cloud.api.CloudResponseSync;
import com.osrstcg.cloud.api.JsonObjects;
import com.osrstcg.cloud.attest.CreditAttestQueue;
import com.osrstcg.cloud.catalog.PackCatalogService;
import com.osrstcg.cloud.catalog.PackPullParser;
import com.osrstcg.cloud.session.CloudSessionService;
import com.osrstcg.cloud.trade.TradeCloudService;
/**
 * Buys a booster pack through the cloud API and applies the resulting pulls, credits and ranks to local state.
 * {@link #buyAndOpenPack(BoosterPackDefinition, Runnable)} makes a blocking network call and updates shared
 * {@link TcgStateService} state, so callers must invoke it off the client thread and marshal any UI work
 * back onto the client thread themselves.
 */
@Slf4j
@Singleton
public final class CloudPackService
{
	private final CloudApiClient api;
	private final CloudSessionService session;
	private final CreditAttestQueue attestQueue;
	private final TradeCloudService tradeCloud;
	private final PackCatalogService packCatalog;
	private final TcgStateService stateService;
	private final Client client;
/** Wires cloud/session/state collaborators used to buy and resolve a pack open. */
	@Inject
	CloudPackService(
		CloudApiClient api,
		CloudSessionService session,
		CreditAttestQueue attestQueue,
		TradeCloudService tradeCloud,
		PackCatalogService packCatalog,
		TcgStateService stateService,
		Client client)
	{
		this.api = api;
		this.session = session;
		this.attestQueue = attestQueue;
		this.tradeCloud = tradeCloud;
		this.packCatalog = packCatalog;
		this.stateService = stateService;
		this.client = client;
	}
/**
	 * Buys and opens {@code booster} via the cloud API. Makes a blocking network call - run off the client
	 * thread. Never throws; failures are reported through the returned {@link PackOpenResult}.
	 * <p>
	 * When opening under a pending reveal, pass a non-null {@code beforeOpenRequest} (typically
	 * {@code packRevealService::armPendingPullsTimeout}) so the UI wait clock arms after local
	 * flush/pre-work. Pass {@code null} only when no pending-reveal timeout applies.
	 */
	public PackOpenResult buyAndOpenPack(BoosterPackDefinition booster, Runnable beforeOpenRequest)
	{
		return buyAndOpenPack(booster, true, beforeOpenRequest);
	}
/**
	 * Core buy-and-open flow: validates session/credits/catalog, calls the open-pack endpoint, then updates
	 * owned cards, credits, sidebar ranks and collection stats from the response.
	 *
	 * @param allowCatalogRetry whether a {@code catalog_mismatch} error should trigger one catalog refresh
	 *                          and a single retry with the refreshed pack definition
	 * @param beforeOpenRequest optional hook run immediately before each {@code openPack} HTTP call
	 */
	private PackOpenResult buyAndOpenPack(BoosterPackDefinition booster, boolean allowCatalogRetry,
		Runnable beforeOpenRequest)
	{
		long creditsBefore = stateService.getCredits();
		if (booster == null)
		{
			return PackOpenResult.failed("No booster pack selected.", creditsBefore, 0);
		}
		if (!session.isReady())
		{
			String reason = session.needsCloudConsent()
				? "Create a profile before opening packs."
				: "Cloud offline - cannot open packs.";
			return PackOpenResult.failed(reason, creditsBefore, booster.getPrice());
		}

		try
		{
			BoosterPackDefinition priced = packCatalog.getCache().get(booster.getId()).orElse(booster);
			int price = priced.getPrice();

			if (stateService.getAuthoritativeCredits() < price)
			{
				attestQueue.flushBlocking();
			}

			long displayCredits = stateService.getCredits();
			if (displayCredits < price)
			{
				refreshCreditsQuietly();
				displayCredits = stateService.getCredits();
				if (displayCredits < price)
				{
					return PackOpenResult.failed(
						"Not enough credits (need " + price + ", have " + displayCredits + ").",
						displayCredits,
						price);
				}
			}

			String catalogVersion = packCatalog.requireCatalogVersion();
			if (catalogVersion == null || catalogVersion.isEmpty())
			{
				return PackOpenResult.failed("Missing catalog version from server.", creditsBefore, price);
			}

			String packId = priced.getId() == null ? "" : priced.getId().trim();
			if (packId.isEmpty())
			{
				return PackOpenResult.failed("Missing pack id.", creditsBefore, price);
			}

			JsonObject body = new JsonObject();
			body.addProperty("packId", packId);
			body.addProperty("clientRequestId", UUID.randomUUID().toString());
			body.addProperty("catalogVersion", catalogVersion);
			body.addProperty("accountHash", Long.toString(client.getAccountHash()));

			Map<CardCollectionKey, Integer> ownedBefore;
			synchronized (stateService)
			{
				ownedBefore = new HashMap<>(stateService.getState().getCollectionState().getOwnedCards());
			}

			if (beforeOpenRequest != null)
			{
				beforeOpenRequest.run();
			}
			JsonObject response = api.openPack(body);
			Double creditsNum = JsonObjects.readNumber(response, "credits");
			long creditsAfter = creditsNum == null
				? stateService.getAuthoritativeCredits()
				: Math.round(creditsNum);
			Double gainedNum = JsonObjects.readNumber(response, "totalCreditsGained");
			long totalGained = gainedNum == null
				? stateService.getState().getTotalCreditsGained()
				: Math.round(gainedNum);

			List<PackCardResult> pulls = new ArrayList<>();
			List<OwnedCardInstance> newInstances = new ArrayList<>();
			String localPulledBy = client.getLocalPlayer() == null
				? ""
				: Text.sanitize(client.getLocalPlayer().getName());
			long now = System.currentTimeMillis();
			if (response.has("cards") && response.get("cards").isJsonArray())
			{
				for (var el : response.getAsJsonArray("cards"))
				{
					if (!el.isJsonObject())
					{
						continue;
					}
					PackCardResult pull = PackPullParser.parseCard(el.getAsJsonObject());
					if (pull == null || pull.getCardName().isBlank())
					{
						continue;
					}
					String pulledBy = pull.getPulledBy() == null || pull.getPulledBy().isBlank()
						? localPulledBy
						: pull.getPulledBy().trim();
					long pulledAt = pull.getPulledAtEpochMs() == null || pull.getPulledAtEpochMs() <= 0L
						? now
						: pull.getPulledAtEpochMs();
					PackCardResult normalized = pull.withProvenance(pulledBy, pulledAt);
					newInstances.add(new OwnedCardInstance(
						normalized.getInstanceId(),
						normalized.getCardName(),
						normalized.isFoil(),
						pulledBy,
						pulledAt));
					pulls.add(normalized);
				}
			}
			stateService.addOwnedCardInstances(newInstances);

			int cardsPerPack = Math.max(1, packCatalog.getCache().getPackSize());
			int openedPacks = (int) stateService.getState().getEconomyState().getOpenedPacks()
				+ (pulls.size() / cardsPerPack);

			stateService.replaceCloudEconomyCache(creditsAfter, openedPacks, totalGained);
			absorbRanksFromPackOpen(response);
			CloudSidebarCollectionStats optimistic = CloudSidebarCollectionStats.withOptimisticPackPulls(
				stateService.getCloudCollectionStats(), ownedBefore, pulls);
			if (optimistic != null)
			{
				stateService.replaceCollectionStatsCache(optimistic);
			}
			CloudResponseSync.applyRevision(response, stateService, tradeCloud);
			tradeCloud.requestForcedRefresh();

			boolean apex = JsonObjects.readBoolean(response, "apex");
			String displayName = priced.getName() == null ? booster.getName() : priced.getName();
			return PackOpenResult.succeeded(
				"Pack opened.",
				creditsBefore,
				creditsAfter,
				price,
				pulls,
				displayName,
				packId,
				apex);
		}
		catch (CloudApiException ex)
		{
			if (allowCatalogRetry && ex.isCatalogMismatch())
			{
				log.info("Pack catalog mismatch - refetch then retry open");
				try
				{
					packCatalog.refreshAfterCatalogMismatch().join();
				}
				catch (Exception refreshEx)
				{
					log.warn("catalog_mismatch refetch failed", refreshEx);
				}
				BoosterPackDefinition updated = packCatalog.getCache().get(booster.getId()).orElse(null);
				if (updated == null)
				{
					return PackOpenResult.failed(
						"Pack catalog updated - pack no longer available.",
						creditsBefore,
						booster.getPrice());
				}
				return buyAndOpenPack(updated, false, beforeOpenRequest);
			}
			log.warn("Pack open failed: {} {}", ex.getCode(), ex.getMessage());
			session.noteLockFromApiException(ex);
			if (ex.isInsufficientCredits())
			{
				applyInsufficientCreditsFix(ex);
			}
			String message = ex.isCatalogMismatch()
				? "Pack catalog updated, try again."
				: ex.getMessage();
			return PackOpenResult.failed(message, stateService.getCredits(), booster.getPrice());
		}
		catch (Exception ex)
		{
			log.warn("Pack open failed", ex);
			return PackOpenResult.failed("Pack open failed: " + ex.getMessage(), creditsBefore, booster.getPrice());
		}
	}
/** Reconciles local credits with the server's reported balance after an insufficient-credits failure. */
	private void applyInsufficientCreditsFix(CloudApiException ex)
	{
		Long serverCredits = ex == null ? null : ex.getServerCredits();
		if (serverCredits != null)
		{
			int openedPacks = (int) stateService.getState().getEconomyState().getOpenedPacks();
			long totalGained = stateService.getState().getTotalCreditsGained();
			stateService.replaceCloudEconomyCache(serverCredits, openedPacks, totalGained);
			stateService.clearOptimisticCredits();
		}
		refreshCreditsQuietly();
	}
/** Refreshes credits from the server, swallowing and logging any failure. */
	private void refreshCreditsQuietly()
	{
		try
		{
			session.refreshCreditsFromServer();
		}
		catch (Exception ex)
		{
			log.warn("Credit refresh after insufficient-credits failed", ex);
		}
	}
/** Applies the optional 6-element {@code ranks} array from a pack-open response to sidebar state, if present and valid. */
	private void absorbRanksFromPackOpen(JsonObject response)
	{
		if (response == null || !response.has("ranks") || !response.get("ranks").isJsonArray())
		{
			return;
		}
		JsonArray arr = response.getAsJsonArray("ranks");
		if (arr.size() != 6)
		{
			return;
		}
		int[] ranks = new int[6];
		for (int i = 0; i < 6; i++)
		{
			JsonElement el = arr.get(i);
			if (el == null || !el.isJsonPrimitive() || !el.getAsJsonPrimitive().isNumber())
			{
				return;
			}
			int n = el.getAsInt();
			if (n < 0)
			{
				return;
			}
			ranks[i] = n;
		}
		stateService.replaceSidebarRanks(ranks);
	}
}

