package com.osrstcg.cloud.activity;

import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
/**
 * Immutable, thread-safe snapshot of activity config for chat matching, NPC id exclusions,
 * and per-NPC kill credit multipliers.
 */
public final class CompiledActivityConfig
{
/** Empty config used before any fetch/disk-cache load has succeeded. */
	public static final CompiledActivityConfig EMPTY = new CompiledActivityConfig(
		"",
		List.of(),
		Set.of(),
		Map.of());

	private final String version;
	private final List<CompiledChatRule> chatRules;
	private final Set<Integer> excludedNpcIds;
	private final Map<Integer, Double> killCreditMultipliers;
/** Normalizes nulls to empty and defensively copies the collections into immutable ones. */
	CompiledActivityConfig(
		String version,
		List<CompiledChatRule> chatRules,
		Set<Integer> excludedNpcIds,
		Map<Integer, Double> killCreditMultipliers)
	{
		this.version = version == null ? "" : version;
		this.chatRules = chatRules == null ? List.of() : List.copyOf(chatRules);
		this.excludedNpcIds = excludedNpcIds == null ? Set.of() : Set.copyOf(excludedNpcIds);
		this.killCreditMultipliers = killCreditMultipliers == null ? Map.of() : Map.copyOf(killCreditMultipliers);
	}
/** Opaque version string this config was compiled from; empty for {@link #EMPTY}. */
	public String getVersion()
	{
		return version;
	}

	public List<CompiledChatRule> getChatRules()
	{
		return chatRules;
	}
/** Whether {@code npcId} is excluded from credit-earning activities. */
	public boolean isExcludedNpc(int npcId)
	{
		return excludedNpcIds.contains(npcId);
	}
/**
	 * Optimistic kill-credit multiplier for {@code npcId}; defaults to {@code 1.0} when unset.
	 */
	public double getKillCreditMultiplier(int npcId)
	{
		Double multiplier = killCreditMultipliers.get(npcId);
		return multiplier == null ? 1.0 : multiplier;
	}
/** Precompiled chat-message match rule: literal prefix or regex, mutually exclusive. */
	public static final class CompiledChatRule
	{
		private final String activityId;
		private final long credits;
		private final String label;
		private final String prefix;
		private final Pattern pattern;
/** Normalizes nulls and clamps credits to non-negative; exactly one of {@code prefix}/{@code pattern} is expected. */
		CompiledChatRule(String activityId, long credits, String label, String prefix, Pattern pattern)
		{
			this.activityId = activityId == null ? "" : activityId;
			this.credits = Math.max(0L, credits);
			this.label = label == null ? "" : label;
			this.prefix = prefix;
			this.pattern = pattern;
		}
/** True if {@code message} satisfies this rule's regex or prefix match. */
		public boolean matches(String message)
		{
			if (message == null)
			{
				return false;
			}
			if (pattern != null)
			{
				return pattern.matcher(message).matches();
			}
			return prefix != null && message.startsWith(prefix);
		}

		public String getActivityId()
		{
			return activityId;
		}

		public long getCredits()
		{
			return credits;
		}

		public String getLabel()
		{
			return label;
		}
	}
}

package com.osrstcg.cloud.activity;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.osrstcg.cloud.activity.ActivityConfigModels.ActivitiesConfigResponse;
import com.osrstcg.cloud.activity.ActivityConfigModels.ActivityChatRuleDto;
import com.osrstcg.cloud.activity.ActivityConfigModels.ActivityConfigDto;
import com.osrstcg.cloud.activity.ActivityConfigModels.KillCreditMultiplierDto;
import com.osrstcg.cloud.activity.ActivityConfigModels.NpcExclusionsDto;
import com.osrstcg.cloud.api.CloudApiClient;
import com.osrstcg.cloud.api.CloudApiException;
import com.osrstcg.util.AtomicFiles;
import com.osrstcg.cloud.session.ProfileKeyHasher;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
/**
 * Fetches, caches, and compiles the server-driven activity config (chat-based credit rules and NPC
 * exclusions) used to award activity credits. Holds the current {@link CompiledActivityConfig} in an
 * {@link AtomicReference} for lock-free reads; network refreshes run asynchronously on {@link #scheduler}
 * and never block callers of the getters. A copy is persisted to disk so the last-good config survives
 * restarts and cloud API failures.
 */
@Slf4j
@Singleton
public final class ActivityConfigService
{
	private static final long QUIET_POLL_MINUTES = 10L;

	private final CloudApiClient api;
	private final Gson gson;
	private final ScheduledExecutorService scheduler;

	private final AtomicReference<CompiledActivityConfig> compiled =
		new AtomicReference<>(CompiledActivityConfig.EMPTY);
	private final AtomicBoolean ensureInFlight = new AtomicBoolean(false);
	private final AtomicBoolean softRefreshScheduled = new AtomicBoolean(false);
	private final Object pollLock = new Object();
	private ScheduledFuture<?> quietPollFuture;
/** Wires collaborators and registers to be notified when the cloud API observes a new remote version. */
	@Inject
	ActivityConfigService(CloudApiClient api, Gson gson, ScheduledExecutorService scheduler)
	{
		this.api = api;
		this.gson = gson;
		this.scheduler = scheduler;
		api.setActivitiesVersionListener(this::noteRemoteVersion);
	}
/** Synchronously loads the on-disk cached config, if any, so a compiled config is available before any network fetch. Blocks on disk I/O; call off the client thread during startup. */
	public void loadDiskCacheIfPresent()
	{
		Path file = diskCacheFile();
		if (!Files.isRegularFile(file))
		{
			return;
		}
		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			ActivityConfigDto dto = gson.fromJson(reader, ActivityConfigDto.class);
			if (dto == null)
			{
				return;
			}
			applyDto(dto, false);
			log.info("Loaded activity config from disk (version={}, chatRules={})",
				getVersion(), getChatRules().size());
		}
		catch (IOException | JsonSyntaxException ex)
		{
			log.warn("Failed reading activity config disk cache {}", file, ex);
		}
	}
/** Kicks off an async, best-effort refresh without blocking the caller. */
	public void prefetchAsync()
	{
		scheduler.execute(this::ensureFreshSafe);
	}
/** Starts the periodic quiet poll and triggers an immediate async refresh; call once per login. */
	public void refreshOnLogin()
	{
		startQuietPoll();
		scheduler.execute(this::ensureFreshSafe);
	}
/** Cancels the periodic quiet poll, if running; call on logout. */
	public void stopQuietPoll()
	{
		synchronized (pollLock)
		{
			if (quietPollFuture != null)
			{
				quietPollFuture.cancel(false);
				quietPollFuture = null;
			}
		}
	}
/**
	 * Callback for {@link CloudApiClient}'s version listener: if {@code remoteVersion} differs from the
	 * cached version, schedules a single async refresh (coalesced via {@link #softRefreshScheduled} so
	 * repeated notifications don't queue duplicate refreshes).
	 */
	public void noteRemoteVersion(String remoteVersion)
	{
		if (remoteVersion == null || remoteVersion.isBlank())
		{
			return;
		}
		String remote = remoteVersion.trim();
		String local = getVersion();
		if (!local.isEmpty() && local.equals(remote))
		{
			return;
		}
		if (!softRefreshScheduled.compareAndSet(false, true))
		{
			return;
		}
		scheduler.execute(() ->
		{
			try
			{
				ensureFreshSafe();
			}
			finally
			{
				softRefreshScheduled.set(false);
			}
		});
	}
/**
	 * Synchronously checks the remote version and, if stale, fetches and applies a fresh config; a single
	 * refresh runs at a time ({@link #ensureInFlight} guards re-entry) and failures are logged and swallowed,
	 * keeping the last-good compiled config. Performs blocking network I/O; call from {@link #scheduler}, not
	 * the client thread.
	 */
	public void ensureFresh()
	{
		if (!ensureInFlight.compareAndSet(false, true))
		{
			return;
		}
		try
		{
			ensureFreshLocked();
		}
		catch (CloudApiException | IOException ex)
		{
			if (ex instanceof CloudApiException
				&& "consent_required".equals(((CloudApiException) ex).getCode()))
			{
				return;
			}
			log.warn("Activity config refresh failed; keeping last-good ({})", ex.toString());
		}
		finally
		{
			ensureInFlight.set(false);
		}
	}
/** {@link #ensureFresh()} wrapped with a catch-all so a scheduled task never dies from an unexpected exception. */
	private void ensureFreshSafe()
	{
		try
		{
			ensureFresh();
		}
		catch (Exception ex)
		{
			log.warn("Activity config refresh failed; keeping last-good", ex);
		}
	}
/**
	 * Does the actual version check and conditional-GET fetch: skips the fetch entirely if a lightweight
	 * version check confirms the cache is current, and skips applying the body on a 304. Blocking network I/O.
	 */
	private void ensureFreshLocked() throws CloudApiException, IOException
	{
		String cachedVersion = getVersion();
		String remoteVersion = null;
		try
		{
			remoteVersion = api.getActivitiesVersion();
		}
		catch (Exception ex)
		{
			log.debug("Activity config version check failed", ex);
		}

		if (remoteVersion != null && !remoteVersion.isBlank()
			&& !cachedVersion.isEmpty()
			&& cachedVersion.equals(remoteVersion.trim()))
		{
			return;
		}

		ActivitiesConfigResponse response = api.getActivities(
			cachedVersion.isEmpty() ? null : cachedVersion);
		if (response.isNotModified())
		{
			return;
		}
		ActivityConfigDto body = response.getBody();
		if (body == null)
		{
			return;
		}
		applyDto(body, true);
		log.info("Refreshed activity config (version={}, chatRules={})",
			getVersion(), getChatRules().size());
	}
/** Version of the currently compiled config; non-blocking. */
	public String getVersion()
	{
		return compiled.get().getVersion();
	}
/** Chat rules from the currently compiled config; non-blocking. */
	public List<CompiledActivityConfig.CompiledChatRule> getChatRules()
	{
		return compiled.get().getChatRules();
	}
/** Currently compiled config snapshot; non-blocking. */
	public CompiledActivityConfig getCompiled()
	{
		return compiled.get();
	}
/** Starts a fixed-rate background refresh poll if one isn't already running. */
	private void startQuietPoll()
	{
		synchronized (pollLock)
		{
			if (quietPollFuture != null && !quietPollFuture.isCancelled())
			{
				return;
			}
			quietPollFuture = scheduler.scheduleAtFixedRate(
				this::ensureFreshSafe,
				QUIET_POLL_MINUTES,
				QUIET_POLL_MINUTES,
				TimeUnit.MINUTES);
		}
	}
/** Compiles {@code dto} and publishes it as the current config, optionally persisting the raw DTO to disk. */
	private void applyDto(ActivityConfigDto dto, boolean persistDisk)
	{
		CompiledActivityConfig next = compile(dto);
		compiled.set(next);
		if (persistDisk)
		{
			persistDiskCache(dto);
		}
	}
/**
	 * Converts a raw {@link ActivityConfigDto} into an immutable {@link CompiledActivityConfig}: compiles
	 * each chat rule (dropping invalid ones), expands NPC exclusion ids/ranges into a flat id set, and
	 * parses per-NPC kill credit multipliers.
	 */
	static CompiledActivityConfig compile(ActivityConfigDto dto)
	{
		if (dto == null)
		{
			return CompiledActivityConfig.EMPTY;
		}

		List<CompiledActivityConfig.CompiledChatRule> rules = new ArrayList<>();
		if (dto.chatRules != null)
		{
			for (ActivityChatRuleDto rule : dto.chatRules)
			{
				CompiledActivityConfig.CompiledChatRule compiledRule = compileChatRule(rule);
				if (compiledRule != null)
				{
					rules.add(compiledRule);
				}
			}
		}

		Set<Integer> npcIds = new HashSet<>();
		NpcExclusionsDto excl = dto.npcExclusions;
		if (excl != null)
		{
			if (excl.npcIds != null)
			{
				for (Integer id : excl.npcIds)
				{
					if (id != null)
					{
						npcIds.add(id);
					}
				}
			}
			if (excl.npcIdRanges != null)
			{
				for (List<Integer> range : excl.npcIdRanges)
				{
					if (range == null || range.size() < 2 || range.get(0) == null || range.get(1) == null)
					{
						continue;
					}
					int lo = Math.min(range.get(0), range.get(1));
					int hi = Math.max(range.get(0), range.get(1));
					for (int i = lo; i <= hi; i++)
					{
						npcIds.add(i);
					}
				}
			}
		}

		Map<Integer, Double> killMultipliers = new HashMap<>();
		if (dto.killCreditMultipliers != null)
		{
			for (Map.Entry<String, KillCreditMultiplierDto> entry : dto.killCreditMultipliers.entrySet())
			{
				if (entry == null || entry.getKey() == null || entry.getValue() == null)
				{
					continue;
				}
				int npcId;
				try
				{
					npcId = Integer.parseInt(entry.getKey().trim());
				}
				catch (NumberFormatException ex)
				{
					continue;
				}
				double multiplier = Math.max(0.0, entry.getValue().multiplier);
				killMultipliers.put(npcId, multiplier);
			}
		}

		String version = dto.version == null ? "" : dto.version.trim();
		return new CompiledActivityConfig(version, rules, npcIds, killMultipliers);
	}
/**
	 * Compiles one raw chat rule, or returns null if it's missing required fields or (for a regex rule)
	 * has an invalid pattern.
	 */
	private static CompiledActivityConfig.CompiledChatRule compileChatRule(ActivityChatRuleDto rule)
	{
		if (rule == null || rule.activityId == null || rule.activityId.isBlank()
			|| rule.value == null || rule.value.isEmpty())
		{
			return null;
		}
		String match = rule.match == null ? "prefix" : rule.match.trim().toLowerCase(Locale.ENGLISH);
		if ("regex".equals(match))
		{
			try
			{
				Pattern pattern = Pattern.compile(rule.value);
				return new CompiledActivityConfig.CompiledChatRule(
					rule.activityId.trim(), rule.credits, rule.label, null, pattern);
			}
			catch (PatternSyntaxException ex)
			{
				log.warn("Skipping invalid activity regex for {}: {}", rule.activityId, ex.getMessage());
				return null;
			}
		}
		return new CompiledActivityConfig.CompiledChatRule(
			rule.activityId.trim(), rule.credits, rule.label, rule.value, null);
	}
/** Best-effort atomic write of the raw DTO JSON to the disk cache; failures are logged and swallowed. */
	private void persistDiskCache(ActivityConfigDto dto)
	{
		Path target = diskCacheFile();
		try
		{
			AtomicFiles.writeString(target, gson.toJson(dto), StandardCharsets.UTF_8);
		}
		catch (Exception ex)
		{
			log.debug("Activity config disk cache write failed", ex);
		}
	}
/** Directory under the RuneLite home dir holding the activity config disk cache. */
	private static Path diskCacheDir()
	{
		return ProfileKeyHasher.tcgRoot().resolve("activities");
	}
/** Path to the cached raw activity config JSON file. */
	private static Path diskCacheFile()
	{
		return diskCacheDir().resolve("activities.json");
	}
}

package com.osrstcg.cloud.catalog;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.osrstcg.catalog.CardDefinition;
import com.osrstcg.cloud.api.JsonObjects;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
/**
 * Converts public {@code GET /api/v1/catalog/cards/live} raw {@code { items, npcs }} into
 * plugin {@link CardDefinition}s (one card per parent name; {@code tcg.variants} ids retained).
 */
public final class LiveCardsCatalogParser
{
	private LiveCardsCatalogParser()
	{
	}
/**
	 * Converts the {@code items} and {@code npcs} arrays of a live-catalog response into
	 * {@link CardDefinition}s, deduplicated by name (items take priority over NPCs). Returns an
	 * empty list for null input.
	 */
	public static List<CardDefinition> parse(JsonObject liveJson)
	{
		if (liveJson == null)
		{
			return List.of();
		}
		JsonArray items = liveJson.has("items") && liveJson.get("items").isJsonArray()
			? liveJson.getAsJsonArray("items")
			: new JsonArray();
		JsonArray npcs = liveJson.has("npcs") && liveJson.get("npcs").isJsonArray()
			? liveJson.getAsJsonArray("npcs")
			: new JsonArray();

		Set<String> itemNames = new HashSet<>();
		for (JsonElement el : items)
		{
			if (!el.isJsonObject())
			{
				continue;
			}
			String name = JsonObjects.textTrimmed(el.getAsJsonObject(), "name");
			if (name != null)
			{
				itemNames.add(name);
			}
		}

		List<CardDefinition> cards = new ArrayList<>();
		Set<String> seen = new HashSet<>();
		for (JsonElement el : items)
		{
			if (!el.isJsonObject())
			{
				continue;
			}
			CardDefinition card = normalizeParent(el.getAsJsonObject(), false, itemNames);
			if (card == null || !seen.add(card.getName()))
			{
				continue;
			}
			cards.add(card);
		}
		for (JsonElement el : npcs)
		{
			if (!el.isJsonObject())
			{
				continue;
			}
			CardDefinition card = normalizeParent(el.getAsJsonObject(), true, itemNames);
			if (card == null || !seen.add(card.getName()))
			{
				continue;
			}
			cards.add(card);
		}
		return cards;
	}
/**
	 * Builds a {@link CardDefinition} from one raw item/NPC entry. When an NPC shares its name
	 * with an item, it is renamed to {@code "npc:<id>"} to keep it distinct (or dropped if it
	 * has no id). Returns null when the entry has no name.
	 */
	private static CardDefinition normalizeParent(JsonObject raw, boolean npc, Set<String> itemNames)
	{
		String name = JsonObjects.textTrimmed(raw, "name");
		if (name == null)
		{
			return null;
		}

		JsonObject tcg = JsonObjects.objectOrEmpty(raw, "tcg");
		JsonObject tags = JsonObjects.objectOrEmpty(tcg, "tags");

		List<String> category = new ArrayList<>();
		if (tags.has("labels") && tags.get("labels").isJsonArray())
		{
			for (JsonElement labelEl : tags.getAsJsonArray("labels"))
			{
				if (labelEl.isJsonPrimitive() && labelEl.getAsJsonPrimitive().isString())
				{
					String label = labelEl.getAsString().trim();
					if (!label.isEmpty())
					{
						category.add(label);
					}
				}
			}
		}
		String slot = JsonObjects.textTrimmed(tags, "slot");
		if (slot != null)
		{
			category.add(slot);
		}
		String combatStyle = JsonObjects.textTrimmed(tags, "combatStyle");
		if (combatStyle != null)
		{
			category.add(combatStyle);
		}
		if (npc)
		{
			category.add("NPC");
		}

		Double idNumber = JsonObjects.readNumber(raw, "id");
		Long id = idNumber == null ? null : Math.round(idNumber);
		String cardName = name;
		if (npc && itemNames.contains(name))
		{
			if (id == null)
			{
				return null;
			}
			cardName = "npc:" + id;
		}

		CardDefinition card = new CardDefinition();
		card.setId(id);
		card.setName(cardName);
		card.setDisplayName(name);
		card.setCategory(category);
		// Region tags exist on both items and NPCs in live JSON (pack filters / shop progress).
		List<String> regions = parseStringList(raw, "regions");
		if (!regions.isEmpty())
		{
			card.setRegions(regions);
		}
		card.setExamine(JsonObjects.textTrimmed(raw, "examine"));
		String imagePath = JsonObjects.textTrimmed(raw, "imagePath");
		if (imagePath != null)
		{
			card.setImageUrl(imagePath);
		}
		String wikiPage = JsonObjects.textTrimmed(JsonObjects.objectOrEmpty(raw, "wiki"), "page");
		if (wikiPage != null)
		{
			card.setWikiPage(wikiPage);
		}
		Double scoreNumber = JsonObjects.readNumber(tcg, "score");
		if (scoreNumber != null)
		{
			card.setScore(Math.round(scoreNumber));
		}
		Double foilScoreNumber = JsonObjects.readNumber(tcg, "foilScore");
		Long foilScore = foilScoreNumber == null ? null : Math.round(foilScoreNumber);
		if (foilScore != null && foilScore >= 0L)
		{
			card.setFoilScore(foilScore);
		}
		Double overrideFoilScoreNumber = JsonObjects.readNumber(tcg, "overrideFoilScore");
		Long overrideFoilScore = overrideFoilScoreNumber == null ? null : Math.round(overrideFoilScoreNumber);
		if (overrideFoilScore != null && overrideFoilScore >= 0L && card.getFoilScore() == null)
		{
			card.setFoilScore(overrideFoilScore);
		}
		String tierLabel = JsonObjects.textTrimmed(tcg, "tierLabel");
		if (tierLabel != null)
		{
			card.setTierLabel(tierLabel);
		}
		List<Long> variantIds = parseVariantIds(tcg);
		if (!variantIds.isEmpty())
		{
			card.setVariantIds(variantIds);
		}
		return card;
	}
/** Distinct {@code tcg.variants[].id} values in encounter order. */
	private static List<Long> parseVariantIds(JsonObject tcg)
	{
		if (tcg == null || !tcg.has("variants") || !tcg.get("variants").isJsonArray())
		{
			return List.of();
		}
		List<Long> out = new ArrayList<>();
		Set<Long> seen = new HashSet<>();
		for (JsonElement el : tcg.getAsJsonArray("variants"))
		{
			if (el == null || !el.isJsonObject())
			{
				continue;
			}
			Double variantIdNumber = JsonObjects.readNumber(el.getAsJsonObject(), "id");
			Long variantId = variantIdNumber == null ? null : Math.round(variantIdNumber);
			if (variantId == null || !seen.add(variantId))
			{
				continue;
			}
			out.add(variantId);
		}
		return out;
	}
/** Reads a JSON array of strings at {@code key}, trimming and dropping blanks; empty list if absent/not an array. */
	static List<String> parseStringList(JsonObject o, String key)
	{
		if (o == null || !o.has(key) || !o.get(key).isJsonArray())
		{
			return List.of();
		}
		List<String> out = new ArrayList<>();
		for (JsonElement el : o.getAsJsonArray(key))
		{
			if (!el.isJsonPrimitive() || !el.getAsJsonPrimitive().isString())
			{
				continue;
			}
			String value = el.getAsString().trim();
			if (!value.isEmpty())
			{
				out.add(value);
			}
		}
		return out;
	}
}

package com.osrstcg.cloud.catalog;

import com.osrstcg.catalog.BoosterPackDefinition;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
/** In-memory snapshot of {@code GET /api/v1/packs}. Empty when disconnected. */
public final class PackCatalogCache
{
	private final String catalogVersion;
	private final int packSize;
	private final List<BoosterPackDefinition> packs;
	private final boolean fromServer;
/**
	 * @param packSize clamped to a minimum of 0.
	 * @param packs defensively copied into an unmodifiable list; null treated as empty.
	 * @param fromServer whether this cache reflects an actual server fetch, vs. the empty placeholder.
	 */
	public PackCatalogCache(
		String catalogVersion,
		int packSize,
		List<BoosterPackDefinition> packs,
		boolean fromServer)
	{
		this.catalogVersion = catalogVersion == null ? "" : catalogVersion;
		this.packSize = Math.max(0, packSize);
		this.packs = packs == null
			? List.of()
			: Collections.unmodifiableList(List.copyOf(packs));
		this.fromServer = fromServer;
	}
/** Server-reported catalog version, or {@code ""} if unknown. */
	public String getCatalogVersion()
	{
		return catalogVersion;
	}
/** Number of cards in a booster pack per this catalog. */
	public int getPackSize()
	{
		return packSize;
	}
/** Unmodifiable list of packs in this catalog. */
	public List<BoosterPackDefinition> getPacks()
	{
		return packs;
	}
/** True when this cache was populated from an actual server response, as opposed to the empty placeholder. */
	public boolean isFromServer()
	{
		return fromServer;
	}
/** True when this catalog has no packs. */
	public boolean isEmpty()
	{
		return packs.isEmpty();
	}
/** Builds a lookup map keyed by trimmed pack id, keeping the first pack seen for any duplicate id. */
	public Map<String, BoosterPackDefinition> byId()
	{
		Map<String, BoosterPackDefinition> map = new LinkedHashMap<>();
		for (BoosterPackDefinition pack : packs)
		{
			if (pack == null || pack.getId() == null || pack.getId().isBlank())
			{
				continue;
			}
			map.putIfAbsent(pack.getId().trim(), pack);
		}
		return Collections.unmodifiableMap(map);
	}
/** Looks up a pack by id (via {@link #byId()}); empty when {@code packId} is null/blank or not found. */
	public Optional<BoosterPackDefinition> get(String packId)
	{
		if (packId == null || packId.isBlank())
		{
			return Optional.empty();
		}
		return Optional.ofNullable(byId().get(packId.trim()));
	}
}

package com.osrstcg.cloud.catalog;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.osrstcg.catalog.BoosterPackDefinition;
import com.osrstcg.catalog.CardImageCacheService;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import com.osrstcg.cloud.api.CloudApiClient;
import com.osrstcg.cloud.api.JsonObjects;
/**
 * Holds the in-memory {@link PackCatalogCache} for the shop, fetching it from {@code GET /packs}
 * on login or after a catalog-mismatch error and preloading pack images. Fetches run on the
 * injected scheduler and make a blocking network call, so they must not run on the client thread.
 */
@Slf4j
@Singleton
public final class PackCatalogService
{
	private static final int DEFAULT_PACK_SIZE = 5;

	private final CloudApiClient api;
	private final ScheduledExecutorService scheduler;
	private final CardImageCacheService imageCacheService;

	private final AtomicReference<PackCatalogCache> cache = new AtomicReference<>();
	private final AtomicBoolean loginFetchAttempted = new AtomicBoolean(false);
	private final AtomicReference<Runnable> changeListener = new AtomicReference<>(null);

	@Inject
	PackCatalogService(
		CloudApiClient api,
		ScheduledExecutorService scheduler,
		CardImageCacheService imageCacheService)
	{
		this.api = api;
		this.scheduler = scheduler;
		this.imageCacheService = imageCacheService;
		this.cache.set(emptyCache());
	}
/** Registers a callback invoked (not necessarily on the client thread) whenever the pack catalog changes. */
	public void setChangeListener(Runnable listener)
	{
		changeListener.set(listener);
	}
/** Current catalog snapshot; never null (an empty placeholder before the first successful fetch). */
	public PackCatalogCache getCache()
	{
		return cache.get();
	}
/** Packs to show in the shop: empty until a real server catalog has been loaded. */
	public List<BoosterPackDefinition> getVisibleBoosters()
	{
		PackCatalogCache current = getCache();
		if (!current.isFromServer() || current.isEmpty())
		{
			return List.of();
		}
		return current.getPacks();
	}
/** Finds a pack by collection key or id; returns null if not found or if either argument is unusable. */
	public static BoosterPackDefinition findById(List<BoosterPackDefinition> packs, String packId)
	{
		if (packId == null || packId.isBlank() || packs == null)
		{
			return null;
		}
		for (BoosterPackDefinition pack : packs)
		{
			if (pack == null)
			{
				continue;
			}
			if (packId.equals(pack.getCollectionKey()) || packId.equals(pack.getId()))
			{
				return pack;
			}
		}
		return null;
	}
/** Current catalog version, preferring the cache's, falling back to the API client's last-seen value. */
	public String requireCatalogVersion()
	{
		String version = getCache().getCatalogVersion();
		if (version != null && !version.isBlank())
		{
			return version.trim();
		}
		String fromApi = api.getCachedCatalogVersion();
		return fromApi == null ? "" : fromApi.trim();
	}
/** Fetches the pack catalog once per login: no-op if already attempted since the last {@link #clear()}. */
	public CompletableFuture<Void> refreshOnLogin()
	{
		if (!loginFetchAttempted.compareAndSet(false, true))
		{
			return CompletableFuture.completedFuture(null);
		}
		return CompletableFuture.runAsync(() -> fetchAndApply(
			false,
			"GET /packs empty; shop stays empty",
			"Pack catalog loaded ({} packs, version={})",
			"Login pack catalog fetch failed; shop stays empty"), scheduler);
	}
/** Forces an async refetch after the server reports a {@code catalog_mismatch} error. */
	public CompletableFuture<Void> refreshAfterCatalogMismatch()
	{
		return CompletableFuture.runAsync(() -> fetchAndApply(
			true,
			"catalog_mismatch refetch empty; keeping cache",
			"Pack catalog refreshed after mismatch ({} packs, version={})",
			"catalog_mismatch pack catalog refetch failed"), scheduler);
	}
/** Resets to the empty catalog and allows {@link #refreshOnLogin()} to fetch again (e.g. on logout). */
	public void clear()
	{
		loginFetchAttempted.set(false);
		cache.set(emptyCache());
		notifyChanged();
	}
/**
	 * Blocking fetch-and-apply. Leaves the previous cache if the fetch fails or returns no packs.
	 * When {@code markLogin} is true, marks the login-fetch gate satisfied on success.
	 */
	private void fetchAndApply(boolean markLogin, String emptyLog, String successLog, String failLog)
	{
		try
		{
			PackCatalogCache parsed = parseServerCatalog(api.getPacks());
			if (parsed.isEmpty())
			{
				log.error(emptyLog);
				return;
			}
			cache.set(parsed);
			if (markLogin)
			{
				loginFetchAttempted.set(true);
			}
			notifyChanged();
			preloadPackImages(parsed).whenComplete((ok, err) -> notifyChanged());
			log.info(successLog, parsed.getPacks().size(), parsed.getCatalogVersion());
		}
		catch (Exception e)
		{
			log.warn(failLog, e);
		}
	}
/** Kicks off async preloading of every hosted thumbnail/image URL referenced by the catalog. */
	private CompletableFuture<Void> preloadPackImages(PackCatalogCache catalog)
	{
		if (catalog == null || imageCacheService == null)
		{
			return CompletableFuture.completedFuture(null);
		}
		List<String> urls = new ArrayList<>();
		for (BoosterPackDefinition pack : catalog.getPacks())
		{
			if (pack == null)
			{
				continue;
			}
			if (BoosterPackDefinition.isHostedImagePath(pack.getThumbnail()))
			{
				urls.add(pack.getThumbnail().trim());
			}
			if (BoosterPackDefinition.isHostedImagePath(pack.getImage()))
			{
				urls.add(pack.getImage().trim());
			}
		}
		if (urls.isEmpty())
		{
			return CompletableFuture.completedFuture(null);
		}
		return imageCacheService.preloadAsync(urls);
	}
/** Parses a {@code GET /packs} response body into a {@link PackCatalogCache}, tolerating missing/null fields. */
	static PackCatalogCache parseServerCatalog(JsonObject json)
	{
		String version = JsonObjects.text(json, "catalogVersion");
		if (version == null)
		{
			version = "";
		}
		Double packSizeNum = JsonObjects.readNumber(json, "packSize");
		int packSize = packSizeNum == null ? DEFAULT_PACK_SIZE : Math.max(1, (int) Math.round(packSizeNum));
		List<BoosterPackDefinition> packs = new ArrayList<>();
		if (json != null && json.has("packs") && json.get("packs").isJsonArray())
		{
			for (JsonElement el : json.getAsJsonArray("packs"))
			{
				if (!el.isJsonObject())
				{
					continue;
				}
				BoosterPackDefinition pack = parsePackEntry(el.getAsJsonObject());
				if (pack != null)
				{
					packs.add(pack);
				}
			}
		}
		return new PackCatalogCache(version, packSize, packs, true);
	}
/** Parses one {@code packs[]} entry; returns null when {@code id} is missing/blank. */
	private static BoosterPackDefinition parsePackEntry(JsonObject o)
	{
		String id = JsonObjects.textTrimmed(o, "id");
		if (id == null)
		{
			return null;
		}
		BoosterPackDefinition pack = new BoosterPackDefinition();
		pack.setId(id);
		String name = JsonObjects.text(o, "name");
		pack.setName(name == null ? id : name);
		pack.setPrice(JsonObjects.readInt(o, "price"));
		String thumb = JsonObjects.textTrimmed(o, "thumbnail");
		if (thumb != null)
		{
			pack.setThumbnail(thumb);
		}
		String image = JsonObjects.textTrimmed(o, "image");
		if (image != null)
		{
			pack.setImage(image);
		}
		pack.setCategory(LiveCardsCatalogParser.parseStringList(o, "category"));
		String collectionName = JsonObjects.textTrimmed(o, "collectionName");
		if (collectionName != null)
		{
			pack.setCollectionName(collectionName);
		}
		return pack;
	}
/** The placeholder cache used before any successful server fetch, or after {@link #clear()}. */
	private static PackCatalogCache emptyCache()
	{
		return new PackCatalogCache("", 0, List.of(), false);
	}
/** Invokes the registered change listener, if any. */
	private void notifyChanged()
	{
		Runnable listener = changeListener.get();
		if (listener != null)
		{
			listener.run();
		}
	}
}

