/** Parses the {@code inbox} array of a trade-inbox response, skipping malformed entries. */
	public List<TradeInboxItem> parseInbox(JsonObject response)
	{
		List<TradeInboxItem> out = new ArrayList<>();
		if (response == null || !response.has("inbox") || !response.get("inbox").isJsonArray())
		{
			return out;
		}
		for (JsonElement el : response.getAsJsonArray("inbox"))
		{
			if (!el.isJsonObject())
			{
				continue;
			}
			JsonObject o = el.getAsJsonObject();
			String tradeId = text(o, "tradeId");
			if (tradeId == null)
			{
				continue;
			}
			String from = text(o, "fromDisplayName");
			out.add(new TradeInboxItem(tradeId, from == null ? "" : from, readBoolean(o, "notified")));
		}
		return out;
	}
/**
	 * Persists {@code accessToken}/{@code refreshToken}/{@code accountId}/{@code status} from an auth
	 * response, binds them to {@code boundAccountHash}, and marks migrated if indicated.
	 */
	public void applyTokenResponse(JsonObject tokens, long boundAccountHash)
	{
		if (tokens == null)
		{
			return;
		}
		tokenStore.saveTokens(
			text(tokens, "accessToken"),
			text(tokens, "refreshToken"),
			text(tokens, "accountId"),
			text(tokens, "status"),
			boundAccountHash);
		if (textTrimmed(tokens, "migratedAt") != null || readBoolean(tokens, "migrated"))
		{
			tokenStore.setMigrated(true);
		}
	}
/**
	 * Issues an authenticated request; on a 401 makes one attempt to refresh the access token and
	 * retries once before giving up.
	 */
	private JsonObject requestAuthed(String method, String pathAndQuery, JsonObject body)
		throws CloudApiException, IOException
	{
		try
		{
			return request(method, pathAndQuery, body, true);
		}
		catch (CloudApiException ex)
		{
			if (!ex.isUnauthorized() || !tryRefresh())
			{
				throw ex;
			}
			return request(method, pathAndQuery, body, true);
		}
	}
/**
	 * Attempts a synchronous token refresh using the stored refresh token and current profile
	 * key hash. Clears stored credentials and invokes the stale-refresh handler if the refresh
	 * token itself is rejected as stale.
	 *
	 * @return true if the refresh succeeded and new tokens were applied.
	 */
	private boolean tryRefresh()
	{
		String refresh = tokenStore.getRefreshToken();
		String profileHash = profileKeyHasher.currentProfileKeyHash();
		long boundAccountHash = tokenStore.getBoundAccountHash();
		if (refresh == null || profileHash == null || boundAccountHash == -1L)
		{
			return false;
		}
		try
		{
			applyTokenResponse(refresh(refresh, profileHash), boundAccountHash);
			return true;
		}
		catch (CloudApiException e)
		{
			if (e.isStaleRefreshToken())
			{
				log.info("Clearing stale credentials after refresh failure ({})", e.getCode());
				tokenStore.clear();
				Runnable handler = staleRefreshHandler;
				if (handler != null)
				{
					handler.run();
				}
			}
			else
			{
				log.warn("Cloud token refresh failed: {} {}", e.getCode(), e.getMessage());
			}
			return false;
		}
		catch (Exception e)
		{
			log.warn("Cloud token refresh failed", e);
			return false;
		}
	}
/**
	 * Builds and executes a single HTTP request against the cloud API. Enforces the consent gate,
	 * attaches the bearer token when {@code authed}, serializes {@code body} as the JSON payload
	 * for non-GET methods, and throws {@link CloudApiException} on a non-2xx response.
	 */
	private JsonObject request(String method, String pathAndQuery, JsonObject body, boolean authed)
		throws CloudApiException, IOException
	{
		requireCloudConsentAllowed();
		Request.Builder b = new Request.Builder().url(requireApiUrl(pathAndQuery));
		if (authed)
		{
			String access = tokenStore.getAccessToken();
			if (access == null)
			{
				throw new CloudApiException(401, "missing_token", "Not signed in to cloud");
			}
			b.header("Authorization", "Bearer " + access);
		}
		if ("GET".equals(method))
		{
			b.get();
		}
		else
		{
			String payload = body == null ? "{}" : gson.toJson(body);
			b.method(method, RequestBody.create(JSON, payload));
		}

		try (Response response = executeWithFailover(b.build()))
		{
			notifyActivitiesVersion(response.header("X-Activities-Version"));
			String text = readBody(response);
			JsonObject json = parseObject(text);
			if (!response.isSuccessful())
			{
				throw httpError(response.code(), text);
			}
			return json;
		}
	}
/** Builds a {@link CloudApiException} from an error response and notifies the account-lock handler if applicable. */
	private CloudApiException httpError(int status, String body)
	{
		CloudApiException ex = exceptionFromHttpBody(status, body);
		if (ex.isAccountBanned() || ex.isAccountQuarantined())
		{
			Consumer<CloudApiException> handler = accountLockHandler;
			if (handler != null)
			{
				try
				{
					handler.accept(ex);
				}
				catch (RuntimeException handlerEx)
				{
					log.debug("Account lock handler failed", handlerEx);
				}
			}
		}
		return ex;
	}
/** Parses an error response body's {@code error.code}/{@code error.message}/{@code credits} fields into an exception. */
	private static CloudApiException exceptionFromHttpBody(int status, String body)
	{
		String code = "http_error";
		String message = body == null ? "" : body;
		JsonObject json = parseObject(body);
		JsonObject err = objectOrEmpty(json, "error");
		String parsedCode = textTrimmed(err, "code");
		if (parsedCode != null)
		{
			code = parsedCode;
		}
		String parsedMessage = text(err, "message");
		if (parsedMessage != null && !parsedMessage.isBlank())
		{
			message = parsedMessage;
		}
		JsonObject details = objectOrEmpty(err, "details");
		Long serverCredits = null;
		Double credits = readNumber(json, "credits");
		if (credits == null)
		{
			credits = readNumber(details, "credits");
		}
		if (credits != null)
		{
			serverCredits = Math.round(credits);
		}
		return new CloudApiException(status, code, CloudHttpErrorMapper.humanize(status, code, message),
			serverCredits);
	}
/** Forwards a non-blank {@code X-Activities-Version} header value to the registered listener, swallowing its errors. */
	private void notifyActivitiesVersion(String headerValue)
	{
		if (headerValue == null || headerValue.isBlank())
		{
			return;
		}
		Consumer<String> listener = activitiesVersionCb;
		if (listener != null)
		{
			try
			{
				listener.accept(headerValue.trim());
			}
			catch (Exception ex)
			{
				log.debug("Activities version listener failed", ex);
			}
		}
	}
/** Removes the surrounding quotes from a raw ETag header value, if present. */
	private static String stripQuotes(String etag)
	{
		if (etag == null)
		{
			return "";
		}
		String t = etag.trim();
		if (t.length() >= 2 && t.startsWith("\"") && t.endsWith("\""))
		{
			return t.substring(1, t.length() - 1);
		}
		return t;
	}
/**
	 * Executes {@code request}; on transport failure while still on the primary API host, sticks to
	 * the web host and retries once (same path under {@code /api/v1}).
	 */
	private Response executeWithFailover(Request request) throws IOException
	{
		try
		{
			return http.newCall(request).execute();
		}
		catch (IOException first)
		{
			if (useWebApi)
			{
				throw first;
			}
			useWebApi = true;
			HttpUrl web = HttpUrl.parse(CloudEndpoints.WEB_BASE_URL);
			log.info("API host unreachable; falling back to {}", CloudEndpoints.WEB_BASE_URL);
			TcgPluginGameMessages.queueDebugGameMessage(chatMessageManager,
				"Connected to fallback API address");
			return http.newCall(request.newBuilder()
				.url(request.url().newBuilder().host(web.host()).build())
				.build()).execute();
		}
	}
/** Resolves and parses the API URL for {@code pathAndQuery}, throwing if the configured base URL is invalid. */
	private HttpUrl requireApiUrl(String pathAndQuery) throws CloudApiException
	{
		HttpUrl url = HttpUrl.parse(CloudEndpoints.apiUrl(pathAndQuery));
		if (url == null)
		{
			throw new CloudApiException(0, "invalid_base_url", "Invalid API base URL: " + CloudEndpoints.API_BASE_URL);
		}
		if (useWebApi)
		{
			HttpUrl web = HttpUrl.parse(CloudEndpoints.WEB_BASE_URL);
			url = url.newBuilder().host(web.host()).build();
		}
		return url;
	}
/** Issues a GET, enforcing the consent gate and attaching an If-None-Match header when {@code cachedVersion} is set. */
	private Response getWithOptionalEtag(String path, String cachedVersion) throws CloudApiException, IOException
	{
		requireCloudConsentAllowed();
		Request.Builder b = new Request.Builder().url(requireApiUrl(path)).get();
		if (cachedVersion != null && !cachedVersion.isBlank())
		{
			String etag = cachedVersion.trim();
			if (!etag.startsWith("\""))
			{
				etag = "\"" + etag + "\"";
			}
			b.header("If-None-Match", etag);
		}
		return executeWithFailover(b.build());
	}
/** Reads the response body as UTF-8 text, or {@code ""} if there is none. */
	private static String readBody(Response response) throws IOException
	{
		ResponseBody body = response.body();
		return body == null ? "" : new String(body.bytes(), StandardCharsets.UTF_8);
	}
/** Parses {@code text} as a JSON object; returns an empty object for blank/invalid/non-object input. */
	private static JsonObject parseObject(String text)
	{
		if (text == null || text.isEmpty())
		{
			return new JsonObject();
		}
		try
		{
			JsonElement el = new JsonParser().parse(text);
			return el.isJsonObject() ? el.getAsJsonObject() : new JsonObject();
		}
		catch (Exception e)
		{
			return new JsonObject();
		}
	}

	private static JsonObject nameAndHashBody(String displayName, long accountHash)
	{
		JsonObject body = new JsonObject();
		body.addProperty("displayName", displayName);
		body.addProperty("accountHash", Long.toString(accountHash));
		return body;
	}
}

package com.osrstcg.cloud.attest;

import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.BooleanSupplier;
/** Timer and early-flush scheduling for {@link CreditAttestQueue}. */
final class CreditAttestScheduler
{
	private final ScheduledExecutorService scheduler;
	private final AtomicBoolean running;
	private final AtomicLong lastGoodAttestAfterMs;
	private final AtomicBoolean earlyFlushScheduled;
	private final AtomicBoolean retryFlushScheduled = new AtomicBoolean(false);
	private final long defaultAttestAfterMs;
	private final Runnable flushSafeFalse;
	private final BooleanSupplier stillRunning;
	private final Object scheduleLock = new Object();
	private ScheduledFuture<?> flushFuture;
	private ScheduledFuture<?> retryFlushFuture;
/** @param flushSafeFalse invoked to run a non-teardown flush; {@code stillRunning} checked after each tick to decide whether to reschedule */
	CreditAttestScheduler(
		ScheduledExecutorService scheduler,
		AtomicBoolean running,
		AtomicLong lastGoodAttestAfterMs,
		AtomicBoolean earlyFlushScheduled,
		long defaultAttestAfterMs,
		Runnable flushSafeFalse,
		BooleanSupplier stillRunning)
	{
		this.scheduler = scheduler;
		this.running = running;
		this.lastGoodAttestAfterMs = lastGoodAttestAfterMs;
		this.earlyFlushScheduled = earlyFlushScheduled;
		this.defaultAttestAfterMs = defaultAttestAfterMs;
		this.flushSafeFalse = flushSafeFalse;
		this.stillRunning = stillRunning;
	}
/** Starts the periodic flush timer at the default interval, if not already running. Idempotent. */
	void start()
	{
		synchronized (scheduleLock)
		{
			if (running.get())
			{
				return;
			}
			running.set(true);
			lastGoodAttestAfterMs.set(defaultAttestAfterMs);
			scheduleNextLocked(lastGoodAttestAfterMs.get());
		}
	}
/** Stops the scheduler and cancels any pending periodic or retry flush. */
	void stop()
	{
		synchronized (scheduleLock)
		{
			running.set(false);
			flushFuture = cancel(flushFuture);
			retryFlushFuture = cancel(retryFlushFuture);
			retryFlushScheduled.set(false);
		}
	}
/** Runs a flush immediately on the executor, coalescing concurrent requests via {@code earlyFlushScheduled}. */
	void scheduleEarlyFlush()
	{
		if (!running.get())
		{
			return;
		}
		if (!earlyFlushScheduled.compareAndSet(false, true))
		{
			return;
		}
		scheduler.execute(() ->
		{
			try
			{
				runFlushIfActive();
			}
			finally
			{
				earlyFlushScheduled.set(false);
			}
		});
	}
/**
	 * Schedules a single flush retry after {@code delayMs}, unless the scheduler is stopped or a retry
	 * is already pending (only one retry flush may be in flight at a time).
	 */
	void scheduleRetryFlush(long delayMs)
	{
		if (!running.get())
		{
			return;
		}
		if (!retryFlushScheduled.compareAndSet(false, true))
		{
			return;
		}
		synchronized (scheduleLock)
		{
			if (!running.get())
			{
				retryFlushScheduled.set(false);
				return;
			}
			retryFlushFuture = scheduler.schedule(() ->
			{
				try
				{
					runFlushIfActive();
				}
				finally
				{
					retryFlushScheduled.set(false);
					synchronized (scheduleLock)
					{
						retryFlushFuture = null;
					}
				}
			}, Math.max(0L, delayMs), TimeUnit.MILLISECONDS);
		}
	}
/** Periodic timer callback: runs a flush, then reschedules itself using the latest attest-after interval. */
	void flushTick()
	{
		try
		{
			flushSafeFalse.run();
		}
		finally
		{
			synchronized (scheduleLock)
			{
				if (stillRunning.getAsBoolean())
				{
					scheduleNextLocked(lastGoodAttestAfterMs.get());
				}
			}
		}
	}
/** Schedules the next periodic {@link #flushTick()}; must be called while holding {@link #scheduleLock}. */
	private void scheduleNextLocked(long delayMs)
	{
		if (!running.get())
		{
			return;
		}
		flushFuture = scheduler.schedule(this::flushTick, Math.max(0L, delayMs), TimeUnit.MILLISECONDS);
	}

	private void runFlushIfActive()
	{
		if (running.get())
		{
			flushSafeFalse.run();
		}
	}

/** Cancels {@code future} if non-null; must hold {@link #scheduleLock}. Returns null for clearing the field. */
	private static ScheduledFuture<?> cancel(ScheduledFuture<?> future)
	{
		if (future != null)
		{
			future.cancel(false);
		}
		return null;
	}
}

package com.osrstcg.cloud.attest;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.osrstcg.cloud.api.CloudApiClient;
import com.osrstcg.cloud.api.CloudApiException;
import com.osrstcg.cloud.api.CloudResponseSync;
import com.osrstcg.cloud.api.JsonObjects;
import java.io.IOException;
import java.util.List;
import java.util.UUID;
import lombok.extern.slf4j.Slf4j;
/**
 * Sends one coalesced batch of credit events to the cloud attest endpoint and applies the response:
 * clears optimistic credits, requeues fixable rejects, updates sidebar economy stats, and forces a
 * refresh when server state changed. Must run on a background/flush thread, never the client thread.
 */
@Slf4j
final class CreditAttestPoster
{
	private final CreditAttestQueue queue;
	private final CloudApiClient api;
	private final AttestRejectRequeuer requeuer;

	CreditAttestPoster(CreditAttestQueue queue, CloudApiClient api, AttestRejectRequeuer requeuer)
	{
		this.queue = queue;
		this.api = api;
		this.requeuer = requeuer;
	}
/**
	 * Posts {@code batch} to the attest API, requeues any rejected-but-fixable events, clears optimistic
	 * credits for what the server accepted, and applies any economy/revision changes from the response.
	 *
	 * @return true if applying the response changed local credits or the trade revision
	 */
	boolean postAttestBatch(List<JsonObject> batch, long boundHash, String displayName) throws Exception
	{
		assertPostIdentity(boundHash, queue.liveAccountHash(), queue.session.tokensBoundTo(boundHash));
		String idempotencyKey = UUID.randomUUID().toString();
		JsonObject body = new JsonObject();
		body.addProperty("accountHash", Long.toString(boundHash));
		body.addProperty("idempotencyKey", idempotencyKey);
		if (displayName != null && !displayName.isEmpty())
		{
			body.addProperty("displayName", displayName);
		}
		JsonArray events = new JsonArray();
		long batchOptimisticEstimate = 0L;
		for (JsonObject e : batch)
		{
			batchOptimisticEstimate += CreditAttestCoalescer.optimisticOf(e);
			events.add(CreditAttestCoalescer.forWire(e));
		}
		body.add("events", events);

		queue.debugCreditAttestSend(batch, batchOptimisticEstimate);

		long creditsBefore = queue.stateService.getCredits();
		long pendingBefore = queue.stateService.getPendingOptimisticCredits();
		long revisionBefore = queue.tradeCloud.getLastRevision();

		JsonObject response = api.attest(body);
		queue.noteAttestAfterMs(response);
		AttestRejectRequeuer.RequeueResult requeueResult = requeuer.requeueRejectedEvents(response, batch);
		queue.session.noteAttestBanFlags(response);

		long clearOptimistic = CreditAttestQueue.resolveOptimisticClearAmount(
			response, batch, batchOptimisticEstimate, requeueResult);
		if (clearOptimistic > 0L)
		{
			queue.stateService.clearOptimisticCredits(clearOptimistic);
		}

		queue.debugCreditAttestResponse(response, clearOptimistic, pendingBefore);

		boolean changed = false;
		boolean appliedEconomy = false;

		if (CloudResponseSync.hasEconomyFields(response))
		{
			Double creditsNum = JsonObjects.readNumber(response, "credits");
			long serverCredits = creditsNum == null
				? queue.stateService.getAuthoritativeCredits()
				: Math.round(creditsNum);
			log.debug(
				"attest eco srv={} pend={} clr={} after={} rej={}",
				serverCredits,
				pendingBefore,
				clearOptimistic,
				queue.stateService.getPendingOptimisticCredits(),
				CreditAttestQueue.formatRejectedReasons(response));
			CloudResponseSync.applyEconomyFields(response, queue.session::applySidebarStats);
			appliedEconomy = true;
			if (queue.stateService.getCredits() != creditsBefore)
			{
				changed = true;
			}
		}
		else if (!requeueResult.reasons.isEmpty())
		{
			log.debug("attest rej no eco: {}", requeueResult.reasons);
		}

		Double revision = JsonObjects.readNumber(response, "revision");
		if (revision != null)
		{
			long rev = Math.round(revision);
			if (rev != revisionBefore)
			{
				changed = true;
			}
			queue.tradeCloud.noteRevision(rev);
		}

		long rateCapAfterMs = CreditAttestQueue.parseRateCapAfterMs(response);
		if (rateCapAfterMs > 0L)
		{
			try
			{
				queue.session.refreshCreditsFromServer(false);
				appliedEconomy = true;
				if (queue.stateService.getCredits() != creditsBefore)
				{
					changed = true;
				}
			}
			catch (Exception syncEx)
			{
				log.debug("Credits sync before rate-cap pause failed", syncEx);
			}
			queue.noteRateCapAfterMs(response);
		}
		queue.rateCapNotifier.onAttestResponse(response);

		if (appliedEconomy)
		{
			queue.notifyEconomyListener();
		}
		if (changed)
		{
			queue.tradeCloud.requestForcedRefresh();
		}
		return changed;
	}
/** Refuses posts when live identity moved or tokens are no longer bound to the drain-time account. */
	static void assertPostIdentity(long boundHash, long liveHash, boolean tokensBound) throws IOException
	{
		if (boundHash == -1L)
		{
			throw new IOException("Missing account hash for credit attest flush");
		}
		if (liveHash != -1L && liveHash != boundHash)
		{
			throw new IOException("Account changed during credit attest flush");
		}
		if (!tokensBound)
		{
			throw new IOException("Tokens not bound to credit attest account");
		}
	}
/** True for transient I/O failures, server errors (5xx), or rate limiting — worth a retry flush. */
	static boolean isRetryableAttestFailure(Throwable ex)
	{
		if (ex instanceof IOException && !(ex instanceof CloudApiException))
		{
			return true;
		}
		if (ex instanceof CloudApiException)
		{
			CloudApiException apiEx = (CloudApiException) ex;
			return apiEx.isServerError() || apiEx.isRateLimited();
		}
		return false;
	}
}

package com.osrstcg.cloud.attest;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.osrstcg.cloud.api.JsonObjects;
import java.util.ArrayList;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
/**
 * Reinterprets rejected events from an attest response and re-queues fixed-up versions of them onto
 * {@link CreditAttestQueue}. Handles {@code kill_amount_too_large} by splitting an oversized npc_kill
 * into {@link CreditAttestCoalescer#MAX_KILL_AMOUNT} chunks. Runs on the flush thread, as part of
 * {@link CreditAttestPoster#postAttestBatch}.
 */
@Slf4j
final class AttestRejectRequeuer
{
	static final String REASON_KILL_AMT_TOO_LARGE = "kill_amount_too_large";

	private final CreditAttestQueue queue;

	AttestRejectRequeuer(CreditAttestQueue queue)
	{
		this.queue = queue;
	}
/**
	 * Walks {@code response.rejected}, matching each rejection's {@code index} back to the sent
	 * {@code batch}, and re-queues a corrected event for the reasons this class knows how to fix.
	 * Any events produced are prepended to the queue's pending list and an early flush is scheduled.
	 *
	 * @return the reject reasons seen and the indexes into {@code batch} that were requeued
	 */
	AttestRejectRequeuer.RequeueResult requeueRejectedEvents(JsonObject response, List<JsonObject> batch)
	{
		RequeueResult result = new RequeueResult();
		if (response == null || !response.has("rejected") || !response.get("rejected").isJsonArray())
		{
			return result;
		}
		List<JsonObject> requeue = new ArrayList<>();
		for (JsonElement el : response.getAsJsonArray("rejected"))
		{
			if (!el.isJsonObject())
			{
				continue;
			}
			JsonObject rejected = el.getAsJsonObject();
			String reason = JsonObjects.text(rejected, "reason");
			if (reason != null)
			{
				result.reasons.add(reason);
			}
			if (!rejected.has("index") || rejected.get("index").isJsonNull())
			{
				continue;
			}
			int index = rejected.get("index").getAsInt();
			if (index < 0 || index >= batch.size())
			{
				continue;
			}
			JsonObject original = batch.get(index);
			if (original == null)
			{
				continue;
			}

			if (!REASON_KILL_AMT_TOO_LARGE.equals(reason))
			{
				continue;
			}
			if (!CreditAttestCoalescer.TYPE_NPC_KILL.equals(JsonObjects.text(original, "type")))
			{
				continue;
			}
			JsonObject evidence = JsonObjects.objectOrEmpty(original, "evidence");
			int amount = Math.max(1, (int) JsonObjects.readLong(evidence, "amount", 1L));
			if (amount <= CreditAttestCoalescer.MAX_KILL_AMOUNT)
			{
				log.warn("npc_kill rejected as {} with amount {} (≤{}); leaving to server reconcile",
					REASON_KILL_AMT_TOO_LARGE, amount, CreditAttestCoalescer.MAX_KILL_AMOUNT);
				continue;
			}
			String npcName = JsonObjects.text(evidence, "npcName");
			if (npcName == null)
			{
				npcName = "";
			}
			int combatLevel = JsonObjects.readInt(evidence, "combatLevel");
			int npcId = JsonObjects.readInt(evidence, "npcId");
			long at = JsonObjects.readLong(original, "at", System.currentTimeMillis());
			requeue.addAll(CreditAttestCoalescer.splitKillEvents(
				npcId, npcName, combatLevel, amount, at, CreditAttestCoalescer.optimisticOf(original)));
			result.requeuedIndexes.add(index);
		}
		if (!requeue.isEmpty())
		{
			queue.prependPending(requeue);
			queue.attestScheduler.scheduleEarlyFlush();
		}
		return result;
	}
/** Reasons seen and batch indexes requeued for a single {@link #requeueRejectedEvents} call. */
	static final class RequeueResult
	{
		final List<Integer> requeuedIndexes = new ArrayList<>();
		final List<String> reasons = new ArrayList<>();
	}
}

package com.osrstcg.cloud.attest;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.osrstcg.cloud.api.JsonObjects;
import com.osrstcg.util.TcgPluginGameMessages;
import java.util.Locale;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.chat.ChatMessageManager;
/**
 * Watches credit attest responses for {@code rateCapAfterMs} pauses and {@code rate_cap} rejection
 * reasons, posting a throttled player-facing chat warning. Safe to call from any thread; internal
 * state is a single atomic timestamp.
 */
@Slf4j
@Singleton
public final class AttestRateCapNotifier
{
	static final long RATE_CAP_THROTTLE_MS = 3L * 60_000L;
	static final long MINUTE_MS = 60_000L;

	private static final String RATE_CAP_PREFIX = "rate_cap";
	private static final String HOURLY_REJECT_MESSAGE =
		"Credit rate limit hit - try again later.";

	private final Consumer<String> chatSink;
	private final AtomicLong lastRateCapWarnAtMs = new AtomicLong(0L);
/** Injected constructor: routes warnings to the prefixed game chat. */
	@Inject
	AttestRateCapNotifier(ChatMessageManager chatMessageManager)
	{
		this(body -> TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager, body));
	}
/** Test/internal constructor with a pluggable chat sink; a null sink is replaced with a no-op. */
	AttestRateCapNotifier(Consumer<String> chatSink)
	{
		this.chatSink = chatSink == null ? body -> { } : chatSink;
	}
/** Clears the throttle so the next rate-cap rejection warns immediately. Called on session reset. */
	public void reset()
	{
		lastRateCapWarnAtMs.set(0L);
	}
/** Inspects an attest response for rate-cap pauses/rejections and quarantine, using the current time. */
	public void onAttestResponse(JsonObject response)
	{
		onAttestResponse(response, System.currentTimeMillis());
	}
/**
	 * Logs rate-cap pause or rejection found in {@code response} and, subject to throttling,
	 * warns the player in chat. {@code rateCapAfterMs} takes precedence over reject-reason messages.
	 * Also logs a warning if the response is marked quarantined.
	 */
	void onAttestResponse(JsonObject response, long nowMs)
	{
		if (response == null)
		{
			return;
		}

		boolean quarantined = JsonObjects.readBoolean(response, "quarantined");

		long rateCapAfterMs = CreditAttestQueue.parseRateCapAfterMs(response);
		if (rateCapAfterMs > 0L)
		{
			log.info("Credit attest rate cap pause: {}ms", rateCapAfterMs);
			maybeWarnMessage(playerFacingRateCapPauseMessage(rateCapAfterMs), nowMs);
		}
		else if (hasRateCapReject(response))
		{
			log.info("Credit attest rate cap reject");
			maybeWarnMessage(HOURLY_REJECT_MESSAGE, nowMs);
		}
		else
		{
			log.debug("Credit attest rejects (no rate_cap): {}", CreditAttestQueue.formatRejectedReasons(response));
		}

		if (quarantined)
		{
			log.warn("Credit attest response quarantined=true");
		}
	}
/** True if {@code response.rejected} contains any reason starting with {@code rate_cap}. */
	static boolean hasRateCapReject(JsonObject response)
	{
		if (response == null || !response.has("rejected") || !response.get("rejected").isJsonArray())
		{
			return false;
		}
		JsonArray rejected = response.getAsJsonArray("rejected");
		for (JsonElement el : rejected)
		{
			if (el == null || !el.isJsonObject())
			{
				continue;
			}
			String reason = JsonObjects.text(el.getAsJsonObject(), "reason");
			if (isRateCapReason(reason))
			{
				return true;
			}
		}
		return false;
	}
/** True if {@code reason}, case-insensitively, starts with the {@code rate_cap} prefix. */
	static boolean isRateCapReason(String reason)
	{
		if (reason == null || reason.isBlank())
		{
			return false;
		}
		return reason.trim().toLowerCase(Locale.ROOT).startsWith(RATE_CAP_PREFIX);
	}
	/**
	 * Builds the pause chat message for a positive {@code rateCapAfterMs}:
	 * {@code Hourly cap reached. Credit gains paused for X minutes.}
	 */
	static String playerFacingRateCapPauseMessage(long rateCapAfterMs)
	{
		long minutes = rateCapPauseMinutes(rateCapAfterMs);
		return "Hourly cap reached. Credit gains paused for " + minutes + " minutes.";
	}
/** Ceil of {@code rateCapAfterMs} in whole minutes; at least 1 when {@code rateCapAfterMs > 0}. */
	static long rateCapPauseMinutes(long rateCapAfterMs)
	{
		if (rateCapAfterMs <= 0L)
		{
			return 0L;
		}
		return Math.max(1L, (rateCapAfterMs + MINUTE_MS - 1L) / MINUTE_MS);
	}
/** Posts {@code message} unless a rate-cap warning was already sent within {@link #RATE_CAP_THROTTLE_MS}. */
	private void maybeWarnMessage(String message, long nowMs)
	{
		while (true)
		{
			long last = lastRateCapWarnAtMs.get();
			if (last > 0L && nowMs - last < RATE_CAP_THROTTLE_MS)
			{
				log.debug("Rate-cap warning throttled (last={}ms ago)", nowMs - last);
				return;
			}
			if (lastRateCapWarnAtMs.compareAndSet(last, nowMs))
			{
				chatSink.accept(message);
				return;
			}
		}
	}
}

package com.osrstcg.cloud.attest;

import com.google.gson.JsonObject;
import com.osrstcg.cloud.api.JsonObjects;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
/**
 * Stateless helper that merges raw credit-attest events (xp/level-up/npc-kill/activity) into fewer,
 * aggregated wire events, and picks which of those to send first when there are too many for one batch.
 * All methods are static and side-effect free (aside from mutating the {@code coalesced} list passed to
 * {@link #takePriorityBatch}); safe to call from any thread.
 */
public final class CreditAttestCoalescer
{
	public static final int MAX_BATCH = 100;
	public static final int MAX_KILL_AMOUNT = 500;
	public static final int EARLY_FLUSH_COALESCED = 80;
	public static final long HOUR_MS = 3_600_000L;

	public static final String TYPE_NPC_KILL = "npc_kill";
	public static final String TYPE_XP_CHUNK = "xp_chunk";
	public static final String TYPE_LEVEL_UP = "level_up";
	public static final String TYPE_ACTIVITY = "activity";

	public static final String CLIENT_OPTIMISTIC_CREDITS = "_optimisticCredits";
	/** Must match {@code version} in build.gradle / runelite-plugin.properties. Sent on hiscores settle. */
	public static final String PLUGIN_VERSION = "1.0.3";

	private static final Set<String> COMBAT_SKILLS_BLOCK_XP = Set.of(
		"ATTACK", "STRENGTH", "DEFENCE", "RANGED", "MAGIC");
	private static final String HITPOINTS_SKILL_KEY = "HITPOINTS";

	private CreditAttestCoalescer()
	{
	}
/**
	 * Aggregates raw events: xp_chunk merges by skill+hour, level_up merges by skill (widening the
	 * from/to range), npc_kill merges by npc+combat level+hour then splits back into
	 * {@link #MAX_KILL_AMOUNT}-sized chunks, and activity (and any unrecognized type) passes through
	 * unmerged. Combat-skill xp is dropped (see {@link #isCombatSkillName}), as are zero-progress events.
	 */
	public static List<JsonObject> coalesce(List<JsonObject> rawEvents)
	{
		if (rawEvents == null || rawEvents.isEmpty())
		{
			return List.of();
		}

		Map<String, XpAgg> xpBySkillHour = new LinkedHashMap<>();
		Map<String, LevelAgg> levelBySkill = new LinkedHashMap<>();
		Map<KillKey, KillAgg> kills = new LinkedHashMap<>();
		List<JsonObject> activities = new ArrayList<>();

		for (JsonObject raw : rawEvents)
		{
			if (raw == null)
			{
				continue;
			}
			String type = JsonObjects.text(raw, "type");
			if (type == null || type.isEmpty())
			{
				continue;
			}
			JsonObject evidence = JsonObjects.objectOrEmpty(raw, "evidence");
			long at = atOf(raw);
			long optimistic = optimisticOf(raw);

			switch (type)
			{
				case TYPE_XP_CHUNK:
					mergeXp(xpBySkillHour, evidence, at, optimistic);
					break;
				case TYPE_LEVEL_UP:
					mergeLevelUp(levelBySkill, evidence, at, optimistic);
					break;
				case TYPE_NPC_KILL:
					mergeKill(kills, evidence, at, optimistic);
					break;
				case TYPE_ACTIVITY:
					activities.add(copyEvent(TYPE_ACTIVITY, evidence, at, optimistic));
					break;
				default:
					activities.add(copyEvent(type, evidence, at, optimistic));
					break;
			}
		}

		List<JsonObject> out = new ArrayList<>();
		for (Map.Entry<String, LevelAgg> e : levelBySkill.entrySet())
		{
			LevelAgg agg = e.getValue();
			if (agg.toLevel > agg.fromLevel)
			{
				out.add(buildLevelUp(agg.emitSkill, agg.fromLevel, agg.toLevel, agg.lastAt, agg.optimisticCredits));
			}
		}
		for (Map.Entry<String, XpAgg> e : xpBySkillHour.entrySet())
		{
			XpAgg agg = e.getValue();
			if (agg.xpDelta > 0L)
			{
				out.add(buildXp(agg.emitSkill, agg.xpDelta, agg.lastAt, agg.optimisticCredits));
			}
		}
		for (Map.Entry<KillKey, KillAgg> e : kills.entrySet())
		{
			KillKey key = e.getKey();
			KillAgg agg = e.getValue();
			out.addAll(splitKillEvents(key.npcId, key.npcName, key.combatLevel, agg.amount, agg.lastAt, agg.optimisticCredits));
		}
		out.addAll(activities);
		return out;
	}
/**
	 * Removes up to {@code max} events from {@code coalesced} (mutating it) and returns them as a batch,
	 * highest {@link #priorityScore} first, so the most valuable credits are sent when a flush can't fit
	 * everything in one request.
	 */
	public static List<JsonObject> takePriorityBatch(List<JsonObject> coalesced, int max)
	{
		if (coalesced == null || coalesced.isEmpty() || max <= 0)
		{
			return List.of();
		}
		if (coalesced.size() <= max)
		{
			List<JsonObject> all = new ArrayList<>(coalesced);
			coalesced.clear();
			return all;
		}

		List<Scored> scored = new ArrayList<>(coalesced.size());
		for (int i = 0; i < coalesced.size(); i++)
		{
			scored.add(new Scored(i, coalesced.get(i), priorityScore(coalesced.get(i))));
		}
		scored.sort(Comparator
			.comparingLong((Scored s) -> s.score).reversed()
			.thenComparingInt(s -> s.index));

		Set<Integer> takeIdx = new HashSet<>();
		List<JsonObject> batch = new ArrayList<>(max);
		for (int i = 0; i < max && i < scored.size(); i++)
		{
			takeIdx.add(scored.get(i).index);
			batch.add(scored.get(i).event);
		}

		List<JsonObject> leftover = new ArrayList<>(coalesced.size() - batch.size());
		for (int i = 0; i < coalesced.size(); i++)
		{
			if (!takeIdx.contains(i))
			{
				leftover.add(coalesced.get(i));
			}
		}
		coalesced.clear();
		coalesced.addAll(leftover);
		return batch;
	}
/** True for the melee/ranged/magic/defence skills whose xp is never attested directly (kills are instead). */
	public static boolean isCombatSkillName(String skill)
	{
		return COMBAT_SKILLS_BLOCK_XP.contains(normalizeSkillKey(skill));
	}
/** True for "HITPOINTS" or any skill name prefixed with it (e.g. boss-specific hitpoints variants). */
	public static boolean isHitpointsSkillName(String skill)
	{
		String key = normalizeSkillKey(skill);
		return key.equals(HITPOINTS_SKILL_KEY) || key.startsWith(HITPOINTS_SKILL_KEY + " ");
	}
/**
	 * True if every event in {@code events} is a hitpoints xp_chunk. Used to hold back a batch that
	 * carries no real credit value (hitpoints xp is never awarded optimistic credits) rather than
	 * spending a flush cycle on it.
	 */
	public static boolean isHitpointsXpOnly(List<JsonObject> events)
	{
		if (events == null || events.isEmpty())
		{
			return false;
		}
		for (JsonObject event : events)
		{
			if (event == null || !TYPE_XP_CHUNK.equals(JsonObjects.text(event, "type")))
			{
				return false;
			}
			String skill = textOrEmpty(JsonObjects.objectOrEmpty(event, "evidence"), "skill");
			if (!isHitpointsSkillName(skill))
			{
				return false;
			}
		}
		return true;
	}
/** Trims and upper-cases a skill name for use as a stable grouping/comparison key; null becomes "". */
	public static String normalizeSkillKey(String skill)
	{
		if (skill == null)
		{
			return "";
		}
		return skill.trim().toUpperCase(Locale.ROOT);
	}

	private static String textOrEmpty(JsonObject o, String key)
	{
		String value = JsonObjects.text(o, key);
		return value == null ? "" : value;
	}
/** Floors an epoch-millis timestamp to its hour bucket, clamping negative input to 0. */
	public static long epochHour(long atMs)
	{
		long t = atMs;
		if (t < 0L)
		{
			t = 0L;
		}
		return t / HOUR_MS;
	}
/** Adds one xp_chunk's delta into its skill+hour bucket; skips combat skills and non-positive deltas. */
	private static void mergeXp(Map<String, XpAgg> xpBySkillHour, JsonObject evidence, long at, long optimistic)
	{
		String skill = textOrEmpty(evidence, "skill");
		if (isCombatSkillName(skill))
		{
			return;
		}
		long xpDelta = JsonObjects.readLong(evidence, "xpDelta");
		if (xpDelta <= 0L)
		{
			return;
		}
		String skillKey = normalizeSkillKey(skill);
		if (skillKey.isEmpty())
		{
			return;
		}
		String key = skillKey + ":" + epochHour(at);
		XpAgg agg = xpBySkillHour.get(key);
		if (agg == null)
		{
			agg = new XpAgg();
			agg.emitSkill = skill.trim();
			xpBySkillHour.put(key, agg);
		}
		agg.xpDelta += xpDelta;
		agg.optimisticCredits += Math.max(0L, optimistic);
		agg.lastAt = Math.max(agg.lastAt, at);
	}
/** Widens a skill's level-up bucket to cover [min fromLevel, max toLevel]; skips non-progressing entries. */
	private static void mergeLevelUp(Map<String, LevelAgg> levelBySkill, JsonObject evidence, long at, long optimistic)
	{
		String skill = textOrEmpty(evidence, "skill");
		int fromLevel = JsonObjects.readInt(evidence, "fromLevel");
		int toLevel = JsonObjects.readInt(evidence, "toLevel");
		if (toLevel <= fromLevel)
		{
			return;
		}
		String key = normalizeSkillKey(skill);
		if (key.isEmpty())
		{
			return;
		}
		LevelAgg agg = levelBySkill.get(key);
		if (agg == null)
		{
			agg = new LevelAgg();
			agg.emitSkill = skill.trim();
			agg.fromLevel = fromLevel;
			agg.toLevel = toLevel;
			agg.lastAt = at;
			agg.optimisticCredits = Math.max(0L, optimistic);
			levelBySkill.put(key, agg);
			return;
		}
		if (fromLevel < agg.fromLevel)
		{
			agg.fromLevel = fromLevel;
		}
		if (toLevel > agg.toLevel)
		{
			agg.toLevel = toLevel;
		}
		agg.optimisticCredits += Math.max(0L, optimistic);
		agg.lastAt = Math.max(agg.lastAt, at);
	}
/** Adds one npc_kill's amount into its npc+combat-level+hour bucket. */
	private static void mergeKill(Map<KillKey, KillAgg> kills, JsonObject evidence, long at, long optimistic)
	{
		String npcName = textOrEmpty(evidence, "npcName");
		int combatLevel = JsonObjects.readInt(evidence, "combatLevel");
		int npcId = JsonObjects.readInt(evidence, "npcId");
		int amount = Math.max(1, (int) JsonObjects.readLong(evidence, "amount", 1L));
		KillKey key = new KillKey(npcId, npcName, combatLevel, epochHour(at));
		KillAgg agg = kills.get(key);
		if (agg == null)
		{
			agg = new KillAgg();
			kills.put(key, agg);
		}
		agg.amount += amount;
		agg.optimisticCredits += Math.max(0L, optimistic);
		agg.lastAt = Math.max(agg.lastAt, at);
	}
/** Ranks events for {@link #takePriorityBatch}: level_up highest, then xp_chunk, npc_kill, activity. */
	private static long priorityScore(JsonObject event)
	{
		String type = JsonObjects.text(event, "type");
		JsonObject evidence = JsonObjects.objectOrEmpty(event, "evidence");
		if (TYPE_LEVEL_UP.equals(type))
		{
			int span = Math.max(0, JsonObjects.readInt(evidence, "toLevel") - JsonObjects.readInt(evidence, "fromLevel"));
			return 1_000_000_000L + span * 1_000L;
		}
		if (TYPE_XP_CHUNK.equals(type))
		{
			return 500_000_000L + Math.min(JsonObjects.readLong(evidence, "xpDelta"), 400_000_000L);
		}
		if (TYPE_NPC_KILL.equals(type))
		{
			return 250_000_000L + Math.min((int) JsonObjects.readLong(evidence, "amount", 1L), 200_000_000);
		}
		if (TYPE_ACTIVITY.equals(type))
		{
			return 100_000_000L;
		}
		return 1_000L;
	}
/** Builds a wire-shaped xp_chunk event from aggregated values. */
	private static JsonObject buildXp(String skill, long xpDelta, long at, long optimisticCredits)
	{
		JsonObject evidence = new JsonObject();
		evidence.addProperty("skill", skill == null ? "" : skill);
		evidence.addProperty("xpDelta", xpDelta);
		return copyEvent(TYPE_XP_CHUNK, evidence, at, optimisticCredits);
	}
/** Builds a wire-shaped level_up event from aggregated values. */
	private static JsonObject buildLevelUp(String skill, int fromLevel, int toLevel, long at, long optimisticCredits)
	{
		JsonObject evidence = new JsonObject();
		evidence.addProperty("skill", skill == null ? "" : skill);
		evidence.addProperty("fromLevel", fromLevel);
		evidence.addProperty("toLevel", toLevel);
		return copyEvent(TYPE_LEVEL_UP, evidence, at, optimisticCredits);
	}
/** Builds a wire-shaped npc_kill event from aggregated values; omits npcId/npcName when unset. */
	private static JsonObject buildKill(int npcId, String npcName, int combatLevel, int amount, long at, long optimisticCredits)
	{
		JsonObject evidence = new JsonObject();
		if (npcId > 0)
		{
			evidence.addProperty("npcId", npcId);
		}
		if (npcName != null && !npcName.isEmpty())
		{
			evidence.addProperty("npcName", npcName);
		}
		evidence.addProperty("combatLevel", combatLevel);
		evidence.addProperty("amount", amount);
		return copyEvent(TYPE_NPC_KILL, evidence, at, optimisticCredits);
	}

	/** Splits an npc_kill with {@code amount} into {@link #MAX_KILL_AMOUNT}-sized wire events. */
	static List<JsonObject> splitKillEvents(
		int npcId, String npcName, int combatLevel, int amount, long at, long optimisticTotal)
	{
		List<JsonObject> out = new ArrayList<>();
		int remaining = amount;
		long optimisticRemaining = optimisticTotal;
		while (remaining > 0)
		{
			int chunk = Math.min(MAX_KILL_AMOUNT, remaining);
			long chunkOptimistic = remaining <= chunk
				? optimisticRemaining
				: (amount <= 0 ? 0L : (optimisticTotal * chunk) / amount);
			chunkOptimistic = Math.min(chunkOptimistic, optimisticRemaining);
			out.add(buildKill(npcId, npcName, combatLevel, chunk, at, chunkOptimistic));
			optimisticRemaining -= chunkOptimistic;
			remaining -= chunk;
		}
		return out;
	}

/** Assembles a {type, evidence, at, [optimisticCredits]} event, deep-copying the evidence object. */
	static JsonObject copyEvent(String type, JsonObject evidence, long at, long optimisticCredits)
	{
		JsonObject event = new JsonObject();
		event.addProperty("type", type);
		event.add("evidence", evidence == null ? new JsonObject() : evidence.deepCopy());
		event.addProperty("at", at);
		if (optimisticCredits > 0L)
		{
			event.addProperty(CLIENT_OPTIMISTIC_CREDITS, optimisticCredits);
		}
		return event;
	}
/** Reads the client-side optimistic credit estimate stashed on an event, or 0 if absent/invalid. */
	public static long optimisticOf(JsonObject event)
	{
		return Math.max(0L, JsonObjects.readLong(event, CLIENT_OPTIMISTIC_CREDITS));
	}
/** Returns a copy of {@code event} with the client-only optimistic-credits field stripped for sending. */
	public static JsonObject forWire(JsonObject event)
	{
		if (event == null)
		{
			return new JsonObject();
		}
		JsonObject copy = event.deepCopy();
		copy.remove(CLIENT_OPTIMISTIC_CREDITS);
		return copy;
	}
/** Reads an event's {@code at} timestamp, defaulting to now if missing/null. */
	private static long atOf(JsonObject event)
	{
		return JsonObjects.readLong(event, "at", System.currentTimeMillis());
	}
/** Running total for one skill+hour xp_chunk bucket. */
	private static final class XpAgg
	{
		private String emitSkill;
		private long xpDelta;
		private long lastAt;
		private long optimisticCredits;
	}
/** Widening from/to level range for one skill's level_up bucket. */
	private static final class LevelAgg
	{
		private String emitSkill;
		private int fromLevel;
		private int toLevel;
		private long lastAt;
		private long optimisticCredits;
	}
/** Running total for one npc+combat-level+hour npc_kill bucket. */
	private static final class KillAgg
	{
		private int amount;
		private long lastAt;
		private long optimisticCredits;
	}
/** Grouping key for npc_kill aggregation: npc identity, combat level, and hour bucket. */
	private static final class KillKey
	{
		private final int npcId;
		private final String npcName;
		private final int combatLevel;
		private final long epochHour;

		private KillKey(int npcId, String npcName, int combatLevel, long epochHour)
		{
			this.npcId = Math.max(0, npcId);
			this.npcName = npcName == null ? "" : npcName;
			this.combatLevel = combatLevel;
			this.epochHour = epochHour;
		}
/** {@inheritDoc} */
		@Override
		public boolean equals(Object o)
		{
			if (this == o)
			{
				return true;
			}
			if (!(o instanceof KillKey))
			{
				return false;
			}
			KillKey that = (KillKey) o;
			return npcId == that.npcId
				&& combatLevel == that.combatLevel
				&& epochHour == that.epochHour
				&& Objects.equals(npcName, that.npcName);
		}
/** {@inheritDoc} */
		@Override
		public int hashCode()
		{
			return Objects.hash(npcId, npcName, combatLevel, epochHour);
		}
	}
/** An event paired with its index in the source list and its {@link #priorityScore}, for sorting. */
	private static final class Scored
	{
		private final int index;
		private final JsonObject event;
		private final long score;

		private Scored(int index, JsonObject event, long score)
		{
			this.index = index;
			this.event = event;
			this.score = score;
		}
	}
}

package com.osrstcg.cloud.attest;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.osrstcg.state.TcgStateService;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.chat.ChatMessageManager;
import com.osrstcg.cloud.api.CloudApiClient;
import com.osrstcg.cloud.api.CloudApiException;
import com.osrstcg.cloud.api.JsonObjects;
import com.osrstcg.cloud.session.CachedDisplayName;
import com.osrstcg.cloud.session.CloudSessionService;
import com.osrstcg.cloud.trade.TradeCloudService;
import com.osrstcg.util.TcgPluginGameMessages;
/**
 * In-memory queue of raw credit-earning events (xp, level-ups, npc kills, activities) awaiting
 * attestation to the cloud. Buffers events as they occur, coalesces and prioritizes them at flush
 * time via {@link CreditAttestCoalescer}, posts batches through {@link CreditAttestPoster}, and
 * requeues fixable rejects via {@link AttestRejectRequeuer}. {@link #enqueue} is called from the client
 * thread as gameplay events happen; flushes run on the injected {@link ScheduledExecutorService}, guarded
 * by internal locks, so callers never need external synchronization.
 */
@Slf4j
@Singleton
public final class CreditAttestQueue
{
	private static final long DEFAULT_ATTEST_AFTER_MS = 60_000L;
	private static final long LARGE_XP_SPIKE_DELTA = 50_000L;
	private static final int ATTEST_RETRY_ATTEMPTS = 3;
	private static final long ATTEST_RETRY_BACKOFF_MS = 10_000L;
	final CloudSessionService session;
	final TradeCloudService tradeCloud;
	final TcgStateService stateService;
	private final Client client;
	private final ChatMessageManager chatMessageManager;
	private final ScheduledExecutorService scheduler;
	final AttestRateCapNotifier rateCapNotifier;

	private final Object lock = new Object();
	private final Object flushGate = new Object();
	private final List<JsonObject> pendingRaw = new ArrayList<>();
	private final AtomicReference<Runnable> economyListener = new AtomicReference<>(null);
	private final AtomicBoolean earlyFlushScheduled = new AtomicBoolean(false);
	private final AtomicBoolean running = new AtomicBoolean(false);
	private final AtomicLong lastGoodAttestAfterMs = new AtomicLong(DEFAULT_ATTEST_AFTER_MS);
/** Wall-clock deadline while credit gains are frozen by rateCapAfterMs; 0 means not frozen. */
	private final AtomicLong rateCapUntilMs = new AtomicLong(0L);
	private final AtomicInteger consecutiveRetryFailures = new AtomicInteger(0);
	private final AttestRejectRequeuer rejectRequeuer;
	private final CreditAttestPoster poster;
	final CreditAttestScheduler attestScheduler;
	private volatile long lastAccountHash = -1L;
	private final CachedDisplayName displayName = new CachedDisplayName();
/** Injected constructor; wires up the sub-scheduler with a flush callback and initial default interval. */
	@Inject
	CreditAttestQueue(
		CloudApiClient api,
		CloudSessionService session,
		TradeCloudService tradeCloud,
		TcgStateService stateService,
		Client client,
		ChatMessageManager chatMessageManager,
		ScheduledExecutorService scheduler,
		AttestRateCapNotifier rateCapNotifier)
	{
		this.session = session;
		this.tradeCloud = tradeCloud;
		this.stateService = stateService;
		this.client = client;
		this.chatMessageManager = chatMessageManager;
		this.scheduler = scheduler;
		this.rateCapNotifier = rateCapNotifier;
		this.rejectRequeuer = new AttestRejectRequeuer(this);
		this.poster = new CreditAttestPoster(this, api, rejectRequeuer);
		this.attestScheduler = new CreditAttestScheduler(
			scheduler, running, lastGoodAttestAfterMs, earlyFlushScheduled, DEFAULT_ATTEST_AFTER_MS,
			() -> flushSafe(false), running::get);
	}
/** Registers a callback invoked whenever attest processing changes credits/pending totals; replaces any prior listener. */
	public void setEconomyListener(Runnable listener)
	{
		economyListener.set(listener);
	}
/** Starts periodic flushing. */
	public void start()
	{
		attestScheduler.start();
	}
/** Stops periodic flushing and resets retry/rate-cap state for the next session. */
	public void stop()
	{
		stop(true);
	}
/**
	 * Stops periodic flushing and resets retry state.
	 *
	 * @param clearRateCap false when pausing for a restricted world so the server rate-cap deadline is kept
	 */
	public void stop(boolean clearRateCap)
	{
		attestScheduler.stop();
		if (clearRateCap)
		{
			rateCapUntilMs.set(0L);
		}
		consecutiveRetryFailures.set(0);
		rateCapNotifier.reset();
	}
/** True while server {@code rateCapAfterMs} is freezing optimistic credit gains. */
	public boolean isRateCapActive()
	{
		return isRateCapActive(System.currentTimeMillis());
	}
/** True when {@code nowMs} is before the rate-cap freeze deadline. */
	boolean isRateCapActive(long nowMs)
	{
		long until = rateCapUntilMs.get();
		return until > 0L && nowMs < until;
	}
/** Clamps a server-provided attest interval to at least {@link #DEFAULT_ATTEST_AFTER_MS}, falling back when unset. */
	private static long resolveAttestAfterMs(long ms, long fallbackMs)
	{
		if (ms <= 0L)
		{
			long fb = fallbackMs > 0L ? fallbackMs : DEFAULT_ATTEST_AFTER_MS;
			return Math.max(DEFAULT_ATTEST_AFTER_MS, fb);
		}
		return ms;
	}
/** Updates the periodic flush interval from the server's {@code attestAfterMs}/{@code pollAfterMs} hint, if present. */
	void noteAttestAfterMs(JsonObject response)
	{
		long fallback = lastGoodAttestAfterMs.get();
		Double parsed = JsonObjects.readNumber(response, "attestAfterMs", "pollAfterMs");
		long ms = parsed == null ? 0L : Math.round(parsed);
		lastGoodAttestAfterMs.set(resolveAttestAfterMs(ms, fallback));
	}
/**
	 * Freezes optimistic credit gains when {@code response} includes a positive {@code rateCapAfterMs}:
	 * clears remaining optimistic credits while attests keep collecting and flushing. Call after a
	 * skip-flush credits sync. No-op when the field is omitted or {@code <= 0}.
	 */
	void noteRateCapAfterMs(JsonObject response)
	{
		long ms = parseRateCapAfterMs(response);
		if (ms <= 0L)
		{
			return;
		}
		long now = System.currentTimeMillis();
		rateCapUntilMs.set(now + ms);
		stateService.clearOptimisticCredits();
		notifyEconomyListener();
		log.info("Credit attest rate-cap freeze for {}ms (until={})", ms, rateCapUntilMs.get());
	}
/** Reads {@code rateCapAfterMs} from an attest response, or 0 when absent/invalid. */
	static long parseRateCapAfterMs(JsonObject response)
	{
		return Math.max(0L, JsonObjects.readLong(response, "rateCapAfterMs"));
	}
/** Optimistic credits for a new enqueue; 0 while rate-cap freezes credit gains. */
	static long enqueueOptimisticCredits(long optimisticCredits, boolean rateCapActive)
	{
		return rateCapActive ? 0L : optimisticCredits;
	}
/** Drops all in-memory pending events without flushing. */
	public void discardPending()
	{
		synchronized (lock)
		{
			pendingRaw.clear();
		}
	}
/** Forgets last-known account hash, pending events, and cached display name after logout flush. */
	public void clearAccountIdentity()
	{
		synchronized (lock)
		{
			pendingRaw.clear();
			lastAccountHash = -1L;
		}
		displayName.clear();
	}
/** Live Jagex account hash from the client ({@code -1} when logged out). */
	long liveAccountHash()
	{
		return client.getAccountHash();
	}
/**
	 * Records one raw credit-earning event for later attestation. Filters out combat-skill xp and
	 * non-progressing level-ups, applies the optimistic credit estimate to local state immediately,
	 * and triggers an early flush on a coalesced-count or xp-spike threshold. No-op if the session
	 * can't currently collect attests. Expected to run on the client thread.
	 */
	public boolean enqueue(String type, JsonObject evidence, long optimisticCredits)
	{
		if (!session.canCollectAttests())
		{
			return false;
		}
		optimisticCredits = enqueueOptimisticCredits(optimisticCredits, isRateCapActive());
		resolveDisplayName();
		String skill = "";
		long xpDelta = 0L;
		if (CreditAttestCoalescer.TYPE_XP_CHUNK.equals(type))
		{
			String skillText = JsonObjects.text(evidence, "skill");
			skill = skillText == null ? "" : skillText;
			if (CreditAttestCoalescer.isCombatSkillName(skill))
			{
				return false;
			}
			xpDelta = JsonObjects.readLong(evidence, "xpDelta");
			if (xpDelta <= 0L)
			{
				return false;
			}
			if (CreditAttestCoalescer.isHitpointsSkillName(skill))
			{
				optimisticCredits = 0L;
			}
		}
		if (CreditAttestCoalescer.TYPE_LEVEL_UP.equals(type))
		{
			int fromLevel = JsonObjects.readInt(evidence, "fromLevel");
			int toLevel = JsonObjects.readInt(evidence, "toLevel");
			if (toLevel <= fromLevel)
			{
				return false;
			}
		}

		JsonObject event = CreditAttestCoalescer.copyEvent(type, evidence, System.currentTimeMillis(), optimisticCredits);

		boolean spikeFlush = false;
		synchronized (lock)
		{
			if (resolveAccountHashLocked() == -1L)
			{
				return false;
			}
			pendingRaw.add(event);
			int coalescedEstimate = CreditAttestCoalescer.coalesce(pendingRaw).size();
			if (coalescedEstimate >= CreditAttestCoalescer.EARLY_FLUSH_COALESCED)
			{
				spikeFlush = true;
			}
			else if (CreditAttestCoalescer.TYPE_XP_CHUNK.equals(type)
				&& !CreditAttestCoalescer.isHitpointsSkillName(skill)
				&& xpDelta >= LARGE_XP_SPIKE_DELTA)
			{
				spikeFlush = true;
			}
		}
		applyOptimistic(optimisticCredits);
		if (spikeFlush)
		{
			attestScheduler.scheduleEarlyFlush();
		}
		return true;
	}
/** Schedules an immediate, non-blocking flush on the executor. */
	public void flushNow()
	{
		scheduler.execute(() -> flushSafe(false));
	}
/**
	 * Runs a teardown flush synchronously on the calling thread (used on shutdown/logout). Must not be
	 * called from the client thread.
	 *
	 * @return true if the flush changed local credits or the trade revision
	 */
	public boolean flushBlocking()
	{
		return flushSafe(true);
	}
/**
	 * Reads the current account hash from the client, caching it. On account change, clears in-memory
	 * pending events for the previous account.
	 */
	long resolveAccountHash()
	{
		synchronized (lock)
		{
			return resolveAccountHashLocked();
		}
	}
/** Same as {@link #resolveAccountHash()} but caller already holds {@link #lock}. */
	private long resolveAccountHashLocked()
	{
		long hash = client.getAccountHash();
		if (hash != -1L)
		{
			if (lastAccountHash != -1L && lastAccountHash != hash)
			{
				pendingRaw.clear();
			}
			lastAccountHash = hash;
			return hash;
		}
		return lastAccountHash;
	}
/** Reads and sanitizes the local player's RSN, caching the last known value for use when unavailable. */
	String resolveDisplayName()
	{
		return displayName.resolve(client);
	}
/** Adds an optimistic credit estimate to local state and notifies the economy listener, if positive. */
	private void applyOptimistic(long optimisticCredits)
	{
		if (optimisticCredits > 0)
		{
			stateService.addOptimisticCredits(optimisticCredits);
			notifyEconomyListener();
		}
	}
/**
	 * On a retryable failure (and not during teardown), schedules a backing-off retry flush up to
	 * {@link #ATTEST_RETRY_ATTEMPTS} times; otherwise resets the failure counter.
	 */
	private void maybeScheduleRetryFlush(boolean teardown, Exception ex)
	{
		if (teardown || !CreditAttestPoster.isRetryableAttestFailure(ex))
		{
			consecutiveRetryFailures.set(0);
			return;
		}
		int attempt = consecutiveRetryFailures.incrementAndGet();
		if (attempt >= ATTEST_RETRY_ATTEMPTS)
		{
			log.debug("Credit attest retry exhausted after {} failure(s)", attempt);
			return;
		}
		long delayMs = ATTEST_RETRY_BACKOFF_MS * attempt;
		log.debug("Credit attest scheduling retry {}/{} in {}ms after {}",
			attempt, ATTEST_RETRY_ATTEMPTS, delayMs, ex.toString());
		attestScheduler.scheduleRetryFlush(delayMs);
	}
/** Inserts events at the front of the pending list, so they're the next candidates for flushing. */
	void prependPending(List<JsonObject> events)
	{
		synchronized (lock)
		{
			pendingRaw.addAll(0, events);
		}
	}
/** Runs {@link #flush} and swallows/logs any exception so scheduler callbacks never throw. */
	private boolean flushSafe(boolean teardown)
	{
		try
		{
			return flush(teardown);
		}
		catch (CloudApiException e)
		{
			log.warn("Credit attest flush failed: {} {}", e.getCode(), e.getMessage());
			return false;
		}
		catch (Exception e)
		{
			log.warn("Credit attest flush failed", e);
			return false;
		}
	}
/**
	 * Drains and posts all pending events, one coalesced+prioritized batch at a time, until the pending
	 * list is empty. Serialized via {@link #flushGate} so only one flush runs at a time. A batch that's
	 * only hitpoints xp is held back rather than sent (except on teardown). On a post failure, the batch
	 * (and any remaining coalesced events) are put back on the front of the pending list and the
	 * exception propagates.
	 *
	 * @param teardown true for a shutdown flush, which uses a looser readiness check than a normal flush
	 * @return true if any posted batch changed local credits or the trade revision
	 */
	private boolean flush(boolean teardown) throws Exception
	{
		if (teardown)
		{
			if (!session.canAttestFlush())
			{
				return false;
			}
		}
		else if (!session.isReady())
		{
			return false;
		}
		synchronized (flushGate)
		{
			boolean changed = false;
			while (true)
			{
				List<JsonObject> raw;
				long boundHash;
				String displayNameSnapshot;
				synchronized (lock)
				{
					if (pendingRaw.isEmpty())
					{
						break;
					}
					boundHash = resolveAccountHashLocked();
					if (boundHash == -1L)
					{
						pendingRaw.clear();
						break;
					}
					displayNameSnapshot = displayName.resolve(client);
					raw = new ArrayList<>(pendingRaw);
					pendingRaw.clear();
				}

				int rawCount = raw.size();
				List<JsonObject> coalesced = new ArrayList<>(CreditAttestCoalescer.coalesce(raw));
				log.debug("Credit attest coalesce: raw={} → coalesced={}", rawCount, coalesced.size());

				if (coalesced.isEmpty())
				{
					continue;
				}

				if (!teardown && CreditAttestCoalescer.isHitpointsXpOnly(coalesced))
				{
					prependPending(coalesced);
					break;
				}

				while (!coalesced.isEmpty())
				{
					List<JsonObject> batch = CreditAttestCoalescer.takePriorityBatch(
						coalesced, CreditAttestCoalescer.MAX_BATCH);
					if (batch.isEmpty())
					{
						break;
					}
					if (!teardown && CreditAttestCoalescer.isHitpointsXpOnly(batch))
					{
						prependPending(coalesced);
						prependPending(batch);
						coalesced.clear();
						break;
					}
					long started = System.currentTimeMillis();
					try
					{
						boolean batchChanged = poster.postAttestBatch(batch, boundHash, displayNameSnapshot);
						consecutiveRetryFailures.set(0);
						changed |= batchChanged;
						log.debug("Credit attest OK: events={} durationMs={}",
							batch.size(), System.currentTimeMillis() - started);
					}
					catch (Exception ex)
					{
						prependPending(coalesced);
						prependPending(batch);
						maybeScheduleRetryFlush(teardown, ex);
						throw ex;
					}
				}
			}
			return changed;
		}
	}
/**
	 * Determines how many optimistic credits to clear after a batch is posted: prefers the server's
	 * accepted-credits sum when present, otherwise falls back to the batch's optimistic estimate minus
	 * whatever was held back for requeued (not yet resolved) events.
	 */
	static long resolveOptimisticClearAmount(
		JsonObject response,
		List<JsonObject> batch,
		long batchOptimisticEstimate,
		AttestRejectRequeuer.RequeueResult requeueResult)
	{
		long acceptedSum = sumAcceptedCredits(response);
		if (acceptedSum >= 0L)
		{
			return acceptedSum;
		}
		long holdBack = 0L;
		if (requeueResult != null)
		{
			for (int index : requeueResult.requeuedIndexes)
			{
				if (index >= 0 && index < batch.size())
				{
					holdBack += CreditAttestCoalescer.optimisticOf(batch.get(index));
				}
			}
		}
		return Math.max(0L, batchOptimisticEstimate - holdBack);
	}
/** Sums the credit amounts of {@code response.accepted}, or -1 if the field is absent/malformed. */
	private static long sumAcceptedCredits(JsonObject response)
	{
		if (response == null || !response.has("accepted") || !response.get("accepted").isJsonArray())
		{
			return -1L;
		}
		JsonArray accepted = response.getAsJsonArray("accepted");
		if (accepted.size() == 0)
		{
			return 0L;
		}
		long sum = 0L;
		boolean sawAmount = false;
		for (JsonElement el : accepted)
		{
			if (el == null || !el.isJsonObject())
			{
				continue;
			}
			JsonObject row = el.getAsJsonObject();
			Double amount = JsonObjects.readNumber(row, "credits", "amount", "awarded", "creditDelta");
			if (amount != null)
			{
				sawAmount = true;
				sum += Math.max(0L, Math.round(amount));
			}
		}
		return sawAmount ? sum : -1L;
	}
/** Posts a debug-chat summary of an outgoing attest batch, if debug chat is on. */
	void debugCreditAttestSend(List<JsonObject> batch, long optimisticEstimate)
	{
		if (!stateService.isDebugChatEnabled() || batch == null || batch.isEmpty())
		{
			return;
		}
		String message = "send " + batch.size();
		if (optimisticEstimate > 0L)
		{
			message += " (+" + optimisticEstimate + ")";
		}
		TcgPluginGameMessages.queueDebugGameMessage(chatMessageManager, message);
	}
/** Posts a debug-chat summary of an attest response, if debug chat is on. */
	void debugCreditAttestResponse(JsonObject response, long clearOptimistic, long pendingBefore)
	{
		if (!stateService.isDebugChatEnabled() || response == null)
		{
			return;
		}
		StringBuilder message = new StringBuilder("attest");
		if (response.has("credits") && !response.get("credits").isJsonNull())
		{
			message.append(" cr=").append(response.get("credits").getAsLong());
		}
		if (clearOptimistic > 0L)
		{
			message.append(" clr=").append(clearOptimistic);
		}
		long pendingAfter = stateService.getPendingOptimisticCredits();
		if (pendingBefore != pendingAfter)
		{
			message.append(" pend ").append(pendingBefore).append("->").append(pendingAfter);
		}
		String rejected = formatRejectedReasons(response);
		if (rejected != null && !"[]".equals(rejected))
		{
			message.append(" rej=").append(rejected);
		}
		TcgPluginGameMessages.queueDebugGameMessage(chatMessageManager, message.toString());
	}
/** Formats {@code response.rejected} reasons as a bracketed, comma-separated list for logging/chat. */
	static String formatRejectedReasons(JsonObject response)
	{
		if (response == null || !response.has("rejected") || !response.get("rejected").isJsonArray())
		{
			return "[]";
		}
		StringBuilder sb = new StringBuilder("[");
		boolean first = true;
		for (JsonElement el : response.getAsJsonArray("rejected"))
		{
			if (!el.isJsonObject())
			{
				continue;
			}
			String reason = JsonObjects.text(el.getAsJsonObject(), "reason");
			if (reason == null)
			{
				continue;
			}
			if (!first)
			{
				sb.append(',');
			}
			first = false;
			sb.append(reason);
		}
		sb.append(']');
		return sb.toString();
	}
/** Invokes the registered economy listener, if any. */
	void notifyEconomyListener()
	{
		Runnable listener = economyListener.get();
		if (listener != null)
		{
			listener.run();
		}
	}
}

package com.osrstcg.cloud.session;

import com.osrstcg.state.OwnedCardInstance;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import com.osrstcg.cloud.api.CloudApiClient;
import com.osrstcg.cloud.api.JsonObjects;
/**
 * Fetches the full owned-card collection from {@code /me/cards} in pages when the player state
 * response indicates cards are paginated, and retries the whole state pull once if the server
 * revision drifts mid-paging. Blocking: every method here issues synchronous HTTP calls via
 * {@link CloudApiClient} and must be called off the client/EDT thread.
 */
@Slf4j
final class CloudCollectionPager
{
	static final int ME_CARDS_PAGE_LIMIT = 500;
	static final int ME_CARDS_MAX_PAGES = 200;

	private final CloudApiClient api;
/** Wires the API client; no side effects. */
	CloudCollectionPager(CloudApiClient api)
	{
		this.api = api;
	}
/**
	 * Parses {@code stateJson} and, if cards are paginated, fetches all pages from {@code /me/cards}.
	 * On a revision drift mid-paging, re-fetches the full state once and pages again against the new revision.
	 */
	CloudPlayerStateParser.ParsedCloudPlayerState loadCloudPlayerStateWithCards(JsonObject stateJson)
		throws Exception
	{
		CloudPlayerStateParser.ParsedCloudPlayerState parsed = CloudPlayerStateParser.parse(stateJson);
		try
		{
			return resolveCardsForState(parsed);
		}
		catch (IOException ex)
		{
			String msg = ex.getMessage();
			if (msg == null || !msg.startsWith("me/cards revision drift"))
			{
				throw ex;
			}
			log.info("me/cards revision changed during paging; retry pull");
			return resolveCardsForState(CloudPlayerStateParser.parse(api.getState()));
		}
	}
/** Returns {@code parsed} unchanged if cards aren't paginated, otherwise fills in cards fetched by page. */
	CloudPlayerStateParser.ParsedCloudPlayerState resolveCardsForState(
		CloudPlayerStateParser.ParsedCloudPlayerState parsed) throws Exception
	{
		if (parsed == null || !parsed.cardsPaged)
		{
			return parsed;
		}
		List<OwnedCardInstance> cards = fetchAllOwnedCards(parsed.revision);
		return parsed.withCards(cards);
	}
/**
	 * Pages through {@code /me/cards} until {@code hasMore} is false, verifying each page reports
	 * {@code expectedRevision}. Throws if a page's revision doesn't match (caller should retry from
	 * fresh state), if paging exceeds {@link #ME_CARDS_MAX_PAGES}, or if a page claims more results
	 * without a cursor.
	 */
	List<OwnedCardInstance> fetchAllOwnedCards(long expectedRevision) throws Exception
	{
		List<OwnedCardInstance> all = new ArrayList<>();
		String cursor = null;
		boolean hasMore = true;
		int pages = 0;
		while (hasMore)
		{
			if (++pages > ME_CARDS_MAX_PAGES)
			{
				throw new IOException("me/cards pagination exceeded " + ME_CARDS_MAX_PAGES + " pages");
			}
			JsonObject page = api.getCardsPage(ME_CARDS_PAGE_LIMIT, cursor);
			Double pageRevNum = JsonObjects.readNumber(page, "revision");
			long pageRevision = pageRevNum == null ? expectedRevision : Math.max(0L, Math.round(pageRevNum));
			if (pageRevision != expectedRevision)
			{
				throw new IOException("me/cards revision drift (" + pageRevision + " vs " + expectedRevision + ")");
			}
			all.addAll(CloudPlayerStateParser.parseCards(page.get("cards")));
			hasMore = JsonObjects.readBoolean(page, "hasMore");
			if (hasMore)
			{
				cursor = JsonObjects.textTrimmed(page, "nextCursor");
				if (cursor == null)
				{
					throw new IOException("me/cards hasMore without nextCursor");
				}
			}
		}
		return all;
	}
}

package com.osrstcg.cloud.session;

import com.osrstcg.util.TcgPluginGameMessages;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.chat.ChatMessageManager;
import com.osrstcg.cloud.activity.ActivityConfigService;
import com.osrstcg.cloud.api.CloudApiClient;
import com.osrstcg.cloud.api.CloudApiException;
import com.osrstcg.cloud.api.CloudConnectionState;
import com.osrstcg.cloud.catalog.CardCatalogService;
import com.osrstcg.cloud.catalog.PackCatalogService;
import com.osrstcg.state.TcgStateService;
import com.osrstcg.state.CollectionState;
/**
 * Handles the one-time cloud profile creation/consent flow: pairing or refreshing a session,
 * marking the profile migrated, and adopting an already-migrated server collection when local
 * progress exists but this profile hasn't consented yet. Blocking: methods issue synchronous HTTP
 * calls and must not run on the client/EDT thread.
 */
@Slf4j
final class CloudProfileConsentService
{
	private final CloudSessionService session;
	private final CloudCollectionSyncService collectionSync;
	private final Client client;
	private final CloudApiClient api;
	private final CloudTokenStore tokens;
	private final ProfileKeyHasher profileKeyHasher;
	private final TcgStateService stateService;
	private final ChatMessageManager chatMessageManager;
	private final PackCatalogService packCatalogService;
	private final CardCatalogService cardCatalogService;
	private final ActivityConfigService activityConfigService;
/** Wires collaborators; no side effects. */
	CloudProfileConsentService(
		CloudSessionService session,
		CloudCollectionSyncService collectionSync,
		Client client,
		CloudApiClient api,
		CloudTokenStore tokens,
		ProfileKeyHasher profileKeyHasher,
		TcgStateService stateService,
		ChatMessageManager chatMessageManager,
		PackCatalogService packCatalogService,
		CardCatalogService cardCatalogService,
		ActivityConfigService activityConfigService)
	{
		this.session = session;
		this.collectionSync = collectionSync;
		this.client = client;
		this.api = api;
		this.tokens = tokens;
		this.profileKeyHasher = profileKeyHasher;
		this.stateService = stateService;
		this.chatMessageManager = chatMessageManager;
		this.packCatalogService = packCatalogService;
		this.cardCatalogService = cardCatalogService;
		this.activityConfigService = activityConfigService;
	}
/**
	 * Creates (or completes consent for) the cloud profile for the current RuneScape account: requires
	 * being logged in with a known account hash, display name, and RuneLite profile key. Runs the
	 * pairing/migration flow inside {@link CloudApiClient#openConsentTraffic()} so consent-gated
	 * traffic is permitted for its duration.
	 */
	void createProfile() throws Exception
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			throw new IllegalStateException("Log in to RuneScape first");
		}
		long accountHash = client.getAccountHash();
		if (accountHash == -1L)
		{
			throw new IllegalStateException("Waiting for account");
		}
		String displayName = session.resolveDisplayName();
		if (displayName == null)
		{
			throw new IllegalStateException("Waiting for display name");
		}
		String profileHash = profileKeyHasher.currentProfileKeyHash();
		if (profileHash == null)
		{
			throw new IllegalStateException("No RuneLite profile key");
		}

		try (AutoCloseable ignored = api.openConsentTraffic())
		{
			createProfileAllowed(accountHash, displayName, profileHash);
		}
	}
/**
	 * Ensures a session is active (refreshing or pairing as needed), adopts an already-migrated
	 * server collection if applicable, then marks the profile migrated and finishes consent if it
	 * wasn't already.
	 */
	private void createProfileAllowed(
		long accountHash,
		String displayName,
		String profileHash) throws Exception
	{
		if (!session.isSessionActive())
		{
			session.setState(CloudConnectionState.CONNECTING, "Connecting…");
			api.getHealth();
			if (CloudTokenStore.shouldClearForAccount(tokens.getBoundAccountHash(), tokens.hasRefreshToken(), accountHash))
			{
				tokens.clear();
			}
			if (tokens.hasRefreshToken())
			{
				try
				{
					api.applyTokenResponse(api.refresh(tokens.getRefreshToken(), profileHash), accountHash);
				}
				catch (CloudApiException refreshEx)
				{
					if (!refreshEx.isStaleRefreshToken())
					{
						throw refreshEx;
					}
					log.info("Clearing stale cloud credentials during create profile ({})", refreshEx.getCode());
					tokens.clear();
				}
			}
			if (!tokens.hasRefreshToken())
			{
				session.pairSession(displayName, profileHash, accountHash);
			}
			adoptServerMigrationIfNeeded();
			session.setState(CloudConnectionState.CONNECTED,
				tokens.isMigrated() ? "Connected" : "Create a profile");
		}

		if (tokens.isMigrated())
		{
			finishConsentSuccess();
			return;
		}

		tokens.setMigrated(true);
		TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
			"Created cloud profile.");
		finishConsentSuccess();
	}
/**
	 * Post-consent bring-up: refreshes local cache from cloud, settles offline hiscores, marks the
	 * session connected, clears obsolete local caches, and refreshes pack/card catalogs and activity
	 * config. Bails out early if the account becomes locked (banned/quarantined) partway through.
	 */
	void finishConsentSuccess() throws Exception
	{
		collectionSync.refreshLocalCacheFromCloud();

		if (session.isAccountLocked())
		{
			return;
		}
		session.settleHiscoresIfCooldownDone();
		if (session.isAccountLocked())
		{
			return;
		}
		session.setState(CloudConnectionState.CONNECTED, "Connected");
		session.deleteObsoleteLocalCaches();
		packCatalogService.refreshOnLogin();
		cardCatalogService.refreshNow();
		activityConfigService.refreshOnLogin();
	}
/**
	 * If this profile hasn't recorded migration locally but has local progress (credits/packs/cards)
	 * and has an access token, checks the server state: if the server shows the account already
	 * migrated (has a migration timestamp or cards), adopts that server collection/economy locally
	 * and marks migrated, skipping the consent prompt. No-op otherwise.
	 */
	void adoptServerMigrationIfNeeded() throws Exception
	{
		if (tokens.isMigrated() || tokens.getAccessToken() == null)
		{
			return;
		}
		if (!session.hasLocalProgress())
		{
			return;
		}

		JsonObject stateJson = api.getState();
		CloudPlayerStateParser.ParsedCloudPlayerState parsed =
			collectionSync.loadCloudPlayerStateWithCards(stateJson);
		boolean serverMigrated = (parsed.migratedAt != null && !parsed.migratedAt.isBlank())
			|| !parsed.cards.isEmpty();
		if (!serverMigrated)
		{
			return;
		}

		log.info("Cloud already migrated; adopting server collection");
		tokens.setMigrated(true);
		if (parsed.accountStatus != null && !parsed.accountStatus.isBlank())
		{
			session.applyAccountStatus(parsed.accountStatus);
		}
		stateService.replaceCloudGroupKey(parsed.groupKey);
		stateService.replaceFromCloudState(
			CollectionState.copyOf(parsed.cards),
			parsed.economy,
			parsed.totalCreditsGained,
			parsed.revision,
			parsed.stateHash,
			parsed.collectionHash,
			parsed.sidebarStats);
		session.deleteObsoleteLocalCaches();
		cardCatalogService.refreshNow();
	}
}

package com.osrstcg.cloud.session;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.osrstcg.util.AtomicFiles;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Comparator;
import java.util.Objects;
import java.util.stream.Stream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
/**
 * Per-account cloud session file ({@code cloud-session.json}) under the account-hash profile folder.
 * Blocking I/O — call off the client thread when possible.
 */
@Slf4j
@Singleton
public final class CloudSessionFileStore
{
	static final String SESSION_FILENAME = "cloud-session.json";
	private static final int SCHEMA_VERSION = 1;

	private final Path profilesRoot;
	private final Gson gson;

	@Inject
	CloudSessionFileStore(Gson gson)
	{
		this(ProfileKeyHasher.profilesRoot(), gson);
	}

	CloudSessionFileStore(Path profilesRoot, Gson gson)
	{
		this.profilesRoot = profilesRoot;
		this.gson = Objects.requireNonNull(gson, "gson");
	}
/** Session file path for an account, or {@code null} if the account hash is unset. */
	Path sessionFile(long accountHash)
	{
		Path dir = accountDir(accountHash);
		return dir == null ? null : dir.resolve(SESSION_FILENAME);
	}
/** Profile directory for an account, or {@code null} if unset. */
	Path accountDir(long accountHash)
	{
		String id = ProfileKeyHasher.accountDirName(accountHash);
		return id == null ? null : profilesRoot.resolve(id);
	}
/** Loads the session for {@code accountHash}, or {@code null} if missing/invalid. */
	public SessionData load(long accountHash)
	{
		Path file = sessionFile(accountHash);
		if (file == null || !Files.isRegularFile(file))
		{
			return null;
		}
		try
		{
			String json = Files.readString(file, StandardCharsets.UTF_8);
			if (json == null || json.isBlank())
			{
				return null;
			}
			SessionData data = gson.fromJson(json, SessionData.class);
			if (data == null || blank(data.accessToken) || blank(data.refreshToken))
			{
				return null;
			}
			return data;
		}
		catch (IOException | JsonSyntaxException ex)
		{
			log.warn("Failed reading cloud session {}", file, ex);
			return null;
		}
	}
/** Atomically writes the session file for {@code accountHash}. No-op if tokens or hash are invalid. */
	public void save(long accountHash, SessionData data)
	{
		if (accountHash == -1L || data == null || blank(data.accessToken) || blank(data.refreshToken))
		{
			return;
		}
		Path file = sessionFile(accountHash);
		if (file == null)
		{
			return;
		}
		SessionData out = new SessionData();
		out.schemaVersion = SCHEMA_VERSION;
		out.accessToken = data.accessToken;
		out.refreshToken = data.refreshToken;
		out.accountId = blank(data.accountId) ? null : data.accountId;
		out.status = blank(data.status) ? null : data.status;
		out.boundAccountHash = accountHash;
		try
		{
			AtomicFiles.writeString(file, gson.toJson(out), StandardCharsets.UTF_8);
		}
		catch (IOException ex)
		{
			log.warn("Failed writing cloud session for accountHash={}", ProfileKeyHasher.accountDirName(accountHash), ex);
		}
	}
/** Deletes the session file for an account. Failures are logged and swallowed. */
	public void delete(long accountHash)
	{
		Path file = sessionFile(accountHash);
		if (file == null)
		{
			return;
		}
		try
		{
			Files.deleteIfExists(file);
		}
		catch (IOException ex)
		{
			log.debug("Failed deleting cloud session for accountHash={}", ProfileKeyHasher.accountDirName(accountHash), ex);
		}
	}
/**
	 * Deletes the entire per-account profile directory (save, session, leftovers).
	 * Failures are logged and swallowed.
	 */
	public void deleteAccountDir(long accountHash)
	{
		Path dir = accountDir(accountHash);
		if (dir == null || !Files.isDirectory(dir))
		{
			return;
		}
		try (Stream<Path> walk = Files.walk(dir))
		{
			walk.sorted(Comparator.reverseOrder()).forEach(path ->
			{
				try
				{
					Files.deleteIfExists(path);
				}
				catch (IOException ex)
				{
					log.debug("Failed deleting {}", path, ex);
				}
			});
		}
		catch (IOException ex)
		{
			log.warn("Failed wiping profile dir accountHash={}", ProfileKeyHasher.accountDirName(accountHash), ex);
		}
	}

	private static boolean blank(String value)
	{
		return value == null || value.isBlank();
	}
/** JSON shape for {@value #SESSION_FILENAME}. */
	public static final class SessionData
	{
		public int schemaVersion;
		public String accessToken;
		public String refreshToken;
		public String accountId;
		public String status;
		public long boundAccountHash = -1L;
	}
}

package com.osrstcg.cloud.session;

import com.osrstcg.state.CloudSidebarCollectionStats;
import com.osrstcg.state.CollectionState;
import com.osrstcg.state.TcgState;
import com.osrstcg.interop.TcgPublicStatsCalculator;
import com.osrstcg.state.TcgStateService;
import com.google.gson.JsonObject;
import javax.inject.Provider;
import lombok.extern.slf4j.Slf4j;
import com.osrstcg.cloud.api.CloudApiClient;
import com.osrstcg.cloud.api.JsonObjects;
import com.osrstcg.cloud.attest.CreditAttestQueue;
/**
 * Pulls cloud economy/collection state and reconciles it into local {@link TcgStateService}.
 * Compares local vs server revisions and collection hashes to decide whether a full {@code /me/cards}
 * pull is needed. Blocking: the {@code refresh*}/{@code reconcile*} methods issue synchronous HTTP
 * calls and must not run on the client/EDT thread.
 */
@Slf4j
final class CloudCollectionSyncService
{
	private final CloudSessionService session;
	private final CloudApiClient api;
	private final CloudTokenStore tokens;
	private final TcgStateService stateService;
	private final Provider<CreditAttestQueue> attestQueueProvider;
	private final TcgPublicStatsCalculator publicStatsCalculator;
	private final CloudCollectionPager pager;
/** Wires collaborators; no side effects. */
	CloudCollectionSyncService(
		CloudSessionService session,
		CloudApiClient api,
		CloudTokenStore tokens,
		TcgStateService stateService,
		Provider<CreditAttestQueue> attestQueueProvider,
		TcgPublicStatsCalculator publicStatsCalculator,
		CloudCollectionPager pager)
	{
		this.session = session;
		this.api = api;
		this.tokens = tokens;
		this.stateService = stateService;
		this.attestQueueProvider = attestQueueProvider;
		this.publicStatsCalculator = publicStatsCalculator;
		this.pager = pager;
	}
/**
	 * Updates cached economy (credits/opened packs/total gained) and collection sidebar stats from a
	 * {@code stats}-shaped response, and applies any account status it carries. No-op if {@code stats}
	 * is null.
	 */
	void applySidebarStats(JsonObject stats)
	{
		if (stats == null)
		{
			return;
		}
		boolean hasEconomy = stats.has("credits") || stats.has("openedPacks") || stats.has("totalCreditsGained");
		if (hasEconomy)
		{
			Double creditsNum = JsonObjects.readNumber(stats, "credits");
			long credits = creditsNum == null
				? stateService.getAuthoritativeCredits()
				: Math.round(creditsNum);
			Double openedNum = JsonObjects.readNumber(stats, "openedPacks");
			int openedPacks = openedNum == null
				? (int) stateService.getState().getEconomyState().getOpenedPacks()
				: (int) Math.round(openedNum);
			Double gainedNum = JsonObjects.readNumber(stats, "totalCreditsGained");
			long totalGained = gainedNum == null
				? stateService.getState().getTotalCreditsGained()
				: Math.round(gainedNum);
			stateService.replaceCloudEconomyCache(credits, openedPacks, totalGained);
		}
		if (CloudSidebarCollectionStats.hasCollectionFields(stats))
		{
			stateService.replaceCollectionStatsCache(CloudSidebarCollectionStats.fromStatsJson(stats));
		}
		String status = JsonObjects.text(stats, "status");
		if (status != null)
		{
			session.applyAccountStatus(status);
		}
	}
/**
	 * Reacts to a push/inbox stats update: logs (does not itself resolve) a mismatch between server
	 * and locally-computed sidebar counts, then delegates to {@link #reconcileCollectionWithCloud}
	 * to pull a fresh collection if needed. No-op while cloud consent is pending, or if {@code stats}
	 * is null. Reconcile failures are swallowed and logged at debug level.
	 */
	void reconcileCollectionFromInbox(JsonObject stats)
	{
		if (stats == null || session.needsCloudConsent())
		{
			return;
		}
		try
		{
			CloudPlayerStateParser.SyncMarkers serverMarkers = CloudPlayerStateParser.readSyncMarkers(stats);
			long localRevision = stateService.getState().getCloudRevision();
			if (CloudSidebarCollectionStats.hasCollectionFields(stats))
			{
				CloudSidebarCollectionStats server = CloudSidebarCollectionStats.fromStatsJson(stats);
				CloudSidebarCollectionStats local = publicStatsCalculator.computeLocalSidebarStats();
				if (!CloudSidebarCollectionStats.countsAgree(server, local))
				{
					String localCollHash = stateService.getCloudCollectionHash();
					String serverCollHash = serverMarkers.collectionHash;
					boolean collectionChanged =
						(!serverCollHash.isEmpty() && !serverCollHash.equalsIgnoreCase(localCollHash))
						|| (serverCollHash.isEmpty() && localRevision < serverMarkers.revision);
					if (collectionChanged)
					{
						log.info("coll mismatch srv={} loc={} - pull",
							server.getUniqueOwned(), local.getUniqueOwned());
					}
					else
					{
						log.debug("coll mismatch hash ok srv={} loc={} - skip pull",
							server.getUniqueOwned(), local.getUniqueOwned());
					}
				}
			}
			reconcileCollectionWithCloud(stats);
		}
		catch (Exception e)
		{
			log.debug("Collection reconcile from inbox failed", e);
		}
	}
/**
	 * Flushes any pending credit attests, then re-fetches and applies server stats, clearing the
	 * local optimistic credit adjustment. No-op if there's no access token, consent is pending, or
	 * the account is locked.
	 */
	void refreshCreditsFromServer() throws Exception
	{
		refreshCreditsFromServer(true);
	}
/**
	 * Re-fetches and applies server stats ({@code GET /me/stats}), clearing local optimistic credits.
	 * When {@code flushFirst} is true, flushes pending attests first. Use {@code flushFirst=false}
	 * when already inside an attest flush (avoids re-entering the flush gate).
	 */
	void refreshCreditsFromServer(boolean flushFirst) throws Exception
	{
		if (tokens.getAccessToken() == null || session.needsCloudConsent() || session.isAccountLocked())
		{
			return;
		}
		if (flushFirst)
		{
			try
			{
				attestQueueProvider.get().flushBlocking();
			}
			catch (Exception ex)
			{
				log.debug("Attest flush before credit refresh failed", ex);
			}
		}
		JsonObject stats = api.getStats();
		applySidebarStats(stats);
		stateService.clearOptimisticCredits();
	}
/** Fetches server stats, applies them, and reconciles the local collection against the cloud copy. */
	void refreshLocalCacheFromCloud() throws Exception
	{
		JsonObject stats = api.getStats();
		applySidebarStats(stats);
		reconcileCollectionWithCloud(stats);
	}
/**
	 * Compares local sync markers against {@code stats} and, if the collection hash differs (or the
	 * legacy revision is behind with no hash to compare), pulls the full player state and cards from
	 * {@code /me/state} via {@link CloudCollectionPager} and replaces local collection/economy state.
	 * If unchanged but the revision/hash advanced, only updates the local sync markers. No-op while
	 * cloud consent is pending.
	 */
	void reconcileCollectionWithCloud(JsonObject stats) throws Exception
	{
		if (session.needsCloudConsent())
		{
			return;
		}

		CloudPlayerStateParser.SyncMarkers server = CloudPlayerStateParser.readSyncMarkers(stats);
		TcgState local = stateService.getState();
		long localRevision = local.getCloudRevision();
		String localHash = local.getCloudStateHash();
		String localCollHash = stateService.getCloudCollectionHash();
		String serverCollHash = server.collectionHash;
		boolean collectionChanged = (!serverCollHash.isEmpty() && !serverCollHash.equalsIgnoreCase(localCollHash))
			|| (serverCollHash.isEmpty() && server.revision > localRevision);

		if (!collectionChanged)
		{
			if (server.revision > localRevision
				|| (!server.stateHash.isEmpty() && !server.stateHash.equalsIgnoreCase(localHash)))
			{
				stateService.applyCloudSyncMarkers(server.revision, server.stateHash);
			}
			return;
		}

		String reason = (serverCollHash.isEmpty() && server.revision > localRevision) ? "rev behind"
			: "coll hash mismatch";
		log.info("coll sync ({}; loc={} srv={})",
			reason, localCollHash, serverCollHash);

		JsonObject stateJson = api.getState();
		CloudPlayerStateParser.ParsedCloudPlayerState parsed = pager.loadCloudPlayerStateWithCards(stateJson);
		if (!parsed.migrated)
		{
			if (!tokens.isMigrated())
			{
				log.info("not migrated yet; skip coll pull");
				return;
			}
		}
		else
		{
			tokens.setMigrated(true);
		}
		stateService.replaceCloudGroupKey(parsed.groupKey);
		stateService.replaceFromCloudState(
			CollectionState.copyOf(parsed.cards),
			parsed.economy,
			parsed.totalCreditsGained,
			parsed.revision,
			parsed.stateHash,
			parsed.collectionHash,
			parsed.sidebarStats);
		if (parsed.accountStatus != null && !parsed.accountStatus.isBlank())
		{
			session.applyAccountStatus(parsed.accountStatus);
		}
		log.info("synced coll rev={} cards={} migrated={}",
			parsed.revision, parsed.cards.size(), parsed.migrated);
	}
/** Delegates to {@link CloudCollectionPager#loadCloudPlayerStateWithCards}. */
	CloudPlayerStateParser.ParsedCloudPlayerState loadCloudPlayerStateWithCards(JsonObject stateJson) throws Exception
	{
		return pager.loadCloudPlayerStateWithCards(stateJson);
	}
}

package com.osrstcg.cloud.session;

import java.util.EnumSet;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.WorldType;
/**
 * Detects world types (PvP arena, Deadman, seasonal, etc.) where cloud credits/attests must be
 * disabled, and describes which blocked types are active on the current world.
 */
@Singleton
public final class RestrictedWorldGuard
{
	private static final Set<WorldType> BLOCKED = EnumSet.of(
		WorldType.PVP_ARENA,
		WorldType.DEADMAN,
		WorldType.SEASONAL,
		WorldType.TOURNAMENT_WORLD,
		WorldType.QUEST_SPEEDRUNNING,
		WorldType.NOSAVE_MODE,
		WorldType.BETA_WORLD);

	public static final String STATUS_MESSAGE = "Credits disabled on this world type";

	private final Client client;

	@Inject
	RestrictedWorldGuard(Client client)
	{
		this.client = client;
	}
/** Whether the current world (per the client) has a blocked world type. */
	public boolean isRestricted()
	{
		return isRestricted(client == null ? null : client.getWorldType());
	}
/** Whether any of {@code types} is a blocked world type. */
	public static boolean isRestricted(EnumSet<WorldType> types)
	{
		if (types == null || types.isEmpty())
		{
			return false;
		}
		for (WorldType blocked : BLOCKED)
		{
			if (types.contains(blocked))
			{
				return true;
			}
		}
		return false;
	}
/** Comma-joined names of the blocked world types present on the current world, or {@code ""} if none. */
	public String describeBlockedTypes()
	{
		EnumSet<WorldType> types = client == null ? null : client.getWorldType();
		if (types == null || types.isEmpty())
		{
			return "";
		}
		return types.stream()
			.filter(BLOCKED::contains)
			.map(Enum::name)
			.collect(Collectors.joining(", "));
	}
}

package com.osrstcg.cloud.session;

import com.osrstcg.persist.TcgStateHash;
import com.osrstcg.util.NumberFormatting;
import com.osrstcg.util.TcgPluginGameMessages;
import com.google.gson.JsonObject;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.chat.ChatMessageManager;
import com.osrstcg.cloud.api.CloudApiClient;
import com.osrstcg.cloud.api.CloudApiException;
import com.osrstcg.cloud.api.CloudResponseSync;
import com.osrstcg.cloud.api.JsonObjects;
import com.osrstcg.cloud.trade.TradeCloudService;
import javax.inject.Provider;
/**
 * Settles offline hiscores gains into cloud credits once per login. Never called on logout —
 * {@link #clearGate()} cancels any pending retry so a delayed settle cannot fire after disconnect.
 * Handles transient {@code hiscores_unavailable} failures with a single delayed retry. Blocking:
 * methods issue synchronous HTTP calls via {@link CloudApiClient} and must not run on the
 * client/EDT thread, except the scheduled retry body which runs on {@link #scheduler}.
 */
@Slf4j
final class HiscoresSettleService
{
	private static final long HISCORES_RETRY_DELAY_SEC = 70L;
	private final CachedDisplayName cachedDisplayName = new CachedDisplayName();
	private final Client client;
	private final CloudApiClient api;
	private final CloudTokenStore tokens;
	private final RestrictedWorldGuard restrictedWorldGuard;
	private final ScheduledExecutorService scheduler;
	private final ChatMessageManager chatMessageManager;
	private final Provider<TradeCloudService> tradeCloudProvider;
	private final Consumer<JsonObject> applySidebarStats;
	private final AtomicBoolean hiscoresSettledThisLogin;
	private final AtomicBoolean hiscoresRetryScheduled;
	private final BooleanSupplier needsCloudConsent;
	private final BooleanSupplier isAccountLocked;
	private final BooleanSupplier debugChatEnabled;
/** Bumped by {@link #clearGate()} so in-flight/scheduled retries become no-ops after logout. */
	private final AtomicLong settleEpoch = new AtomicLong(0L);
	private final Object retryLock = new Object();
	private ScheduledFuture<?> retryFuture;
/** Wires collaborators and the shared login/retry flags owned by {@link CloudSessionService}. */
	HiscoresSettleService(
		Client client,
		CloudApiClient api,
		CloudTokenStore tokens,
		RestrictedWorldGuard restrictedWorldGuard,
		ScheduledExecutorService scheduler,
		ChatMessageManager chatMessageManager,
		Provider<TradeCloudService> tradeCloudProvider,
		Consumer<JsonObject> applySidebarStats,
		AtomicBoolean hiscoresSettledThisLogin,
		AtomicBoolean hiscoresRetryScheduled,
		BooleanSupplier needsCloudConsent,
		BooleanSupplier isAccountLocked,
		BooleanSupplier debugChatEnabled)
	{
		this.client = client;
		this.api = api;
		this.tokens = tokens;
		this.restrictedWorldGuard = restrictedWorldGuard;
		this.scheduler = scheduler;
		this.chatMessageManager = chatMessageManager;
		this.tradeCloudProvider = tradeCloudProvider;
		this.applySidebarStats = applySidebarStats;
		this.hiscoresSettledThisLogin = hiscoresSettledThisLogin;
		this.hiscoresRetryScheduled = hiscoresRetryScheduled;
		this.needsCloudConsent = needsCloudConsent;
		this.isAccountLocked = isAccountLocked;
		this.debugChatEnabled = debugChatEnabled;
	}
/**
	 * Settles offline hiscores gains into credits, once per login (guarded by
	 * {@link #hiscoresSettledThisLogin}). No-op when not logged into RuneScape (never on logout).
	 * On error, delegates to {@link #handleSettleError}.
	 */
	void settleAfterCloudLogin()
	{
		long epoch = settleEpoch.get();
		if (hiscoresSettledThisLogin.get() || !canSettleNow())
		{
			return;
		}
		long accountHash = client.getAccountHash();
		if (accountHash == -1L)
		{
			return;
		}
		String displayName = cachedDisplayName.resolve(client);
		if (displayName == null)
		{
			return;
		}

		try
		{
			if (!stillValid(epoch) || !canSettleNow())
			{
				return;
			}
			chatAccountHashPrefix(accountHash);
			JsonObject response = api.settleHiscores(displayName, accountHash);
			if (!stillValid(epoch))
			{
				return;
			}
			handleSettleResponse(response, accountHash, displayName, false);
		}
		catch (CloudApiException ex)
		{
			if (!stillValid(epoch))
			{
				return;
			}
			handleSettleError(ex, accountHash, displayName);
		}
		catch (Exception ex)
		{
			log.warn("Hiscores settle failed", ex);
		}
	}
/**
	 * Invalidates settle for this session: bumps the epoch, cancels any pending retry, and resets
	 * once-per-login flags. Called on logout/disconnect/lock so settle cannot fire afterward.
	 */
	void clearGate()
	{
		settleEpoch.incrementAndGet();
		hiscoresSettledThisLogin.set(false);
		hiscoresRetryScheduled.set(false);
		cancelRetry();
	}
/** Drops cached RSN used for settle/retry after logout flush. */
	void clearCachedDisplayName()
	{
		cachedDisplayName.clear();
	}
/** True only while logged into RuneScape with tokens/consent/world gates open. */
	private boolean canSettleNow()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}
		if (tokens.getAccessToken() == null || needsCloudConsent.getAsBoolean() || isAccountLocked.getAsBoolean())
		{
			return false;
		}
		return !restrictedWorldGuard.isRestricted();
	}

	private boolean stillValid(long epoch)
	{
		return settleEpoch.get() == epoch;
	}
/**
	 * Applies sidebar credits from a settle response. Soft-skip {@code settle_throttle}
	 * refreshes credits but does not consume the once-per-login gate — a single delayed retry is
	 * scheduled so the cooldown can clear. Other successes (including {@code hiscores_stale}) mark
	 * settled.
	 */
	private void handleSettleResponse(
		JsonObject response,
		long accountHash,
		String displayName,
		boolean isRetry)
	{
		applySettleResponse(response);
		if (response == null)
		{
			hiscoresSettledThisLogin.set(true);
			return;
		}

		boolean skipped = JsonObjects.readBoolean(response, "skipped");
		String reason = JsonObjects.text(response, "reason");
		if (reason == null)
		{
			reason = "";
		}

		if (!isRetry && skipped && "settle_throttle".equals(reason))
		{
			log.info("Hiscores settle soft-skip ({}); retry in {}s", reason, HISCORES_RETRY_DELAY_SEC);
			scheduleRetry(accountHash, displayName, HISCORES_RETRY_DELAY_SEC);
			return;
		}

		hiscoresSettledThisLogin.set(true);
	}
/**
	 * Classifies a settle failure: "not found"/forbidden/locked codes are treated as terminal for
	 * this login (marks settled, no retry); {@code hiscores_unavailable}/503 schedules one retry;
	 * anything else is just logged.
	 */
	private void handleSettleError(CloudApiException ex, long accountHash, String displayName)
	{
		String code = ex.getCode() == null ? "" : ex.getCode();
		int status = ex.getStatus();
		if ("hiscores_not_found".equals(code) || status == 404)
		{
			hiscoresSettledThisLogin.set(true);
			log.info("Hiscores settle skipped: not on hiscores ({})", ex.getMessage());
			return;
		}
		if ("sandbox_forbidden".equals(code)
			|| "quarantined".equals(code)
			|| "banned".equals(code)
			|| "account_banned".equals(code)
			|| "not_trade_eligible".equals(code)
			|| status == 403)
		{
			hiscoresSettledThisLogin.set(true);
			log.info("Hiscores settle forbidden ({}): {}", code, ex.getMessage());
			return;
		}
		if ("hiscores_unavailable".equals(code) || status == 503)
		{
			log.warn("Hiscores settle unavailable; one retry: {}", ex.getMessage());
			scheduleRetry(accountHash, displayName, HISCORES_RETRY_DELAY_SEC);
			return;
		}
		log.warn("Hiscores settle failed: {} {}", code, ex.getMessage());
	}
/**
	 * Schedules a single delayed settle retry (guarded by {@link #hiscoresRetryScheduled} so only one
	 * retry is ever pending). The retry re-checks preconditions and the settle epoch before calling
	 * settle again; {@link #clearGate()} cancels it on logout.
	 */
	private void scheduleRetry(long accountHash, String displayName, long delaySec)
	{
		if (!hiscoresRetryScheduled.compareAndSet(false, true))
		{
			return;
		}
		long epoch = settleEpoch.get();
		ScheduledFuture<?> future = scheduler.schedule(() ->
		{
			try
			{
				if (!stillValid(epoch)
					|| hiscoresSettledThisLogin.get()
					|| !canSettleNow()
					|| client.getAccountHash() != accountHash)
				{
					return;
				}
				String retryName = cachedDisplayName.resolve(client);
				if (retryName == null)
				{
					retryName = displayName;
				}
				if (retryName == null || !stillValid(epoch) || !canSettleNow())
				{
					return;
				}
				chatAccountHashPrefix(accountHash);
				JsonObject response = api.settleHiscores(retryName, accountHash);
				if (!stillValid(epoch))
				{
					return;
				}
				handleSettleResponse(response, accountHash, retryName, true);
			}
			catch (CloudApiException ex)
			{
				if (!stillValid(epoch))
				{
					return;
				}
				hiscoresSettledThisLogin.set(true);
				log.warn("Hiscores settle retry failed: {} {}", ex.getCode(), ex.getMessage());
			}
			catch (Exception ex)
			{
				if (!stillValid(epoch))
				{
					return;
				}
				hiscoresSettledThisLogin.set(true);
				log.warn("Hiscores settle retry failed", ex);
			}
			finally
			{
				synchronized (retryLock)
				{
					retryFuture = null;
				}
			}
		}, delaySec, TimeUnit.SECONDS);
		synchronized (retryLock)
		{
			retryFuture = future;
		}
	}

	private void cancelRetry()
	{
		ScheduledFuture<?> future;
		synchronized (retryLock)
		{
			future = retryFuture;
			retryFuture = null;
		}
		if (future != null)
		{
			future.cancel(false);
		}
	}
/**
	 * Applies a settle response's sidebar credits/revision. Posts a chat toast when hiscores credits
	 * were accepted or clawed back.
	 */
	private void applySettleResponse(JsonObject response)
	{
		if (response == null)
		{
			return;
		}

		boolean skipped = JsonObjects.readBoolean(response, "skipped");
		boolean hasCredits = response.has("credits") && !response.get("credits").isJsonNull();

		if (skipped && !hasCredits)
		{
			return;
		}

		CloudResponseSync.applyEconomyAndRevision(response, applySidebarStats, tradeCloudProvider.get());

		long accepted = JsonObjects.readLong(response, "accepted", 0L);
		if (accepted > 0L)
		{
			String toast = "Credited " + NumberFormatting.format(accepted) + " credits from hiscores!";
			TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager, toast);
		}

		long clawback = JsonObjects.readLong(response, "clawbackCredits", 0L);
		if (clawback > 0L)
		{
			String toast = "Removed " + NumberFormatting.format(clawback)
				+ " credits due to hiscores mismatch.";
			TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager, toast);
		}
	}

	private void chatAccountHashPrefix(long accountHash)
	{
		if (!debugChatEnabled.getAsBoolean())
		{
			return;
		}
		String digest = TcgStateHash.hexOfUtf8(Long.toString(accountHash));
		String prefix = digest.length() <= 5 ? digest : digest.substring(0, 5);
		TcgPluginGameMessages.queueDebugGameMessage(chatMessageManager,
			"acct " + prefix);
	}
}

package com.osrstcg.cloud.session;

