package com.osrstcg.cloud.session;

import com.osrstcg.cloud.api.CloudConnectionState;
import com.osrstcg.cloud.attest.CreditAttestQueue;
import com.osrstcg.cloud.trade.TradeCloudService;
import com.osrstcg.ui.SidebarRefresh;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.WorldChanged;
/**
 * Wires {@link CloudSessionService} connection lifecycle to RuneLite client events: connects on
 * login/world change, disconnects on logout, and schedules randomized-delay reconnect attempts
 * while cloud is reachable-but-not-ready. Starts/stops the credit attest queue and trade sync
 * alongside session readiness, and pauses all cloud traffic on restricted world types. Connection
 * attempts run on the injected {@link ScheduledExecutorService}; UI refresh callbacks are marshalled
 * onto the EDT via {@link SwingUtilities#invokeLater}.
 */
@Slf4j
@Singleton
public class CloudSessionCoordinator
{
	private static final long CLOUD_RECONNECT_MIN_MS = 5L * 60L * 1000L;
	private static final long CLOUD_RECONNECT_MAX_MS = 15L * 60L * 1000L;

	private final Client client;
	private final CloudSessionService cloudSessionService;
	private final CreditAttestQueue creditAttestQueue;
	private final TradeCloudService tradeCloudService;
	private final SidebarRefresh sidebarRefresh;
	private final ScheduledExecutorService scheduler;

	private final AtomicBoolean cloudConnectInFlight = new AtomicBoolean(false);
	private final AtomicBoolean clientShuttingDown = new AtomicBoolean(false);
	private final AtomicLong sessionEpoch = new AtomicLong(0L);
	private final Object cloudReconnectLock = new Object();
	private ScheduledFuture<?> cloudReconnectFuture;
	private GameState lastObservedGameState;
/** Wires collaborators; no side effects. */
	@Inject
	public CloudSessionCoordinator(
		Client client,
		CloudSessionService cloudSessionService,
		CreditAttestQueue creditAttestQueue,
		TradeCloudService tradeCloudService,
		SidebarRefresh sidebarRefresh,
		ScheduledExecutorService scheduler)
	{
		this.client = client;
		this.cloudSessionService = cloudSessionService;
		this.creditAttestQueue = creditAttestQueue;
		this.tradeCloudService = tradeCloudService;
		this.sidebarRefresh = sidebarRefresh;
		this.scheduler = scheduler;
	}
/**
	 * Registers a listener on {@link CloudSessionService} that starts/stops the attest queue and
	 * trade sync in response to readiness changes, manages reconnect scheduling, and refreshes the
	 * sidebar on every status change.
	 */
	public void installStatusListener()
	{
		cloudSessionService.setStatusListener(() ->
		{
			if (cloudSessionService.isReady())
			{
				cancelReconnect();
				creditAttestQueue.start();
				tradeCloudService.start();
				creditAttestQueue.flushNow();
			}
			else if (!cloudSessionService.canCollectAttests())
			{
				cancelReconnect();
			}
			else
			{
				scheduleReconnectIfNeeded();
			}
			sidebarRefresh.refresh();
		});
	}
/** Removes the status listener installed by {@link #installStatusListener()}. */
	public void clearStatusListener()
	{
		cloudSessionService.setStatusListener(null);
	}
/**
	 * Kicks off (or no-ops if already in flight) an async attempt to establish/verify the cloud
	 * session on {@link #scheduler}. Short-circuits if the account is locked or the world is
	 * restricted. On success, cancels any pending reconnect and starts the attest queue and trade
	 * sync; on failure, schedules a reconnect.
	 */
	public void connect()
	{
		if (clientShuttingDown.get())
		{
			return;
		}
		if (cloudSessionService.isAccountLocked())
		{
			cancelReconnect();
			SwingUtilities.invokeLater(sidebarRefresh::refresh);
			return;
		}
		if (cloudSessionService.isRestrictedWorld())
		{
			pauseForRestrictedWorld();
			return;
		}
		if (!cloudConnectInFlight.compareAndSet(false, true))
		{
			return;
		}
		scheduler.execute(() ->
		{
			try
			{
				if (clientShuttingDown.get())
				{
					return;
				}
				sessionEpoch.incrementAndGet();
				if (cloudSessionService.isAccountLocked())
				{
					cancelReconnect();
					SwingUtilities.invokeLater(sidebarRefresh::refresh);
					return;
				}
				if (cloudSessionService.isRestrictedWorld())
				{
					pauseForRestrictedWorld();
					return;
				}
				cloudSessionService.ensureSession();
				if (cloudSessionService.isReady())
				{
					cancelReconnect();
					creditAttestQueue.start();
					tradeCloudService.start();
					creditAttestQueue.flushNow();
				}
				else
				{
					scheduleReconnectIfNeeded();
				}
			}
			finally
			{
				cloudConnectInFlight.set(false);
			}
		});
	}
/** Cancels reconnect, flushes pending attests off-thread, then stops traffic and marks restricted. */
	public void pauseForRestrictedWorld()
	{
		if (clientShuttingDown.get())
		{
			return;
		}
		cancelReconnect();
		scheduler.execute(this::pauseRestrictedFlushAndStop);
	}
/** Scheduler-thread body for {@link #pauseForRestrictedWorld()}. */
	private void pauseRestrictedFlushAndStop()
	{
		try
		{
			if (!cloudSessionService.isAccountLocked())
			{
				creditAttestQueue.flushBlocking();
			}
		}
		catch (Exception e)
		{
			log.warn("Credit attest flush before restricted pause failed", e);
		}
		finally
		{
			creditAttestQueue.stop(false);
			tradeCloudService.stop();
			cloudSessionService.enterRestrictedWorld();
			SwingUtilities.invokeLater(sidebarRefresh::refresh);
		}
	}
/**
	 * Tears down the cloud session on logout. Cancels hiscores settle first (so no settle-hiscores
	 * can fire during teardown). If the account is locked, discards pending attests without flushing;
	 * otherwise blocks flushing pending attests before disconnecting.
	 */
	public void disconnect()
	{
		long epoch = sessionEpoch.get();
		cancelReconnect();
		cloudSessionService.cancelHiscoresSettle();
		if (cloudSessionService.isAccountLocked())
		{
			creditAttestQueue.stop();
			creditAttestQueue.discardPending();
			creditAttestQueue.clearAccountIdentity();
			cloudSessionService.forgetInMemoryAccountIdentity();
			tradeCloudService.stop();
			if (!clientShuttingDown.get() && epoch != sessionEpoch.get())
			{
				return;
			}
			cloudSessionService.disconnectQuietly();
			return;
		}
		creditAttestQueue.flushBlocking();
		creditAttestQueue.clearAccountIdentity();
		cloudSessionService.forgetInMemoryAccountIdentity();
		creditAttestQueue.stop();
		tradeCloudService.stop();
		if (!clientShuttingDown.get() && epoch != sessionEpoch.get())
		{
			return;
		}
		cloudSessionService.disconnectQuietly();
	}
/**
	 * Runs {@link #disconnect()} on {@link #scheduler} without blocking the caller. Use from the
	 * client thread (logout / plugin unload) so attest HTTP never runs there. No-ops during
	 * {@link #beginClientShutdown()} so ClientShutdown owns the flush.
	 */
	public void disconnectFromClientThread()
	{
		if (clientShuttingDown.get())
		{
			return;
		}
		scheduler.execute(this::disconnect);
	}
/** Marks client exit in progress and cancels reconnect; pairs with {@link #flushAttestsForShutdown()}. */
	public void beginClientShutdown()
	{
		clientShuttingDown.set(true);
		cancelReconnect();
	}
/**
	 * Schedules a single reconnect attempt with a random delay between {@link #CLOUD_RECONNECT_MIN_MS}
	 * and {@link #CLOUD_RECONNECT_MAX_MS}, unless one is already pending, reconnect isn't applicable
	 * (not logged in, can't collect attests, already ready, or waiting on game identity), or the
	 * current connection state isn't {@code ERROR}/{@code DISCONNECTED}.
	 */
	public void scheduleReconnectIfNeeded()
	{
		if (client.getGameState() != GameState.LOGGED_IN
			|| !cloudSessionService.canCollectAttests()
			|| cloudSessionService.isReady()
			|| cloudSessionService.isWaitingForGameIdentity())
		{
			cancelReconnect();
			return;
		}
		CloudConnectionState state = cloudSessionService.getConnectionState();
		if (state != CloudConnectionState.ERROR && state != CloudConnectionState.DISCONNECTED)
		{
			return;
		}
		synchronized (cloudReconnectLock)
		{
			if (cloudReconnectFuture == null || cloudReconnectFuture.isDone())
			{
				long delayMs = CLOUD_RECONNECT_MIN_MS
					+ ThreadLocalRandom.current().nextLong(CLOUD_RECONNECT_MAX_MS - CLOUD_RECONNECT_MIN_MS + 1L);
				cloudReconnectFuture = scheduler.schedule(
					this::onReconnectTimer,
					delayMs,
					TimeUnit.MILLISECONDS);
			}
		}
		cloudSessionService.noteOfflineReconnectScheduled();
	}
/** Fires when a scheduled reconnect delay elapses; re-attempts {@link #connect()} if still needed. */
	private void onReconnectTimer()
	{
		synchronized (cloudReconnectLock)
		{
			cloudReconnectFuture = null;
		}
		if (client.getGameState() != GameState.LOGGED_IN
			|| !cloudSessionService.canCollectAttests()
			|| cloudSessionService.isReady())
		{
			return;
		}
		connect();
	}
/** Cancels any pending scheduled reconnect, if one exists. */
	public void cancelReconnect()
	{
		synchronized (cloudReconnectLock)
		{
			if (cloudReconnectFuture != null)
			{
				cloudReconnectFuture.cancel(false);
				cloudReconnectFuture = null;
			}
		}
	}
/**
	 * Per-tick hook: if logged in, not locked, not already connecting/active, and still waiting for
	 * game identity (display name/account hash) to become available, retries {@link #connect()}.
	 */
	public void onLoggedInGameTick()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		if (cloudSessionService.isAccountLocked())
		{
			return;
		}
		if (cloudSessionService.isSessionActive() || cloudConnectInFlight.get())
		{
			return;
		}
		if (cloudSessionService.isWaitingForGameIdentity())
		{
			connect();
		}
	}
/**
	 * Reacts to RuneLite game state transitions: flushes pending attests on leaving a logged-in
	 * session (excluding hop/loading transitions), disconnects on reaching the login screen, and
	 * connects (or resumes a restricted-world pause) on reaching logged-in.
	 */
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState gs = event.getGameState();
		GameState previous = lastObservedGameState;
		lastObservedGameState = gs;

		if (previous == GameState.LOGGED_IN
			&& gs != GameState.LOGGED_IN
			&& gs != GameState.HOPPING
			&& gs != GameState.LOADING)
		{
			creditAttestQueue.flushNow();
		}

		if (gs == GameState.LOGIN_SCREEN)
		{
			disconnectFromClientThread();
		}
		else if (gs == GameState.LOGGED_IN)
		{
			if (previous == GameState.LOADING || previous == GameState.HOPPING)
			{
				connectOrPauseForWorld();
			}
			else
			{
				connect();
			}
		}
	}
/** Re-attempts connect on world hop (world type may have changed) and refreshes the sidebar. */
	public void onWorldChanged(WorldChanged event)
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			connectOrPauseForWorld();
			SwingUtilities.invokeLater(sidebarRefresh::refresh);
		}
	}
/** Pauses cloud traffic on restricted worlds; otherwise connects. */
	private void connectOrPauseForWorld()
	{
		if (cloudSessionService.isRestrictedWorld())
		{
			pauseForRestrictedWorld();
		}
		else
		{
			connect();
		}
	}
/**
	 * Client-shutdown hook: cancels hiscores settle, then blocking-flushes pending attests (unless
	 * the account is locked), logging rather than throwing on failure, then always stops
	 * attest/trade traffic and disconnects.
	 */
	public void flushAttestsForShutdown()
	{
		cloudSessionService.cancelHiscoresSettle();
		try
		{
			if (!cloudSessionService.isAccountLocked())
			{
				creditAttestQueue.flushBlocking();
			}
		}
		catch (Exception e)
		{
			log.warn("Credit attest flush on client shutdown failed", e);
		}
		finally
		{
			creditAttestQueue.clearAccountIdentity();
			cloudSessionService.forgetInMemoryAccountIdentity();
			creditAttestQueue.stop();
			tradeCloudService.stop();
			cloudSessionService.disconnectQuietly();
		}
	}
}

package com.osrstcg.cloud.session;

import com.osrstcg.state.TcgState;
import com.osrstcg.catalog.CardImageCacheService;
import com.osrstcg.interop.TcgPublicStatsCalculator;
import com.osrstcg.state.TcgStateService;
import com.osrstcg.util.TcgPluginGameMessages;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.util.Text;
import com.osrstcg.cloud.activity.ActivityConfigService;
import com.osrstcg.cloud.api.CloudApiClient;
import com.osrstcg.cloud.api.CloudApiException;
import com.osrstcg.cloud.api.CloudConnectionState;
import com.osrstcg.cloud.api.JsonObjects;
import com.osrstcg.cloud.attest.CreditAttestQueue;
import com.osrstcg.cloud.catalog.CardCatalogService;
import com.osrstcg.cloud.catalog.PackCatalogService;
import com.osrstcg.cloud.trade.TradeCloudService;
import com.osrstcg.credit.CreditAwardService;
/**
 * Owns the cloud connection lifecycle and account-lock state for the plugin: authenticates/pairs
 * the RuneLite profile with the cloud backend, tracks connection state and status messages, gates
 * traffic behind consent/lock/restricted-world checks, and delegates collection sync, hiscores
 * settling, and profile-consent work to {@link CloudCollectionSyncService}, {@link HiscoresSettleService},
 * and {@link CloudProfileConsentService} respectively. {@link #ensureSession()} is synchronized and
 * blocking (issues synchronous HTTP calls) and must not run on the client/EDT thread.
 */
@Slf4j
@Singleton
public final class CloudSessionService
{
	private static final String WAITING_FOR_ACCOUNT = "Waiting for account";
	private static final String WAITING_FOR_DISPLAY_NAME = "Waiting for display name";
	private static final String CONSENT_WAITING_STATUS = "Create a profile";

	private final Client client;
	private final CloudApiClient api;
	private final CloudTokenStore tokens;
	private final ProfileKeyHasher profileKeyHasher;
	private final TcgStateService stateService;
	private final ChatMessageManager chatMessageManager;
	private final PackCatalogService packCatalogService;
	private final CardCatalogService cardCatalogService;
	private final CardImageCacheService cardImageCacheService;
	private final ActivityConfigService activityConfigService;
	private final RestrictedWorldGuard restrictedWorldGuard;
	private final ScheduledExecutorService scheduler;
	private final Provider<TradeCloudService> tradeCloudProvider;
	private final Provider<CreditAttestQueue> attestQueueProvider;
	private final Provider<CreditAwardService> creditAwards;
	private final CloudCollectionPager collectionPager;
	private final CloudCollectionSyncService collectionSync;
	private final HiscoresSettleService hiscoresSettle;
	private final CloudProfileConsentService profileConsent;

	private final AtomicReference<CloudConnectionState> connectionState =
		new AtomicReference<>(CloudConnectionState.DISCONNECTED);
	private final AtomicReference<String> statusMessage = new AtomicReference<>("Disconnected");
	private final AtomicReference<Runnable> statusListener = new AtomicReference<>(null);
	private final AtomicBoolean hiscoresSettledThisLogin = new AtomicBoolean(false);
	private final AtomicBoolean hiscoresRetryScheduled = new AtomicBoolean(false);
	private final AtomicBoolean accountBanned = new AtomicBoolean(false);
	private final AtomicBoolean accountQuarantined = new AtomicBoolean(false);
	/** Keeps event-world UI/gates after leaving a restricted world until credit settle clears. */
	private final AtomicBoolean restrictedExitHold = new AtomicBoolean(false);
	private final List<Runnable> accountLockCleanups = new CopyOnWriteArrayList<>();

	public static final String ACCOUNT_BANNED_STATUS =
		"Account banned. See the account panel.";
	public static final String ACCOUNT_QUARANTINED_STATUS =
		"Account quarantined. See the account panel.";
/**
	 * Wires collaborators, constructs the internal {@link CloudCollectionPager}/{@link CloudCollectionSyncService}/
	 * {@link HiscoresSettleService}/{@link CloudProfileConsentService} helpers, and registers this
	 * service's stale-refresh and account-lock handlers with {@code api}.
	 */
	@Inject
	CloudSessionService(
		Client client,
		CloudApiClient api,
		CloudTokenStore tokens,
		ProfileKeyHasher profileKeyHasher,
		TcgStateService stateService,
		ChatMessageManager chatMessageManager,
		PackCatalogService packCatalogService,
		CardCatalogService cardCatalogService,
		CardImageCacheService cardImageCacheService,
		ActivityConfigService activityConfigService,
		RestrictedWorldGuard restrictedWorldGuard,
		ScheduledExecutorService scheduler,
		Provider<TradeCloudService> tradeCloudProvider,
		Provider<CreditAttestQueue> attestQueueProvider,
		Provider<CreditAwardService> creditAwards,
		TcgPublicStatsCalculator publicStatsCalculator)
	{
		this.client = client;
		this.api = api;
		this.tokens = tokens;
		this.profileKeyHasher = profileKeyHasher;
		this.stateService = stateService;
		this.chatMessageManager = chatMessageManager;
		this.packCatalogService = packCatalogService;
		this.cardCatalogService = cardCatalogService;
		this.cardImageCacheService = cardImageCacheService;
		this.activityConfigService = activityConfigService;
		this.restrictedWorldGuard = restrictedWorldGuard;
		this.scheduler = scheduler;
		this.tradeCloudProvider = tradeCloudProvider;
		this.attestQueueProvider = attestQueueProvider;
		this.creditAwards = creditAwards;
		this.collectionPager = new CloudCollectionPager(api);
		this.collectionSync = new CloudCollectionSyncService(
			this, api, tokens, stateService, attestQueueProvider,
			publicStatsCalculator, collectionPager);
		this.hiscoresSettle = new HiscoresSettleService(
			client, api, tokens, restrictedWorldGuard, scheduler, chatMessageManager, tradeCloudProvider,
			collectionSync::applySidebarStats, hiscoresSettledThisLogin, hiscoresRetryScheduled,
			this::needsCloudConsent, this::isAccountLocked, stateService::isDebugChatEnabled);
		this.profileConsent = new CloudProfileConsentService(
			this, collectionSync, client, api, tokens, profileKeyHasher, stateService,
			chatMessageManager, packCatalogService, cardCatalogService, activityConfigService);
		api.setStaleRefreshHandler(this::handleStaleRefresh);
		api.setAccountLockHandler(this::noteLockFromApiException);
	}
/** Invoked by {@link CloudApiClient} when a refresh token is rejected as stale: clears login gates and disconnects. */
	private void handleStaleRefresh()
	{
		clearLoginFetchGates();
		setState(CloudConnectionState.DISCONNECTED,
			needsCloudConsent() ? CONSENT_WAITING_STATUS : "Disconnected");
	}
/** Current cloud connection state. */
	public CloudConnectionState getConnectionState()
	{
		return connectionState.get();
	}
/** Human-readable status message associated with the current connection state. */
	public String getStatusMessage()
	{
		return statusMessage.get();
	}
/** Whether the player needs to log into RuneScape before cloud session setup can proceed. */
	public boolean isRunescapeLoginRequired()
	{
		return client.getGameState() != GameState.LOGGED_IN;
	}
/** Whether the connection state is CONNECTED and an access token is present. */
	public boolean isSessionActive()
	{
		return connectionState.get() == CloudConnectionState.CONNECTED && tokens.getAccessToken() != null;
	}
/** Whether the session is active and no gate (consent/lock/restricted world) is blocking traffic. */
	public boolean isReady()
	{
		return isSessionActive() && cloudGatesOpen() && tokens.tokensBoundTo(client.getAccountHash());
	}
/**
	 * Whether credit attests may currently be collected: gates open and cloud tokens are bound to
	 * the live Jagex account hash (prevents enqueue while another account's JWTs are still stored).
	 */
	public boolean canCollectAttests()
	{
		return cloudGatesOpen() && tokens.tokensBoundTo(client.getAccountHash());
	}
/** True unless cloud consent is pending, the account is locked, or the world is restricted. */
	private boolean cloudGatesOpen()
	{
		return !needsCloudConsent() && !isAccountLocked()
			&& !isRestrictedWorld();
	}
/**
	 * Updates the status message to indicate an offline reconnect was scheduled, if a reconnect is
	 * applicable and the current state is ERROR/DISCONNECTED. No-op otherwise.
	 */
	public void noteOfflineReconnectScheduled()
	{
		if (!canCollectAttests() || isReady())
		{
			return;
		}
		CloudConnectionState state = connectionState.get();
		if (state != CloudConnectionState.ERROR && state != CloudConnectionState.DISCONNECTED)
		{
			return;
		}
		String message = "Cloud unreachable - retrying 5-15m";
		if (message.equals(statusMessage.get()))
		{
			return;
		}
		setState(state, message);
	}
/** Whether the current world type is one where cloud credits are disabled. */
	public boolean isRestrictedWorldLive()
	{
		return restrictedWorldGuard.isRestricted();
	}
/** Whether cloud/UI should treat the world as restricted (live type, or post-exit settle hold). */
	public boolean isRestrictedWorld()
	{
		return isRestrictedWorldLive() || restrictedExitHold.get();
	}
/** Sticky event-world mode for leave/enter settle until credit settle ends (or live restricted). */
	public void beginRestrictedExitHold()
	{
		if (!restrictedExitHold.compareAndSet(false, true))
		{
			return;
		}
		Runnable listener = statusListener.get();
		if (listener != null)
		{
			listener.run();
		}
	}
/** @return true if a restricted-exit hold was cleared */
	public boolean clearRestrictedExitHold()
	{
		return restrictedExitHold.getAndSet(false);
	}
/** Whether the account is currently flagged banned. */
	public boolean isAccountBanned()
	{
		return accountBanned.get();
	}
/** Whether the account is currently flagged quarantined. */
	public boolean isAccountQuarantined()
	{
		return accountQuarantined.get();
	}
/** Whether the account is banned or quarantined. */
	public boolean isAccountLocked()
	{
		return isAccountBanned() || isAccountQuarantined();
	}
/** Whether the account panel may be opened: requires a token, consent, an unrestricted world, and (active or locked) session. */
	public boolean canOpenAccountPanel()
	{
		if (tokens.getAccessToken() == null || needsCloudConsent() || isRestrictedWorld())
		{
			return false;
		}
		return isSessionActive() || isAccountLocked();
	}
/** Stops hiscores/activity polling and moves the connection to DISCONNECTED with a restricted-world message. */
	public void enterRestrictedWorld()
	{
		activityConfigService.stopQuietPoll();
		String detail = restrictedWorldGuard.describeBlockedTypes();
		String message = detail.isEmpty()
			? RestrictedWorldGuard.STATUS_MESSAGE
			: RestrictedWorldGuard.STATUS_MESSAGE + " (" + detail + ")";
		setState(CloudConnectionState.DISCONNECTED, message);
	}
/** Flags the account as banned and pauses all cloud traffic. */
	public void enterAccountBanned()
	{
		enterAccountLock(accountBanned, ACCOUNT_BANNED_STATUS, "banned");
	}
/** Flags the account as quarantined and pauses all cloud traffic, unless already banned. */
	public void enterAccountQuarantined()
	{
		if (isAccountBanned())
		{
			return;
		}
		enterAccountLock(accountQuarantined, ACCOUNT_QUARANTINED_STATUS, "quarantined");
	}
/** Sets {@code flag}, pauses cloud traffic, updates status, and logs once on first transition into the lock. */
	private void enterAccountLock(AtomicBoolean flag, String statusMessage, String kind)
	{
		boolean already = flag.getAndSet(true);
		pauseCloudTrafficOnLock();
		setState(CloudConnectionState.DISCONNECTED, statusMessage);
		if (!already)
		{
			log.warn("Account {}; cloud traffic stopped until logout", kind);
		}
	}
/** Persists {@code status} and, if it's "banned"/"quarantined", enters the corresponding lock. No-op if blank. */
	void applyAccountStatus(String status)
	{
		if (status == null || status.isBlank())
		{
			return;
		}
		tokens.setAccountStatus(status);
		String normalized = status.trim();
		if ("banned".equalsIgnoreCase(normalized))
		{
			enterAccountBanned();
		}
		else if ("quarantined".equalsIgnoreCase(normalized))
		{
			enterAccountQuarantined();
		}
	}
/** Registers a callback to run when the account transitions into a locked (banned/quarantined) state. */
	public void registerAccountLockCleanup(Runnable cleanup)
	{
		if (cleanup != null)
		{
			accountLockCleanups.add(cleanup);
		}
	}
/**
	 * Stops and discards pending attests, runs registered lock cleanups (catching and logging any
	 * failure so one bad cleanup doesn't block the rest), and stops trade sync, activity polling,
	 * hiscores gating, and the pack catalog.
	 */
	private void pauseCloudTrafficOnLock()
	{
		CreditAttestQueue attestQueue = attestQueueProvider.get();
		attestQueue.stop();
		attestQueue.discardPending();
		for (Runnable cleanup : accountLockCleanups)
		{
			try
			{
				cleanup.run();
			}
			catch (Exception ex)
			{
				log.warn("Account lock cleanup failed", ex);
			}
		}
		stateService.clearOptimisticCredits();
		tradeCloudProvider.get().stop();
		activityConfigService.stopQuietPoll();
		hiscoresSettle.clearGate();
		packCatalogService.clear();
	}
/** Applies banned/quarantined flags read from an attest response, if present. No-op if {@code response} is null. */
	public void noteAttestBanFlags(JsonObject response)
	{
		if (response == null)
		{
			return;
		}
		applyAccountLockFlags(
			JsonObjects.readBoolean(response, "banned"),
			JsonObjects.readBoolean(response, "quarantined"));
	}
/** Applies banned/quarantined flags carried on a {@link CloudApiException}, if present. No-op if null. */
	public void noteLockFromApiException(CloudApiException ex)
	{
		if (ex == null)
		{
			return;
		}
		applyAccountLockFlags(ex.isAccountBanned(), ex.isAccountQuarantined());
	}
/** Enters the banned lock if {@code banned}, else the quarantined lock if {@code quarantined}. */
	private void applyAccountLockFlags(boolean banned, boolean quarantined)
	{
		if (banned)
		{
			enterAccountBanned();
			return;
		}
		if (quarantined)
		{
			enterAccountQuarantined();
		}
	}
/** Whether pending credit attests may be flushed to the server right now. */
	public boolean canAttestFlush()
	{
		if (tokens.getAccessToken() == null || needsCloudConsent() || isAccountLocked())
		{
			return false;
		}
		long live = client.getAccountHash();
		if (live != -1L)
		{
			return tokens.tokensBoundTo(live);
		}
		// Logout teardown: hash already cleared; allow flush if tokens remain bound to an account.
		return tokens.getBoundAccountHash() != -1L;
	}
/** Whether in-memory cloud tokens are bound to {@code accountHash}. */
	public boolean tokensBoundTo(long accountHash)
	{
		return tokens.tokensBoundTo(accountHash);
	}
/**
	 * Drops in-memory last-account identity (token cache + hiscores display name) without deleting
	 * on-disk per-account session files or writing account hash to RSProfile.
	 */
	public void forgetInMemoryAccountIdentity()
	{
		tokens.forgetInMemoryAccount();
		hiscoresSettle.clearCachedDisplayName();
	}
/** Whether this profile still needs to complete the cloud consent/migration flow. */
	public boolean needsCloudConsent()
	{
		return !tokens.isMigrated();
	}
/** Replaces the connection-status change listener (single slot; pass {@code null} to clear). */
	public void setStatusListener(Runnable listener)
	{
		statusListener.set(listener);
	}
/** Whether the status message indicates we're blocked waiting for account hash or display name. */
	public boolean isWaitingForGameIdentity()
	{
		String message = statusMessage.get();
		return WAITING_FOR_DISPLAY_NAME.equals(message) || WAITING_FOR_ACCOUNT.equals(message);
	}
/**
	 * Synchronously drives the cloud session state machine to completion: validates preconditions
	 * (not locked, not restricted world, logged in, has account hash, consent granted, has display
	 * name/profile key), refreshes or pairs credentials, adopts server migration if needed, syncs
	 * collection state, settles hiscores, and refreshes catalogs — moving through CONNECTING to
	 * CONNECTED, or to ERROR/DISCONNECTED with an explanatory status message on failure. Blocking:
	 * issues synchronous HTTP calls; callers must invoke off the client/EDT thread. Synchronized so
	 * concurrent callers serialize rather than racing the connection state machine.
	 */
	public synchronized void ensureSession()
	{
		if (isAccountLocked())
		{
			setState(CloudConnectionState.DISCONNECTED,
				isAccountBanned() ? ACCOUNT_BANNED_STATUS : ACCOUNT_QUARANTINED_STATUS);
			return;
		}
		if (isRestrictedWorld())
		{
			enterRestrictedWorld();
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			setState(CloudConnectionState.DISCONNECTED, "Log in to RuneScape");
			return;
		}
		long accountHash = client.getAccountHash();
		if (accountHash == -1L)
		{
			setState(CloudConnectionState.DISCONNECTED, WAITING_FOR_ACCOUNT);
			return;
		}
		if (needsCloudConsent())
		{
			setState(CloudConnectionState.DISCONNECTED, CONSENT_WAITING_STATUS);
			return;
		}
		if (CloudTokenStore.shouldClearForAccount(tokens.getBoundAccountHash(), tokens.hasRefreshToken(), accountHash))
		{
			log.info("Clearing credentials for different account");
			tokens.clear();
		}
		String displayName = resolveDisplayName();
		boolean needsDisplayName = !tokens.hasRefreshToken();
		if (needsDisplayName && displayNameMissing(displayName))
		{
			setState(CloudConnectionState.DISCONNECTED, WAITING_FOR_DISPLAY_NAME);
			return;
		}
		String profileHash = profileKeyHasher.currentProfileKeyHash();
		if (profileHash == null)
		{
			setState(CloudConnectionState.ERROR, "No RuneLite profile key");
			return;
		}

		// Hop reconnects keep an active session; only settle after a real login/disconnect.
		boolean shouldSettle = !isSessionActive();
		setState(CloudConnectionState.CONNECTING, "Connecting…");
		try
		{
			api.getHealth();
			if (tokens.hasRefreshToken())
			{
				try
				{
					api.applyTokenResponse(api.refresh(tokens.getRefreshToken(), profileHash), accountHash);
				}
				catch (CloudApiException refreshEx)
				{
					if (!refreshEx.isStaleRefreshToken())
					{
						throw refreshEx;
					}
					log.info("Clearing stale cloud credentials ({})", refreshEx.getCode());
					tokens.clear();
				}
			}

			if (!tokens.hasRefreshToken())
			{
				if (displayNameMissing(displayName))
				{
					setState(CloudConnectionState.DISCONNECTED, WAITING_FOR_DISPLAY_NAME);
					return;
				}
				pairSession(displayName, profileHash, accountHash);
			}

			profileConsent.adoptServerMigrationIfNeeded();
			collectionSync.refreshLocalCacheFromCloud();
			if (isAccountLocked())
			{
				return;
			}
			if (shouldSettle)
			{
				settleHiscoresIfCooldownDone();
			}
			if (isAccountLocked())
			{
				return;
			}
			setState(CloudConnectionState.CONNECTED, "Connected");
			packCatalogService.refreshOnLogin();
			cardCatalogService.refreshOnLogin();
			activityConfigService.refreshOnLogin();
		}
		catch (CloudApiException ex)
		{
			log.warn("Cloud session failed: {} {}", ex.getCode(), ex.getMessage());
			if (isAccountLocked())
			{
				return;
			}
			boolean alreadyError = connectionState.get() == CloudConnectionState.ERROR;
			setState(CloudConnectionState.ERROR, ex.getMessage());
			if (!alreadyError)
			{
				TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
					"Cloud: " + ex.getMessage());
			}
		}
		catch (Exception ex)
		{
			log.warn("Cloud session failed", ex);
			boolean alreadyError = connectionState.get() == CloudConnectionState.ERROR;
			setState(CloudConnectionState.ERROR, "Cloud unreachable");
			if (!alreadyError)
			{
				TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
					"Cloud unreachable");
			}
		}
	}
/** Sanitized local player display name, or {@code null} if the player/name isn't available yet. */
	String resolveDisplayName()
	{
		if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null)
		{
			return null;
		}
		String name = Text.sanitize(client.getLocalPlayer().getName());
		return name == null || name.isEmpty() ? null : name;
	}
/** Delegates to {@link CloudProfileConsentService#createProfile()}. Blocking; synchronized. */
	public synchronized void createProfile() throws Exception
	{
		profileConsent.createProfile();
	}
/** Deletes on-disk card catalog and image caches left over from before this profile migrated. */
	void deleteObsoleteLocalCaches()
	{
		cardCatalogService.deleteDiskCache();
		cardImageCacheService.deleteObsoleteImageCacheDirs();
	}
/** Clears lock flags, login gates, and cloud-derived local caches, then moves to DISCONNECTED. */
	public void disconnectQuietly()
	{
		accountBanned.set(false);
		accountQuarantined.set(false);
		restrictedExitHold.set(false);
		clearLoginFetchGates();
		stateService.clearCollectionStatsCache();
		stateService.clearCloudGroupKey();
		setState(CloudConnectionState.DISCONNECTED, "Disconnected");
	}
/**
	 * Cancels any in-flight/pending hiscores settle (including delayed retries). Call at the start of
	 * logout/shutdown teardown so settle-hiscores cannot be sent while attests are flushing.
	 */
	public void cancelHiscoresSettle()
	{
		hiscoresSettle.clearGate();
	}

	void settleHiscoresIfCooldownDone()
	{
		if (!creditAwards.get().isCreditAwardOnCooldown())
		{
			hiscoresSettle.settleAfterCloudLogin();
		}
	}

	public void scheduleHiscoresSettle()
	{
		scheduler.execute(this::settleHiscoresIfCooldownDone);
	}
/** Delegates to {@link CloudCollectionSyncService#applySidebarStats(JsonObject)}. */
	public void applySidebarStats(JsonObject stats)
	{
		collectionSync.applySidebarStats(stats);
	}
/** Delegates to {@link CloudCollectionSyncService#reconcileCollectionFromInbox(JsonObject)}. */
	public void reconcileCollectionFromInbox(JsonObject stats)
	{
		collectionSync.reconcileCollectionFromInbox(stats);
	}
/** Delegates to {@link CloudCollectionSyncService#refreshCreditsFromServer()}. Blocking. */
	public void refreshCreditsFromServer() throws Exception
	{
		collectionSync.refreshCreditsFromServer();
	}
/**
	 * Delegates to {@link CloudCollectionSyncService#refreshCreditsFromServer(boolean)}. Blocking.
	 * Pass {@code flushFirst=false} when already inside an attest flush to avoid deadlock.
	 */
	public void refreshCreditsFromServer(boolean flushFirst) throws Exception
	{
		collectionSync.refreshCreditsFromServer(flushFirst);
	}
/** Pairs a new session for this profile/account and applies the returned token response. Blocking. */
	void pairSession(String displayName, String profileHash, long accountHash)
		throws CloudApiException, IOException
	{
		JsonObject start = api.pairStart(displayName, profileHash, accountHash);
		api.applyTokenResponse(start, accountHash);
	}
/** Whether the local state has any credits, opened packs, or owned cards worth migrating. */
	boolean hasLocalProgress()
	{
		TcgState local = stateService.getState();
		return local.getEconomyState().getCredits() > 0
			|| local.getEconomyState().getOpenedPacks() > 0
			|| !local.getCollectionState().getOwnedInstances().isEmpty();
	}
/** Updates connection state and status message, then notifies the registered status listener, if any. */
	void setState(CloudConnectionState state, String message)
	{
		connectionState.set(state);
		statusMessage.set(message == null ? "" : message);
		Runnable listener = statusListener.get();
		if (listener != null)
		{
			listener.run();
		}
	}
/** Resets per-login one-shot gates (catalog fetch, activity polling, hiscores settle) so they re-run on next login. */
	private void clearLoginFetchGates()
	{
		packCatalogService.clear();
		cardCatalogService.resetLoginFetchGate();
		activityConfigService.stopQuietPoll();
		hiscoresSettle.clearGate();
	}
/** Whether {@code displayName} is null or empty. */
	private static boolean displayNameMissing(String displayName)
	{
		return displayName == null || displayName.isEmpty();
	}
}

package com.osrstcg.cloud.session;

import net.runelite.api.Client;
import net.runelite.client.util.Text;
/** Sanitized local-player RSN with last-known fallback when the client name is unavailable. */
public final class CachedDisplayName
{
	private String last;
/** Reads and sanitizes the local player's name, caching the last known value. */
	public String resolve(Client client)
	{
		if (client != null && client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null)
		{
			String name = Text.sanitize(client.getLocalPlayer().getName());
			if (name != null && !name.isEmpty())
			{
				last = name;
				return name;
			}
		}
		return last;
	}
/** Drops the cached RSN (call after logout flush so the next account starts clean). */
	public void clear()
	{
		last = null;
	}
}

package com.osrstcg.cloud.session;

import com.osrstcg.cloud.api.JsonObjects;
import com.osrstcg.cloud.session.CloudSessionFileStore.SessionData;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
/** Session JWT store (access/refresh). Not account credentials. Consent stays in RS-profile config. */
@Singleton
public final class CloudTokenStore
{
	private static final String GROUP = "osrstcg";
	private static final String ACCESS = "cloudAccessToken";
	private static final String REFRESH = "cloudRefreshToken";
	private static final String ACCOUNT_ID = "cloudAccountId";
	private static final String BOUND_ACCOUNT_HASH = "cloudBoundAccountHash";
	private static final String MIGRATED = "cloudMigrated";
	private static final String STATUS = "cloudAccountStatus";

	private final ConfigManager configManager;
	private final Client client;
	private final CloudSessionFileStore sessionFileStore;

	private volatile long lastKnownAccountHash = -1L;
	private volatile long cachedAccountHash = -1L;
	private volatile SessionData cached;

	@Inject
	CloudTokenStore(ConfigManager configManager, Client client, CloudSessionFileStore sessionFileStore)
	{
		this.configManager = configManager;
		this.client = client;
		this.sessionFileStore = sessionFileStore;
	}
/** Returns the stored access token, or {@code null} if none is set. */
	public String getAccessToken()
	{
		SessionData data = session();
		return data == null ? null : JsonObjects.blankToNull(data.accessToken);
	}
/** Returns the stored refresh token, or {@code null} if none is set. */
	public String getRefreshToken()
	{
		SessionData data = session();
		return data == null ? null : JsonObjects.blankToNull(data.refreshToken);
	}
/**
	 * Jagex account hash these tokens were issued for, or {@code -1} if unset/unparseable.
	 * Used to refuse refresh when a different account is logged in on the same RS profile.
	 */
	public long getBoundAccountHash()
	{
		SessionData data = session();
		if (data == null)
		{
			return -1L;
		}
		return data.boundAccountHash != 0L ? data.boundAccountHash : -1L;
	}
/** Whether stored tokens are bound to {@code accountHash} (and that hash is valid). */
	public boolean tokensBoundTo(long accountHash)
	{
		return isBoundTo(getBoundAccountHash(), accountHash);
	}
/**
	 * Whether existing credentials must be cleared before connecting as {@code liveAccountHash}.
	 * Unbound legacy tokens ({@code boundAccountHash == -1}) also force a re-pair.
	 */
	static boolean shouldClearForAccount(long boundAccountHash, boolean hasRefreshToken, long liveAccountHash)
	{
		if (!hasRefreshToken || liveAccountHash == -1L)
		{
			return false;
		}
		return !isBoundTo(boundAccountHash, liveAccountHash);
	}

	static boolean isBoundTo(long boundAccountHash, long accountHash)
	{
		if (accountHash == -1L)
		{
			return false;
		}
		return boundAccountHash == accountHash;
	}
/** Parses a stored bound-hash string; {@code -1} if null/blank/unparseable. */
	static long parseBoundAccountHash(String raw)
	{
		String value = JsonObjects.blankToNull(raw);
		if (value == null)
		{
			return -1L;
		}
		try
		{
			return Long.parseLong(value);
		}
		catch (NumberFormatException ex)
		{
			return -1L;
		}
	}
/** Whether this profile has completed the one-time cloud migration/consent flow. */
	public boolean isMigrated()
	{
		return "true".equalsIgnoreCase(configManager.getRSProfileConfiguration(GROUP, MIGRATED));
	}
/**
	 * Persists the access/refresh token pair, optional account id/status, and the Jagex account
	 * hash these tokens belong to. No-op if either token is null/empty or {@code boundAccountHash}
	 * is {@code -1}.
	 */
	public void saveTokens(
		String accessToken,
		String refreshToken,
		String accountId,
		String status,
		long boundAccountHash)
	{
		if (accessToken == null || accessToken.isEmpty() || refreshToken == null || refreshToken.isEmpty())
		{
			return;
		}
		if (boundAccountHash == -1L)
		{
			return;
		}
		lastKnownAccountHash = boundAccountHash;
		SessionData data = new SessionData();
		data.accessToken = accessToken;
		data.refreshToken = refreshToken;
		data.accountId = accountId;
		data.status = status;
		data.boundAccountHash = boundAccountHash;
		sessionFileStore.save(boundAccountHash, data);
		cachedAccountHash = boundAccountHash;
		cached = data;
		unsetLegacyTokenKeys();
	}
/** Marks (or unmarks) this profile as having completed cloud migration/consent. */
	public void setMigrated(boolean migrated)
	{
		configManager.setRSProfileConfiguration(GROUP, MIGRATED, migrated ? "true" : "false");
	}
/** Persists the account status (e.g. banned/quarantined). No-op if {@code status} is null/empty. */
	public void setAccountStatus(String status)
	{
		if (status == null || status.isEmpty())
		{
			return;
		}
		SessionData data = session();
		long hash = resolveAccountHash();
		if (data == null || hash == -1L)
		{
			return;
		}
		data.status = status;
		sessionFileStore.save(hash, data);
		cachedAccountHash = hash;
		cached = data;
	}
/** Removes stored access/refresh tokens, account id, bound hash, and status (does not clear the migrated flag). */
	public void clear()
	{
		evictLocal(false);
	}
/** Deletes the entire on-disk profile folder for the current account (save + session). */
	public void wipeAccountProfileDir()
	{
		evictLocal(true);
	}

	private void evictLocal(boolean wipeDir)
	{
		long hash = resolveAccountHash();
		if (hash != -1L)
		{
			if (wipeDir)
			{
				sessionFileStore.deleteAccountDir(hash);
			}
			else
			{
				sessionFileStore.delete(hash);
			}
		}
		cachedAccountHash = -1L;
		cached = null;
		lastKnownAccountHash = -1L;
		unsetLegacyTokenKeys();
	}
/**
	 * Drops in-memory lastKnown/cached session without deleting on-disk {@code cloud-session.json}
	 * and without writing account hash to RSProfile.
	 */
	public void forgetInMemoryAccount()
	{
		lastKnownAccountHash = -1L;
		cachedAccountHash = -1L;
		cached = null;
	}
/** Whether a refresh token is currently stored. */
	public boolean hasRefreshToken()
	{
		return getRefreshToken() != null;
	}

	private SessionData session()
	{
		long hash = resolveAccountHash();
		if (hash == -1L)
		{
			return null;
		}
		if (cachedAccountHash == hash && cached != null)
		{
			if (shouldClearForAccount(cached.boundAccountHash, !blank(cached.refreshToken), hash))
			{
				clear();
				return null;
			}
			return cached;
		}
		migrateLegacyTokensIfNeeded(hash);
		SessionData loaded = sessionFileStore.load(hash);
		if (loaded != null && shouldClearForAccount(loaded.boundAccountHash, !blank(loaded.refreshToken), hash))
		{
			sessionFileStore.delete(hash);
			cachedAccountHash = hash;
			cached = null;
			unsetLegacyTokenKeys();
			return null;
		}
		if (loaded != null && loaded.boundAccountHash == -1L)
		{
			loaded.boundAccountHash = hash;
		}
		cachedAccountHash = hash;
		cached = loaded;
		return loaded;
	}

	private long resolveAccountHash()
	{
		long hash = client.getAccountHash();
		if (hash != -1L)
		{
			lastKnownAccountHash = hash;
			return hash;
		}
		return lastKnownAccountHash;
	}
/**
	 * One-time move of RS-profile token keys into {@code cloud-session.json} for the live account.
	 * Mismatched bound hash → drop legacy keys (force re-pair). Never moves {@code cloudMigrated}.
	 */
	private void migrateLegacyTokensIfNeeded(long liveAccountHash)
	{
		String access = JsonObjects.blankToNull(configManager.getRSProfileConfiguration(GROUP, ACCESS));
		String refresh = JsonObjects.blankToNull(configManager.getRSProfileConfiguration(GROUP, REFRESH));
		if (access == null && refresh == null
			&& configManager.getRSProfileConfiguration(GROUP, ACCOUNT_ID) == null
			&& configManager.getRSProfileConfiguration(GROUP, BOUND_ACCOUNT_HASH) == null
			&& configManager.getRSProfileConfiguration(GROUP, STATUS) == null)
		{
			return;
		}
		if (sessionFileStore.load(liveAccountHash) != null)
		{
			unsetLegacyTokenKeys();
			return;
		}
		if (access == null || refresh == null)
		{
			unsetLegacyTokenKeys();
			return;
		}
		long bound = parseBoundAccountHash(configManager.getRSProfileConfiguration(GROUP, BOUND_ACCOUNT_HASH));
		if (bound != -1L && bound != liveAccountHash)
		{
			unsetLegacyTokenKeys();
			return;
		}
		SessionData data = new SessionData();
		data.accessToken = access;
		data.refreshToken = refresh;
		data.accountId = JsonObjects.blankToNull(configManager.getRSProfileConfiguration(GROUP, ACCOUNT_ID));
		data.status = JsonObjects.blankToNull(configManager.getRSProfileConfiguration(GROUP, STATUS));
		data.boundAccountHash = liveAccountHash;
		sessionFileStore.save(liveAccountHash, data);
		unsetLegacyTokenKeys();
	}

	private void unsetLegacyTokenKeys()
	{
		configManager.unsetRSProfileConfiguration(GROUP, ACCESS);
		configManager.unsetRSProfileConfiguration(GROUP, REFRESH);
		configManager.unsetRSProfileConfiguration(GROUP, ACCOUNT_ID);
		configManager.unsetRSProfileConfiguration(GROUP, BOUND_ACCOUNT_HASH);
		configManager.unsetRSProfileConfiguration(GROUP, STATUS);
	}

	private static boolean blank(String value)
	{
		return value == null || value.isEmpty();
	}
}

package com.osrstcg.cloud.session;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.osrstcg.cloud.api.JsonObjects;
import com.osrstcg.state.CloudSidebarCollectionStats;
import com.osrstcg.state.EconomyState;
import com.osrstcg.state.OwnedCardInstance;
import java.util.ArrayList;
import java.util.List;
/**
 * Stateless parser for the JSON payloads returned by the cloud {@code /me/state} and related
 * endpoints. Converts raw {@link JsonObject}s into typed, defensively-normalized value objects
 * ({@link ParsedCloudPlayerState}, {@link SyncMarkers}).
 */
public final class CloudPlayerStateParser
{
	private CloudPlayerStateParser()
	{
	}
/**
	 * Parses a full {@code /me/state}-shaped root object (account/economy/stats/cards sections)
	 * into a {@link ParsedCloudPlayerState}. Returns {@link ParsedCloudPlayerState#empty()} if
	 * {@code root} is null. Cards are read from the top-level {@code cards} field, falling back to
	 * {@code collection.cards} for older payload shapes.
	 */
	public static ParsedCloudPlayerState parse(JsonObject root)
	{
		if (root == null)
		{
			return ParsedCloudPlayerState.empty();
		}

		JsonObject account = JsonObjects.objectOrEmpty(root, "account");
		JsonObject economy = JsonObjects.objectOrEmpty(root, "economy");
		JsonObject stats = JsonObjects.objectOrEmpty(root, "stats");

		List<OwnedCardInstance> cards = parseCards(root.get("cards"));
		if (cards.isEmpty() && root.has("collection") && root.get("collection").isJsonObject())
		{
			cards = parseCards(root.getAsJsonObject("collection").get("cards"));
		}

		String migratedAt = JsonObjects.text(account, "migratedAt");
		boolean migratedFlag = JsonObjects.readBoolean(account, "migrated");
		long revisionEarly = JsonObjects.readLong(economy, "revision", 0L);
		boolean migrated = (migratedAt != null && !migratedAt.isBlank())
			|| migratedFlag
			|| !cards.isEmpty();

		long credits = JsonObjects.readLong(economy, "credits", 0L);
		long openedPacks = JsonObjects.readLong(economy, "openedPacks", 0L);
		long totalCreditsGained = JsonObjects.readLong(economy, "totalCreditsGained", credits);
		long revision = revisionEarly;
		String stateHash = JsonObjects.text(economy, "stateHash");
		if (stateHash == null)
		{
			stateHash = "";
		}
		String collectionHash = JsonObjects.text(economy, "collectionHash");
		if (collectionHash == null)
		{
			collectionHash = "";
		}

		CloudSidebarCollectionStats sidebarStats = null;
		if (CloudSidebarCollectionStats.hasCollectionFields(stats) || stats.has("credits") || stats.has("openedPacks"))
		{
			sidebarStats = CloudSidebarCollectionStats.fromStatsJson(stats);
		}

		String status = JsonObjects.text(account, "status");
		boolean cardsPaged = JsonObjects.readBoolean(root, "cardsPaged");

		String groupKey = null;
		if (root.has("group") && root.get("group").isJsonObject())
		{
			groupKey = JsonObjects.text(root.getAsJsonObject("group"), "groupKey");
			if (groupKey != null && groupKey.isBlank())
			{
				groupKey = null;
			}
		}

		return new ParsedCloudPlayerState(
			migrated,
			migratedAt,
			status,
			new EconomyState(credits, openedPacks),
			totalCreditsGained,
			revision,
			stateHash,
			collectionHash,
			sidebarStats,
			cards,
			cardsPaged,
			groupKey);
	}
/**
	 * Converts a {@code cards} JSON array into {@link OwnedCardInstance}s, skipping any element that
	 * isn't an object, is marked beta, or is missing a usable card name. Returns an empty list if
	 * {@code cardsEl} is null or not an array.
	 */
	public static List<OwnedCardInstance> parseCards(JsonElement cardsEl)
	{
		List<OwnedCardInstance> out = new ArrayList<>();
		if (cardsEl == null || !cardsEl.isJsonArray())
		{
			return out;
		}
		JsonArray cards = cardsEl.getAsJsonArray();
		for (JsonElement el : cards)
		{
			if (el == null || !el.isJsonObject())
			{
				continue;
			}
			JsonObject card = el.getAsJsonObject();
			if (JsonObjects.readBoolean(card, "beta"))
			{
				continue;
			}
			String name = JsonObjects.text(card, "cardName");
			if (name == null || name.isBlank())
			{
				name = JsonObjects.text(card, "name");
			}
			if (name == null || name.isBlank())
			{
				continue;
			}
			String instanceId = JsonObjects.text(card, "instanceId");
			boolean foil = JsonObjects.readBoolean(card, "foil");
			String pulledBy = JsonObjects.text(card, "pulledBy");
			long pulledAt = Math.max(0L, JsonObjects.readLong(card, "pulledAt", 0L));
			out.add(new OwnedCardInstance(instanceId, name.trim(), foil,
				pulledBy == null ? "" : pulledBy, pulledAt));
		}
		return out;
	}
/**
	 * Reads revision/stateHash/collectionHash sync markers from either a stats payload with a nested
	 * {@code economy} object or an economy object directly, falling back to top-level fields when the
	 * nested ones are absent. Returns zero/blank markers if {@code statsOrEconomy} is null.
	 */
	public static SyncMarkers readSyncMarkers(JsonObject statsOrEconomy)
	{
		if (statsOrEconomy == null)
		{
			return new SyncMarkers(0L, "", "");
		}
		JsonObject economy = statsOrEconomy.has("economy") && statsOrEconomy.get("economy").isJsonObject()
			? statsOrEconomy.getAsJsonObject("economy")
			: statsOrEconomy;
		long revision = JsonObjects.readLong(economy, "revision", JsonObjects.readLong(statsOrEconomy, "revision", 0L));
		String hash = JsonObjects.text(economy, "stateHash");
		if (hash == null)
		{
			hash = JsonObjects.text(statsOrEconomy, "stateHash");
		}
		String collectionHash = JsonObjects.text(economy, "collectionHash");
		if (collectionHash == null)
		{
			collectionHash = JsonObjects.text(statsOrEconomy, "collectionHash");
		}
		return new SyncMarkers(revision, hash == null ? "" : hash, collectionHash == null ? "" : collectionHash);
	}
/** Revision/hash markers used to detect whether local state is behind the cloud copy. */
	public static final class SyncMarkers
	{
		public final long revision;
		public final String stateHash;
		public final String collectionHash;
/** Normalizes revision to non-negative and hashes to trimmed, non-null strings. */
		public SyncMarkers(long revision, String stateHash, String collectionHash)
		{
			this.revision = Math.max(0L, revision);
			this.stateHash = stateHash == null ? "" : stateHash.trim();
			this.collectionHash = collectionHash == null ? "" : collectionHash.trim();
		}
	}
/**
	 * Normalized, immutable snapshot of a cloud player-state response: migration/account status,
	 * economy totals, sync markers, and the owned card collection (which may be a placeholder when
	 * {@link #cardsPaged} is true, pending a follow-up page fetch via {@link CloudCollectionPager}).
	 */
	public static final class ParsedCloudPlayerState
	{
		public final boolean migrated;
		public final String migratedAt;
		public final String accountStatus;
		public final EconomyState economy;
		public final long totalCreditsGained;
		public final long revision;
		public final String stateHash;
		public final String collectionHash;
		public final CloudSidebarCollectionStats sidebarStats;
		public final List<OwnedCardInstance> cards;
		public final boolean cardsPaged;
		public final String groupKey;
/** Normalizes all fields (non-negative numbers, non-null/trimmed strings, immutable card list). */
		ParsedCloudPlayerState(
			boolean migrated,
			String migratedAt,
			String accountStatus,
			EconomyState economy,
			long totalCreditsGained,
			long revision,
			String stateHash,
			String collectionHash,
			CloudSidebarCollectionStats sidebarStats,
			List<OwnedCardInstance> cards,
			boolean cardsPaged,
			String groupKey)
		{
			this.migrated = migrated;
			this.migratedAt = migratedAt;
			this.accountStatus = accountStatus;
			this.economy = economy == null ? EconomyState.empty() : economy;
			this.totalCreditsGained = Math.max(0L, totalCreditsGained);
			this.revision = Math.max(0L, revision);
			this.stateHash = stateHash == null ? "" : stateHash.trim();
			this.collectionHash = collectionHash == null ? "" : collectionHash.trim();
			this.sidebarStats = sidebarStats;
			this.cards = cards == null ? List.of() : List.copyOf(cards);
			this.cardsPaged = cardsPaged;
			this.groupKey = groupKey == null || groupKey.isBlank() ? null : groupKey.trim();
		}
/** Returns a copy with {@code nextCards} substituted and {@code cardsPaged} cleared. */
		public ParsedCloudPlayerState withCards(List<OwnedCardInstance> nextCards)
		{
			return new ParsedCloudPlayerState(
				migrated,
				migratedAt,
				accountStatus,
				economy,
				totalCreditsGained,
				revision,
				stateHash,
				collectionHash,
				sidebarStats,
				nextCards,
				false,
				groupKey);
		}
/** An unmigrated, zeroed-out state used when there is no cloud payload to parse. */
		static ParsedCloudPlayerState empty()
		{
			return new ParsedCloudPlayerState(false, null, null, EconomyState.empty(), 0L, 0L, "", "",
				null, List.of(), false, null);
		}
	}
}

package com.osrstcg.pack;
/**
 * CSS {@code cubic-bezier(0.2, 0.7, 0.2, 1)} timing - maps linear 0..1 time to eased flip progress.
 */
final class CardFlipEasing
{
	private CardFlipEasing()
	{
	}
/**
	 * Eases a linear 0..1 flip time into 0..1 progress along the cubic-bezier curve, via Newton-Raphson
	 * inversion of the bezier's x(u) against {@code t}.
	 */
	static float flipEase(float t)
	{
		if (t <= 0f)
		{
			return 0f;
		}
		if (t >= 1f)
		{
			return 1f;
		}
		// Unit cubic Bezier with P0=(0,0), P1=(0.2,0.7), P2=(0.2,1), P3=(1,1).
		float u = t;
		for (int i = 0; i < 6; i++)
		{
			float x = cubicBezier(u, 0.2f, 0.2f);
			float dx = cubicBezierDerivative(u, 0.2f, 0.2f);
			if (Math.abs(dx) < 1e-6f)
			{
				break;
			}
			u -= (x - t) / dx;
			if (u < 0f)
			{
				u = 0f;
			}
			else if (u > 1f)
			{
				u = 1f;
			}
		}
		return cubicBezier(u, 0.7f, 1f);
	}
/** Evaluates a single component of the unit cubic bezier at parameter {@code u} for control points {@code p1}/{@code p2}. */
	private static float cubicBezier(float u, float p1, float p2)
	{
		float omu = 1f - u;
		return 3f * omu * omu * u * p1 + 3f * omu * u * u * p2 + u * u * u;
	}
/** Derivative of {@link #cubicBezier} with respect to {@code u}, used by the Newton-Raphson step. */
	private static float cubicBezierDerivative(float u, float p1, float p2)
	{
		float omu = 1f - u;
		return 3f * omu * omu * p1 + 6f * omu * u * (p2 - p1) + 3f * u * u * (1f - p2);
	}
}

