/**
 * State machine driving the pack-open reveal overlay: pack-tap animation, waiting for the server's pulls,
 * dealing cards in batches, per-card flip reveals, and the wait-to-close pause. All public methods are
 * {@code synchronized} on this instance and are expected to be called from the client thread; {@link #tick()}
 * and {@link #capturePaintFrame()} are driven once per paint frame to advance time-based phases.
 */
@Singleton
public class PackRevealService
{
/** Reveal overlay phases, advanced by {@link #tick()} (time-driven) or user input ({@link #handleClick}, {@link #advanceFromKeyboard}). */
	public enum Phase
	{
/** No reveal in progress. */
		IDLE,
/** Pack sleeve shown, waiting for the player to click/tap it. */
		PACK_READY,
/** Pack sleeve fading out after being tapped. */
		PACK_FADING,
/** Fade finished but the server hasn't supplied pulls yet ({@link #supplyRevealPulls} not yet called). */
		AWAITING_PULLS,
/** Cards animating into their dealt positions. */
		CARD_DEAL,
/** Cards dealt and awaiting per-card flip clicks/keyboard advance. */
		CARD_REVEAL,
/** Current batch fully revealed; waiting for input to start the next batch or close the overlay. */
		WAIT_CLOSE
	}
/** One resolved reveal card: the raw server pull, its display definition, rarity tier/color, and new-to-collection flag. */
	@Value
	public static class RevealCard
	{
		PackCardResult pull;
		CardDefinition definition;
		RarityMath.Tier tier;
		Color rarityColor;
		boolean isNew;
	}
/** Immutable copy of the current reveal state for the overlay to paint one frame from, without holding the service lock. */
	@Getter
	public static final class RevealPaintSnapshot
	{
		private final Phase phase;
		private final List<RevealCard> cards;
		@Getter(AccessLevel.NONE)
		private final boolean[] revealedByIndex;
		@Getter(AccessLevel.NONE)
		private final float[] flipProgressByIndex;
		private final long phaseElapsedMs;
		private final double packFadeProgress;
		private final String boosterPackId;
		private final boolean apexPackOpen;
/** Copies the given frame state; array/collection ownership is transferred from the caller. */
		private RevealPaintSnapshot(Phase phase, List<RevealCard> cards, boolean[] revealedByIndex,
			float[] flipProgressByIndex, long phaseElapsedMs,
			double packFadeProgress, String boosterPackId, boolean apexPackOpen)
		{
			this.phase = phase;
			this.cards = cards;
			this.revealedByIndex = revealedByIndex;
			this.flipProgressByIndex = flipProgressByIndex;
			this.phaseElapsedMs = phaseElapsedMs;
			this.packFadeProgress = packFadeProgress;
			this.boosterPackId = boosterPackId == null ? "" : boosterPackId;
			this.apexPackOpen = apexPackOpen;
		}
/** Whether the visible card at {@code index} has completed its flip. */
		public boolean isCardRevealed(int index)
		{
			return index >= 0 && index < revealedByIndex.length && revealedByIndex[index];
		}
/** Eased flip progress (0..1) for the visible card at {@code index}; 1 once revealed, 0 if out of range. */
		public float getFlipProgress(int index)
		{
			if (index < 0 || flipProgressByIndex == null || index >= flipProgressByIndex.length)
			{
				return isCardRevealed(index) ? 1f : 0f;
			}
			return flipProgressByIndex[index];
		}
/** Whether any still-face-down card in this batch would play mythic/legendary-foil reveal audio when flipped. */
		public boolean hasUnrevealedMythic()
		{
			return hasUnrevealedPremiumAudio(cards, revealedByIndex);
		}
	}

	private static final long PACK_FADE_MS = 500L;

	public static final long PACK_DEAL_STAGGER_MS = 115L;
	public static final long PACK_DEAL_FLIGHT_MS = 260L;
	public static final int MAX_VISIBLE_REVEAL_CARDS = 5;
	public static final long PENDING_PULLS_TIMEOUT_MS = 5_000L;
	public static final String PENDING_PULLS_TIMEOUT_MESSAGE =
		"There was a problem opening the pack at this time. Try again later.";

	private final CardImageCacheService imageCacheService;
	private final PackCatalogService packCatalogService;
	private final PackRevealSoundService packRevealSoundService;
	private final PullNotificationService pullNotificationService;
	private final RevealCardResolver revealCardResolver;

	private Phase phase = Phase.IDLE;
	private List<RevealCard> cards = List.of();
	private int batchOffset;
	private int revealedCount;
	private boolean[] revealedByIndex = new boolean[0];
	private boolean[] collectionChatPosted = new boolean[0];
	private long[] flipStartedAtMs = new long[0];
	public static final int CARD_FLIP_MS = 550;
	private long phaseStartedAt;
	private String boosterPackId = "";
	private boolean apexPackOpen;
	private boolean awaitingServerPulls;
	private long pendingRevealStartedAtMs;
	private boolean pendingPullsTimedOut;
	private Set<String> preOwnedFoilNames = Set.of();

	@Inject
	public PackRevealService(CardDatabase cardDatabase, CardImageCacheService imageCacheService,
		PackCatalogService packCatalogService, PackRevealSoundService packRevealSoundService,
		PullNotificationService pullNotificationService)
	{
		this.imageCacheService = imageCacheService;
		this.packCatalogService = packCatalogService;
		this.packRevealSoundService = packRevealSoundService;
		this.pullNotificationService = pullNotificationService;
		this.revealCardResolver = new RevealCardResolver(cardDatabase);
	}
/**
	 * Starts a reveal in {@link Phase#PACK_READY} with placeholder cards, before the server has responded
	 * with actual pulls. The pending-pulls timeout is not armed here — call {@link #armPendingPullsTimeout}
	 * once local pre-work is done and the open-pack HTTP is about to fire. Call {@link #supplyRevealPulls}
	 * once the pulls arrive, or {@link #abortPendingReveal} if the buy call fails.
	 */
	public synchronized void beginPendingReveal(String boosterPackId,
		boolean apexPackOpen, int expectedCardCount)
	{
		packRevealSoundService.hardStop();
		this.boosterPackId = boosterPackId == null ? "" : boosterPackId.trim();
		this.apexPackOpen = apexPackOpen;
		preloadRevealSleeve(this.boosterPackId);
		List<RevealCard> placeholders = revealCardResolver.createPlaceholderCards(expectedCardCount);
		this.cards = placeholders;
		this.batchOffset = 0;
		this.collectionChatPosted = new boolean[placeholders.size()];
		initCurrentBatchRevealFlags();
		this.phaseStartedAt = 0L;
		this.awaitingServerPulls = true;
		this.pendingRevealStartedAtMs = 0L;
		this.pendingPullsTimedOut = false;
		revealCardResolver.rebuildRarityTierIndex();
		this.phase = Phase.PACK_READY;
	}
/**
	 * Arms the {@link #PENDING_PULLS_TIMEOUT_MS} clock for an in-flight pending reveal. Call immediately
	 * before the open-pack HTTP so local flush/pre-work does not consume the wait budget. Idempotent:
	 * a catalog-mismatch retry must not reset the clock. No-op if already armed, idle, or not awaiting.
	 */
	public synchronized void armPendingPullsTimeout()
	{
		if (phase == Phase.IDLE || !awaitingServerPulls || pendingRevealStartedAtMs > 0L)
		{
			return;
		}
		pendingRevealStartedAtMs = System.currentTimeMillis();
	}
/** Kicks off async preloading of the card-back and (if resolvable) pack-specific reveal sleeve images. */
	private void preloadRevealSleeve(String packId)
	{
		ArrayList<String> urls = new ArrayList<>(2);
		urls.add(SharedCardRenderer.CARD_BACK_PATH);
		if (packId != null && !packId.isBlank())
		{
			BoosterPackDefinition pack = packCatalogService.getCache().get(packId).orElse(null);
			String sleeve = pack == null ? null : pack.revealSleevePath();
			if (sleeve != null)
			{
				urls.add(sleeve);
			}
		}
		imageCacheService.preloadAsync(urls);
	}
/**
	 * Async continuation of {@link #beginPendingReveal}: resolves the server's pulls into
	 * {@link RevealCard}s shuffled within each {@link #MAX_VISIBLE_REVEAL_CARDS}-card chunk
	 * (keeps large-pack apex sets contiguous), preloads their images, and advances the phase out of
	 * {@code AWAITING_PULLS}/ pending {@code CARD_DEAL}/{@code CARD_REVEAL} if the corresponding wait
	 * has already elapsed.
	 * Returns {@code false} (leaving state untouched) if the reveal was aborted or the pulls resolved to nothing.
	 */
	public synchronized boolean supplyRevealPulls(List<PackCardResult> pulls, Set<CardCollectionKey> preOwnedCards,
		boolean apexPackOpen)
	{
		if (phase == Phase.IDLE)
		{
			return false;
		}
		List<RevealCard> resolved = revealCardResolver.resolveRevealCards(pulls, preOwnedCards);
		if (resolved.isEmpty())
		{
			return false;
		}

		preOwnedFoilNames = buildPreOwnedFoilNames(preOwnedCards);
		ThreadLocalRandom rnd = ThreadLocalRandom.current();
		for (int start = 0; start < resolved.size(); start += MAX_VISIBLE_REVEAL_CARDS)
		{
			int end = Math.min(start + MAX_VISIBLE_REVEAL_CARDS, resolved.size());
			Collections.shuffle(resolved.subList(start, end), rnd);
		}
		this.cards = List.copyOf(resolved);
		this.batchOffset = 0;
		this.apexPackOpen = apexPackOpen;
		imageCacheService.preloadAsync(this.cards.stream()
			.flatMap(c ->
			{
				CardDefinition def = c.getDefinition();
				if (def == null)
				{
					return Stream.empty();
				}
				boolean foil = c.getPull() != null && c.getPull().isFoil();
				String foilPath = def.getFoilImagePath();
				if (foil && foilPath != null && !foilPath.isBlank())
				{
					return Stream.of(foilPath);
				}
				return Stream.of(def.getImageUrl());
			})
			.collect(Collectors.toList()));
		this.collectionChatPosted = new boolean[this.cards.size()];
		initCurrentBatchRevealFlags();
		this.awaitingServerPulls = false;
		this.pendingRevealStartedAtMs = 0L;

		if (phase == Phase.AWAITING_PULLS
			|| (phase == Phase.PACK_FADING && phaseStartedAt > 0L
				&& (System.currentTimeMillis() - phaseStartedAt) >= PACK_FADE_MS))
		{
			phase = Phase.CARD_DEAL;
			phaseStartedAt = System.currentTimeMillis();
		}
		else if (phase == Phase.CARD_DEAL && phaseStartedAt > 0L
			&& (System.currentTimeMillis() - phaseStartedAt) >= packDealPhaseTotalMs(visibleCount()))
		{
			phase = Phase.CARD_REVEAL;
			phaseStartedAt = System.currentTimeMillis();
		}
		return true;
	}
/** Cancels a reveal that never received server pulls (buy call failed) and returns to {@link Phase#IDLE}. */
	public synchronized void abortPendingReveal()
	{
		packRevealSoundService.hardStop();
		reset();
	}
/** Display name used for the pull/party chat announcement for a revealed card. */
	private static String cardNameForParty(RevealCard card)
	{
		return CardDisplayNames.titleForDefinition(
			card == null ? null : card.getDefinition(),
			card == null ? null : card.getPull());
	}
/**
	 * Handles a click/tap on the reveal overlay: taps the pack sleeve to start fading it, clicks past a
	 * fully-revealed batch to advance, or clicks an individual face-down card to start its flip (playing
	 * flip/mythic sound; pull notification fires when the flip completes).
	 */
	public synchronized void handleClick(Point click, Rectangle packBounds, List<Rectangle> cardBounds)
	{
		if (phase == Phase.IDLE)
		{
			return;
		}

		if (phase == Phase.PACK_READY)
		{
			if (packBounds != null && click != null && packBounds.contains(click))
			{
				phase = Phase.PACK_FADING;
				phaseStartedAt = System.currentTimeMillis();
			}
			return;
		}

		if (phase == Phase.CARD_DEAL || phase == Phase.AWAITING_PULLS)
		{
			return;
		}

		int batchSize = visibleCount();
		if (click != null && batchSize > 0 && (allRevealSlotsFaceUp() || revealedCount >= batchSize))
		{
			advancePastWaitClose();
			return;
		}

		if (phase == Phase.CARD_REVEAL && revealedCount < batchSize)
		{
			int clickedIndex = clickedCardIndex(cardBounds, click);
			if (clickedIndex >= 0 && clickedIndex < revealedByIndex.length
				&& !revealedByIndex[clickedIndex]
				&& (clickedIndex >= flipStartedAtMs.length || flipStartedAtMs[clickedIndex] <= 0L))
			{
				int absIndex = batchOffset + clickedIndex;
				RevealCard clicked = cards.get(absIndex);
				if (clickedIndex < flipStartedAtMs.length)
				{
					flipStartedAtMs[clickedIndex] = System.currentTimeMillis();
				}
				packRevealSoundService.playCardFlip();
				if (isPremiumRevealAudioPull(clicked))
				{
					packRevealSoundService.playMythicReveal();
				}
			}
		}
	}
/**
	 * Keyboard equivalent of tapping through the reveal: starts the pack fade, force-reveals the current
	 * batch (skipping the deal/flip animation) if pulls are resolvable, or advances past a finished batch.
	 * @return {@code true} if this call closed the reveal overlay entirely
	 */
	public synchronized boolean advanceFromKeyboard()
	{
		if (phase == Phase.IDLE)
		{
			return false;
		}

		if (phase == Phase.PACK_READY)
		{
			phase = Phase.PACK_FADING;
			phaseStartedAt = System.currentTimeMillis();
			return false;
		}

		int batchSize = visibleCount();
		if (phase == Phase.PACK_FADING || phase == Phase.AWAITING_PULLS || phase == Phase.CARD_DEAL
			|| (phase == Phase.CARD_REVEAL && revealedCount < batchSize))
		{
			if (awaitingServerPulls || cards.isEmpty() || !hasResolvablePulls())
			{
				return false;
			}
			forceRevealBatchAndWaitClose();
			return false;
		}

		return advancePastWaitClose();
	}
/** Starts the next card batch if any remain, otherwise closes the reveal. @return {@code true} if the reveal closed */
	private boolean advancePastWaitClose()
	{
		if (hasMoreBatches())
		{
			startNextBatch();
			return false;
		}
		reset();
		return true;
	}
/** Marks every card in the current batch revealed immediately, announces pulls, and enters {@link Phase#WAIT_CLOSE}. */
	private void forceRevealBatchAndWaitClose()
	{
		int batchSize = visibleCount();
		if (phase == Phase.CARD_REVEAL && revealedCount < batchSize)
		{
			packRevealSoundService.playCardFlip();
		}
		announcePartyUnrevealedPulls(true);
		if (hasUnrevealedPremiumAudio(visibleCards(), revealedByIndex))
		{
			packRevealSoundService.playMythicReveal();
		}
		revealedCount = batchSize;
		for (int i = 0; i < revealedByIndex.length; i++)
		{
			revealedByIndex[i] = true;
		}
		for (int i = 0; i < flipStartedAtMs.length; i++)
		{
			flipStartedAtMs[i] = 0L;
		}
		notifyPackAtBatchEnd();
		phase = Phase.WAIT_CLOSE;
		phaseStartedAt = System.currentTimeMillis();
	}
/**
	 * Timer-driven: advances time-based phase transitions (pending-pulls timeout, pack fade to deal/await,
	 * deal to reveal, reveal to wait-close once fully face-up). Called once per paint frame via
	 * {@link #capturePaintFrame()}.
	 */
	public synchronized void tick()
	{
		if (awaitingServerPulls
			&& pendingRevealStartedAtMs > 0L
			&& (System.currentTimeMillis() - pendingRevealStartedAtMs) >= PENDING_PULLS_TIMEOUT_MS)
		{
			pendingPullsTimedOut = true;
			packRevealSoundService.hardStop();
			reset();
			return;
		}

		if (phase == Phase.PACK_FADING && phaseStartedAt > 0L && (System.currentTimeMillis() - phaseStartedAt) >= PACK_FADE_MS)
		{
			if (cards.isEmpty())
			{
				phase = Phase.AWAITING_PULLS;
				phaseStartedAt = System.currentTimeMillis();
			}
			else
			{
				phase = Phase.CARD_DEAL;
				phaseStartedAt = System.currentTimeMillis();
			}
		}
		else if (phase == Phase.CARD_DEAL && phaseStartedAt > 0L
			&& (System.currentTimeMillis() - phaseStartedAt) >= packDealPhaseTotalMs(visibleCount()))
		{
			if (awaitingServerPulls || !hasResolvablePulls())
			{
				return;
			}
			phase = Phase.CARD_REVEAL;
			phaseStartedAt = System.currentTimeMillis();
		}
		else if (phase == Phase.CARD_REVEAL && allRevealSlotsFaceUp())
		{
			enterWaitCloseAfterBatch();
		}
	}
/** Whether every card in the batch has a real (non-placeholder) pull identity, i.e. the server has responded. */
	private boolean hasResolvablePulls()
	{
		if (cards.isEmpty())
		{
			return false;
		}
		for (RevealCard card : cards)
		{
			if (!hasRealPullIdentity(card))
			{
				return false;
			}
		}
		return true;
	}
/** Total duration of the deal animation for a batch of {@code cardCount} cards (stagger between cards plus one flight). */
	public static long packDealPhaseTotalMs(int cardCount)
	{
		if (cardCount <= 0)
		{
			return 0L;
		}
		return (long) (cardCount - 1) * PACK_DEAL_STAGGER_MS + PACK_DEAL_FLIGHT_MS;
	}
/** Whether a reveal is in progress (any phase other than {@link Phase#IDLE}). */
	public synchronized boolean isActive()
	{
		return phase != Phase.IDLE;
	}
/**
	 * Timer-driven: advances the state machine ({@link #tick()}, completing any finished card flips) and
	 * returns an immutable snapshot of the current frame for the overlay to paint, or empty if there's
	 * nothing to draw.
	 */
	public synchronized Optional<RevealPaintSnapshot> capturePaintFrame()
	{
		tick();
		completeFinishedFlipsLocked();
		if (phase == Phase.IDLE)
		{
			return Optional.empty();
		}
		if (cards.isEmpty()
			&& phase != Phase.PACK_READY
			&& phase != Phase.PACK_FADING
			&& phase != Phase.AWAITING_PULLS)
		{
			return Optional.empty();
		}
		long phaseElapsedMs = computePhaseElapsedMsLocked();
		double packFadeProgress = computePackFadeProgressLocked();
		boolean[] revCopy = Arrays.copyOf(revealedByIndex, revealedByIndex.length);
		float[] flipCopy = buildFlipProgressLocked();
		return Optional.of(new RevealPaintSnapshot(
			phase,
			List.copyOf(visibleCards()),
			revCopy,
			flipCopy,
			phaseElapsedMs,
			packFadeProgress,
			boosterPackId,
			apexPackOpen));
	}
/**
	 * Marks any in-progress card flip revealed once {@link #CARD_FLIP_MS} has elapsed since it started, and
	 * enters {@link Phase#WAIT_CLOSE} if that completes the batch.
	 */
	private void completeFinishedFlipsLocked()
	{
		if (flipStartedAtMs.length == 0)
		{
			return;
		}
		long now = System.currentTimeMillis();
		boolean anyCompleted = false;
		for (int i = 0; i < flipStartedAtMs.length; i++)
		{
			if (flipStartedAtMs[i] <= 0L)
			{
				continue;
			}
			if (i < revealedByIndex.length && revealedByIndex[i])
			{
				flipStartedAtMs[i] = 0L;
				continue;
			}
			if (now - flipStartedAtMs[i] < CARD_FLIP_MS)
			{
				continue;
			}
			if (i < revealedByIndex.length && !revealedByIndex[i])
			{
				revealedByIndex[i] = true;
				revealedCount++;
				anyCompleted = true;
				int absIndex = batchOffset + i;
				if (absIndex >= 0 && absIndex < cards.size())
				{
					notifyPullAndMarkPosted(cards.get(absIndex), absIndex);
				}
			}
			flipStartedAtMs[i] = 0L;
		}
		if (anyCompleted && phase == Phase.CARD_REVEAL && revealedCount >= visibleCount() && visibleCount() > 0)
		{
			enterWaitCloseAfterBatch();
		}
	}
/** Computes per-card eased flip progress (1 if revealed, 0 if not started, eased elapsed fraction otherwise). */
	private float[] buildFlipProgressLocked()
	{
		float[] out = new float[Math.max(revealedByIndex.length, flipStartedAtMs.length)];
		long now = System.currentTimeMillis();
		for (int i = 0; i < out.length; i++)
		{
			if (i < revealedByIndex.length && revealedByIndex[i])
			{
				out[i] = 1f;
				continue;
			}
			if (i >= flipStartedAtMs.length || flipStartedAtMs[i] <= 0L)
			{
				out[i] = 0f;
				continue;
			}
			float linear = (float) ((now - flipStartedAtMs[i]) / (double) CARD_FLIP_MS);
			out[i] = CardFlipEasing.flipEase(Math.max(0f, Math.min(1f, linear)));
		}
		return out;
	}
/** Milliseconds elapsed since the current phase began, or 0 if the phase has no start time. */
	private long computePhaseElapsedMsLocked()
	{
		if (phaseStartedAt <= 0L)
		{
			return 0L;
		}
		return Math.max(0L, System.currentTimeMillis() - phaseStartedAt);
	}
/** Pack-sleeve fade progress (0..1): 1 once past the fade, in-progress fraction during {@code PACK_FADING}, else 0. */
	private double computePackFadeProgressLocked()
	{
		if (phase == Phase.AWAITING_PULLS
			|| phase == Phase.CARD_DEAL
			|| phase == Phase.CARD_REVEAL
			|| phase == Phase.WAIT_CLOSE)
		{
			return 1.0d;
		}
		if (phase != Phase.PACK_FADING || phaseStartedAt <= 0L)
		{
			return 0.0d;
		}
		double elapsed = (double) (System.currentTimeMillis() - phaseStartedAt);
		return PackRevealDealLayout.clamp01(elapsed / (double) PACK_FADE_MS);
	}
/** Current reveal phase. */
	public synchronized Phase getPhase()
	{
		return phase;
	}
/** Cards in the currently visible batch (up to {@link #MAX_VISIBLE_REVEAL_CARDS}). */
	public synchronized List<RevealCard> getCards()
	{
		return List.copyOf(visibleCards());
	}
/** Whether the visible card at {@code index} has completed its flip. */
	public synchronized boolean isCardRevealed(int index)
	{
		return index >= 0 && index < revealedByIndex.length && revealedByIndex[index];
	}
/** Whether a reveal has started but the server's pulls haven't arrived yet. */
	public synchronized boolean isAwaitingServerPulls()
	{
		return awaitingServerPulls;
	}
/** Consumes (clears) and returns whether the pending-pulls wait timed out since the last call. */
	public synchronized boolean consumePendingPullsTimeout()
	{
		if (!pendingPullsTimedOut)
		{
			return false;
		}
		pendingPullsTimedOut = false;
		return true;
	}
/** Clears all reveal state and returns to {@link Phase#IDLE}. */
	public synchronized void reset()
	{
		phase = Phase.IDLE;
		cards = List.of();
		batchOffset = 0;
		revealedCount = 0;
		revealedByIndex = new boolean[0];
		collectionChatPosted = new boolean[0];
		flipStartedAtMs = new long[0];
		phaseStartedAt = 0L;
		boosterPackId = "";
		apexPackOpen = false;
		awaitingServerPulls = false;
		pendingRevealStartedAtMs = 0L;
		preOwnedFoilNames = Set.of();
	}
/** Lower-cased names of cards the player already owned as foils before this reveal, for "already have" UI hints. */
	public synchronized Set<String> getPreOwnedFoilNames()
	{
		return Set.copyOf(preOwnedFoilNames);
	}
/** Extracts lower-cased, normalized names of foil cards from the pre-reveal owned-cards set. */
	private static Set<String> buildPreOwnedFoilNames(Set<CardCollectionKey> preOwnedCards)
	{
		if (preOwnedCards == null || preOwnedCards.isEmpty())
		{
			return Set.of();
		}
		return preOwnedCards.stream()
			.filter(Objects::nonNull)
			.filter(CardCollectionKey::isFoil)
			.map(CardCollectionKey::getCardName)
			.filter(name -> name != null && !name.isBlank())
			.map(name -> name.trim().toLowerCase(Locale.ROOT))
			.collect(Collectors.toUnmodifiableSet());
	}
/**
	 * Force-closes an in-progress reveal (e.g. plugin shutdown or forced navigation away): announces any
	 * unrevealed pulls and pending collection chat, stops sounds, resets to idle, and returns the full
	 * card list that was in play.
	 */
	public synchronized List<RevealCard> abortActiveReveal()
	{
		if (!isActive())
		{
			return List.of();
		}
		announcePartyUnrevealedPulls(false);
		announceRemainingCollectionChat();
		List<RevealCard> snapshot = List.copyOf(cards);
		packRevealSoundService.hardStop();
		reset();
		return snapshot;
	}
/** Posts the collection-add chat message for any real pull that hasn't had one posted yet. */
	private void announceRemainingCollectionChat()
	{
		for (int i = 0; i < cards.size(); i++)
		{
			if (i < collectionChatPosted.length && collectionChatPosted[i])
			{
				continue;
			}
			RevealCard card = cards.get(i);
			if (!hasRealPullIdentity(card))
			{
				continue;
			}
			pullNotificationService.postCollectionAddChat(card);
			if (i < collectionChatPosted.length)
			{
				collectionChatPosted[i] = true;
			}
		}
	}
/** Whether {@code card} carries an actual server pull (as opposed to a placeholder awaiting server pulls). */
	private static boolean hasRealPullIdentity(RevealCard card)
	{
		return card != null
			&& card.getPull() != null
			&& card.getPull().getCardName() != null
			&& !card.getPull().getCardName().isBlank();
	}
/** Posts the pull notification for {@code card} and marks its collection chat as posted if it was sent. */
	private void notifyPullAndMarkPosted(RevealCard card, int absIndex)
	{
		if (pullNotificationService.notifyPull(
			cardNameForParty(card),
			card.isNew(),
			isFoilPull(card),
			card.getTier(),
			CardInfoTipModel.instanceIdFor(card),
			card.getPull().getCondition())
			&& absIndex < collectionChatPosted.length)
		{
			collectionChatPosted[absIndex] = true;
		}
	}
/** Whether any not-yet-revealed card in {@code cards} would trigger premium (mythic/legendary-foil) reveal audio. */
	private static boolean hasUnrevealedPremiumAudio(List<RevealCard> cards, boolean[] revealedByIndex)
	{
		for (int i = 0; i < cards.size(); i++)
		{
			boolean revealed = i < revealedByIndex.length && revealedByIndex[i];
			if (revealed)
			{
				continue;
			}
			if (isPremiumRevealAudioPull(cards.get(i)))
			{
				return true;
			}
		}
		return false;
	}
/** Index of the card bounds rectangle containing {@code click}, or -1 if none matched. */
	private int clickedCardIndex(List<Rectangle> bounds, Point click)
	{
		if (bounds == null || click == null)
		{
			return -1;
		}
		for (int i = 0; i < bounds.size(); i++)
		{
			Rectangle boundsAtIndex = bounds.get(i);
			if (boundsAtIndex != null && boundsAtIndex.contains(click))
			{
				return i;
			}
		}
		return -1;
	}
/**
	 * Posts pull notifications for cards not yet revealed. When {@code currentBatchOnly} is true, limits
	 * this to the visible batch (used when force-revealing it); otherwise covers every unrevealed card
	 * across the whole reveal (used when aborting).
	 */
	private void announcePartyUnrevealedPulls(boolean currentBatchOnly)
	{
		if (currentBatchOnly)
		{
			for (int i = 0; i < revealedByIndex.length; i++)
			{
				if (revealedByIndex[i])
				{
					continue;
				}
				int absIndex = batchOffset + i;
				if (absIndex < 0 || absIndex >= cards.size())
				{
					continue;
				}
				notifyPullAndMarkPosted(cards.get(absIndex), absIndex);
			}
			return;
		}
		for (int absIndex = 0; absIndex < cards.size(); absIndex++)
		{
			if (isAbsolutelyRevealed(absIndex))
			{
				continue;
			}
			notifyPullAndMarkPosted(cards.get(absIndex), absIndex);
		}
	}
/** Notifies party/chat of the full pack contents once every 5th card position is reached (i.e. pack fully revealed). */
	private void notifyPackAtBatchEnd()
	{
		if ((batchOffset + visibleCount()) % 5 == 0)
		{
			pullNotificationService.notifyPackAtEnd(List.copyOf(visibleCards()));
		}
	}
/** Whether the card at absolute index {@code absIndex} (across all batches) has been revealed. */
	private boolean isAbsolutelyRevealed(int absIndex)
	{
		if (absIndex < batchOffset)
		{
			return true;
		}
		int local = absIndex - batchOffset;
		if (local >= 0 && local < revealedByIndex.length)
		{
			return revealedByIndex[local];
		}
		return false;
	}
/** Whether {@code card} should play the premium reveal sting: any Godly pull, or a foil Legendary+ pull. */
	private static boolean isPremiumRevealAudioPull(RevealCard card)
	{
		if (card == null)
		{
			return false;
		}
		if (card.getTier() == RarityMath.Tier.GODLY)
		{
			return true;
		}
		if (!isFoilPull(card))
		{
			return false;
		}
		return card.getTier().ordinal() >= RarityMath.Tier.LEGENDARY.ordinal();
	}
/** Whether {@code card}'s underlying pull is a foil. */
	private static boolean isFoilPull(RevealCard card)
	{
		return card != null && card.getPull() != null && card.getPull().isFoil();
	}
/** Whether every slot in the current batch is revealed (and the batch is fully sized/populated). */
	private boolean allRevealSlotsFaceUp()
	{
		int batchSize = visibleCount();
		if (batchSize <= 0 || revealedByIndex.length != batchSize)
		{
			return false;
		}
		for (int i = 0; i < revealedByIndex.length; i++)
		{
			if (!revealedByIndex[i])
			{
				return false;
			}
		}
		return true;
	}
/** Number of cards visible in the current batch, capped at {@link #MAX_VISIBLE_REVEAL_CARDS}. */
	private int visibleCount()
	{
		if (cards.isEmpty() || batchOffset >= cards.size())
		{
			return 0;
		}
		return Math.min(MAX_VISIBLE_REVEAL_CARDS, cards.size() - batchOffset);
	}
/** The sublist of {@link #cards} making up the current batch. */
	private List<RevealCard> visibleCards()
	{
		int n = visibleCount();
		if (n <= 0)
		{
			return List.of();
		}
		return cards.subList(batchOffset, batchOffset + n);
	}
/** Whether cards remain beyond the current batch. */
	private boolean hasMoreBatches()
	{
		return batchOffset + visibleCount() < cards.size();
	}
/** (Re)allocates the per-slot revealed/flip-start arrays for the current batch and resets the revealed count. */
	private void initCurrentBatchRevealFlags()
	{
		int n = visibleCount();
		revealedCount = 0;
		revealedByIndex = new boolean[n];
		flipStartedAtMs = new long[n];
	}
/** Advances the batch offset past the current batch and begins dealing the next one. */
	private void startNextBatch()
	{
		batchOffset += visibleCount();
		initCurrentBatchRevealFlags();
		packRevealSoundService.resetDealMotionSounds();
		phase = Phase.CARD_DEAL;
		phaseStartedAt = System.currentTimeMillis();
	}
/** Notifies the full pack contents if this batch completes it, then enters {@link Phase#WAIT_CLOSE}. */
	private void enterWaitCloseAfterBatch()
	{
		notifyPackAtBatchEnd();
		phase = Phase.WAIT_CLOSE;
		phaseStartedAt = System.currentTimeMillis();
	}
}

package com.osrstcg.pack;

import com.osrstcg.OsrsTcgConfig;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;
/**
 * Plays the pack-reveal sound effects (mythic hum/reveal, card flip, card deal stagger, apex hover),
 * gated by {@link OsrsTcgConfig#enableSounds()}. Not thread-confined to the client thread, but all
 * public methods are {@code synchronized} against shared per-resource/per-reveal state.
 */
@Slf4j
@Singleton
public class PackRevealSoundService
{
	private static final String HUM_RESOURCE = "/com/osrstcg/sounds/hum.wav";

	private static final String REVEAL_RESOURCE = "/com/osrstcg/sounds/reveal.wav";
	private static final String CARD_DEAL_RESOURCE = "/com/osrstcg/sounds/card.wav";
	private static final String FLIP_RESOURCE = "/com/osrstcg/sounds/flip.wav";
	private static final String APEX_PACK_HOVER_RESOURCE = "/com/osrstcg/sounds/apex.wav";

	private static final float GAIN_APEX_HOVER_DB = linearGainToDb(0.425f);

	private final OsrsTcgConfig config;
	private final AudioPlayer audioPlayer;

	private boolean humOpenFailed;
	private boolean humPlayedThisReveal;

	private boolean revealOpenFailed;
	private boolean flipOpenFailed;
	private boolean cardDealOpenFailed;
	private boolean apexHoverOpenFailed;
/** Greatest card index whose deal-start sound has been played this deal phase ({@code -1} = none). */
	private int dealMotionSoundUpToIndex = -1;
/** Wires the config (for the sound-enabled toggle) and the shared audio player. */
	@Inject
	public PackRevealSoundService(OsrsTcgConfig config, AudioPlayer audioPlayer)
	{
		this.config = config;
		this.audioPlayer = audioPlayer;
	}
/** Plays the mythic hum once per reveal, when wanted and not previously failed/played. */
	public synchronized void tryPlayMythicHum(boolean humWanted)
	{
		if (!config.enableSounds() || humOpenFailed || humPlayedThisReveal || !humWanted)
		{
			return;
		}

		if (!playResource(HUM_RESOURCE, "hum.wav", 0f))
		{
			humOpenFailed = true;
			return;
		}

		humPlayedThisReveal = true;
	}
/** Plays the mythic/legendary-foil reveal sting. */
	public synchronized void playMythicReveal()
	{
		if (!config.enableSounds() || revealOpenFailed)
		{
			return;
		}
		if (!playResource(REVEAL_RESOURCE, "reveal.wav", 0f))
		{
			revealOpenFailed = true;
		}
	}
/** Plays the card-flip sound. */
	public synchronized void playCardFlip()
	{
		if (!config.enableSounds() || flipOpenFailed)
		{
			return;
		}
		if (!playResource(FLIP_RESOURCE, "flip.wav", 0f))
		{
			flipOpenFailed = true;
		}
	}
/** Plays the apex-pack hover sound once, at reduced gain; no-ops after it fails to open. */
	public synchronized void playApexPackHoverOneShot()
	{
		if (!config.enableSounds() || apexHoverOpenFailed)
		{
			return;
		}
		if (!playResource(APEX_PACK_HOVER_RESOURCE, "apex.wav", GAIN_APEX_HOVER_DB))
		{
			apexHoverOpenFailed = true;
		}
	}
/**
	 * Timer-driven: called every paint frame during the card-deal phase to play one deal-stagger sound
	 * per card whose stagger offset ({@code index * staggerMs}) has elapsed since the phase began.
	 * Resets the played-up-to index when the deal phase isn't active.
	 */
	public synchronized void tickDealMotionSounds(boolean dealPhaseActive, long elapsedMs, int cardCount, long staggerMs)
	{
		if (!dealPhaseActive || !config.enableSounds())
		{
			dealMotionSoundUpToIndex = -1;
			return;
		}

		if (cardCount <= 0 || staggerMs <= 0L || cardDealOpenFailed)
		{
			return;
		}

		while (dealMotionSoundUpToIndex + 1 < cardCount)
		{
			int next = dealMotionSoundUpToIndex + 1;
			if (elapsedMs < next * staggerMs)
			{
				break;
			}
			if (!playResource(CARD_DEAL_RESOURCE, "card.wav", 0f))
			{
				cardDealOpenFailed = true;
				break;
			}
			dealMotionSoundUpToIndex = next;
		}
	}
/** Resets the deal-stagger progress so the next batch's deal sounds play from the start. */
	public synchronized void resetDealMotionSounds()
	{
		dealMotionSoundUpToIndex = -1;
	}
/** Clears per-reveal sound state (mythic hum played flag, deal-stagger progress) when a reveal ends or aborts. */
	public synchronized void hardStop()
	{
		humPlayedThisReveal = false;
		dealMotionSoundUpToIndex = -1;
	}
/**
	 * Plays the given resource at {@code gainDb}, logging and returning {@code false} if the resource is
	 * missing or playback throws.
	 */
	private boolean playResource(String resourcePath, String logName, float gainDb)
	{
		if (PackRevealSoundService.class.getResource(resourcePath) == null)
		{
			log.warn("Missing resource {}", resourcePath);
			return false;
		}

		try
		{
			audioPlayer.play(PackRevealSoundService.class, resourcePath, gainDb);
			return true;
		}
		catch (Exception ex)
		{
			log.warn("Could not play {} ({})", logName, resourcePath, ex);
			return false;
		}
	}
/** Converts a 0..1 linear gain to decibels, clamping input to {@code [0, 1]} and flooring silence at -80dB. */
	private static float linearGainToDb(float linear01)
	{
		float v = Math.max(0f, Math.min(1f, linear01));
		if (v < 0.0005f)
		{
			return -80f;
		}
		return (float) (20.0 * Math.log10(v));
	}
}

package com.osrstcg.pack;

import com.osrstcg.catalog.CardDatabase;
import com.osrstcg.catalog.CardDefinition;
import com.osrstcg.catalog.RarityMath;
import com.osrstcg.cloud.api.CloudEndpoints;
import com.osrstcg.state.CardCollectionKey;
import com.osrstcg.state.PackCardResult;
import com.osrstcg.util.CardDisplayNames;
import java.awt.Color;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;
import lombok.extern.slf4j.Slf4j;
/**
 * Resolves server pack pulls into overlay {@link PackRevealService.RevealCard}s (placeholders,
 * catalog materialization, rarity index). Callers must hold the reveal-service lock.
 */
@Slf4j
final class RevealCardResolver
{
	private final CardDatabase cardDatabase;
	private final Map<String, RarityMath.Tier> rarityTierByCardName = new HashMap<>();

	RevealCardResolver(CardDatabase cardDatabase)
	{
		this.cardDatabase = cardDatabase;
	}
/** Rebuilds the card-name-to-rarity-tier lookup from the current catalog; call before resolving a reveal. */
	void rebuildRarityTierIndex()
	{
		rarityTierByCardName.clear();
		for (CardDefinition card : cardDatabase.getCards())
		{
			if (card == null || card.getName() == null || card.getName().trim().isEmpty())
			{
				continue;
			}
			RarityMath.Tier tier = RarityMath.tierFromLabel(card.getTierLabel());
			rarityTierByCardName.put(card.getName().toLowerCase(), tier);
		}
	}
/** Builds {@code count} face-down common placeholder cards shown while server pulls are pending. */
	List<PackRevealService.RevealCard> createPlaceholderCards(int count)
	{
		if (count <= 0)
		{
			return List.of();
		}
		List<PackRevealService.RevealCard> out = new ArrayList<>(count);
		Color commonColor = RarityMath.Tier.COMMON.getColor();
		for (int i = 0; i < count; i++)
		{
			out.add(new PackRevealService.RevealCard(
				new PackCardResult("", false),
				null,
				RarityMath.Tier.COMMON,
				commonColor,
				false));
		}
		return List.copyOf(out);
	}
/**
	 * Converts server pack pulls into {@link PackRevealService.RevealCard}s: resolves each pull against the
	 * card catalog, materializes a display definition, resolves rarity tier, and flags cards not already
	 * present in {@code preOwnedCards} as new. Pulls with a null card name are dropped.
	 */
	List<PackRevealService.RevealCard> resolveRevealCards(List<PackCardResult> pulls, Set<CardCollectionKey> preOwnedCards)
	{
		if (pulls == null || pulls.isEmpty())
		{
			return List.of();
		}
		List<PackRevealService.RevealCard> resolved = new ArrayList<>();
		Set<String> preOwnedKeys = preOwnedCards == null ? Set.of() : preOwnedCards.stream()
			.filter(Objects::nonNull)
			.map(k -> normalizeKey(k.getCardName(), k.isFoil()))
			.collect(Collectors.toSet());
		for (PackCardResult pull : pulls)
		{
			if (pull == null || pull.getCardName() == null)
			{
				continue;
			}

			CardDefinition catalog = findCard(pull.getCardName()).orElse(null);
			CardDefinition definition = materializeRevealDefinition(pull, catalog);
			RarityMath.Tier tier = tierForPackPull(pull, pull.getCardName());
			Color rarityColor = tier.getColor();
			boolean isNew = !preOwnedKeys.contains(normalizeKey(pull.getCardName(), pull.isFoil()));
			resolved.add(new PackRevealService.RevealCard(pull, definition, tier, rarityColor, isNew));
		}
		return resolved;
	}
/**
	 * Prefer server {@code tierLabel} for cloud pack pulls; otherwise local catalog display tier.
	 */
	RarityMath.Tier tierForPackPull(PackCardResult pull, String catalogCardName)
	{
		if (pull != null && pull.hasServerTier())
		{
			Optional<RarityMath.Tier> parsed = RarityMath.tryParseTierLabel(pull.getTierLabel());
			if (parsed.isEmpty())
			{
				log.warn("Unknown pack pull tierLabel '{}' for card '{}' - using Common",
					pull.getTierLabel(), pull.getCardName());
				return RarityMath.Tier.COMMON;
			}
			return parsed.get();
		}
		return tierForCard(catalogCardName);
	}
/**
	 * Builds the {@link CardDefinition} shown for a pull: starts from the local catalog entry when found
	 * (falling back to a minimal definition otherwise), then overlays server-supplied image paths, artist
	 * credit, examine text, wiki page, and score/tier for pulls carrying server data.
	 */
	private CardDefinition materializeRevealDefinition(PackCardResult pull, CardDefinition catalog)
	{
		CardDefinition definition = new CardDefinition();
		String title = CardDisplayNames.titleForPull(pull, catalog);
		if (catalog != null)
		{
			definition.setName(title);
			definition.setDisplayName(CardDisplayNames.firstNonBlank(
				pull != null ? pull.getDisplayName() : null,
				catalog.getDisplayName(),
				catalog.getName()));
			definition.setId(catalog.getId());
			definition.setCategory(catalog.getCategory() == null ? new ArrayList<>() : new ArrayList<>(catalog.getCategory()));
			definition.setRegions(catalog.getRegions() == null ? new ArrayList<>() : new ArrayList<>(catalog.getRegions()));
			definition.setImageUrl(catalog.getImageUrl());
			definition.setLevel(catalog.getLevel());
			definition.setValue(catalog.getValue());
			definition.setScore(catalog.getScore());
			definition.setFoilScore(catalog.getFoilScore());
			definition.setTierLabel(catalog.getTierLabel());
			definition.setExamine(catalog.getExamine());
			definition.setWikiPage(catalog.getWikiPage());
		}
		else
		{
			definition.setName(title);
			definition.setDisplayName(pull != null ? pull.getDisplayName() : null);
			definition.setCategory(new ArrayList<>());
		}

		if (pull.getImagePath() != null && !pull.getImagePath().isBlank())
		{
			String absolute = CloudEndpoints.resolvePublicUrl(pull.getImagePath());
			if (absolute != null && !absolute.isBlank())
			{
				definition.setImageUrl(absolute);
			}
		}
		if (pull.getFoilImagePath() != null && !pull.getFoilImagePath().isBlank())
		{
			String absolute = CloudEndpoints.resolvePublicUrl(pull.getFoilImagePath());
			if (absolute != null && !absolute.isBlank())
			{
				definition.setFoilImagePath(absolute);
			}
			if (pull.getArtistName() != null && !pull.getArtistName().isBlank())
			{
				definition.setArtistName(pull.getArtistName());
			}
			if (pull.getArtistColor() != null && !pull.getArtistColor().isBlank())
			{
				definition.setArtistColor(pull.getArtistColor());
			}
			if (pull.getArtistUrl() != null && !pull.getArtistUrl().isBlank())
			{
				definition.setArtistUrl(pull.getArtistUrl());
			}
			if (pull.getExamine() != null && !pull.getExamine().isBlank())
			{
				definition.setExamine(pull.getExamine());
			}
		}
		if (pull.getWikiPage() != null && !pull.getWikiPage().isBlank())
		{
			definition.setWikiPage(pull.getWikiPage());
		}

		if (pull.hasServerTier() || pull.getScore() > 0L)
		{
			if (pull.isFoil())
			{
				definition.setFoilScore(pull.getScore());
			}
			else
			{
				definition.setScore(pull.getScore());
			}
			if (pull.getTierLabel() != null && !pull.getTierLabel().isBlank())
			{
				definition.setTierLabel(pull.getTierLabel());
			}
			definition.setValue(null);
		}
		return definition;
	}
/** Case-insensitive lookup of a catalog card by name. */
	private Optional<CardDefinition> findCard(String name)
	{
		return cardDatabase.getCards().stream()
			.filter(Objects::nonNull)
			.filter(c -> c.getName() != null && c.getName().equalsIgnoreCase(name))
			.findFirst();
	}
/** Looks up the local catalog display tier for a card name, defaulting to {@code COMMON} when unknown. */
	private RarityMath.Tier tierForCard(String cardName)
	{
		if (cardName == null)
		{
			return RarityMath.Tier.COMMON;
		}
		return rarityTierByCardName.getOrDefault(cardName.toLowerCase(), RarityMath.Tier.COMMON);
	}
/** Builds a case-insensitive, foil-aware dedup key for pre-owned-card comparisons. */
	private static String normalizeKey(String cardName, boolean foil)
	{
		return (cardName == null ? "" : cardName.trim().toLowerCase()) + "|" + (foil ? "1" : "0");
	}
}

package com.osrstcg.ui;

import com.osrstcg.catalog.CardDefinition;
import com.osrstcg.catalog.RarityMath;
import com.osrstcg.ui.card.CardColorMath;
import com.osrstcg.ui.card.CardFaceDrawRequest;
import com.osrstcg.ui.card.CardFonts;
import com.osrstcg.ui.card.CardFxPainter;
import com.osrstcg.ui.card.ExamineTextLayout;
import com.osrstcg.ui.card.FoilFx;
import com.osrstcg.ui.card.WearFx;
import com.osrstcg.util.NumberFormatting;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.List;
import net.runelite.client.ui.ColorScheme;
/**
 * Rasterizes card faces and backs (banded and full-art layouts) for {@link TcgPanel} and other card
 * UI. Rendering itself is pure AWT/Graphics2D work with no threading requirement; callers on the EDT
 * typically go through {@link CardFaceCache} to avoid re-rendering on every repaint.
 */
public final class SharedCardRenderer
{
	public static final int DEFAULT_CARD_WIDTH = 180;
	public static final int DEFAULT_CARD_HEIGHT = 260;

	private static final Color FRAME_DARK = new Color(0x1A1A1A);
	private static final Color FOIL_FRAME_GOLD = new Color(0xD4AF37);
	private static final Color PANEL_DARK = new Color(0x222222);
	private static final Color PANEL_MID = new Color(0x2F2F2F);

	private static final int[] BAND_FRACTIONS = {10, 40, 10, 30, 10};
	private static final float BANDED_TITLE_EM_MIN = 0.80f;
	private static final int BANDED_TITLE_FIT_STEPS = 10;

	public static final String CARD_BACK_PATH = "/images/Cardback_new.png";
/** Not instantiated; all members are static. */
	private SharedCardRenderer()
	{
	}
/**
	 * Paints the request's face into {@code bounds} only if already rasterized in {@link CardFaceCache};
	 * does not render on a miss. Returns whether it painted anything.
	 */
	public static boolean drawCardFaceIfCached(Graphics2D g, Rectangle bounds, CardFaceDrawRequest req)
	{
		if (g == null || bounds == null || req == null || bounds.width < 4 || bounds.height < 4)
		{
			return false;
		}
		BufferedImage face = CardFaceCache.getIfPresent(bounds.width, bounds.height, req);
		if (face == null)
		{
			return false;
		}
		paintCachedFace(g, bounds, req, face);
		return true;
	}
/** Blits a pre-rendered face image and, for foil requests, overlays an animated sparkle pass on top. */
	private static void paintCachedFace(Graphics2D g, Rectangle bounds, CardFaceDrawRequest req, BufferedImage face)
	{
		g.drawImage(face, bounds.x, bounds.y, null);

		FoilFx foilFx = req.getFoilFx();
		if (foilFx != null && req.isFoil())
		{
			double scale = bounds.width / (double) DEFAULT_CARD_WIDTH;
			CardFxPainter.drawAnimatedSparkles(
				g,
				bounds.x,
				bounds.y,
				bounds.width,
				bounds.height,
				outerRadius(bounds.width),
				scale,
				foilFx,
				System.nanoTime() / 1_000_000_000.0d);
		}
	}
/** Draws the card back into {@code bounds}: the given image if provided, else a plain foil/dark placeholder. */
	public static void drawCardBack(Graphics2D g, Rectangle bounds, boolean foil,
		BufferedImage cardBack)
	{
		if (g == null || bounds == null || bounds.width < 2 || bounds.height < 2)
		{
			return;
		}

		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			enableQuality(g2);
			double radius = outerRadius(bounds.width);
			Shape card = new RoundRectangle2D.Double(bounds.x, bounds.y, bounds.width, bounds.height, radius * 2.0d, radius * 2.0d);
			g2.clip(card);

			if (cardBack != null)
			{
				drawCoverCentered(g2, cardBack, bounds);
				return;
			}

			g2.setColor(foil ? FOIL_FRAME_GOLD : FRAME_DARK);
			g2.fill(card);
			CardTextLayout.drawCenteredText(g2, bounds, "OSRS TCG", CardFonts.bold(bounds.width / (double) DEFAULT_CARD_WIDTH), Color.WHITE, 0);
		}
		finally
		{
			g2.dispose();
		}
	}
/** Maps a rarity color back to its {@link RarityMath.Tier} label; falls back to Common if no tier matches. */
	public static String tierLabelForRarityColor(Color color)
	{
		if (color == null)
		{
			return RarityMath.Tier.COMMON.getLabel();
		}
		for (RarityMath.Tier tier : RarityMath.Tier.values())
		{
			if (tier.getColor().getRGB() == color.getRGB())
			{
				return tier.getLabel();
			}
		}
		return RarityMath.Tier.COMMON.getLabel();
	}
/** Renders and caches a face ahead of paint time, skipping requests with no size or missing art. */
	public static void prewarmFace(int w, int h, CardFaceDrawRequest req)
	{
		if (req == null || w < 4 || h < 4 || CardFaceCache.expectsArtButMissing(req))
		{
			return;
		}
		CardFaceCache.cachedFace(w, h, req);
	}
/** Returns whether {@code req} already has a rendered face cached at this size, without rendering it. */
	public static boolean isFaceCached(int w, int h, CardFaceDrawRequest req)
	{
		if (req == null || w < 4 || h < 4)
		{
			return false;
		}
		return CardFaceCache.contains(w, h, req);
	}
/**
	 * Fully rasterizes a card face at {@code w}x{@code h}: banded or full-art layout per
	 * {@link CardFaceDrawRequest#isFullArt()}, then wear filter/overlay if the request carries a
	 * {@link WearFx}. Called by {@link CardFaceCache} on a cache miss.
	 */
	static BufferedImage renderFace(int w, int h, CardFaceDrawRequest req)
	{
		BufferedImage face = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Geometry geo = new Geometry(w, h);

		Graphics2D g2 = face.createGraphics();
		try
		{
			enableQuality(g2);
			if (req.isFullArt())
			{
				paintFullArt(g2, geo, req);
			}
			else
			{
				paintBanded(g2, geo, req);
			}
		}
		finally
		{
			g2.dispose();
		}

		WearFx wear = req.getWear();
		if (wear != null)
		{
			CardFxPainter.applyWearFilter(face, wear.getGrade().getFade());
			CardFxPainter.drawWear(face, geo.outerRadius, wear);
		}
		return face;
	}
/** Paints the classic five-band layout: title, art, tier, examine text, and score bands stacked vertically. */
	private static void paintBanded(Graphics2D g2, Geometry geo, CardFaceDrawRequest req)
	{
		CardDefinition card = req.getCard();
		Color rarity = req.getRarityColor();

		Shape outer = new RoundRectangle2D.Double(0, 0, geo.width, geo.height, geo.outerRadius * 2.0d, geo.outerRadius * 2.0d);
		g2.setColor(req.isFoil() ? FOIL_FRAME_GOLD : FRAME_DARK);
		g2.fill(outer);

		if (req.isFoil())
		{
			drawInsetRing(g2, geo, new Color(255, 255, 255, 31));
		}

		Color themedDark = CardColorMath.blendColors(PANEL_DARK, rarity, 0.32d);
		Color themedMid = CardColorMath.blendColors(PANEL_MID, rarity, 0.20d);
		fillBand(g2, geo.title, themedDark, geo.bandRadius);
		fillBand(g2, geo.art, themedMid, geo.bandRadius);
		fillBand(g2, geo.tier, themedDark, geo.bandRadius);
		fillBand(g2, geo.examine, themedMid, geo.bandRadius);
		fillBand(g2, geo.score, themedDark, geo.bandRadius);

		Color titleColor = CardColorMath.brighterColor(rarity);
		String titleText = CardTextLayout.valueOrFallback(card == null ? null : card.getName(), "Unknown Card");
		int titleMaxWidth = Math.max(8, geo.title.width - geo.bandPadX * 2);
		Font titleFont = fitBandedTitleFont(g2, titleText, titleMaxWidth, geo.scale);
		int titleNudgeY = Math.max(2, (int) Math.round(3.0d * geo.scale));
		Rectangle titleBox = new Rectangle(
			geo.title.x,
			geo.title.y + titleNudgeY,
			geo.title.width,
			Math.max(1, geo.title.height - titleNudgeY));
		CardTextLayout.drawWrappedCentered(g2, titleBox, titleText, titleFont, titleColor, 1, geo.bandPadX, true);

		drawArt(g2, geo, req);

		String tierLabel = CardTextLayout.valueOrFallback(req.getTierLabel(), tierLabelForRarityColor(rarity));
		CardTextLayout.drawCenteredText(g2, geo.tier, tierLabel, CardFonts.bold(geo.scale), titleColor, geo.bandPadX);

		// ZWSP/blank examine = hide (never draw a placeholder).
		String examine = card == null || card.getExamine() == null ? "" : card.getExamine().replace("\u200B", "").trim();
		if (!examine.isEmpty())
		{
			drawExamine(g2, geo, examine);
		}

		CardTextLayout.drawCenteredText(g2, geo.score, "Score: " + scoreText(req),
			CardFonts.bold(geo.scale), Color.WHITE, geo.bandPadX);
	}
/**
	 * Paints the full-bleed art layout: art fills the inner well with title/examine/score overlaid as
	 * scrimmed, shadowed text. Disables text antialiasing/fractional metrics for crisper small text,
	 * restoring both hints in the {@code finally} block.
	 */
	private static void paintFullArt(Graphics2D g2, Geometry geo, CardFaceDrawRequest req)
	{
		CardDefinition card = req.getCard();
		Color rarity = req.getRarityColor();
		String tierLabel = CardTextLayout.valueOrFallback(req.getTierLabel(), tierLabelForRarityColor(rarity));
		boolean godlyRim = "Godly".equalsIgnoreCase(tierLabel);

		Object prevTextAa = g2.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
		Object prevFrac = g2.getRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS);
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		g2.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);

		Shape outer = new RoundRectangle2D.Double(0, 0, geo.width, geo.height, geo.outerRadius * 2.0d, geo.outerRadius * 2.0d);
		g2.setColor(godlyRim ? FOIL_FRAME_GOLD : rarity);
		g2.fill(outer);

		drawInsetRing(g2, geo, new Color(255, 255, 255, 46));

		Shape well = new RoundRectangle2D.Double(
			geo.innerX, geo.innerY, geo.innerW, geo.innerH,
			geo.innerRadius * 2.0d, geo.innerRadius * 2.0d);
		g2.setColor(FRAME_DARK);
		g2.fill(well);

		Shape prevClip = g2.getClip();
		try
		{
			g2.clip(well);
			BufferedImage art = req.getArt();
			if (art != null)
			{
				drawCoverCentered(g2, art, new Rectangle(geo.innerX, geo.innerY, geo.innerW, geo.innerH));
			}
			else
			{
				String imagePath = card == null ? null : card.getFoilImagePath();
				String artText = (imagePath != null && !imagePath.trim().isEmpty()) ? "Loading artwork..." : "No artwork";
				CardTextLayout.drawCenteredText(g2, new Rectangle(geo.innerX, geo.innerY, geo.innerW, geo.innerH),
					artText, CardFonts.body(geo.scale), ColorScheme.LIGHT_GRAY_COLOR, geo.fullPadX);
			}

			int titlePadY = Math.max(1, (int) Math.round(2.0d * geo.scale));
			int titlePadX = Math.max(1, (int) Math.round(6.0d * geo.scale));
			int titleNudgeY = Math.max(2, (int) Math.round(3.0d * geo.scale));
			Font titleFont = CardFonts.fullArtTitle(geo.scale);
			FontMetrics titleFm = g2.getFontMetrics(titleFont);
			int titleScrimH = Math.min(geo.innerH,
				titlePadY + titleNudgeY + titleFm.getHeight() + Math.max(2, (int) Math.round(4.0d * geo.scale)));
			Rectangle titleScrim = new Rectangle(geo.innerX, geo.innerY, geo.innerW, titleScrimH);
			paintVerticalScrim(g2, titleScrim, true);

			g2.setFont(CardFonts.fullArtTitle(1.0d));
			String titleText = CardTextLayout.ellipsizeFullArtTitle(g2.getFontMetrics(),
				card == null ? null : card.getName());
			Rectangle titleBox = new Rectangle(
				geo.innerX + titlePadX, geo.innerY + titlePadY + titleNudgeY,
				Math.max(8, geo.innerW - titlePadX * 2),
				Math.max(8, titleScrimH - titlePadY - titleNudgeY));
			drawCenteredTextShadowed(g2, titleBox, titleText, titleFont, CardColorMath.brighterColor(rarity), 0, geo.scale, false, true);

			String examineRaw = card == null || card.getExamine() == null ? "" : card.getExamine().replace("\u200B", "").trim();
			g2.setFont(CardFonts.fullArtExamine(1.0d));
			List<String> examLines = CardTextLayout.wrapFullArtExamine(g2.getFontMetrics(), examineRaw);
			if (!examLines.isEmpty())
			{
				int examineW = Math.max(8, geo.innerW - Math.max(1, (int) Math.round(12.0d * geo.scale)));
				Font examineFont = CardFonts.fullArtExamine(geo.scale);
				int lineH = Math.max(1, (int) Math.round(examineFont.getSize2D() * 1.2d));
				int blockH = lineH * examLines.size();
				int centerY = geo.innerY + (int) Math.round(geo.innerH * 0.75d);
				int top = centerY - blockH / 2;
				int left = geo.innerX + (geo.innerW - examineW) / 2;
				drawFullArtExamine(g2, left, top, examineW, examLines, examineFont, lineH, geo.scale);
			}

			Font scoreFont = CardFonts.fullArtScore(geo.scale);
			FontMetrics scoreFm = g2.getFontMetrics(scoreFont);
			int scorePadY = titlePadY;
			int scorePadX = titlePadX;
			int scoreScrimH = Math.min(geo.innerH,
				scorePadY * 2 + scoreFm.getHeight() + Math.max(2, (int) Math.round(4.0d * geo.scale)));
			Rectangle scoreScrim = new Rectangle(geo.innerX, geo.innerY + geo.innerH - scoreScrimH, geo.innerW, scoreScrimH);
			paintVerticalScrim(g2, scoreScrim, false);
			Rectangle scoreBox = new Rectangle(
				geo.innerX + scorePadX, scoreScrim.y + scorePadY,
				Math.max(8, geo.innerW - scorePadX * 2),
				Math.max(8, scoreScrimH - scorePadY * 2));
			drawCenteredTextShadowed(g2, scoreBox, "Score: " + scoreText(req), scoreFont, Color.WHITE, 0, geo.scale, true, false);
		}
		finally
		{
			g2.setClip(prevClip);
			if (prevTextAa != null)
			{
				g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, prevTextAa);
			}
			if (prevFrac != null)
			{
				g2.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, prevFrac);
			}
		}
	}
/** Strokes a thin rounded-rect ring just inside the card's outer edge, e.g. the foil highlight ring. */
	private static void drawInsetRing(Graphics2D g2, Geometry geo, Color color)
	{
		float ringWidth = (float) Math.max(1.0d, Math.round(geo.scale));
		Shape ring = new RoundRectangle2D.Double(
			ringWidth / 2.0d, ringWidth / 2.0d,
			geo.width - ringWidth, geo.height - ringWidth,
			Math.max(0.0d, geo.outerRadius * 2.0d - ringWidth), Math.max(0.0d, geo.outerRadius * 2.0d - ringWidth));
		g2.setColor(color);
		g2.setStroke(new BasicStroke(ringWidth));
		g2.draw(ring);
		g2.setStroke(new BasicStroke(1f));
	}
/** Fills {@code rect} with a black gradient that fades out away from the top (or bottom) edge, used behind overlaid text. */
	private static void paintVerticalScrim(Graphics2D g2, Rectangle rect, boolean fromTop)
	{
		if (rect.height <= 0 || rect.width <= 0)
		{
			return;
		}
		float x1 = rect.x;
		float x2 = rect.x;
		float y1 = fromTop ? rect.y : rect.y + rect.height;
		float y2 = fromTop ? rect.y + rect.height : rect.y;
		java.awt.LinearGradientPaint paint = new java.awt.LinearGradientPaint(
			x1, y1, x2, y2,
			new float[]{0f, 0.70f, 1f},
			new Color[]{
				new Color(0, 0, 0, 140),
				new Color(0, 0, 0, 71),
				new Color(0, 0, 0, 0)});
		g2.setPaint(paint);
		g2.fillRect(rect.x, rect.y, rect.width, rect.height);
	}
/** Draws pre-wrapped full-art examine text, one centered stroked/shadowed line at a time. */
	private static void drawFullArtExamine(Graphics2D g2, int left, int top, int width,
		List<String> lines, Font font, int lineHeight, double scale)
	{
		g2.setFont(font);
		FontMetrics fm = g2.getFontMetrics();
		float stroke = (float) Math.max(0.75d, 1.0d * scale);
		int y = top + fm.getAscent() + Math.max(0, (lineHeight - fm.getHeight()) / 2);
		for (String line : lines)
		{
			int x = left + Math.max(0, (width - fm.stringWidth(line)) / 2);
			drawStrokedShadowedString(g2, line, x, y, Color.WHITE, stroke, scale);
			y += lineHeight;
		}
	}
/** Draws {@code text} as a glyph outline with a soft drop shadow and a dark stroke around the fill, for legibility over art. */
	private static void drawStrokedShadowedString(Graphics2D g2, String text, int x, int y,
		Color fill, float strokeWidth, double scale)
	{
		int drop = Math.max(1, (int) Math.round(1.0d * scale));
		java.awt.font.GlyphVector gv = g2.getFont().createGlyphVector(g2.getFontRenderContext(), text);
		Shape outline = gv.getOutline(x, y);
		Shape dropOutline = gv.getOutline(x, y + drop);

		g2.setColor(new Color(0, 0, 0, 179));
		g2.fill(dropOutline);

		g2.setColor(new Color(0, 0, 0, 235));
		g2.setStroke(new BasicStroke(Math.max(1f, strokeWidth * 2f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g2.draw(outline);
		g2.setColor(fill == null ? Color.WHITE : fill);
		g2.fill(outline);
		g2.setStroke(new BasicStroke(1f));
	}
/**
	 * Centers (or top-aligns) shadowed text within {@code rect}, optionally ellipsizing to fit, clipped
	 * to the rect while drawing.
	 */
	private static void drawCenteredTextShadowed(Graphics2D g2, Rectangle rect, String text, Font font,
		Color color, int horizontalPadding, double scale, boolean ellipsize, boolean topAlign)
	{
		g2.setFont(font == null ? CardFonts.fullArtScore(1.0d) : font);
		FontMetrics fm = g2.getFontMetrics();
		int pad = Math.max(0, horizontalPadding);
		int maxWidth = Math.max(1, rect.width - pad * 2);
		String value = ellipsize
			? CardTextLayout.ellipsizeToWidth(CardTextLayout.valueOrFallback(text, ""), fm, maxWidth)
			: CardTextLayout.valueOrFallback(text, "");
		int x = rect.x + pad + Math.max(0, (maxWidth - fm.stringWidth(value)) / 2);
		int y = topAlign
			? rect.y + fm.getAscent()
			: rect.y + ((rect.height - fm.getHeight()) / 2) + fm.getAscent();
		Shape clip = g2.getClip();
		try
		{
			g2.clip(rect);
			drawTitleScoreShadow(g2, value, x, y, color, scale);
		}
		finally
		{
			g2.setClip(clip);
		}
	}
/** Draws multi-pass drop-shadowed/outlined text (title and score overlays) using {@code drawString}, cheaper than glyph outlines. */
	private static void drawTitleScoreShadow(Graphics2D g2, String text, int x, int y, Color color, double scale)
	{
		int drop = Math.max(1, (int) Math.round(1.0d * scale));
		g2.setColor(new Color(0, 0, 0, 230));
		g2.drawString(text, x, y + drop);
		g2.drawString(text, x + drop, y + drop);
		g2.setColor(new Color(0, 0, 0, 242));
		g2.drawString(text, x - 1, y);
		g2.drawString(text, x + 1, y);
		g2.drawString(text, x, y - 1);
		g2.drawString(text, x, y + 1);
		g2.setColor(color == null ? Color.WHITE : color);
		g2.drawString(text, x, y);
	}
/** Fills a banded-layout section with a solid rounded-rect color. */
	private static void fillBand(Graphics2D g2, Rectangle band, Color fill, int radius)
	{
		g2.setColor(fill);
		g2.fillRoundRect(band.x, band.y, band.width, band.height, radius * 2, radius * 2);
	}
/** Draws the banded layout's art band: the card's art image fit-centered, or a loading/placeholder message if art isn't loaded. */
	private static void drawArt(Graphics2D g2, Geometry geo, CardFaceDrawRequest req)
	{
		Rectangle inner = inset(geo.art, geo.artPad);
		BufferedImage art = req.getArt();
		if (art != null)
		{
			drawFitCentered(g2, art, inner);
			return;
		}

		CardDefinition card = req.getCard();
		String imageUrl = card == null ? null : card.getImageUrl();
		String artText = (imageUrl != null && !imageUrl.trim().isEmpty()) ? "Loading artwork..." : "No artwork";
		CardTextLayout.drawCenteredText(g2, geo.art, artText, CardFonts.body(geo.scale),
			ColorScheme.LIGHT_GRAY_COLOR, geo.bandPadX);
	}
/** Draws the banded layout's examine text: fits an em size that wraps within the band, then wraps and centers each line. */
	private static void drawExamine(Graphics2D g2, Geometry geo, String examine)
	{
		String text = examine == null ? "" : examine;
		if (text.isEmpty())
		{
			return;
		}
		int maxWidth = Math.max(1, geo.examine.width - geo.bandPadX * 2);
		int bandHeight = geo.examine.height;

		float em = ExamineTextLayout.fitExamineEm(g2::getFontMetrics, geo.scale, text, maxWidth, bandHeight);
		Font font = CardFonts.examine(geo.scale, em);
		FontMetrics fm = g2.getFontMetrics(font);
		List<String> lines = ExamineTextLayout.wrapBreakWord(fm, text, maxWidth);
		int lineHeight = ExamineTextLayout.lineHeightPx(font.getSize2D());

		g2.setFont(font);
		g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
		int blockHeight = lines.size() * lineHeight;
		int y = geo.examine.y + (bandHeight - blockHeight) / 2 + fm.getAscent();
		int pad = geo.bandPadX;

		Shape clip = g2.getClip();
		try
		{
			g2.clip(geo.examine);
			for (String line : lines)
			{
				int x = geo.examine.x + pad + Math.max(0, (maxWidth - fm.stringWidth(line)) / 2);
				g2.drawString(line, x, y);
				y += lineHeight;
			}
		}
		finally
		{
			g2.setClip(clip);
		}
	}
/** Formats the score to display: the server-supplied display score if present, else the card's computed (foil-adjusted) score, or "-" with no card. */
	static String scoreText(CardFaceDrawRequest req)
	{
		Long server = req.getDisplayScore();
		if (server != null)
		{
			return NumberFormatting.format(server.longValue());
		}
		CardDefinition card = req.getCard();
		if (card == null)
		{
			return "-";
		}
		boolean foil = req.isFullArt() || req.isUseFoilAdjustedScore();
		return NumberFormatting.format(card.displayScore(foil));
	}
/** Pre-computed layout for a card of a given pixel size: outer/inner bounds and the five band rectangles. */
	private static final class Geometry
	{
		private final int width;
		private final int height;
		private final double scale;
		private final double outerRadius;
		private final int innerX;
		private final int innerY;
		private final int innerW;
		private final int innerH;
		private final int innerRadius;
		private final int bandRadius;
		private final int bandPadX;
		private final int fullPadX;
		private final int artPad;
		private final Rectangle title;
		private final Rectangle art;
		private final Rectangle tier;
		private final Rectangle examine;
		private final Rectangle score;
/** Computes scale-relative paddings/radii and divides the inner well into five bands per {@link #BAND_FRACTIONS}. */
		private Geometry(int width, int height)
		{
			this.width = width;
			this.height = height;
			this.scale = width / (double) DEFAULT_CARD_WIDTH;
			this.outerRadius = outerRadius(width);
			this.bandRadius = Math.max(1, (int) Math.round(6.0d * scale));
			this.bandPadX = Math.max(1, (int) Math.round(4.0d * scale));
			this.fullPadX = Math.max(1, (int) Math.round(6.0d * scale));
			this.artPad = Math.max(1, (int) Math.round(2.0d * scale));
			this.innerRadius = Math.max(1, (int) Math.round(4.0d * scale));

			int rim = Math.max(1, Math.min(Math.min(width, height) / 4, (int) Math.round(7.0d * scale)));
			this.innerX = rim;
			this.innerY = rim;
			this.innerW = Math.max(1, width - rim * 2);
			this.innerH = Math.max(1, height - rim * 2);

			int gap = Math.max(2, (int) Math.round(2.0d * scale));
			int gaps = BAND_FRACTIONS.length - 1;
			if (gap * gaps >= innerH)
			{
				gap = Math.max(0, (innerH - BAND_FRACTIONS.length) / Math.max(1, gaps));
			}
			int available = Math.max(BAND_FRACTIONS.length, innerH - gap * gaps);

			Rectangle[] bands = new Rectangle[BAND_FRACTIONS.length];
			int cumulative = 0;
			int prevEdge = 0;
			for (int i = 0; i < BAND_FRACTIONS.length; i++)
			{
				cumulative += BAND_FRACTIONS[i];
				int edge = (int) Math.round(available * cumulative / 100.0d);
				int top = innerY + prevEdge + i * gap;
				int bandHeight = Math.max(1, edge - prevEdge);
				bands[i] = new Rectangle(innerX, top, innerW, bandHeight);
				prevEdge = edge;
			}

			this.title = bands[0];
			this.art = bands[1];
			this.tier = bands[2];
			this.examine = bands[3];
			this.score = bands[4];
		}
	}
/** Corner radius scaled proportionally to card width, relative to {@link #DEFAULT_CARD_WIDTH}. */
	private static double outerRadius(int width)
	{
		return Math.max(1.0d, 11.0d * width / (double) DEFAULT_CARD_WIDTH);
	}
/** Rounded-rect arc diameter (2x radius) matching {@link #outerRadius(int)}, for callers that need Swing's arc-diameter convention. */
	public static int outerArcDiameter(int width)
	{
		return Math.max(2, (int) Math.round(outerRadius(width) * 2.0d));
	}
/** Shrinks a rectangle by {@code pad} on all sides, clamping width/height to at least 1. */
	private static Rectangle inset(Rectangle r, int pad)
	{
		return new Rectangle(r.x + pad, r.y + pad, Math.max(1, r.width - pad * 2), Math.max(1, r.height - pad * 2));
	}
/**
	 * Binary-searches the largest title em size (down to {@link #BANDED_TITLE_EM_MIN}) that fits
	 * {@code title} within {@code maxWidth} at the banded layout's title font.
	 */
	private static Font fitBandedTitleFont(Graphics2D g2, String title, int maxWidth, double scale)
	{
		String text = CardTextLayout.valueOrFallback(title, "");
		int width = Math.max(1, maxWidth);
		Font largest = CardFonts.title(scale, CardFonts.TITLE_EM);
		if (g2.getFontMetrics(largest).stringWidth(text) <= width)
		{
			return largest;
		}
		float bestEm = BANDED_TITLE_EM_MIN;
		float lo = BANDED_TITLE_EM_MIN;
		float hi = CardFonts.TITLE_EM;
		for (int i = 0; i < BANDED_TITLE_FIT_STEPS; i++)
		{
			float mid = (lo + hi) * 0.5f;
			Font candidate = CardFonts.title(scale, mid);
			if (g2.getFontMetrics(candidate).stringWidth(text) <= width)
			{
				bestEm = mid;
				lo = mid;
			}
			else
			{
				hi = mid;
			}
		}
		return CardFonts.title(scale, bestEm);
	}
/** Draws {@code image} scaled to fit entirely within {@code rect} (letterboxed), centered, clipped to the rect. */
	private static void drawFitCentered(Graphics2D g2, BufferedImage image, Rectangle rect)
	{
		int sourceWidth = image.getWidth();
		int sourceHeight = image.getHeight();
		if (sourceWidth <= 0 || sourceHeight <= 0)
		{
			return;
		}
		double ratio = Math.min((double) rect.width / sourceWidth, (double) rect.height / sourceHeight);
		int w = Math.max(1, (int) Math.round(sourceWidth * ratio));
		int h = Math.max(1, (int) Math.round(sourceHeight * ratio));
		int x = rect.x + (rect.width - w) / 2;
		int y = rect.y + (rect.height - h) / 2;
		Shape clip = g2.getClip();
		try
		{
			g2.clip(rect);
			g2.drawImage(image, x, y, w, h, null);
		}
		finally
		{
			g2.setClip(clip);
		}
	}
/** Draws {@code image} scaled to fully cover {@code rect} (cropped, not letterboxed), centered. Caller must clip if needed. */
	private static void drawCoverCentered(Graphics2D g2, BufferedImage image, Rectangle rect)
	{
		int sourceWidth = image.getWidth();
		int sourceHeight = image.getHeight();
		if (sourceWidth <= 0 || sourceHeight <= 0)
		{
			return;
		}
		double ratio = Math.max((double) rect.width / sourceWidth, (double) rect.height / sourceHeight);
		int w = Math.max(1, (int) Math.round(sourceWidth * ratio));
		int h = Math.max(1, (int) Math.round(sourceHeight * ratio));
		int x = rect.x + (rect.width - w) / 2;
		int y = rect.y + (rect.height - h) / 2;
		g2.drawImage(image, x, y, w, h, null);
	}
/** Turns on antialiasing, bilinear interpolation, and pure stroke control for higher-quality rendering. */
	private static void enableQuality(Graphics2D g2)
	{
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
	}
}

