/**
 * Shop tab controller: renders the credits header and the booster tile grid, keeps buy-button enabled
 * state in sync with credits/reveal/consent state, and routes buy clicks through {@link PackOpenCoordinator}.
 * All rendering methods mutate Swing components and must run on the EDT.
 */
public final class ShopTab
{
	private static final int BOOSTER_GRID_GAP = 6;

	private final CardDatabase cardDatabase;
	private final PackRevealService packRevealService;
	private final PackOpenCoordinator packOpenCoordinator;
	private final PackCatalogService packCatalogService;
	private final CardImageCacheService imageCacheService;
	private final CloudSessionService cloudSessionService;
	private final OverviewTab overviewTab;
	private final IntSupplier shopWidth;
	private final Supplier<PackCloseSnapshot> snapshotSupplier;
	private final Runnable refreshUi;
	private final Runnable beginRevealFreeze;
	private final Runnable clearRevealFreeze;

	private final JPanel shopHeaderPanel;
	private final JPanel packsContent;
	private final AtomicBoolean packOpenInFlight = new AtomicBoolean(false);
	private JLabel creditsValueLabel;
	private final List<JButton> buyButtons = new ArrayList<>();
	private final List<Integer> buyPrices = new ArrayList<>();
/** Wires the collaborators and the pre-built Swing panels this controller drives. */
	public ShopTab(
		CardDatabase cardDatabase,
		PackRevealService packRevealService,
		PackOpenCoordinator packOpenCoordinator,
		PackCatalogService packCatalogService,
		CardImageCacheService imageCacheService,
		CloudSessionService cloudSessionService,
		OverviewTab overviewTab,
		IntSupplier shopWidth,
		Supplier<PackCloseSnapshot> snapshotSupplier,
		Runnable refreshUi,
		Runnable beginRevealFreeze,
		Runnable clearRevealFreeze,
		JPanel shopHeaderPanel,
		JPanel packsContent)
	{
		this.cardDatabase = cardDatabase;
		this.packRevealService = packRevealService;
		this.packOpenCoordinator = packOpenCoordinator;
		this.packCatalogService = packCatalogService;
		this.imageCacheService = imageCacheService;
		this.cloudSessionService = cloudSessionService;
		this.overviewTab = overviewTab;
		this.shopWidth = shopWidth;
		this.snapshotSupplier = snapshotSupplier;
		this.refreshUi = refreshUi;
		this.beginRevealFreeze = beginRevealFreeze;
		this.clearRevealFreeze = clearRevealFreeze;
		this.shopHeaderPanel = shopHeaderPanel;
		this.packsContent = packsContent;
	}
/** Empties the header and pack panels and drops cached buy-button/price/credits-label state. */
	public void clear()
	{
		shopHeaderPanel.removeAll();
		packsContent.removeAll();
		buyButtons.clear();
		buyPrices.clear();
		creditsValueLabel = null;
	}
/** Computes fresh set-completion progress from the current state and renders the shop from it. */
	public void render()
	{
		PackCloseSnapshot displaySnap = snapshotSupplier.get();
		List<BoosterShopRow> shopRows = ShopProgress.computeRows(
			displaySnap, cardDatabase.getCards(), cardDatabase.getCards(),
			shopVisibleBoosters());
		renderFromPackClose(displaySnap, shopRows);
	}
/**
	 * Renders the shop from an already-computed snapshot and row list (used right after a pack close, when
	 * progress was already recalculated): preloads thumbnails, rebuilds the header, and rebuilds the tile grid.
	 */
	public void renderFromPackClose(PackCloseSnapshot snap, List<BoosterShopRow> shopRows)
	{
		preloadShopPackThumbnails(shopRows);
		rebuildShopHeader(snap.credits);
		buyButtons.clear();
		buyPrices.clear();
		packsContent.removeAll();
		packsContent.add(boosterShopPanelFromPrecalc(snap.credits, shopRows));
		packsContent.revalidate();
		packsContent.repaint();
	}
/** Update the credits header and buy-button enabled state without rebuilding pack tiles. */
	public void updateCredits(long credits)
	{
		if (creditsValueLabel != null)
		{
			creditsValueLabel.setText(NumberFormatting.format(credits));
		}
		applyBuyButtonEnabledState(credits);
	}
/** Computes set-completion progress rows for the currently visible boosters against {@code snap}. */
	public List<BoosterShopRow> computeRows(PackCloseSnapshot snap)
	{
		return ShopProgress.computeRows(
			snap, cardDatabase.getCards(), cardDatabase.getCards(),
			shopVisibleBoosters());
	}
/** Kicks off async prefetch of hosted booster thumbnail images. */
	private void preloadShopPackThumbnails(List<BoosterShopRow> shopRows)
	{
		if (shopRows == null || imageCacheService == null)
		{
			return;
		}
		List<String> urls = new ArrayList<>();
		for (BoosterShopRow row : shopRows)
		{
			if (row == null || row.booster == null)
			{
				continue;
			}
			String thumb = row.booster.getThumbnail();
			if (BoosterPackDefinition.isHostedImagePath(thumb))
			{
				urls.add(thumb.trim());
			}
		}
		if (!urls.isEmpty())
		{
			imageCacheService.preloadAsync(urls);
		}
	}
/** Rebuilds the credits stat panel and caches its value label for later in-place updates via {@link #updateCredits}. */
	private void rebuildShopHeader(long credits)
	{
		shopHeaderPanel.removeAll();
		JPanel creditsPanel = overviewTab.imageStatPanel("Credits", NumberFormatting.format(credits), SidebarLayout.CREDITS_IMAGE_PATH);
		Component east = ((BorderLayout) creditsPanel.getLayout()).getLayoutComponent(BorderLayout.EAST);
		creditsValueLabel = east instanceof JLabel ? (JLabel) east : null;
		shopHeaderPanel.add(creditsPanel);
		shopHeaderPanel.add(Box.createRigidArea(new Dimension(0, 8)));
		shopHeaderPanel.revalidate();
		shopHeaderPanel.repaint();
	}
/** Lays the booster tiles out as a two-column grid (or an info message when there are none), sized to {@link #shopWidth}. */
	private JPanel boosterShopPanelFromPrecalc(long credits, List<BoosterShopRow> rows)
	{
		JPanel outer = new JPanel();
		outer.setLayout(new BoxLayout(outer, BoxLayout.Y_AXIS));
		outer.setOpaque(false);

		if (rows == null || rows.isEmpty())
		{
			outer.add(infoPanel("No booster packs available. Try relogging."));
			SidebarLayout.clampFixedWidth(outer, shopWidth.getAsInt());
			return outer;
		}

		int buttonW = shopBoosterButtonWidth();

		JPanel grid = new JPanel();
		grid.setLayout(new BoxLayout(grid, BoxLayout.Y_AXIS));
		grid.setOpaque(false);
		grid.setAlignmentX(JComponent.LEFT_ALIGNMENT);

		List<JButton> buttons = new ArrayList<>();
		buyButtons.clear();
		buyPrices.clear();
		for (BoosterShopRow row : rows)
		{
			if (row == null || row.booster == null)
			{
				continue;
			}
			JButton buy = createBoosterBuyButton(
				row.booster, row.progressOwn, row.progressFoilOwn, row.progressTotal, buttonW);
			buyButtons.add(buy);
			buyPrices.add(row.booster.getPrice());
			buttons.add(buy);
		}
		applyBuyButtonEnabledState(credits);

		for (int i = 0; i < buttons.size(); i += 2)
		{
			if (i > 0)
			{
				grid.add(Box.createVerticalStrut(BOOSTER_GRID_GAP));
			}
			JPanel row = new JPanel();
			row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
			row.setOpaque(false);
			row.setAlignmentX(JComponent.LEFT_ALIGNMENT);
			row.add(buttons.get(i));
			if (i + 1 < buttons.size())
			{
				row.add(Box.createHorizontalStrut(BOOSTER_GRID_GAP));
				row.add(buttons.get(i + 1));
			}
			row.add(Box.createHorizontalGlue());
			int inner = shopWidth.getAsInt();
			int rowH = Math.max(1, row.getPreferredSize().height);
			row.setPreferredSize(new Dimension(inner, rowH));
			row.setMaximumSize(new Dimension(Integer.MAX_VALUE, rowH));
			row.setMinimumSize(new Dimension(0, rowH));
			grid.add(row);
		}

		Dimension gridPref = grid.getPreferredSize();
		grid.setPreferredSize(gridPref);
		grid.setMaximumSize(new Dimension(Integer.MAX_VALUE, gridPref.height));

		outer.add(grid);
		SidebarLayout.clampFixedWidth(outer, shopWidth.getAsInt());
		return outer;
	}
/** Enables each buy button only when no reveal is in progress, cloud consent isn't pending, and credits cover its price. */
	private void applyBuyButtonEnabledState(long credits)
	{
		boolean consentPending = cloudSessionService.needsCloudConsent();
		boolean revealBusy = packRevealService.isActive();
		int n = Math.min(buyButtons.size(), buyPrices.size());
		for (int i = 0; i < n; i++)
		{
			JButton buy = buyButtons.get(i);
			int price = buyPrices.get(i);
			buy.setEnabled(!revealBusy && !consentPending && credits >= price);
			if (consentPending)
			{
				buy.setToolTipText("Create a profile before opening packs.");
			}
			else
			{
				buy.setToolTipText(null);
			}
		}
	}
/** Mutable copy of the currently visible boosters from the catalog service. */
	private List<BoosterPackDefinition> shopVisibleBoosters()
	{
		return new ArrayList<>(packCatalogService.getVisibleBoosters());
	}
/** Width of one booster tile: half the shop width (minus the grid gap), floored at 96px. */
	private int shopBoosterButtonWidth()
	{
		int inner = shopWidth.getAsInt();
		return Math.max(96, (inner - BOOSTER_GRID_GAP) / 2);
	}
/** Builds a simple bordered panel showing a status/info message (e.g. "no boosters available"). */
	private JPanel infoPanel(String message)
	{
		JPanel panel = new JPanel(new BorderLayout());
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(new EmptyBorder(6, 6, 6, 6));
		JLabel label = SidebarLayout.textPanel(message);
		label.setHorizontalAlignment(SwingConstants.LEFT);
		panel.add(label, BorderLayout.CENTER);
		SidebarLayout.clampPanelWidth(panel);
		return panel;
	}
/** Cached thumbnail icon for a booster, or {@code null} if it has no hosted thumbnail or it's not yet cached. */
	private ImageIcon shopPackIcon(BoosterPackDefinition booster)
	{
		String thumbnail = booster == null ? null : booster.getThumbnail();
		if (!BoosterPackDefinition.isHostedImagePath(thumbnail))
		{
			return null;
		}
		java.awt.image.BufferedImage remote = imageCacheService.getCached(thumbnail.trim());
		return remote != null ? new ImageIcon(remote) : null;
	}
/** Builds one booster's buy button, wiring its click to open the pack via {@link #packOpenCoordinator}. */
	private JButton createBoosterBuyButton(BoosterPackDefinition booster, int progressOwn, int progressFoilOwn, int progressTotal,
		int buttonWidth)
	{
		return BoosterBuyButtonFactory.create(
			booster, progressOwn, progressFoilOwn, progressTotal, buttonWidth,
			shopPackIcon(booster),
			() -> packOpenCoordinator.openFromShop(
				booster, packOpenInFlight, beginRevealFreeze, clearRevealFreeze, refreshUi,
				SwingUtilities::invokeLater));
	}
}

package com.osrstcg.ui.shop;

import com.osrstcg.catalog.BoosterPackDefinition;
import com.osrstcg.catalog.CardDefinition;
import com.osrstcg.catalog.CollectionSetCompletionUtil;
import com.osrstcg.state.CardCollectionKey;
import com.osrstcg.ui.collection.CollectionListModel;
import com.osrstcg.ui.layout.PackCloseSnapshot;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
/**
 * Computes per-booster set-completion progress (owned / foil-owned / total) for the shop and collection
 * tabs, caching each pack's eligible-name set keyed on the current card/roll-pool list identity.
 */
public final class ShopProgress
{
	private static final Object ELIGIBLE_LOCK = new Object();
	private static List<CardDefinition> cachedAllCards;
	private static List<CardDefinition> cachedRollPool;
	private static final Map<String, Set<String>> eligibleByPackKey = new java.util.HashMap<>();

	private ShopProgress()
	{
	}
/** Names of cards owned as a foil (positive quantity, non-blank name), from an owned-card count map. */
	public static Set<String> foilCollectedNamesFromOwned(Map<CardCollectionKey, Integer> owned)
	{
		Set<String> foilNames = new HashSet<>();
		for (Map.Entry<CardCollectionKey, Integer> entry : owned.entrySet())
		{
			CardCollectionKey key = entry.getKey();
			if (key == null || !key.isFoil())
			{
				continue;
			}
			String cardName = key.getCardName();
			Integer qty = entry.getValue();
			if (cardName == null || qty == null || qty <= 0)
			{
				continue;
			}
			String trimmed = cardName.trim();
			if (!trimmed.isEmpty())
			{
				foilNames.add(trimmed);
			}
		}
		return foilNames;
	}
/**
	 * Counts owned/foil-owned/total for a booster's eligible card set.
	 * @return {@code {own, foilOwn, total}}
	 */
	public static int[] ownedTotal(
		BoosterPackDefinition booster,
		List<CardDefinition> allCards,
		List<CardDefinition> rollPool,
		Map<CardCollectionKey, Integer> owned)
	{
		Set<String> collectedNames = CollectionSetCompletionUtil.collectedNamesFromOwned(owned);
		Set<String> foilCollectedNames = foilCollectedNamesFromOwned(owned);
		Set<String> eligible = eligibleNames(booster, allCards, rollPool);
		int total = eligible.size();
		int own = 0;
		int foilOwn = 0;
		for (String name : eligible)
		{
			if (collectedNames.contains(name))
			{
				own++;
			}
			if (foilCollectedNames.contains(name))
			{
				foilOwn++;
			}
		}
		return new int[] { own, foilOwn, total };
	}
/**
	 * Looks up (or computes and caches) the eligible-name set for a booster. The cache is invalidated
	 * whenever the {@code allCards}/{@code rollPool} list identity changes.
	 */
	private static Set<String> eligibleNames(
		BoosterPackDefinition booster,
		List<CardDefinition> allCards,
		List<CardDefinition> rollPool)
	{
		synchronized (ELIGIBLE_LOCK)
		{
			if (allCards != cachedAllCards || rollPool != cachedRollPool)
			{
				eligibleByPackKey.clear();
				cachedAllCards = allCards;
				cachedRollPool = rollPool;
			}
			String key = packEligibleKey(booster);
			Set<String> cached = eligibleByPackKey.get(key);
			if (cached != null)
			{
				return cached;
			}
			Set<String> eligible = CollectionListModel.eligibleNamesForPack(booster, allCards, rollPool);
			eligibleByPackKey.put(key, eligible);
			return eligible;
		}
	}
/** Cache key for a booster: its id, or its category filters when the id is missing/blank. */
	private static String packEligibleKey(BoosterPackDefinition booster)
	{
		if (booster == null)
		{
			return "";
		}
		String id = booster.getId();
		if (id != null && !id.isBlank())
		{
			return id;
		}
		return String.valueOf(booster.getCategoryFilters());
	}
/** Builds one {@link BoosterShopRow} per non-null booster, with progress computed against {@code snap.owned}. */
	public static List<BoosterShopRow> computeRows(
		PackCloseSnapshot snap,
		List<CardDefinition> allCards,
		List<CardDefinition> rollPool,
		List<BoosterPackDefinition> boosters)
	{
		List<BoosterShopRow> out = new ArrayList<>(boosters.size());
		for (BoosterPackDefinition booster : boosters)
		{
			if (booster == null)
			{
				continue;
			}
			int[] p = ownedTotal(booster, allCards, rollPool, snap.owned);
			out.add(new BoosterShopRow(booster, p[0], p[1], p[2]));
		}
		return out;
	}
}

package com.osrstcg.ui.shop;

import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import javax.swing.JPanel;
/**
 * Fixed-size dual-segment progress bar for a shop tile: a green fill for standard-owned cards overlaid
 * with a yellow fill for foil-owned cards, both as a percentage of the set total. Immutable once
 * constructed; must be built and painted on the EDT.
 */
public final class ShopPackProgressBar extends JPanel
{
	public static final int WIDTH_PX = 75;
	public static final int HEIGHT_PX = 6;

	private static final Color TRACK = new Color(0x2e2e2e);
	private static final Color TRACK_BORDER = new Color(0x555555);
	private static final Color STANDARD_FILL = new Color(0x4caf50);
	private static final Color FOIL_FILL = new Color(0xF2C94C);

	private final int barWidthPx;
	private final int standardFillPx;
	private final int foilFillPx;
/** Precomputes fill widths (clamped to 0-100%) from the owned/total counts for painting. */
	public ShopPackProgressBar(int barWidthPx, int standardOwn, int foilOwn, int total)
	{
		this.barWidthPx = barWidthPx;
		double standardPct = total <= 0 ? 0.0 : (100.0 * standardOwn) / total;
		double foilPct = total <= 0 ? 0.0 : (100.0 * foilOwn) / total;
		this.standardFillPx = (int) Math.round(barWidthPx * Math.min(100.0, Math.max(0.0, standardPct)) / 100.0);
		this.foilFillPx = (int) Math.round(barWidthPx * Math.min(100.0, Math.max(0.0, foilPct)) / 100.0);
		int outerW = barWidthPx + 2;
		int outerH = HEIGHT_PX + 2;
		Dimension size = new Dimension(outerW, outerH);
		setOpaque(false);
		setPreferredSize(size);
		setMinimumSize(size);
		setMaximumSize(size);
		setAlignmentX(Component.CENTER_ALIGNMENT);
	}
/** Paints the bordered track, then the standard and foil fill segments over it. */
	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			int x = 1;
			int y = 1;
			int h = HEIGHT_PX;
			g2.setColor(TRACK_BORDER);
			g2.fillRect(0, 0, barWidthPx + 2, h + 2);
			g2.setColor(TRACK);
			g2.fillRect(x, y, barWidthPx, h);
			if (standardFillPx > 0)
			{
				g2.setColor(STANDARD_FILL);
				g2.fillRect(x, y, standardFillPx, h);
			}
			if (foilFillPx > 0)
			{
				g2.setColor(FOIL_FILL);
				g2.fillRect(x, y, foilFillPx, h);
			}
		}
		finally
		{
			g2.dispose();
		}
	}
}

package com.osrstcg.ui.account;

import com.google.gson.JsonObject;
import com.osrstcg.cloud.api.CloudApiClient;
import com.osrstcg.cloud.api.CloudApiException;
import com.osrstcg.cloud.api.CloudEndpoints;
import com.osrstcg.cloud.api.JsonObjects;
import com.osrstcg.cloud.session.CloudSessionService;
import com.osrstcg.util.TcgPluginGameMessages;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.swing.JButton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.util.LinkBrowser;
/**
 * Opens the OSRS TCG website account page (signed in via a one-time web code) from the sidebar,
 * and drives the enabled/disabled state of the account button. Network calls run on the
 * given scheduler; UI updates are marshalled back onto the Swing EDT.
 */
@Slf4j
public final class AccountPanelLauncher
{
	private final CloudSessionService cloudSessionService;
	private final CloudApiClient cloudApiClient;
	private final ScheduledExecutorService scheduler;
	private final ChatMessageManager chatMessageManager;
	private final Runnable updateButtonState;
	private final AtomicBoolean inFlight = new AtomicBoolean(false);
/** @param updateButtonState invoked (on the EDT) whenever button-enabled state may have changed */
	public AccountPanelLauncher(
		CloudSessionService cloudSessionService,
		CloudApiClient cloudApiClient,
		ScheduledExecutorService scheduler,
		ChatMessageManager chatMessageManager,
		Runnable updateButtonState)
	{
		this.cloudSessionService = cloudSessionService;
		this.cloudApiClient = cloudApiClient;
		this.scheduler = scheduler;
		this.chatMessageManager = chatMessageManager;
		this.updateButtonState = updateButtonState;
	}
/**
	 * Requests a login web-code from the cloud API and opens the resulting URL in the system browser.
	 * No-ops if the world is restricted, the panel can't currently be opened, or a request is already
	 * in flight. Runs the network call on {@link #scheduler} and browser launch on the EDT.
	 *
	 * @param next path to redirect to after web login; defaults to {@code /me} if blank
	 */
	public void open(String next)
	{
		if (cloudSessionService.isRestrictedWorld()
			|| !cloudSessionService.canOpenAccountPanel())
		{
			updateButtonState.run();
			return;
		}
		if (!inFlight.compareAndSet(false, true))
		{
			return;
		}
		updateButtonState.run();
		String nextPath = next == null || next.isBlank() ? "/me" : next.trim();
		scheduler.execute(() ->
		{
			try
			{
				JsonObject response = cloudApiClient.webCode(nextPath);
				String url = resolveWebLoginUrlOrFallback(response, nextPath);
				if (url == null || url.isEmpty())
				{
					throw new IllegalStateException("missing_login_url");
				}
				SwingUtilities.invokeLater(() -> LinkBrowser.browse(url));
			}
			catch (CloudApiException ex)
			{
				log.warn("Open account panel web-code failed: {} {}", ex.getCode(), ex.getMessage());
				queueOpenAccountPanelError(ex.getMessage());
			}
			catch (Exception ex)
			{
				log.warn("Open account panel failed", ex);
				queueOpenAccountPanelError(null);
			}
			finally
			{
				inFlight.set(false);
				SwingUtilities.invokeLater(updateButtonState);
			}
		});
	}
/** Refreshes enabled state and tooltip of the account panel button from current cloud session state. */
	public void updateManageAccountState(JButton openAccountPanelButton)
	{
		if (openAccountPanelButton == null)
		{
			return;
		}
		boolean canOpen = cloudSessionService.canOpenAccountPanel();
		boolean busy = inFlight.get();
		openAccountPanelButton.setEnabled(canOpen && !busy);
		openAccountPanelButton.setToolTipText(canOpen
			? "Open the website signed in to your cloud account"
			: "Connect to cloud first");
	}
/** Queues a chat message reporting that opening the account panel failed, with optional detail. */
	private void queueOpenAccountPanelError(String detail)
	{
		String message = detail == null || detail.isBlank()
			? "Could not open account page"
			: "Could not open account page - " + detail.trim();
		TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager, message);
	}
/** @return the {@code url} field from a web-code response, or {@code null} if absent/blank. */
	public static String resolveWebLoginUrl(JsonObject response)
	{
		return JsonObjects.textTrimmed(response, "url");
	}
/** @return a {@code /login} URL for the web base with the code and redirect path encoded, or {@code null} if inputs are missing. */
	public static String buildWebLoginUrl(String webBaseUrl, String code, String next)
	{
		if (code == null || code.isBlank() || webBaseUrl == null || webBaseUrl.isBlank())
		{
			return null;
		}
		String nextPath = next == null || next.isBlank() ? "/me" : next.trim();
		String encodedCode = URLEncoder.encode(code.trim(), StandardCharsets.UTF_8);
		String encodedNext = URLEncoder.encode(nextPath, StandardCharsets.UTF_8);
		return webBaseUrl + "/login?code=" + encodedCode + "&next=" + encodedNext;
	}
/**
	 * Prefers building a login URL from the response's one-time {@code code}; falls back to the
	 * response's {@code url} rewritten onto the configured web base.
	 */
	private String resolveWebLoginUrlOrFallback(JsonObject response, String next)
	{
		String code = JsonObjects.textTrimmed(response, "code");
		if (code != null)
		{
			String fromCode = buildWebLoginUrl(CloudEndpoints.WEB_BASE_URL, code, next);
			if (fromCode != null && !fromCode.isEmpty())
			{
				return fromCode;
			}
		}
		String url = resolveWebLoginUrl(response);
		if (url != null)
		{
			return CloudEndpoints.rewriteToWebBase(url);
		}
		return null;
	}
}

package com.osrstcg.ui.account;

import com.osrstcg.cloud.api.CloudApiException;
import com.osrstcg.cloud.session.CloudSessionService;
import com.osrstcg.util.TcgPluginGameMessages;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Insets;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JTextPane;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.LinkBrowser;
/**
 * Drives the sidebar "create profile" flow: shows a cloud-consent dialog, submits profile creation
 * to the cloud service on a background thread, and updates the create-profile button/prompt UI.
 * UI-touching methods must run on, and callback to, the Swing EDT.
 */
@Slf4j
public final class CreateProfileController
{
	public static final String CREATE_PROFILE_PROMPT =
		"OSRS TCG stores collections on a server. You don't seem to have a profile yet. Click the button below to create an OSRS TCG profile for your account.";

	private static final String CONSENT_WARNING_INTRO =
		"This will send data to a third-party server not controlled or verified by RuneLite developers.";
	private static final String CONSENT_DATA_SENT =
		"• Your RuneScape display name and account identifiers used to link this client to your account\n"
			+ "• Your owned cards and their details\n"
			+ "• Your IP address while connected\n"
			+ "• Information about various in-game events to process credit gains";
	private static final int CONSENT_DIALOG_WIDTH = 540;
	private static final int CONSENT_DIALOG_HEIGHT = 220;
	private static final int CONSENT_CONTENT_WIDTH = 500;
	private static final String PRIVACY_URL = "https://osrs-tcg.net/privacy";

	private final CloudSessionService cloudSessionService;
	private final ScheduledExecutorService scheduler;
	private final ChatMessageManager chatMessageManager;
	private final Component dialogParent;
	private final Runnable refreshUi;
	private final Runnable onSuccessSelectOverview;
	private final Runnable onSuccessOpenAlbum;
	private final Runnable afterUi;
	private final AtomicBoolean inFlight = new AtomicBoolean(false);
/**
	 * @param dialogParent parent component for the consent dialog
	 * @param refreshUi rerun after profile creation finishes, regardless of outcome
	 * @param onSuccessSelectOverview run (before {@code afterUi}) if creation succeeded
	 * @param onSuccessOpenAlbum optional, run after {@code refreshUi} if creation succeeded
	 * @param afterUi run once the create-profile flow has been dispatched or completed, to update UI state
	 */
	public CreateProfileController(
		CloudSessionService cloudSessionService,
		ScheduledExecutorService scheduler,
		ChatMessageManager chatMessageManager,
		Component dialogParent,
		Runnable refreshUi,
		Runnable onSuccessSelectOverview,
		Runnable onSuccessOpenAlbum,
		Runnable afterUi)
	{
		this.cloudSessionService = cloudSessionService;
		this.scheduler = scheduler;
		this.chatMessageManager = chatMessageManager;
		this.dialogParent = dialogParent;
		this.refreshUi = refreshUi;
		this.onSuccessSelectOverview = onSuccessSelectOverview;
		this.onSuccessOpenAlbum = onSuccessOpenAlbum;
		this.afterUi = afterUi;
	}
/**
	 * Entry point for the "create profile" button. Skips straight to {@code afterUi} if consent
	 * isn't needed (restricted world or already consented); otherwise shows the consent dialog and,
	 * on acceptance, starts profile creation.
	 */
	public void createProfile()
	{
		if (cloudSessionService.isRestrictedWorld() || !cloudSessionService.needsCloudConsent())
		{
			afterUi.run();
			return;
		}
		if (!confirmConsent())
		{
			return;
		}
		beginCreate();
	}
/**
	 * Submits {@link CloudSessionService#createProfile()} on {@link #scheduler}, guarded against
	 * concurrent invocations, then marshals the success/failure callbacks back onto the EDT.
	 */
	private void beginCreate()
	{
		if (!inFlight.compareAndSet(false, true))
		{
			return;
		}
		afterUi.run();
		scheduler.execute(() ->
		{
			boolean success = false;
			try
			{
				cloudSessionService.createProfile();
				success = true;
			}
			catch (CloudApiException ex)
			{
				TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
					"Create profile failed: " + ex.getMessage());
			}
			catch (Exception ex)
			{
				log.warn("Create profile failed", ex);
				String detail = ex.getMessage() != null && !ex.getMessage().isBlank()
					? ex.getMessage()
					: "try again";
				TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
					"Create profile failed: " + detail);
			}
			finally
			{
				inFlight.set(false);
				boolean goOverview = success;
				SwingUtilities.invokeLater(() ->
				{
					if (goOverview)
					{
						onSuccessSelectOverview.run();
					}
					afterUi.run();
					refreshUi.run();
					if (goOverview && onSuccessOpenAlbum != null)
					{
						onSuccessOpenAlbum.run();
					}
				});
			}
		});
	}
/** Shows the cloud data-consent dialog and returns whether the user accepted. */
	private boolean confirmConsent()
	{
		JPanel sections = new JPanel();
		sections.setOpaque(false);
		sections.setLayout(new BoxLayout(sections, BoxLayout.Y_AXIS));
		sections.add(buildConsentSection("Attention!", CONSENT_WARNING_INTRO, true));
		sections.add(Box.createVerticalStrut(10));
		sections.add(buildConsentSection("What is sent?", CONSENT_DATA_SENT, false));

		JScrollPane scroll = new JScrollPane(sections);
		scroll.setBorder(null);
		scroll.getViewport().setOpaque(false);
		scroll.setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_NEVER);
		scroll.setPreferredSize(new Dimension(CONSENT_DIALOG_WIDTH, CONSENT_DIALOG_HEIGHT));

		int choice = JOptionPane.showConfirmDialog(
			dialogParent,
			scroll,
			"OSRS TCG cloud",
			JOptionPane.YES_NO_OPTION,
			JOptionPane.WARNING_MESSAGE);
		return choice == JOptionPane.YES_OPTION;
	}
/** Builds one titled, word-wrapped section of the consent dialog, optionally with a privacy-policy link. */
	private JPanel buildConsentSection(String title, String body, boolean includePrivacyLink)
	{
		JLabel header = new JLabel(title);
		header.setFont(FontManager.getRunescapeBoldFont());
		header.setForeground(ColorScheme.BRAND_ORANGE);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.setBorder(new EmptyBorder(0, 0, 4, 0));
		JTextArea text = new JTextArea(body);
		text.setEditable(false);
		text.setOpaque(false);
		text.setFocusable(false);
		text.setLineWrap(true);
		text.setWrapStyleWord(true);
		text.setFont(FontManager.getRunescapeFont());
		text.setForeground(Color.WHITE);
		text.setAlignmentX(Component.LEFT_ALIGNMENT);
		sizeConsentText(text, CONSENT_CONTENT_WIDTH);

		JPanel section = new JPanel();
		section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
		section.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		section.setAlignmentX(Component.LEFT_ALIGNMENT);
		section.add(header);
		section.add(text);
		if (includePrivacyLink)
		{
			section.add(buildPrivacyLink());
		}
		int sectionH = Math.max(1, section.getPreferredSize().height);
		section.setMaximumSize(new Dimension(Integer.MAX_VALUE, sectionH));
		return section;
	}
/** Fixes a consent-dialog text area's size to its wrapped-text preferred height at the given width. */
	private static void sizeConsentText(JTextArea text, int width)
	{
		text.setBorder(null);
		text.setMargin(new Insets(0, 0, 0, 0));
		text.setSize(width, Short.MAX_VALUE);
		javax.swing.text.View view = text.getUI().getRootView(text);
		view.setSize(width, Integer.MAX_VALUE);
		int height = Math.max(1, (int) Math.ceil(view.getPreferredSpan(javax.swing.text.View.Y_AXIS)));
		Dimension size = new Dimension(width, height);
		text.setMinimumSize(size);
		text.setPreferredSize(size);
		text.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
	}
/** Builds an underlined, clickable "Privacy policy" label that opens {@link #PRIVACY_URL} in the browser. */
	private JLabel buildPrivacyLink()
	{
		Cursor hand = Cursor.getPredefinedCursor(Cursor.HAND_CURSOR);
		JLabel link = new JLabel("<html><u>Privacy policy</u></html>");
		link.setFont(FontManager.getRunescapeFont());
		link.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		link.setCursor(hand);
		link.setAlignmentX(Component.LEFT_ALIGNMENT);
		link.setToolTipText(PRIVACY_URL);
		link.addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseEntered(java.awt.event.MouseEvent e)
			{
				link.setCursor(hand);
			}

			@Override
			public void mouseClicked(java.awt.event.MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					LinkBrowser.browse(PRIVACY_URL);
				}
			}
		});
		return link;
	}
/** Creates an empty, non-editable text pane styled for the "create profile" sidebar prompt. */
	public static JTextPane createPromptPane()
	{
		JTextPane tp = new JTextPane();
		tp.setEditable(false);
		tp.setOpaque(false);
		tp.setFocusable(false);
		tp.setForeground(Color.YELLOW);
		tp.setFont(FontManager.getRunescapeSmallFont());
		tp.setBorder(null);
		tp.setAlignmentX(Component.CENTER_ALIGNMENT);
		return tp;
	}
/** Sets the prompt text and center-aligned yellow styling, then resizes the pane and its footer wrapper to fit at the given width. */
	public void updatePromptLayout(JTextPane promptPane, JPanel footerWrap, int width)
	{
		if (promptPane == null)
		{
			return;
		}
		promptPane.setText(CREATE_PROFILE_PROMPT);
		javax.swing.text.SimpleAttributeSet attrs = new javax.swing.text.SimpleAttributeSet();
		javax.swing.text.StyleConstants.setAlignment(attrs, javax.swing.text.StyleConstants.ALIGN_CENTER);
		javax.swing.text.StyleConstants.setFontFamily(attrs, promptPane.getFont().getFamily());
		javax.swing.text.StyleConstants.setFontSize(attrs, promptPane.getFont().getSize());
		javax.swing.text.StyleConstants.setForeground(attrs, Color.YELLOW);
		javax.swing.text.StyledDocument doc = promptPane.getStyledDocument();
		doc.setParagraphAttributes(0, doc.getLength(), attrs, false);
		doc.setCharacterAttributes(0, doc.getLength(), attrs, false);

		promptPane.setSize(width, Short.MAX_VALUE);
		int height = Math.max(1, promptPane.getPreferredSize().height);
		Dimension size = new Dimension(width, height);
		promptPane.setMinimumSize(size);
		promptPane.setPreferredSize(size);
		promptPane.setMaximumSize(size);

		footerWrap.setAlignmentX(Component.LEFT_ALIGNMENT);
		footerWrap.setMinimumSize(null);
		footerWrap.setPreferredSize(null);
		footerWrap.setMaximumSize(null);
		int wrapH = Math.max(1, footerWrap.getPreferredSize().height);
		footerWrap.setMinimumSize(new Dimension(0, wrapH));
		footerWrap.setPreferredSize(new Dimension(width, wrapH));
		footerWrap.setMaximumSize(new Dimension(width, wrapH));
	}
/** Enables the create-profile button only while consent is still pending and no request is in flight. */
	public void updateButtonState(JButton createProfileButton)
	{
		if (createProfileButton == null)
		{
			return;
		}
		boolean pending = cloudSessionService.needsCloudConsent();
		boolean busy = inFlight.get();
		createProfileButton.setEnabled(pending && !busy);
		createProfileButton.setText(busy ? "Creating…" : "Create profile");
	}
}

package com.osrstcg.ui.account;

import com.osrstcg.cloud.session.CloudSessionService;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Container;
import java.awt.GridBagLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.FontManager;
/**
 * Sidebar card that replaces the normal tab content with a centered message (event-world
 * unavailable, account locked/banned) and, when relevant, relocates the "open account panel"
 * button into it. Swing component; must be built and updated on the EDT.
 */
public final class SidebarNoticeView
{
/** CardLayout key this view is shown under. */
	public static final String CARD = "SIDEBAR_NOTICE";
	public static final String EVENT_WORLD_UNAVAILABLE = "OSRS TCG is not available on event worlds";

	private final JPanel sidebarNoticeContent = new JPanel(new BorderLayout(0, 0));
	private final JPanel sidebarNoticeMessageWrap = new JPanel(new GridBagLayout());
	private final JPanel sidebarNoticeButtonWrap = new JPanel(new BorderLayout(0, 0));
	private final JButton openAccountPanelButton;
	private final JPanel albumFooterWrap;
	private final CloudSessionService cloudSessionService;
	private final Runnable onManageAccountStateUpdate;
/**
	 * @param openAccountPanelButton shared button that gets reparented into this view when a notice needs it
	 * @param albumFooterWrap the button's normal home, to restore it to when the notice is dismissed
	 * @param onManageAccountStateUpdate invoked after the button is shown, to refresh its enabled state
	 */
	public SidebarNoticeView(
		JButton openAccountPanelButton,
		JPanel albumFooterWrap,
		CloudSessionService cloudSessionService,
		Runnable onManageAccountStateUpdate)
	{
		this.openAccountPanelButton = openAccountPanelButton;
		this.albumFooterWrap = albumFooterWrap;
		this.cloudSessionService = cloudSessionService;
		this.onManageAccountStateUpdate = onManageAccountStateUpdate;
		sidebarNoticeContent.setOpaque(false);
		sidebarNoticeMessageWrap.setOpaque(false);
		sidebarNoticeButtonWrap.setOpaque(false);
		sidebarNoticeButtonWrap.setBorder(new EmptyBorder(8, 0, 0, 0));
		sidebarNoticeContent.add(sidebarNoticeMessageWrap, BorderLayout.CENTER);
		sidebarNoticeContent.add(sidebarNoticeButtonWrap, BorderLayout.SOUTH);
	}
/** @return the root panel for this notice, to be added under {@link #CARD} in a CardLayout. */
	public JPanel content()
	{
		return sidebarNoticeContent;
	}
/** Shows the event-worlds-unavailable message, with no account panel button. */
	public void showEventWorldUnavailable(Runnable hideChrome)
	{
		showFullSidebarNotice(EVENT_WORLD_UNAVAILABLE, false, hideChrome);
	}
/** Shows the account-banned or account-quarantined message (per current session state), with the account panel button. */
	public void showAccountLockedNotice(Runnable hideChrome)
	{
		String message = cloudSessionService.isAccountBanned()
			? CloudSessionService.ACCOUNT_BANNED_STATUS
			: CloudSessionService.ACCOUNT_QUARANTINED_STATUS;
		showFullSidebarNotice(message, true, hideChrome);
	}
/**
	 * Renders the notice card: runs {@code hideChrome} to hide normal tab UI, sets the message text,
	 * and either reparents the account panel button into this view or restores it to the footer.
	 */
	public void showFullSidebarNotice(String messageText, boolean showAccountPanelButton, Runnable hideChrome)
	{
		hideChrome.run();

		sidebarNoticeMessageWrap.removeAll();
		JLabel message = new JLabel("<html><div style='text-align:center;width:180px'>"
			+ messageText
			+ "</div></html>");
		message.setForeground(Color.WHITE);
		message.setFont(FontManager.getRunescapeSmallFont());
		message.setHorizontalAlignment(SwingConstants.CENTER);
		sidebarNoticeMessageWrap.add(message);

		sidebarNoticeButtonWrap.removeAll();
		if (showAccountPanelButton)
		{
			reparentAccountPanelButton(sidebarNoticeButtonWrap);
			sidebarNoticeButtonWrap.setVisible(true);
			onManageAccountStateUpdate.run();
		}
		else
		{
			restoreAccountPanelToFooter();
			sidebarNoticeButtonWrap.setVisible(false);
		}

		sidebarNoticeContent.revalidate();
		sidebarNoticeContent.repaint();
	}
/** Moves the account panel button into {@code target} (a no-op if it's already there), revalidating both containers. */
	public void reparentAccountPanelButton(JPanel target)
	{
		if (target == null || openAccountPanelButton == null)
		{
			return;
		}
		Container parent = openAccountPanelButton.getParent();
		if (parent == target)
		{
			return;
		}
		if (parent != null)
		{
			parent.remove(openAccountPanelButton);
			parent.revalidate();
			parent.repaint();
		}
		target.add(openAccountPanelButton, BorderLayout.CENTER);
		target.revalidate();
		target.repaint();
	}
/** Moves the account panel button back to its normal footer location. */
	public void restoreAccountPanelToFooter()
	{
		if (openAccountPanelButton == null || albumFooterWrap == null)
		{
			return;
		}
		reparentAccountPanelButton(albumFooterWrap);
	}
}

package com.osrstcg.ui.card;

import com.osrstcg.catalog.CardDefinition;
import java.awt.Color;
import java.awt.image.BufferedImage;
import lombok.Getter;
/**
 * Immutable, builder-constructed bundle of everything needed to render one card face: art, rarity color,
 * labels/score, and the optional foil/wear effect state.
 */
@Getter
public final class CardFaceDrawRequest
{
	private final CardDefinition card;
	private final BufferedImage art;
	private final String artKey;
	private final boolean foil;
	private final Color rarityColor;
	private final String tierLabel;
	private final Long displayScore;
	private final boolean useFoilAdjustedScore;
	private final WearFx wear;
	private final FoilFx foilFx;
/** Copies and normalizes builder fields: blanks artKey to null, defaults rarityColor to white, and drops foilFx when not foil. */
	private CardFaceDrawRequest(Builder b)
	{
		this.card = b.card;
		this.art = b.art;
		this.artKey = b.artKey == null || b.artKey.isBlank() ? null : b.artKey.trim();
		this.foil = b.foil;
		this.rarityColor = b.rarityColor == null ? Color.WHITE : b.rarityColor;
		this.tierLabel = b.tierLabel;
		this.displayScore = b.displayScore;
		this.useFoilAdjustedScore = b.useFoilAdjustedScore == null ? b.foil : b.useFoilAdjustedScore;
		this.wear = b.wear;
		this.foilFx = (!b.foil) ? null : b.foilFx;
	}
/** True when this is a foil card with a full-art foil image path defined on {@link #card}. */
	public boolean isFullArt()
	{
		if (!foil || card == null)
		{
			return false;
		}
		String path = card.getFoilImagePath();
		return path != null && !path.isBlank();
	}
/** Starts a new {@link Builder}. */
	public static Builder builder()
	{
		return new Builder();
	}
/** Fluent builder for {@link CardFaceDrawRequest}; every setter returns {@code this}. */
	public static final class Builder
	{
		private CardDefinition card;
		private BufferedImage art;
		private String artKey;
		private boolean foil;
		private Color rarityColor = Color.WHITE;
		private String tierLabel;
		private Long displayScore;
		private Boolean useFoilAdjustedScore;
		private WearFx wear;
		private FoilFx foilFx;
/** Sets the card definition being rendered. */
		public Builder card(CardDefinition value)
		{
			this.card = value;
			return this;
		}
/** Sets the base card art image. */
		public Builder art(BufferedImage value)
		{
			this.art = value;
			return this;
		}
/** Sets the cache key identifying this art variant (trimmed and null-if-blank on build). */
		public Builder artKey(String value)
		{
			this.artKey = value;
			return this;
		}
/** Sets whether this card is foil. */
		public Builder foil(boolean value)
		{
			this.foil = value;
			return this;
		}
/** Sets the rarity tier color (defaults to white if never set or set null). */
		public Builder rarityColor(Color value)
		{
			this.rarityColor = value;
			return this;
		}
/** Sets the tier label text. */
		public Builder tierLabel(String value)
		{
			this.tierLabel = value;
			return this;
		}
/** Sets the score value to display. */
		public Builder displayScore(Long value)
		{
			this.displayScore = value;
			return this;
		}
/** Sets whether the displayed score is foil-adjusted; unset defaults to the {@link #foil} flag. */
		public Builder useFoilAdjustedScore(boolean value)
		{
			this.useFoilAdjustedScore = value;
			return this;
		}
/** Sets the wear (condition damage) effect to render. */
		public Builder wear(WearFx value)
		{
			this.wear = value;
