package com.osrstcg.ui.card;
/**
 * Card condition grade (S best to E worst), each carrying a wear-effect intensity and color-fade amount
 * used to drive {@link WearFx} and {@link CardFxPainter}.
 */
public enum CardGrade
{
	S(0.0d, 0.0d),
	A(0.14d, 0.12d),
	B(0.28d, 0.22d),
	C(0.48d, 0.36d),
	D(0.68d, 0.50d),
	E(0.85d, 0.64d);

	private final double intensity;
	private final double fade;
/** Stores the wear intensity and color-fade amounts for this grade. */
	CardGrade(double intensity, double fade)
	{
		this.intensity = intensity;
		this.fade = fade;
	}
/** Strength of scratch/dirt/edge wear effects for this grade (0 = none). */
	public double getIntensity()
	{
		return intensity;
	}
/** Amount of color desaturation/darkening applied for this grade (0 = none). */
	public double getFade()
	{
		return fade;
	}
/** Maps a 0-100 condition value to a grade band; returns null for a null/NaN/infinite condition. */
	public static CardGrade gradeFromCondition(Double condition)
	{
		if (condition == null || condition.isNaN() || condition.isInfinite())
		{
			return null;
		}
		double c = condition;
		if (c >= 95.0d)
		{
			return S;
		}
		if (c >= 75.0d)
		{
			return A;
		}
		if (c >= 50.0d)
		{
			return B;
		}
		if (c >= 25.0d)
		{
			return C;
		}
		if (c >= 5.0d)
		{
			return D;
		}
		return E;
	}
/** Formats a condition value to two decimal places, or null for a null/NaN/infinite input. */
	public static String formatCondition(Double condition)
	{
		if (condition == null || condition.isNaN() || condition.isInfinite())
		{
			return null;
		}
		return String.format(java.util.Locale.US, "%.2f", condition);
	}

	public static String gradeConditionSuffix(Double condition)
	{
		CardGrade g = gradeFromCondition(condition);
		return g == null ? "" : " - " + g.name() + " (" + formatCondition(condition) + ")";
	}
}

package com.osrstcg.ui.card;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.Value;
/**
 * Deterministic wear (condition damage) layout for a card: a seeded set of scratches and dirt spots plus
 * dirt/edge mix ratios, generated from the card's grade and pull identity so the same card always renders
 * the same wear pattern. Consumed by {@link CardFxPainter#drawWear}.
 */
@Getter
public final class WearFx
{
/** Silhouette used to render one dirt {@link Spot}. */
	public enum SpotShape
	{
		ROUND,
		ELLIPSE,
		SMEAR,
		BLOB,
		SPLOTCH
	}
/** Seeded Mulberry32 PRNG producing doubles in [0, 1), used for deterministic wear generation. */
	public static final class Mulberry32
	{
		private int a;
/** Seeds the generator; a zero seed is replaced with a fixed non-zero constant. */
		public Mulberry32(int seed)
		{
			this.a = seed == 0 ? 0x9E3779B9 : seed;
		}
/** Advances the generator and returns the next pseudo-random value in [0, 1). */
		public double next()
		{
			a = a + 0x6D2B79F5;
			int t = (a ^ (a >>> 15)) * (1 | a);
			t = (t + ((t ^ (t >>> 7)) * (61 | t))) ^ t;
			return ((t ^ (t >>> 14)) & 0xFFFFFFFFL) / 4294967296.0d;
		}
	}
/** A single scratch mark: position (percent), length (percent of width), rotation angle, and opacity. */
	@Value
	public static class Scratch
	{
		double x;
		double y;
		double len;
		double angle;
		double opacity;
	}
/** A single dirt spot: position/size (percent), rotation, per-corner border radius, blur amount, shape, and opacity. */
	@Value
	public static class Spot
	{
		double x;
		double y;
		double w;
		double h;
		double rotate;
		@Getter(AccessLevel.NONE)
		double[] borderRadius;
		double blur;
		SpotShape shape;
		double opacity;
/** Defensive copy of the 8-element per-corner border radius array. */
		public double[] getBorderRadius()
		{
			return borderRadius.clone();
		}
	}

	private final int seed;
	private final CardGrade grade;
	private final double dirtMix;
	private final double edgeMix;
	private final List<Scratch> scratches;
	private final List<Spot> spots;
/** Stores the seed, grade, mix ratios, and wraps the scratch/spot lists as unmodifiable. */
	private WearFx(int seed, CardGrade grade, double dirtMix, double edgeMix, List<Scratch> scratches, List<Spot> spots)
	{
		this.seed = seed;
		this.grade = grade;
		this.dirtMix = dirtMix;
		this.edgeMix = edgeMix;
		this.scratches = Collections.unmodifiableList(scratches);
		this.spots = Collections.unmodifiableList(spots);
	}
/** FNV-1a hash of a string to a 32-bit seed value. */
	public static int hashStringToSeed(String str)
	{
		int h = 0x811C9DC5;
		if (str == null)
		{
			return h;
		}
		for (int i = 0; i < str.length(); i++)
		{
			h ^= str.charAt(i);
			h *= 16777619;
		}
		return h;
	}
/**
	 * Derives a wear seed by hashing the card name, puller, and pull time together, so wear stays stable
	 * across renders of the same pulled copy. Falls back to {@code fallback} (or 1) when all three are empty/zero;
	 * a zero hash result is also mapped to 1 (a valid Mulberry32 seed).
	 */
	public static int wearSeedFromPull(String cardName, String pulledBy, Long pulledAt, int fallback)
	{
		String name = cardName == null ? "" : cardName.trim();
		String by = pulledBy == null ? "" : pulledBy.trim();
		long at = pulledAt == null ? 0L : pulledAt;
		if (name.isEmpty() && by.isEmpty() && at == 0L)
		{
			return fallback == 0 ? 1 : fallback;
		}
		int h = hashStringToSeed(name + "|" + by + "|" + at);
		return h == 0 ? 1 : h;
	}
/**
	 * Builds a {@link WearFx} for a card copy from its condition and pull identity. Returns null
	 * for a grade with zero intensity and fade (i.e. mint condition needs no wear effect). Seeds a PRNG
	 * from the pull identity and, for grades below A, generates randomized scratches; all non-mint grades get
	 * randomized dirt spots (fewer/gentler for grade A, scaled by intensity otherwise).
	 */
	public static WearFx wearFxFromCondition(Double condition, Long pulledAt, String cardName, String pulledBy)
	{
		CardGrade grade = CardGrade.gradeFromCondition(condition);
		if (grade == null)
		{
			return null;
		}
		double intensity = grade.getIntensity();
		double fade = grade.getFade();
		if (intensity <= 0.0d && fade <= 0.0d)
		{
			return null;
		}

		int fallback = conditionFallbackSeed(condition);
		int seed = wearSeedFromPull(cardName, pulledBy, pulledAt, fallback);
		Mulberry32 rand = new Mulberry32(seed);

		double profile = rand.next();
		boolean detailWear = grade != CardGrade.A && grade != CardGrade.S;

		double scratchMix;
		double dirtMix;
		double edgeMix;
		if (detailWear)
		{
			scratchMix = 0.22d + profile * 0.78d;
			dirtMix = 0.22d + (1.0d - profile) * 0.78d;
			edgeMix = 0.25d + rand.next() * 0.55d;
			edgeMix *= 0.55d + scratchMix * 0.45d;
		}
		else
		{
			dirtMix = 0.55d + rand.next() * 0.45d;
			scratchMix = 0.0d;
			edgeMix = 0.0d;
		}

		List<Scratch> scratches = new ArrayList<>();
		if (detailWear)
		{
			long scratchCount = Math.round((1.0d + intensity * 14.0d) * scratchMix);
			for (long i = 0; i < scratchCount; i++)
			{
				double x = 6.0d + rand.next() * 88.0d;
				double y = 8.0d + rand.next() * 84.0d;
				double len = 8.0d + rand.next() * (10.0d + intensity * 30.0d * scratchMix);
				double angle = -42.0d + rand.next() * 84.0d;
				double opacity = (0.12d + rand.next() * (0.14d + intensity * 0.38d)) * (0.65d + scratchMix * 0.35d);
				scratches.add(new Scratch(x, y, len, angle, opacity));
			}
		}

		boolean gradeA = grade == CardGrade.A;
		long spotBudget = gradeA
			? Math.round((2.0d + rand.next() * 3.0d) * dirtMix)
			: Math.round((1.0d + intensity * 12.0d) * dirtMix);

		List<Spot> spots = new ArrayList<>();
		for (long i = 0; i < spotBudget; i++)
		{
			double baseSize = (gradeA ? 3.0d : 4.0d)
				+ rand.next() * (gradeA ? 5.0d : 6.0d + intensity * 14.0d * dirtMix);
			SpotGeom geom = spotGeometry(rand, baseSize);
			double x = 8.0d + rand.next() * 84.0d;
			double y = 10.0d + rand.next() * 80.0d;
			double opacity = ((gradeA ? 0.06d : 0.09d)
				+ rand.next() * (gradeA ? 0.08d : 0.1d + intensity * 0.28d))
				* (0.6d + dirtMix * 0.4d);
			spots.add(new Spot(x, y, geom.w, geom.h, geom.rotate, geom.borderRadius, geom.blur, geom.shape, opacity));
		}

		return new WearFx(seed, grade, dirtMix, edgeMix, scratches, spots);
	}
/** Derives a fallback seed from the raw condition value (scaled to an int) when no pull identity is available; never returns 0. */
	private static int conditionFallbackSeed(Double condition)
	{
		if (condition == null || condition.isNaN() || condition.isInfinite())
		{
			return 1;
		}
		long v = Math.round(condition * 100.0d);
		if (v == 0L)
		{
			return 1;
		}
		return (int) v;
	}
/** Intermediate geometry (shape, size, rotation, border radii, blur) for one dirt spot before wrapping in a {@link Spot}. */
	private static final class SpotGeom
	{
		final SpotShape shape;
		final double w;
		final double h;
		final double rotate;
		final double[] borderRadius;
		final double blur;
/** Stores the computed spot geometry fields verbatim. */
		SpotGeom(SpotShape shape, double w, double h, double rotate, double[] borderRadius, double blur)
		{
			this.shape = shape;
			this.w = w;
			this.h = h;
			this.rotate = rotate;
			this.borderRadius = borderRadius;
			this.blur = blur;
		}
	}
/** Random per-corner border radii (8 values, 22-80%) for an organic (blob/splotch) spot outline. */
	private static double[] organicBorderRadius(Mulberry32 rand)
	{
		double[] corners = new double[8];
		for (int i = 0; i < 8; i++)
		{
			corners[i] = Math.round(22.0d + rand.next() * 58.0d);
		}
		return corners;
	}
/** All 8 border-radius corners set to the same percentage (used for round/ellipse/smear spots). */
	private static double[] uniformRadius(double percent)
	{
		double[] corners = new double[8];
		for (int i = 0; i < 8; i++)
		{
			corners[i] = percent;
		}
		return corners;
	}
/** Randomly picks a spot shape (weighted round/ellipse/smear/blob/splotch) and generates its size, rotation, border radii, and blur. */
	private static SpotGeom spotGeometry(Mulberry32 rand, double baseSize)
	{
		double pick = rand.next();
		SpotShape shape;
		if (pick < 0.2d)
		{
			shape = SpotShape.ROUND;
		}
		else if (pick < 0.42d)
		{
			shape = SpotShape.ELLIPSE;
		}
		else if (pick < 0.62d)
		{
			shape = SpotShape.SMEAR;
		}
		else if (pick < 0.82d)
		{
			shape = SpotShape.BLOB;
		}
		else
		{
			shape = SpotShape.SPLOTCH;
		}

		switch (shape)
		{
			case ELLIPSE:
			{
				double w = baseSize * (0.65d + rand.next() * 0.95d);
				double h = baseSize * (0.38d + rand.next() * 0.58d);
				double rotate = rand.next() * 180.0d;
				return new SpotGeom(shape, w, h, rotate, uniformRadius(50.0d), 0.0d);
			}
			case SMEAR:
			{
				double w = baseSize * (1.4d + rand.next() * 2.4d);
				double h = baseSize * (0.16d + rand.next() * 0.3d);
				double rotate = rand.next() * 180.0d;
				double radius = Math.round(30.0d + rand.next() * 25.0d);
				double blur = 0.35d + rand.next() * 0.65d;
				return new SpotGeom(shape, w, h, rotate, uniformRadius(radius), blur);
			}
			case BLOB:
			{
				double w = baseSize * (0.72d + rand.next() * 0.75d);
				double h = baseSize * (0.62d + rand.next() * 0.85d);
				double rotate = rand.next() * 360.0d;
				double[] radius = organicBorderRadius(rand);
				double blur = 0.2d + rand.next() * 0.55d;
				return new SpotGeom(shape, w, h, rotate, radius, blur);
			}
			case SPLOTCH:
			{
				double w = baseSize * (0.82d + rand.next() * 0.62d);
				double h = baseSize * (0.7d + rand.next() * 0.72d);
				double rotate = -45.0d + rand.next() * 90.0d;
				double[] radius = organicBorderRadius(rand);
				double blur = 0.25d + rand.next() * 0.75d;
				return new SpotGeom(shape, w, h, rotate, radius, blur);
			}
			default:
				return new SpotGeom(SpotShape.ROUND, baseSize, baseSize, 0.0d, uniformRadius(50.0d), 0.0d);
		}
	}
}

package com.osrstcg.ui.card;

import java.awt.Font;
import java.awt.FontMetrics;
import java.util.ArrayList;
import java.util.List;
/**
 * Word-wraps card examine text to a pixel width (breaking mid-word if a single token overflows) and binary
 * searches for the largest examine font size ({@link #EXAMINE_EM_MIN}-{@link #EXAMINE_EM_MAX}) that still fits a band.
 */
public final class ExamineTextLayout
{
	public static final float EXAMINE_EM_MAX = 1.18f;
	public static final float EXAMINE_EM_MIN = 0.72f;
	public static final float EXAMINE_LINE_HEIGHT = 1.05f;
	public static final int EXAMINE_FIT_STEPS = 12;

	private ExamineTextLayout()
	{
	}
/** Line height in pixels for a given font size, using {@link #EXAMINE_LINE_HEIGHT}. */
	public static int lineHeightPx(float fontSizePx)
	{
		return Math.max(1, Math.round(fontSizePx * EXAMINE_LINE_HEIGHT));
	}
/**
	 * Wraps {@code text} to {@code maxWidth} pixels, breaking on whitespace and splitting any single word
	 * that still overflows the width. Normalizes line endings and preserves blank lines/paragraphs.
	 */
	public static List<String> wrapBreakWord(FontMetrics fm, String text, int maxWidth)
	{
		List<String> lines = new ArrayList<>();
		String raw = text == null ? "" : text.replace("\r\n", "\n").replace('\r', '\n').trim();
		if (raw.isEmpty())
		{
			lines.add("");
			return lines;
		}
		int width = Math.max(1, maxWidth);
		String[] paragraphs = raw.split("\n", -1);
		for (String paragraph : paragraphs)
		{
			if (paragraph.isEmpty())
			{
				lines.add("");
				continue;
			}
			wrapParagraphBreakWord(fm, paragraph, width, lines);
		}
		if (lines.isEmpty())
		{
			lines.add("");
		}
		return lines;
	}
/** Greedily packs whitespace-split tokens of one paragraph onto lines no wider than {@code width}, appending to {@code lines}. */
	private static void wrapParagraphBreakWord(
		FontMetrics fm, String paragraph, int width, List<String> lines)
	{
		StringBuilder current = new StringBuilder();
		for (String token : paragraph.split("\\s+"))
		{
			if (token == null || token.isEmpty())
			{
				continue;
			}
			if (current.length() == 0)
			{
				if (fm.stringWidth(token) <= width)
				{
					current.append(token);
				}
				else
				{
					breakTokenAcrossLines(fm, token, width, lines, current);
				}
			}
			else if (fm.stringWidth(current + " " + token) <= width)
			{
				current.append(' ').append(token);
			}
			else
			{
				lines.add(current.toString());
				current.setLength(0);
				if (fm.stringWidth(token) <= width)
				{
					current.append(token);
				}
				else
				{
					breakTokenAcrossLines(fm, token, width, lines, current);
				}
			}
		}
		if (current.length() > 0)
		{
			lines.add(current.toString());
		}
	}
/**
	 * Binary-searches (over {@link #EXAMINE_FIT_STEPS} steps) for the largest em size in
	 * [{@link #EXAMINE_EM_MIN}, {@link #EXAMINE_EM_MAX}] at which the wrapped text fits within
	 * {@code maxWidth} x {@code bandHeight}. Returns {@link #EXAMINE_EM_MAX} for blank text.
	 */
	public static float fitExamineEm(FontMetricsFactory metrics, double scale, String text, int maxWidth, int bandHeight)
	{
		String examine = text == null ? "" : text.trim();
		if (examine.isEmpty())
		{
			return EXAMINE_EM_MAX;
		}
		int width = Math.max(1, maxWidth);
		int height = Math.max(1, bandHeight);

		if (fits(metrics, scale, examine, width, height, EXAMINE_EM_MAX))
		{
			return EXAMINE_EM_MAX;
		}

		float best = EXAMINE_EM_MIN;
		float lo = EXAMINE_EM_MIN;
		float hi = EXAMINE_EM_MAX;
		for (int i = 0; i < EXAMINE_FIT_STEPS; i++)
		{
			float mid = (lo + hi) * 0.5f;
			if (fits(metrics, scale, examine, width, height, mid))
			{
				best = mid;
				lo = mid;
			}
			else
			{
				hi = mid;
			}
		}
		return Math.round(best * 1000f) / 1000f;
	}
/** Whether {@code text}, wrapped at {@code em} size, fits within {@code maxWidth} x {@code bandHeight} (with 0.5px slack). */
	public static boolean fits(
		FontMetricsFactory metrics, double scale, String text, int maxWidth, int bandHeight, float em)
	{
		Font font = CardFonts.examine(scale, em);
		FontMetrics fm = metrics.metricsFor(font);
		List<String> lines = wrapBreakWord(fm, text, maxWidth);
		int lineH = lineHeightPx(font.getSize2D());
		return lines.size() * lineH <= bandHeight + 0.5f;
	}
/** Supplies {@link FontMetrics} for a given font, so layout can be measured without a live graphics context. */
	@FunctionalInterface
	public interface FontMetricsFactory
	{
		FontMetrics metricsFor(Font font);
	}
/**
	 * Splits a single overflowing word into width-limited chunks appended to {@code lines}, leaving the
	 * final chunk in {@code current} for the caller to keep accumulating. Respects surrogate pairs so
	 * multi-char code points are never split.
	 */
	private static void breakTokenAcrossLines(
		FontMetrics fm, String token, int maxWidth, List<String> lines, StringBuilder current)
	{
		int i = 0;
		int len = token.length();
		while (i < len)
		{
			int take = 0;
			while (i + take < len)
			{
				int next = i + take + 1;
				if (Character.isHighSurrogate(token.charAt(i + take)) && next < len
					&& Character.isLowSurrogate(token.charAt(next)))
				{
					next++;
				}
				String candidate = token.substring(i, next);
				if (fm.stringWidth(candidate) <= maxWidth)
				{
					take = next - i;
				}
				else
				{
					break;
				}
			}
			if (take <= 0)
			{
				int next = i + 1;
				if (Character.isHighSurrogate(token.charAt(i)) && next < len
					&& Character.isLowSurrogate(token.charAt(next)))
				{
					next++;
				}
				take = next - i;
			}
			String chunk = token.substring(i, i + take);
			i += take;
			if (i >= len)
			{
				current.append(chunk);
			}
			else
			{
				lines.add(chunk);
			}
		}
	}
}

package com.osrstcg.ui.card;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.LinearGradientPaint;
import java.awt.MultipleGradientPaint;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.AffineTransform;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.Point2D;
import java.awt.geom.Rectangle2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.awt.image.ConvolveOp;
import java.awt.image.DataBufferInt;
import java.awt.image.Kernel;
/**
 * Pixel-level renderer for card visual effects: foil sparkle animation and multi-layer wear (color wash,
 * grime, edge shadows, scratches, spots) painted directly onto a card face image via custom Porter-Duff-style
 * blend modes.
 */
public final class CardFxPainter
{
	private static final double BEZIER_K = 0.5522847498307936d;
/** Pixel compositing modes used to blend an effect layer onto the base card face. */
	public enum BlendMode
	{
		MULTIPLY,
		SOFT_LIGHT,
		LUMINOSITY
	}

	private CardFxPainter()
	{
	}
/** Creates a transparent ARGB scratch layer of at least 1x1 pixels. */
	private static BufferedImage newLayer(int width, int height)
	{
		return new BufferedImage(Math.max(1, width), Math.max(1, height), BufferedImage.TYPE_INT_ARGB);
	}
/** Returns the backing int-ARGB pixel array of an image for direct read/write access. */
	private static int[] pixels(BufferedImage img)
	{
		return ((DataBufferInt) img.getRaster().getDataBuffer()).getData();
	}
/** Creates a {@link Graphics2D} for {@code img} with antialiasing and quality rendering hints enabled. */
	static Graphics2D quality(BufferedImage img)
	{
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		return g;
	}
/**
	 * Composites {@code layer} onto {@code base} in place using {@code mode}, scaled by {@code opacity} and
	 * each source pixel's own alpha. No-ops on null images, non-positive opacity, or fully transparent pixels
	 * on either side.
	 */
	private static void blend(BufferedImage base, BufferedImage layer, BlendMode mode, double opacity)
	{
		if (base == null || layer == null || opacity <= 0.0d)
		{
			return;
		}
		int[] dst = pixels(base);
		int[] src = pixels(layer);
		int n = Math.min(dst.length, src.length);
		double op = Math.min(1.0d, opacity);
		double[] blended = new double[3];

		for (int i = 0; i < n; i++)
		{
			int s = src[i];
			int sa = s >>> 24;
			if (sa == 0)
			{
				continue;
			}
			int d = dst[i];
			int da = d >>> 24;
			if (da == 0)
			{
				continue;
			}

			double f = (sa / 255.0d) * op;
			double sr = ((s >> 16) & 0xFF) / 255.0d;
			double sg = ((s >> 8) & 0xFF) / 255.0d;
			double sb = (s & 0xFF) / 255.0d;
			double br = ((d >> 16) & 0xFF) / 255.0d;
			double bg = ((d >> 8) & 0xFF) / 255.0d;
			double bb = (d & 0xFF) / 255.0d;

			applyMode(mode, br, bg, bb, sr, sg, sb, blended);
			int r = to255(br + (blended[0] - br) * f);
			int g = to255(bg + (blended[1] - bg) * f);
			int b = to255(bb + (blended[2] - bb) * f);
			dst[i] = (da << 24) | (r << 16) | (g << 8) | b;
		}
	}
/** Computes the blended RGB (0-1 each) for base color ({@code br,bg,bb}) and source color ({@code sr,sg,sb}) under {@code mode}, written to {@code out}. */
	private static void applyMode(BlendMode mode, double br, double bg, double bb, double sr, double sg, double sb,
		double[] out)
	{
		switch (mode)
		{
			case MULTIPLY:
				out[0] = br * sr;
				out[1] = bg * sg;
				out[2] = bb * sb;
				return;
			case SOFT_LIGHT:
				out[0] = softLight(br, sr);
				out[1] = softLight(bg, sg);
				out[2] = softLight(bb, sb);
				return;
			case LUMINOSITY:
				setLuminosity(br, bg, bb, luminosity(sr, sg, sb), out);
		}
	}
/** Standard "soft light" blend of backdrop {@code cb} and source {@code cs} channels (each 0-1). */
	private static double softLight(double cb, double cs)
	{
		if (cs <= 0.5d)
		{
			return cb - (1.0d - 2.0d * cs) * cb * (1.0d - cb);
		}
		double d = cb <= 0.25d ? ((16.0d * cb - 12.0d) * cb + 4.0d) * cb : Math.sqrt(cb);
		return cb + (2.0d * cs - 1.0d) * (d - cb);
	}
/** Perceptual luminosity of an RGB color (0-1 each). */
	private static double luminosity(double r, double g, double b)
	{
		return 0.3d * r + 0.59d * g + 0.11d * b;
	}
/** Shifts {@code r,g,b} to have {@code targetLum} luminosity, then clips back into the 0-1 gamut, written to {@code out}. */
	private static void setLuminosity(double r, double g, double b, double targetLum, double[] out)
	{
		double d = targetLum - luminosity(r, g, b);
		double nr = r + d;
		double ng = g + d;
		double nb = b + d;

		double lum = luminosity(nr, ng, nb);
		double min = Math.min(nr, Math.min(ng, nb));
		double max = Math.max(nr, Math.max(ng, nb));
		if (min < 0.0d && lum != min)
		{
			double k = lum / (lum - min);
			nr = lum + (nr - lum) * k;
			ng = lum + (ng - lum) * k;
			nb = lum + (nb - lum) * k;
		}
		if (max > 1.0d && max != lum)
		{
			double k = (1.0d - lum) / (max - lum);
			nr = lum + (nr - lum) * k;
			ng = lum + (ng - lum) * k;
			nb = lum + (nb - lum) * k;
		}
		out[0] = nr;
		out[1] = ng;
		out[2] = nb;
	}
/** Converts a 0-1 channel to a clamped 0-255 int. */
	private static int to255(double v)
	{
		int i = (int) Math.round(v * 255.0d);
		return i < 0 ? 0 : Math.min(i, 255);
	}
/**
	 * Desaturates, and slightly reduces contrast/brightness of, {@code base} in place, scaled by {@code fade}
	 * (0-1). No-ops on a null image or non-positive fade.
	 */
	public static void applyWearFilter(BufferedImage base, double fade)
	{
		if (base == null || fade <= 0.0d)
		{
			return;
		}
		double sat = 1.0d - fade * 0.72d;
		double contrast = 1.0d - fade * 0.08d;
		double brightness = 1.0d - fade * 0.06d;

		double rr = 0.213d + 0.787d * sat;
		double rg = 0.715d - 0.715d * sat;
		double rb = 0.072d - 0.072d * sat;
		double gr = 0.213d - 0.213d * sat;
		double gg = 0.715d + 0.285d * sat;
		double gb = 0.072d - 0.072d * sat;
		double bbr = 0.213d - 0.213d * sat;
		double bg = 0.715d - 0.715d * sat;
		double bb = 0.072d + 0.928d * sat;

		int[] px = pixels(base);
		for (int i = 0; i < px.length; i++)
		{
			int p = px[i];
			int a = p >>> 24;
			if (a == 0)
			{
				continue;
			}
			double r = ((p >> 16) & 0xFF) / 255.0d;
			double g = ((p >> 8) & 0xFF) / 255.0d;
			double b = (p & 0xFF) / 255.0d;

			double nr = rr * r + rg * g + rb * b;
			double ng = gr * r + gg * g + gb * b;
			double nb = bbr * r + bg * g + bb * b;

			nr = ((nr - 0.5d) * contrast + 0.5d) * brightness;
			ng = ((ng - 0.5d) * contrast + 0.5d) * brightness;
			nb = ((nb - 0.5d) * contrast + 0.5d) * brightness;

			px[i] = (a << 24) | (to255(nr) << 16) | (to255(ng) << 8) | to255(nb);
		}
	}
/**
	 * Draws {@code fx}'s foil sparkles (clipped to a rounded-rect card outline at {@code x,y,w,h}) as radial
	 * glow gradients, each sampled from {@link FoilSparkleAnimation} at {@code timeSec} for its current
	 * opacity/scale. No-ops on a null graphics/fx or a degenerate (sub-2px) size.
	 */
	public static void drawAnimatedSparkles(Graphics2D g, int x, int y, int w, int h, double cornerRadius,
		double scale, FoilFx fx, double timeSec)
	{
		if (g == null || fx == null || w < 2 || h < 2)
		{
			return;
		}
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
			Shape card = new RoundRectangle2D.Double(x, y, w, h, cornerRadius * 2.0d, cornerRadius * 2.0d);
			g2.clip(card);

			double glow = 3.125d * scale;
			for (FoilFx.Sparkle s : fx.getSparkles())
			{
				FoilSparkleAnimation.Sample anim = FoilSparkleAnimation.sample(s.getDelay(), s.getDuration(), timeSec);
				if (anim.getOpacity() <= 0.001d)
				{
					continue;
				}
				double d = Math.max(0.5d, s.getSize() * scale * anim.getScale());
				double cx = x + s.getX() / 100.0d * w;
				double cy = y + s.getY() / 100.0d * h;
				Color core = CardColorMath.hsla(s.getHue(), s.getSat(), s.getLight(), anim.getOpacity());
				double outer = d / 2.0d + glow;
				float coreFrac = (float) Math.max(0.05d, Math.min(0.9d, (d / 2.0d) / outer));
				float midFrac = coreFrac + (1f - coreFrac) * 0.3f;
				g2.setPaint(new RadialGradientPaint(
					new Point2D.Double(cx, cy), (float) outer,
					new float[]{0f, coreFrac, midFrac, 1f},
					new Color[]{core, core, alpha(core, anim.getOpacity() * 0.28d), alpha(core, 0.0d)},
					MultipleGradientPaint.CycleMethod.NO_CYCLE));
				g2.fill(new Ellipse2D.Double(cx - outer, cy - outer, outer * 2.0d, outer * 2.0d));
			}
		}
		finally
		{
			g2.dispose();
		}
	}
/**
	 * Paints the full wear pipeline onto {@code face} in place: color wash, grime, edge shadows (skipped for
	 * grades A/S), scratches, and dirt spots, each layer driven by {@code wear}'s grade and randomized detail.
	 * No-ops on a null face or wear.
	 */
	public static void drawWear(BufferedImage face, double cornerRadius, WearFx wear)
	{
		if (face == null || wear == null)
		{
			return;
		}
		int w = face.getWidth();
		int h = face.getHeight();
		Shape card = new RoundRectangle2D.Double(0, 0, w, h, cornerRadius * 2.0d, cornerRadius * 2.0d);
		CardGrade grade = wear.getGrade();

		drawColorWash(face, card, w, h, grade.getFade());
		drawGrime(face, card, w, h, wear);
		if (grade != CardGrade.A && grade != CardGrade.S)
		{
			applyEdges(face, w, h, wear);
		}
		drawScratches(face, card, w, h, wear);
		drawSpots(face, card, w, h, wear);
	}
/** Blends a diagonal light-to-dark gradient over {@code face} (luminosity mode) to fade/darken the card by {@code fade}. */
	private static void drawColorWash(BufferedImage face, Shape card, int w, int h, double fade)
	{
		Color light = new Color(255, 255, 255);
		Color dark = new Color(26, 26, 26);
		BufferedImage layer = newLayer(w, h);
		Graphics2D g = quality(layer);
		try
		{
			g.setPaint(cssLinearGradient(w, h, 160.0d,
				new float[]{0f, 0.40f, 0.4001f, 1f},
				new Color[]{alpha(light, 0.04d * fade), alpha(light, 0.0d), alpha(dark, 0.0d), alpha(dark, 0.22d * fade)}));
			g.fill(card);
		}
		finally
		{
			g.dispose();
		}
		blend(face, layer, BlendMode.LUMINOSITY, 0.35d + fade * 0.65d);
	}
/** Multiply-blends three fixed dark radial patches onto {@code face} to simulate grime buildup, scaled by grade intensity and {@link WearFx#getDirtMix()}. */
	private static void drawGrime(BufferedImage face, Shape card, int w, int h, WearFx wear)
	{
		double i = wear.getGrade().getIntensity();
		double dirt = wear.getDirtMix();
		BufferedImage layer = newLayer(w, h);
		Graphics2D g = quality(layer);
		try
		{
			g.clip(card);
			radialEllipse(g, w, h, 0.55d, 0.40d, 0.50d, 0.40d, new Color(32, 32, 32), 0.14d * i * dirt, 0.75d);
			radialEllipse(g, w, h, 0.78d, 0.70d, 0.35d, 0.28d, new Color(18, 18, 18), 0.32d * i * dirt, 0.70d);
			radialEllipse(g, w, h, 0.18d, 0.22d, 0.40d, 0.30d, new Color(26, 26, 26), 0.34d * i * dirt, 0.70d);
		}
		finally
		{
			g.dispose();
		}
		double opacity = wear.getGrade() == CardGrade.A
			? 0.45d
			: (0.3d + i * 0.7d) * (0.35d + dirt * 0.65d);
		blend(face, layer, BlendMode.MULTIPLY, opacity);
	}
/** Transform that squashes a circular gradient centered at {@code cx,cy} into an ellipse of radii {@code rx,ry}. */
	private static AffineTransform ellipseScaleTx(double cx, double cy, double rx, double ry)
	{
		AffineTransform tx = new AffineTransform();
		tx.translate(cx, cy);
		tx.scale(1.0d, ry / rx);
		tx.translate(-cx, -cy);
		return tx;
	}
/** Fills the whole {@code w}x{@code h} canvas with an elliptical radial gradient (center/radii as percents) fading from {@code color} at {@code alpha} to transparent at {@code endStop}. */
	private static void radialEllipse(Graphics2D g, int w, int h, double cxPct, double cyPct, double rxPct, double ryPct,
		Color color, double alpha, double endStop)
	{
		double cx = cxPct * w;
		double cy = cyPct * h;
		double rx = Math.max(1.0d, rxPct * w);
		double ry = Math.max(1.0d, ryPct * h);
		g.setPaint(new RadialGradientPaint(
			new Point2D.Double(cx, cy), (float) rx, new Point2D.Double(cx, cy),
			new float[]{0f, (float) endStop},
			new Color[]{alpha(color, alpha), alpha(color, 0.0d)},
			MultipleGradientPaint.CycleMethod.NO_CYCLE,
			MultipleGradientPaint.ColorSpaceType.SRGB,
			ellipseScaleTx(cx, cy, rx, ry)));
		g.fill(new Rectangle2D.Double(0, 0, w, h));
	}
/**
	 * Darkens/lightens pixels near the card's border to simulate worn edges: a white highlight ring inside a
	 * black drop-shadow, using distance-from-edge falloff LUTs from {@link #shadowFalloff}. Grade E adds an
	 * extra thin ring. Intensity/opacity scale with grade intensity and {@link WearFx#getEdgeMix()}.
	 */
	private static void applyEdges(BufferedImage face, int w, int h, WearFx wear)
	{
		double i = wear.getGrade().getIntensity();
		double e = wear.getEdgeMix();
		double whiteBlur;
		double whiteAlpha;
		double blackBlur;
		double blackAlpha;
		double ringBlur = 0.0d;
		double ringAlpha = 0.0d;
		double opacity = (0.45d + i * 0.55d) * (0.35d + e * 0.65d);

		if (wear.getGrade() == CardGrade.E)
		{
			whiteBlur = 15.0d;
			whiteAlpha = 0.30d;
			blackBlur = 30.0d;
			blackAlpha = 0.45d;
			ringBlur = 2.0d;
			ringAlpha = 0.35d;
		}
		else
		{
			whiteBlur = 12.0d * i * e;
			whiteAlpha = 0.26d * i * e;
			blackBlur = 24.0d * i * e;
			blackAlpha = 0.34d * i * e;
		}

		int maxDepth = Math.max(1, Math.min(w, h) / 2 + 1);
		double[] whiteLut = shadowFalloff(maxDepth, whiteBlur, whiteAlpha * opacity);
		double[] blackLut = shadowFalloff(maxDepth, blackBlur, blackAlpha * opacity);
		double[] ringLut = ringAlpha > 0.0d ? shadowFalloff(maxDepth, ringBlur, ringAlpha * opacity) : null;

		int[] px = pixels(face);
		for (int y = 0; y < h; y++)
		{
			int rowMin = Math.min(y, h - 1 - y);
			int row = y * w;
			for (int x = 0; x < w; x++)
			{
				int p = px[row + x];
				int a = p >>> 24;
				if (a == 0)
				{
					continue;
				}
				int d = Math.min(rowMin, Math.min(x, w - 1 - x));
				if (d >= maxDepth)
				{
					continue;
				}
				double wa = whiteLut[d];
				double ba = blackLut[d];
				double ra = ringLut == null ? 0.0d : ringLut[d];
				if (wa <= 0.001d && ba <= 0.001d && ra <= 0.001d)
				{
					continue;
				}

				double r = ((p >> 16) & 0xFF) / 255.0d;
				double g = ((p >> 8) & 0xFF) / 255.0d;
				double b = (p & 0xFF) / 255.0d;
				r = r * (1 - ba);
				g = g * (1 - ba);
				b = b * (1 - ba);
				r = r + (1.0d - r) * wa;
				g = g + (1.0d - g) * wa;
				b = b + (1.0d - b) * wa;
				if (ra > 0.0d)
				{
					r = r + (1.0d - r) * ra;
					g = g + (1.0d - g) * ra;
					b = b + (1.0d - b) * ra;
				}
				px[row + x] = (a << 24) | (to255(r) << 16) | (to255(g) << 8) | to255(b);
			}
		}
	}
/** Builds a sigmoid-falloff alpha lookup table (index = pixel distance from edge, 0..{@code size}-1) peaking at {@code peakAlpha} and softened by {@code blur}. */
	private static double[] shadowFalloff(int size, double blur, double peakAlpha)
	{
		double[] lut = new double[size];
		if (peakAlpha <= 0.0d)
		{
			return lut;
		}
		if (blur <= 0.0d)
		{
			lut[0] = peakAlpha;
			return lut;
		}
		double sigma = blur / 2.0d;
		for (int d = 0; d < size; d++)
		{
			lut[d] = peakAlpha * 2.0d / (1.0d + Math.exp(1.702d * d / sigma));
		}
		return lut;
	}
/** Soft-light blends each of {@code wear}'s scratches onto {@code face} as a rotated bar with a dark base and bright highlight streak. */
	private static void drawScratches(BufferedImage face, Shape card, int w, int h, WearFx wear)
	{
		if (wear.getScratches().isEmpty())
		{
			return;
		}
		boolean thick = wear.getGrade() == CardGrade.D || wear.getGrade() == CardGrade.E;
		double thickness = thick ? 1.35d : 1.1d;

		BufferedImage layer = newLayer(w, h);
		Graphics2D g = quality(layer);
		try
		{
			g.clip(card);
			for (WearFx.Scratch s : wear.getScratches())
			{
				double len = Math.max(1.0d, s.getLen() / 100.0d * w);
				double cx = s.getX() / 100.0d * w;
				double cy = s.getY() / 100.0d * h;
				double op = Math.max(0.0d, Math.min(1.0d, s.getOpacity()));

				AffineTransform saved = g.getTransform();
				g.translate(cx, cy);
				g.rotate(Math.toRadians(s.getAngle()));
				g.translate(-len / 2.0d, -thickness / 2.0d);

				Shape bar = new RoundRectangle2D.Double(0, 0, len, thickness, 2, 2);
				g.setColor(alpha(Color.BLACK, 0.28d * op));
				g.translate(0, 0.5d);
				g.fill(bar);
				g.translate(0, -0.5d);

				g.setPaint(new LinearGradientPaint(
					new Point2D.Double(0, 0), new Point2D.Double(len, 0),
					new float[]{0f, 0.20f, 0.55f, 1f},
					new Color[]{
						alpha(Color.WHITE, 0.0d), alpha(Color.WHITE, 0.6d * op),
						alpha(Color.WHITE, 0.22d * op), alpha(Color.WHITE, 0.0d)},
					MultipleGradientPaint.CycleMethod.NO_CYCLE));
				g.fill(bar);
				g.setTransform(saved);
			}
		}
		finally
		{
			g.dispose();
		}
		blend(face, layer, BlendMode.SOFT_LIGHT, 1.0d);
	}
/**
	 * Multiply-blends each of {@code wear}'s dirt spots onto {@code face}: blurred spots are painted on their
	 * own layer and softened via {@link #softenLayer} before blending, while unblurred spots share one sharp layer.
	 */
	private static void drawSpots(BufferedImage face, Shape card, int w, int h, WearFx wear)
	{
		if (wear.getSpots().isEmpty())
		{
			return;
		}
		BufferedImage sharp = newLayer(w, h);
		Graphics2D gs = quality(sharp);
		try
		{
			gs.clip(card);
			for (WearFx.Spot spot : wear.getSpots())
			{
				if (spot.getBlur() > 0.0d)
				{
					BufferedImage soft = newLayer(w, h);
					Graphics2D gb = quality(soft);
					try
					{
						gb.clip(card);
						paintSpot(gb, w, h, spot);
					}
					finally
					{
						gb.dispose();
					}
					blend(face, softenLayer(soft, spot.getBlur()), BlendMode.MULTIPLY, 1.0d);
				}
				else
				{
					paintSpot(gs, w, h, spot);
				}
			}
		}
		finally
		{
			gs.dispose();
		}
		blend(face, sharp, BlendMode.MULTIPLY, 1.0d);
	}
/** Fills one rotated, rounded-rect-clipped spot shape with its shape-specific gradient paint from {@link #spotPaint}. */
	private static void paintSpot(Graphics2D g, int w, int h, WearFx.Spot spot)
	{
		double sw = Math.max(1.0d, spot.getW() / 100.0d * w);
		double sh = Math.max(1.0d, spot.getH() / 100.0d * h);
		double cx = spot.getX() / 100.0d * w;
		double cy = spot.getY() / 100.0d * h;
		double op = Math.max(0.0d, Math.min(1.0d, spot.getOpacity()));

		AffineTransform saved = g.getTransform();
		Shape savedClip = g.getClip();
		try
		{
			g.translate(cx, cy);
			g.rotate(Math.toRadians(spot.getRotate()));
			g.translate(-sw / 2.0d, -sh / 2.0d);

			Shape shape = borderRadiusShape(sw, sh, spot.getBorderRadius());
			g.clip(shape);
			g.setPaint(spotPaint(spot.getShape(), sw, sh, op));
			g.fill(shape);
		}
		finally
		{
			g.setClip(savedClip);
			g.setTransform(saved);
		}
	}
/** Returns the dirt-colored gradient paint appropriate to a spot's {@link WearFx.SpotShape}, sized to {@code w}x{@code h} and scaled by opacity {@code op}. */
	private static java.awt.Paint spotPaint(WearFx.SpotShape shape, double w, double h, double op)
	{
		switch (shape)
		{
			case SMEAR:
				return new LinearGradientPaint(
					new Point2D.Double(0, h / 2.0d), new Point2D.Double(w, h / 2.0d),
					new float[]{0f, 0.18f, 0.50f, 0.82f, 1f},
					new Color[]{
						alpha(new Color(24, 24, 24), 0.0d),
						alpha(new Color(24, 24, 24), 0.55d * op),
						alpha(new Color(18, 18, 18), 0.82d * op),
						alpha(new Color(24, 24, 24), 0.5d * op),
						alpha(new Color(24, 24, 24), 0.0d)},
					MultipleGradientPaint.CycleMethod.NO_CYCLE);
			case ELLIPSE:
				return ellipseGradient(w, h, 0.48d, 0.46d, 0.85d, 0.70d,
					new Color(22, 22, 22), 0.88d * op, new Color(26, 26, 26), 0.32d * op, 0.48f, 0.72f);
			case BLOB:
			case SPLOTCH:
				return ellipseGradient(w, h, 0.44d, 0.40d, 0.72d, 0.68d,
					new Color(20, 20, 20), 0.92d * op, new Color(26, 26, 26), 0.38d * op, 0.42f, 0.74f);
			case ROUND:
			default:
			{
				double r = Math.max(1.0d, Math.hypot(w / 2.0d, h / 2.0d));
				return new RadialGradientPaint(
					new Point2D.Double(w / 2.0d, h / 2.0d), (float) r,
					new float[]{0f, 0.45f, 0.70f},
					new Color[]{
						alpha(new Color(22, 22, 22), 0.9d * op),
						alpha(new Color(26, 26, 26), 0.35d * op),
						alpha(new Color(26, 26, 26), 0.0d)},
					MultipleGradientPaint.CycleMethod.NO_CYCLE);
			}
		}
	}
/** Elliptical (center/radii as percents of {@code w}x{@code h}) radial gradient paint from {@code inner} through {@code mid} to transparent. */
	private static java.awt.Paint ellipseGradient(double w, double h, double cxPct, double cyPct, double rxPct, double ryPct,
		Color inner, double innerAlpha, Color mid, double midAlpha, float midStop, float endStop)
	{
		double cx = cxPct * w;
		double cy = cyPct * h;
		double rx = Math.max(1.0d, rxPct * w);
		double ry = Math.max(1.0d, ryPct * h);
		return new RadialGradientPaint(
			new Point2D.Double(cx, cy), (float) rx, new Point2D.Double(cx, cy),
			new float[]{0f, midStop, endStop},
			new Color[]{alpha(inner, innerAlpha), alpha(mid, midAlpha), alpha(mid, 0.0d)},
			MultipleGradientPaint.CycleMethod.NO_CYCLE,
			MultipleGradientPaint.ColorSpaceType.SRGB,
			ellipseScaleTx(cx, cy, rx, ry));
	}
/** Approximates a Gaussian blur by repeatedly applying a 3x3 box-weighted convolution kernel, {@code blurPx} passes (min 1). */
	private static BufferedImage softenLayer(BufferedImage layer, double blurPx)
	{
		int passes = Math.max(1, (int) Math.round(Math.max(0.2d, blurPx)));
		BufferedImage current = layer;
		float[] kernel = {
			1f / 16f, 2f / 16f, 1f / 16f,
			2f / 16f, 4f / 16f, 2f / 16f,
			1f / 16f, 2f / 16f, 1f / 16f
		};
		ConvolveOp op = new ConvolveOp(new Kernel(3, 3, kernel), ConvolveOp.EDGE_NO_OP, null);
		for (int i = 0; i < passes; i++)
		{
			current = op.filter(current, newLayer(current.getWidth(), current.getHeight()));
		}
		return current;
	}
/** Builds a {@link LinearGradientPaint} spanning the {@code w}x{@code h} canvas at CSS-style {@code angleDeg} (0 = top, clockwise). */
	private static LinearGradientPaint cssLinearGradient(int w, int h, double angleDeg,
		float[] fractions, Color[] colors)
	{
		double a = Math.toRadians(angleDeg);
		double dx = Math.sin(a);
		double dy = -Math.cos(a);
		double len = Math.max(1.0d, Math.abs(w * Math.sin(a)) + Math.abs(h * Math.cos(a)));
		double cx = w / 2.0d;
		double cy = h / 2.0d;
		return new LinearGradientPaint(
			new Point2D.Double(cx - dx * len / 2.0d, cy - dy * len / 2.0d),
			new Point2D.Double(cx + dx * len / 2.0d, cy + dy * len / 2.0d),
			fractions, colors, MultipleGradientPaint.CycleMethod.NO_CYCLE);
	}
/**
	 * Builds a CSS-style rounded-rect path of size {@code w}x{@code h} from 8 per-corner radius percentages
	 * (horizontal/vertical radius for each of top-left, top-right, bottom-right, bottom-left), scaling all
	 * radii down proportionally if any pair would overlap.
	 */
	private static Shape borderRadiusShape(double w, double h, double[] radiiPercent)
	{
		double htl = radiiPercent[0] / 100.0d * w;
		double htr = radiiPercent[1] / 100.0d * w;
		double hbr = radiiPercent[2] / 100.0d * w;
		double hbl = radiiPercent[3] / 100.0d * w;
		double vtl = radiiPercent[4] / 100.0d * h;
		double vtr = radiiPercent[5] / 100.0d * h;
		double vbr = radiiPercent[6] / 100.0d * h;
		double vbl = radiiPercent[7] / 100.0d * h;

		double f = 1.0d;
		f = Math.min(f, ratio(w, htl + htr));
		f = Math.min(f, ratio(w, hbl + hbr));
		f = Math.min(f, ratio(h, vtl + vbl));
		f = Math.min(f, ratio(h, vtr + vbr));
		if (f < 1.0d)
		{
			htl *= f;
			htr *= f;
			hbr *= f;
			hbl *= f;
			vtl *= f;
			vtr *= f;
			vbr *= f;
			vbl *= f;
		}

		Path2D.Double p = new Path2D.Double();
		p.moveTo(htl, 0);
		p.lineTo(w - htr, 0);
		p.curveTo(w - htr + htr * BEZIER_K, 0, w, vtr - vtr * BEZIER_K, w, vtr);
		p.lineTo(w, h - vbr);
		p.curveTo(w, h - vbr + vbr * BEZIER_K, w - hbr + hbr * BEZIER_K, h, w - hbr, h);
		p.lineTo(hbl, h);
		p.curveTo(hbl - hbl * BEZIER_K, h, 0, h - vbl + vbl * BEZIER_K, 0, h - vbl);
		p.lineTo(0, vtl);
		p.curveTo(0, vtl - vtl * BEZIER_K, htl - htl * BEZIER_K, 0, htl, 0);
		p.closePath();
		return p;
	}
/** Fraction by which paired corner radii must shrink to fit within {@code side}; 1.0 (no shrink) if {@code sum} is non-positive or already fits. */
	private static double ratio(double side, double sum)
	{
		return sum <= 0.0d ? 1.0d : Math.min(1.0d, side / sum);
	}
/** Shorthand for {@link CardColorMath#withAlpha}. */
	public static Color alpha(Color c, double a)
	{
		return CardColorMath.withAlpha(c, a);
	}
}

package com.osrstcg.ui.card;

import java.awt.Font;
import java.awt.FontFormatException;
import java.io.IOException;
import java.io.InputStream;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
/**
 * Loads the plugin's bundled RuneScape-style fonts and derives sized variants used across card rendering,
 * scaled from a fixed root size (falls back to SansSerif if a font resource is missing or fails to load).
 */
public final class CardFonts
{
	private static final Logger log = LoggerFactory.getLogger(CardFonts.class);

	public static final float ROOT_SIZE_PX = 15.625f;
	public static final float TITLE_EM = 1.12f;
	public static final float FULL_EXAMINE_EM = 0.92f;
	public static final float FULL_SCORE_EM = 1.08f;

	private static final Font REGULAR = load("com/osrstcg/fonts/runescape.ttf", Font.PLAIN);
	private static final Font BOLD = load("com/osrstcg/fonts/runescape_bold.ttf", Font.BOLD);

	private CardFonts()
	{
	}
/** Regular body font sized to {@code scale} of the root size. */
	public static Font body(double scale)
	{
		return sized(REGULAR, ROOT_SIZE_PX * (float) Math.max(0.01d, scale));
	}
/** Regular examine-text font sized to {@code scale} of the root size times {@code em}. */
	public static Font examine(double scale, float em)
	{
		float clampedEm = Math.max(0.01f, em);
		return sized(REGULAR, ROOT_SIZE_PX * clampedEm * (float) Math.max(0.01d, scale));
	}
/** Bold title font sized to {@code scale} of the root size times {@code em}. */
	public static Font title(double scale, float em)
	{
		float clampedEm = Math.max(0.01f, em);
		return sized(BOLD, ROOT_SIZE_PX * clampedEm * (float) Math.max(0.01d, scale));
	}
/** Bold font sized to {@code scale} of the root size. */
	public static Font bold(double scale)
	{
		return sized(BOLD, ROOT_SIZE_PX * (float) Math.max(0.01d, scale));
	}
/** Bold title font for full-art cards, sized with {@link #TITLE_EM} and rounded to a whole pixel size. */
	public static Font fullArtTitle(double scale)
	{
		return sizedFullArt(BOLD, ROOT_SIZE_PX * TITLE_EM * (float) Math.max(0.01d, scale));
	}
/** Bold examine-text font for full-art cards, sized with {@link #FULL_EXAMINE_EM} and rounded to a whole pixel size. */
	public static Font fullArtExamine(double scale)
	{
		return sizedFullArt(BOLD, ROOT_SIZE_PX * FULL_EXAMINE_EM * (float) Math.max(0.01d, scale));
	}
/** Bold score font for full-art cards, sized with {@link #FULL_SCORE_EM} and rounded to a whole pixel size. */
	public static Font fullArtScore(double scale)
	{
		return sizedFullArt(BOLD, ROOT_SIZE_PX * FULL_SCORE_EM * (float) Math.max(0.01d, scale));
	}
/** Derives {@code base} at {@code sizePx}, floored at 1px. */
	private static Font sized(Font base, float sizePx)
	{
		float size = Math.max(1f, sizePx);
		return base.deriveFont(size);
	}
/** Derives {@code base} at {@code sizePx} rounded to the nearest whole pixel, floored at 1px. */
	private static Font sizedFullArt(Font base, float sizePx)
	{
		float size = Math.max(1f, Math.round(sizePx));
		return base.deriveFont(size);
	}
/** Loads a TrueType font from the given classpath resource, falling back to SansSerif on any failure. */
	private static Font load(String resourcePath, int fallbackStyle)
	{
		try (InputStream in = CardFonts.class.getResourceAsStream("/" + resourcePath))
		{
			if (in == null)
			{
				log.warn("Missing card font resource /{}; falling back to SansSerif", resourcePath);
				return new Font(Font.SANS_SERIF, fallbackStyle, Math.round(ROOT_SIZE_PX));
			}
			Font font = Font.createFont(Font.TRUETYPE_FONT, in);
			return font.deriveFont(ROOT_SIZE_PX);
		}
		catch (FontFormatException | IOException ex)
		{
			log.warn("Failed to load card font /{}; falling back to SansSerif", resourcePath, ex);
			return new Font(Font.SANS_SERIF, fallbackStyle, Math.round(ROOT_SIZE_PX));
		}
	}
}

package com.osrstcg.ui.card;

import com.osrstcg.catalog.RarityMath;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Getter;
import lombok.Value;
/**
 * Deterministic foil sparkle layout for a card: a seeded set of {@link Sparkle}s (position, size, timing,
 * color) generated from the pull identity so the same card always renders the same foil pattern.
 */
@Getter
public final class FoilFx
{
	public static final int DEFAULT_SPARKLE_COUNT = 22;
/** One sparkle's position (percent of card), size, animation timing, and HSL color. */
	@Value
	public static class Sparkle
	{
		double x;
		double y;
		double size;
		double delay;
		double duration;
		double hue;
		double sat;
		double light;
	}

	private final int seed;
	private final List<Sparkle> sparkles;
/** Stores the seed and wraps the sparkle list as unmodifiable. */
	private FoilFx(int seed, List<Sparkle> sparkles)
	{
		this.seed = seed;
		this.sparkles = Collections.unmodifiableList(sparkles);
	}
/**
	 * Builds a {@link FoilFx} for a pulled card: seeds a PRNG from the pull identity ({@code cardName}/{@code pulledAt}),
	 * derives a base hue from the card's rarity tier (silver/near-white sparkles for commons, hue-tinted for
	 * everything else), and generates {@code count} randomly placed and timed sparkles.
	 */
	public static FoilFx foilFxFromPulledAt(
		Long pulledAt, int count, String cardName, String tierLabel, Color tierColor)
	{
		int seed = WearFx.wearSeedFromPull(cardName, "", pulledAt, 1);
		WearFx.Mulberry32 rand = new WearFx.Mulberry32(seed);

		RarityMath.Tier tier = resolveTier(tierLabel, tierColor);
		boolean silver = tier == RarityMath.Tier.COMMON;
		double baseHue = foilBaseHue(tier, tierColor);

		int safeCount = Math.max(0, count);
		List<Sparkle> sparkles = new ArrayList<>(safeCount);
		for (int i = 0; i < safeCount; i++)
		{
			double x = 6.0d + rand.next() * 88.0d;
			double y = 8.0d + rand.next() * 84.0d;
			double size = 1.2d + rand.next() * 2.8d;
			double delay = rand.next() * 2.8d;
			double duration = 1.1d + rand.next() * 2.2d;
			double hue;
			double sat;
			double light;
			if (silver)
			{
				hue = rand.next() * 360.0d;
				sat = (2.0d + rand.next() * 10.0d) / 100.0d;
				light = (82.0d + rand.next() * 14.0d) / 100.0d;
			}
			else
			{
				hue = wrapHue(baseHue - 28.0d + rand.next() * 56.0d);
				sat = 0.90d;
				light = 0.72d;
			}
			sparkles.add(new Sparkle(x, y, size, delay, duration, hue, sat, light));
		}

		return new FoilFx(seed, sparkles);
	}
/**
	 * Resolves the rarity tier to drive sparkle color: prefers a valid {@code tierLabel}; otherwise falls back
	 * to common unless {@code tierColor} carries a distinguishable hue, in which case its hue is used via
	 * {@link #foilBaseHue}.
	 */
	static RarityMath.Tier resolveTier(String tierLabel, Color tierColor)
	{
		RarityMath.Tier fromLabel = RarityMath.tierFromLabel(tierLabel == null ? "" : tierLabel);
		boolean hasLabel = tierLabel != null && !tierLabel.trim().isEmpty();
		if (hasLabel || fromLabel != RarityMath.Tier.COMMON)
		{
			return fromLabel;
		}
		if (hueFromColor(tierColor) == null)
		{
			return RarityMath.Tier.COMMON;
		}
		return fromLabel;
	}
/** Fixed sparkle hue per known rarity tier; for common or any unlisted tier, derives hue from {@code tierColor} instead (0 if none). */
	static double foilBaseHue(RarityMath.Tier tier, Color tierColor)
	{
		if (tier == null || tier == RarityMath.Tier.COMMON)
		{
			return 0.0d;
		}
		switch (tier)
		{
			case UNCOMMON:
				return 145.0d;
			case RARE:
				return 204.0d;
			case EPIC:
				return 282.0d;
			case LEGENDARY:
				return 6.0d;
			case MYTHIC:
				return 330.0d;
			case GODLY:
				return 45.0d;
			default:
				Double fromColor = hueFromColor(tierColor);
				return fromColor == null ? 0.0d : fromColor;
		}
	}
/** Extracts the HSV hue (0-360) from an RGB color, or null if the color is too close to gray to have a meaningful hue. */
	static Double hueFromColor(Color color)
	{
		if (color == null)
		{
			return null;
		}
		double r = color.getRed() / 255.0d;
		double g = color.getGreen() / 255.0d;
		double b = color.getBlue() / 255.0d;
		double max = Math.max(r, Math.max(g, b));
		double min = Math.min(r, Math.min(g, b));
		double d = max - min;
		if (d < 0.04d)
		{
			return null;
		}
		double h;
		if (max == r)
		{
			h = ((g - b) / d) % 6.0d;
		}
		else if (max == g)
		{
			h = (b - r) / d + 2.0d;
		}
		else
		{
			h = (r - g) / d + 4.0d;
		}
		h *= 60.0d;
		if (h < 0.0d)
		{
			h += 360.0d;
		}
		return h;
	}
/** Wraps a hue value into the [0, 360) range. */
	static double wrapHue(double hue)
	{
		double h = hue % 360.0d;
		return h < 0.0d ? h + 360.0d : h;
	}
}

package com.osrstcg.ui.card;
/**
 * Computes a single sparkle's animated opacity and scale at a point in time, looping a fade-in/hold/fade-out
 * cycle (via a cubic-bezier ease) over each sparkle's delay and duration.
 */
public final class FoilSparkleAnimation
{
	private static final double EASE_X1 = 0.42d;
	private static final double EASE_Y1 = 0.0d;
	private static final double EASE_X2 = 0.58d;
	private static final double EASE_Y2 = 1.0d;
/** Opacity and scale of a sparkle at a sampled point in its animation cycle. */
	public static final class Sample
	{
		private final double opacity;
		private final double scale;
/** Stores the sampled opacity and scale. */
		Sample(double opacity, double scale)
		{
			this.opacity = opacity;
			this.scale = scale;
		}
/** Sparkle opacity (0-1) at this sample point. */
		public double getOpacity()
		{
			return opacity;
		}
/** Sparkle size multiplier at this sample point. */
		public double getScale()
		{
			return scale;
		}
	}

	private FoilSparkleAnimation()
	{
	}
/**
	 * Samples a sparkle's animation at {@code timeSec}, given its {@code delaySec} start offset and cycle
	 * {@code durationSec}. Before the delay elapses, or when duration is non-positive, returns the invisible
	 * resting state; otherwise loops the elapsed time into a 0-1 phase and delegates to {@link #samplePhase}.
	 */
	public static Sample sample(double delaySec, double durationSec, double timeSec)
	{
		if (durationSec <= 0.0d)
		{
			return new Sample(0.0d, 0.4d);
		}
		double elapsed = timeSec - delaySec;
		if (elapsed < 0.0d)
		{
			return new Sample(0.0d, 0.4d);
		}
		double phase = (elapsed / durationSec) % 1.0d;
		if (phase < 0.0d)
		{
			phase += 1.0d;
		}
		return samplePhase(phase);
	}
/**
	 * Maps a 0-1 cycle phase to opacity/scale: eased fade-in and grow (0-0.40), a brief hold near full
	 * opacity/scale (0.40-0.55), an eased shrink (0.55-0.70), then an eased fade-out and further shrink
	 * (0.70-1.0). Phase outside (0, 1) is treated as fully invisible.
	 */
	static Sample samplePhase(double phase)
	{
		double p = phase;
		if (p <= 0.0d || p >= 1.0d)
		{
			return new Sample(0.0d, 0.4d);
		}
		if (p <= 0.40d)
		{
			double u = easeInOut(p / 0.40d);
			return lerp(0.0d, 0.4d, 0.95d, 1.0d, u);
		}
		if (p <= 0.55d)
		{
			return new Sample(0.95d, 1.0d);
		}
		if (p <= 0.70d)
		{
			double u = easeInOut((p - 0.55d) / 0.15d);
			return lerp(0.95d, 1.0d, 0.2d, 0.7d, u);
		}
		double u = easeInOut((p - 0.70d) / 0.30d);
		return lerp(0.2d, 0.7d, 0.0d, 0.4d, u);
	}
/** Linearly interpolates opacity and scale between two endpoints by {@code u} (0-1). */
	private static Sample lerp(double o0, double s0, double o1, double s1, double u)
	{
		return new Sample(o0 + (o1 - o0) * u, s0 + (s1 - s0) * u);
	}
/** Clamps {@code t} to 0-1 and applies the class's cubic-bezier ease curve. */
	static double easeInOut(double t)
	{
		double x = Math.max(0.0d, Math.min(1.0d, t));
		if (x <= 0.0d)
		{
			return 0.0d;
		}
		if (x >= 1.0d)
		{
			return 1.0d;
		}
		return cubicBezierY(EASE_X1, EASE_Y1, EASE_X2, EASE_Y2, x);
	}
/** Solves for parametric {@code t} where the cubic-bezier's x-coordinate equals {@code x} (Newton's method), then returns its y. */
	private static double cubicBezierY(double x1, double y1, double x2, double y2, double x)
	{
		double t = x;
		for (int i = 0; i < 8; i++)
		{
			double xEst = bezierCoord(t, x1, x2);
			double dx = bezierDerivative(t, x1, x2);
			if (Math.abs(dx) < 1e-6d)
			{
				break;
			}
			t -= (xEst - x) / dx;
			t = Math.max(0.0d, Math.min(1.0d, t));
		}
		return bezierCoord(t, y1, y2);
	}
/** Evaluates a cubic bezier with control points at 0, {@code p1}, {@code p2}, 1 at parameter {@code t}. */
	private static double bezierCoord(double t, double p1, double p2)
	{
		double u = 1.0d - t;
		return 3.0d * u * u * t * p1 + 3.0d * u * t * t * p2 + t * t * t;
	}
/** Derivative of {@link #bezierCoord} with respect to {@code t}. */
	private static double bezierDerivative(double t, double p1, double p2)
	{
		double u = 1.0d - t;
		return 3.0d * u * u * p1 + 6.0d * u * t * (p2 - p1) + 3.0d * t * t * (1.0d - p2);
	}
}

package com.osrstcg.ui.card;

import java.awt.Color;
/**
 * Color helpers shared by card rendering/effects: brightening, blending, alpha, clamping, and HSLA conversion.
 */
public final class CardColorMath
{
	private CardColorMath()
	{
	}
/** Lifts each RGB channel toward white by 35%, preserving alpha; null input returns opaque white. */
	public static Color brighterColor(Color color)
	{
		if (color == null)
		{
			return Color.WHITE;
		}
		return new Color(lift(color.getRed()), lift(color.getGreen()), lift(color.getBlue()), color.getAlpha());
	}
/** Moves a single 0-255 channel 35% of the way toward 255. */
	private static int lift(int channel)
	{
		return Math.min(255, (int) Math.round(channel + (255 - channel) * 0.35d));
	}
/**
	 * Linearly interpolates RGB from {@code base} toward {@code tint} by {@code amount} (clamped 0-1),
	 * keeping {@code base}'s alpha. Falls back to whichever color is non-null if the other is null.
	 */
	public static Color blendColors(Color base, Color tint, double amount)
	{
		if (base == null)
		{
			return tint == null ? Color.WHITE : tint;
		}
		if (tint == null)
		{
			return base;
		}
		double t = Math.max(0.0d, Math.min(1.0d, amount));
		return new Color(
			mix(base.getRed(), tint.getRed(), t),
			mix(base.getGreen(), tint.getGreen(), t),
			mix(base.getBlue(), tint.getBlue(), t),
			base.getAlpha());
	}
/** Linearly interpolates one 0-255 channel from {@code a} to {@code b} by {@code t}, clamped to 0-255. */
	private static int mix(int a, int b, double t)
	{
		return clamp255((int) Math.round(a + (b - a) * t));
	}
/** Clamps a value to the 0-255 byte range. */
	public static int clamp255(int value)
	{
		return Math.max(0, Math.min(255, value));
	}
/** Returns {@code c} (white if null) with alpha set from {@code a} (0-1, clamped). */
	public static Color withAlpha(Color c, double a)
	{
		if (c == null)
		{
			c = Color.WHITE;
		}
		int av = clamp255((int) Math.round(Math.max(0.0d, Math.min(1.0d, a)) * 255.0d));
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), av);
	}
/** Converts CSS-style HSLA ({@code hueDeg} any value, {@code saturation}/{@code lightness}/{@code alpha} 0-1) to an RGBA {@link Color}. */
	public static Color hsla(double hueDeg, double saturation, double lightness, double alpha)
	{
		double h = ((hueDeg % 360.0d) + 360.0d) % 360.0d / 360.0d;
		double s = Math.max(0.0d, Math.min(1.0d, saturation));
		double l = Math.max(0.0d, Math.min(1.0d, lightness));

		double r;
		double g;
		double b;
		if (s == 0.0d)
		{
			r = l;
			g = l;
			b = l;
		}
		else
		{
			double q = l < 0.5d ? l * (1.0d + s) : l + s - l * s;
			double p = 2.0d * l - q;
			r = hueToChannel(p, q, h + 1.0d / 3.0d);
			g = hueToChannel(p, q, h);
			b = hueToChannel(p, q, h - 1.0d / 3.0d);
		}

		return new Color(
			clamp255((int) Math.round(r * 255.0d)),
			clamp255((int) Math.round(g * 255.0d)),
			clamp255((int) Math.round(b * 255.0d)),
			clamp255((int) Math.round(Math.max(0.0d, Math.min(1.0d, alpha)) * 255.0d)));
	}
/** Standard HSL-to-RGB helper: computes one channel from chroma bounds {@code p}/{@code q} at hue offset {@code t}. */
	private static double hueToChannel(double p, double q, double t)
	{
		double tt = t;
		if (tt < 0.0d)
		{
			tt += 1.0d;
		}
		if (tt > 1.0d)
		{
			tt -= 1.0d;
		}
		if (tt < 1.0d / 6.0d)
		{
			return p + (q - p) * 6.0d * tt;
		}
		if (tt < 1.0d / 2.0d)
		{
			return q;
		}
		if (tt < 2.0d / 3.0d)
		{
			return p + (q - p) * (2.0d / 3.0d - tt) * 6.0d;
		}
		return p;
	}
}

package com.osrstcg.ui.tip;

import com.osrstcg.catalog.CardDefinition;
import com.osrstcg.state.PackCardResult;
import com.osrstcg.pack.PackRevealService;
import com.osrstcg.ui.card.CardGrade;
import com.osrstcg.util.CardDisplayNames;
import java.awt.Color;
import java.awt.Point;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Value;
/**
 * Data and layout math for the card-hover tooltip: builds the label/value/action rows for a card and
 * computes where the tooltip should sit relative to the cursor or canvas. Pure/static; no Swing state
 * of its own — {@link CardInfoTipPainter} does the actual rendering.
 */
public final class CardInfoTipModel
{
	public static final int DELAY_MS = 180;
	public static final int OFFSET_PX = 14;
	public static final int CLAMP_PAD_PX = 8;
	public static final int FADE_IN_MS = 160;

	public static final String ACTION_INSPECT = "inspect";
	public static final String ACTION_OPEN_WIKI = "open-wiki";
/** One tooltip line: either a label/value detail pair, or a clickable action (when {@link #actionId} is set). */
	@Value
	public static class Row
	{
		String label;
		String value;
		String actionId;
		Color valueColor;
/** Detail row with default value color. */
		public Row(String label, String value)
		{
			this(label, value, null, null);
		}
/** Detail row with an explicit value color. */
		public Row(String label, String value, Color valueColor)
		{
			this(label, value, null, valueColor);
		}

		private Row(String label, String value, String actionId, Color valueColor)
		{
			this.label = label == null ? "" : label;
			this.value = value == null ? "" : value;
			this.actionId = actionId == null || actionId.isBlank() ? null : actionId;
			this.valueColor = valueColor;
		}
/** Creates a clickable action row (no value) identified by {@code actionId}. */
		public static Row action(String label, String actionId)
		{
			return new Row(label, "", actionId, null);
		}
/** @return true if this is a clickable action row rather than a detail row. */
		public boolean isAction()
		{
			return actionId != null;
		}
	}
/** Immutable tooltip content: a title plus an ordered list of {@link Row}s. */
	@Value
	public static class Content
	{
		String title;
		List<Row> rows;

		public Content(String title, List<Row> rows)
		{
			this.title = title == null || title.isBlank() ? "Card" : title;
			this.rows = Collections.unmodifiableList(new ArrayList<>(rows == null ? List.of() : rows));
		}
	}

	private CardInfoTipModel()
	{
	}
/**
	 * Positions the tooltip near the cursor, flipping to the opposite side when it would overflow the
	 * canvas edge, then clamps fully inside the canvas (padded by {@link #CLAMP_PAD_PX}).
	 */
	public static Point position(int cursorX, int cursorY, int tipW, int tipH, int canvasW, int canvasH)
	{
		int w = Math.max(1, tipW);
		int h = Math.max(1, tipH);
		int pad = CLAMP_PAD_PX;
		int left = cursorX + OFFSET_PX;
		int top = cursorY + OFFSET_PX;
		if (left + w > canvasW - pad)
		{
			left = cursorX - w - OFFSET_PX;
		}
		if (top + h > canvasH - pad)
		{
			top = cursorY - h - OFFSET_PX;
		}
		left = Math.max(pad, Math.min(left, canvasW - w - pad));
		top = Math.max(pad, Math.min(top, canvasH - h - pad));
		return new Point(left, top);
	}
/** Positions the tooltip pinned to the canvas's top-right corner (padded), used when no cursor position applies. */
	public static Point topRight(int tipW, int tipH, int canvasW, int canvasH)
	{
		int w = Math.max(1, tipW);
		int h = Math.max(1, tipH);
		int pad = CLAMP_PAD_PX;
		int left = Math.max(pad, canvasW - w - pad);
		int top = pad;
		if (top + h > canvasH - pad)
		{
			top = Math.max(pad, canvasH - h - pad);
		}
		return new Point(left, top);
	}
/** {@link #forPackRevealCard(PackRevealService.RevealCard, boolean)} without action rows. */
	public static Content forPackRevealCard(PackRevealService.RevealCard card)
	{
		return forPackRevealCard(card, false);
	}
/**
	 * Builds tooltip content for a pack-reveal card: title, grade/condition row, artist row (when the
	 * card has a foil image and artist name), and optionally "Inspect"/"Open wiki page" action rows.
	 */
	public static Content forPackRevealCard(PackRevealService.RevealCard card, boolean includeContextActions)
	{
		if (card == null)
		{
			return new Content("Card", List.of());
		}
		PackCardResult pull = card.getPull();
		CardDefinition def = card.getDefinition();
		String title = tipTitle(def, pull);
		Double condition = pull == null ? null : pull.getCondition();
		List<Row> rows = packRevealRows(condition);
		appendArtistRow(rows, def);
		if (includeContextActions)
		{
			String instanceId = instanceIdFor(card);
			if (instanceId != null)
			{
				rows.add(Row.action("Inspect", ACTION_INSPECT));
			}
			String wiki = wikiPageFor(card);
			if (wiki != null)
			{
				rows.add(Row.action("Open wiki page", ACTION_OPEN_WIKI));
			}
		}
		return new Content(title, rows);
	}
/** Appends an "Artist" row if the definition has both a foil image and a non-blank artist name. */
	static void appendArtistRow(List<Row> rows, CardDefinition def)
	{
		if (rows == null || def == null)
		{
			return;
		}
		String foilPath = def.getFoilImagePath() == null ? "" : def.getFoilImagePath().trim();
		if (foilPath.isEmpty())
		{
			return;
		}
		String name = def.getArtistName() == null ? "" : def.getArtistName().trim();
		if (name.isEmpty())
		{
			return;
		}
		rows.add(new Row("Artist", name, normalizeArtistColor(def.getArtistColor())));
	}
/** Parses a {@code #RRGGBB} or {@code #RGB} hex string into a {@link Color}; returns {@code null} if unparsable. */
	static Color normalizeArtistColor(String raw)
	{
		if (raw == null)
		{
			return null;
		}
		String s = raw.trim();
		if (s.length() == 7 && s.charAt(0) == '#')
		{
			try
			{
				return Color.decode(s.toUpperCase());
			}
			catch (NumberFormatException ignored)
			{
				return null;
			}
		}
		if (s.length() == 4 && s.charAt(0) == '#')
		{
			char r = s.charAt(1);
			char g = s.charAt(2);
			char b = s.charAt(3);
			try
			{
				return Color.decode(("#" + r + r + g + g + b + b).toUpperCase());
			}
			catch (NumberFormatException ignored)
			{
				return null;
			}
		}
		return null;
	}
/** @return the pulled card's instance id, or {@code null} if the card has no pull or no id. */
	public static String instanceIdFor(PackRevealService.RevealCard card)
	{
		if (card == null)
		{
			return null;
		}
		PackCardResult pull = card.getPull();
		if (pull != null && pull.getInstanceId() != null && !pull.getInstanceId().isBlank())
		{
			return pull.getInstanceId().trim();
		}
		return null;
	}
/** @return the wiki page for this card, preferring the pull's own page over the card definition's. */
	public static String wikiPageFor(PackRevealService.RevealCard card)
	{
		if (card == null)
		{
			return null;
		}
		PackCardResult pull = card.getPull();
		if (pull != null && pull.getWikiPage() != null && !pull.getWikiPage().isBlank())
		{
			return pull.getWikiPage().trim();
		}
		if (card.getDefinition() != null && card.getDefinition().getWikiPage() != null
			&& !card.getDefinition().getWikiPage().isBlank())
		{
			return card.getDefinition().getWikiPage().trim();
		}
		return null;
	}
/** Builds a single "Grade"/"Condition" row from a pull's condition value, preferring the combined grade+condition form. */
	static List<Row> packRevealRows(Double condition)
	{
		List<Row> rows = new ArrayList<>();
		CardGrade grade = CardGrade.gradeFromCondition(condition);
		String conditionLabel = CardGrade.formatCondition(condition);
		if (grade != null && conditionLabel != null)
		{
			rows.add(new Row("Grade", grade.name() + " (" + conditionLabel + ")"));
		}
		else if (grade != null)
		{
			rows.add(new Row("Grade", grade.name()));
		}
		else if (conditionLabel != null)
		{
			rows.add(new Row("Condition", conditionLabel));
		}
		return rows;
	}
/** @return the tooltip title for a card definition/pull pair. */
	static String tipTitle(CardDefinition def, PackCardResult pull)
	{
		return CardDisplayNames.titleForDefinition(def, pull);
	}
}

package com.osrstcg.ui.tip;

import com.osrstcg.ui.tip.CardInfoTipModel.Content;
import com.osrstcg.ui.tip.CardInfoTipModel.Row;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;
import java.util.List;
import java.util.Map;
import net.runelite.client.ui.FontManager;
/**
 * Stateless renderer for the card-hover tooltip: measures the rounded-rect panel size for a given
 * {@link Content}, then paints it (title, detail rows, action rows with hover highlight) onto a
 * {@link Graphics2D}. Must be called from the Swing paint thread (EDT).
 */
public final class CardInfoTipPainter
{
	private static final Color BG = new Color(18, 18, 18, 245);
	private static final Color BORDER = new Color(255, 255, 255, 36);
	private static final Color LABEL = new Color(0xAA, 0xAA, 0xAA);
	private static final Color VALUE = Color.WHITE;
	private static final Color ACTION_HOVER = new Color(255, 255, 255, 28);
	private static final Color SEPARATOR = new Color(255, 255, 255, 36);
	private static final int PAD_X = 13;
	private static final int PAD_Y = 12;
	private static final int RADIUS = 4;
	private static final int TITLE_GAP = 10;
	private static final int ROW_GAP = 7;
	private static final int COL_GAP = 22;
	private static final int ACTION_PAD_Y = 6;
	private static final int MAX_TITLE_CHARS_FALLBACK = 48;

	private CardInfoTipPainter()
	{
	}
/** Computes the pixel size of the tooltip panel needed to fit the title and rows of {@code content}. */
	public static Dimension measure(Graphics2D g, Content content)
	{
		Font titleFont = tipTitleFont();
		Font rowFont = tipRowFont();
		FontMetrics titleFm = g.getFontMetrics(titleFont);
		FontMetrics rowFm = g.getFontMetrics(rowFont);

		String title = content == null ? "Card" : content.getTitle();
		List<Row> rows = content == null ? List.of() : content.getRows();

		int titleW = titleFm.stringWidth(ellipsize(title, titleFm, 360));
		int labelW = 0;
		int valueW = 0;
		int actionW = 0;
		boolean hasAction = false;
		boolean hasDetail = false;
		for (Row row : rows)
		{
			if (row.isAction())
			{
				hasAction = true;
				actionW = Math.max(actionW, rowFm.stringWidth(row.getLabel()));
			}
			else
			{
				hasDetail = true;
				labelW = Math.max(labelW, rowFm.stringWidth(row.getLabel()));
				valueW = Math.max(valueW, rowFm.stringWidth(row.getValue()));
			}
		}
		int rowsW = 0;
		if (hasDetail)
		{
			rowsW = Math.max(rowsW, labelW + COL_GAP + valueW);
		}
		if (hasAction)
		{
			rowsW = Math.max(rowsW, actionW);
		}
		int innerW = Math.max(titleW, rowsW);
		int width = PAD_X * 2 + Math.max(1, innerW);

		int height = PAD_Y + titleFm.getHeight();
		if (!rows.isEmpty())
		{
			height += TITLE_GAP;
			boolean sawAction = false;
			for (int i = 0; i < rows.size(); i++)
			{
				Row row = rows.get(i);
				if (row.isAction())
				{
					if (!sawAction && hasDetail)
					{
						height += ROW_GAP + 1;
					}
					sawAction = true;
					height += rowFm.getHeight() + ACTION_PAD_Y * 2;
				}
				else
				{
					height += rowFm.getHeight();
				}
				if (i + 1 < rows.size())
				{
					Row next = rows.get(i + 1);
					if (!row.isAction() && !next.isAction())
					{
						height += ROW_GAP;
					}
				}
			}
			if (!rows.get(rows.size() - 1).isAction())
			{
				height += PAD_Y;
			}
		}
		else
		{
			height += PAD_Y;
		}
		return new Dimension(width, height);
	}
/**
	 * Paints the tooltip panel at {@code (x, y + yOffset)}, with title/border/rows faded by {@code alpha}.
	 * When {@code hoverX}/{@code hoverY} fall inside an action row, that row is highlighted; each action
	 * row's screen bounds are recorded into {@code outActionBounds} (keyed by action id) if provided.
	 */
	public static void paint(Graphics2D g, int x, int y, Content content, Color titleColor, float alpha, float yOffset,
		Integer hoverX, Integer hoverY, Map<String, Rectangle> outActionBounds)
	{
		if (content == null || alpha <= 0.01f)
		{
			return;
		}
		if (outActionBounds != null)
		{
			outActionBounds.clear();
		}
		Dimension size = measure(g, content);
		int drawY = y + Math.round(yOffset);

		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			g2.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
			g2.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, Math.min(1f, Math.max(0f, alpha))));

			RoundRectangle2D panel = new RoundRectangle2D.Float(x, drawY, size.width, size.height, RADIUS * 2f, RADIUS * 2f);
			g2.setColor(BG);
			g2.fill(panel);
			g2.setColor(BORDER);
			g2.draw(panel);

			Font titleFont = tipTitleFont();
			Font rowFont = tipRowFont();
			FontMetrics titleFm = g2.getFontMetrics(titleFont);
			FontMetrics rowFm = g2.getFontMetrics(rowFont);

			int textX = x + PAD_X;
			int cursorY = drawY + PAD_Y + titleFm.getAscent();
			g2.setFont(titleFont);
			g2.setColor(titleColor == null ? Color.WHITE : titleColor);
			int maxTitleW = size.width - PAD_X * 2;
			g2.drawString(ellipsize(content.getTitle(), titleFm, maxTitleW), textX, cursorY);

			List<Row> rows = content.getRows();
			if (rows.isEmpty())
			{
				return;
			}

			cursorY += titleFm.getDescent() + TITLE_GAP;
			g2.setFont(rowFont);
			int valueRight = x + size.width - PAD_X;
			boolean sawDetail = false;
			boolean drewSeparator = false;
			for (int i = 0; i < rows.size(); i++)
			{
				Row row = rows.get(i);
				if (row.isAction())
				{
					if (sawDetail && !drewSeparator)
					{
						cursorY += ROW_GAP;
						int sepY = cursorY;
						g2.setColor(SEPARATOR);
						g2.drawLine(x + 1, sepY, x + size.width - 2, sepY);
						cursorY += 1;
						drewSeparator = true;
					}
					int rowTop = cursorY;
					int rowH = rowFm.getHeight() + ACTION_PAD_Y * 2;
					Rectangle hit = new Rectangle(x + 1, rowTop, size.width - 2, rowH);
					boolean hover = hoverX != null && hoverY != null && hit.contains(hoverX, hoverY);
					if (hover)
					{
						g2.setColor(ACTION_HOVER);
						g2.fillRect(hit.x, hit.y, hit.width, hit.height);
					}
					g2.setColor(VALUE);
					g2.drawString(row.getLabel(), textX, rowTop + ACTION_PAD_Y + rowFm.getAscent());
					if (outActionBounds != null && row.getActionId() != null)
					{
						outActionBounds.put(row.getActionId(), hit);
					}
					cursorY = rowTop + rowH;
				}
				else
				{
					sawDetail = true;
					cursorY += rowFm.getAscent();
					g2.setColor(LABEL);
					g2.drawString(row.getLabel(), textX, cursorY);
					Color valueColor = row.getValueColor() == null ? VALUE : row.getValueColor();
					g2.setColor(valueColor);
					int vw = rowFm.stringWidth(row.getValue());
					g2.drawString(row.getValue(), valueRight - vw, cursorY);
					cursorY += rowFm.getDescent();
					if (i + 1 < rows.size() && !rows.get(i + 1).isAction())
					{
						cursorY += ROW_GAP;
					}
				}
			}
		}
		finally
		{
			g2.dispose();
		}
	}
/** {@link #paint(Graphics2D, int, int, Content, Color, float, float, Integer, Integer, Map)} with no hover/action-bounds tracking. */
	public static void paint(Graphics2D g, int x, int y, Content content, Color titleColor, float alpha, float yOffset)
	{
		paint(g, x, y, content, titleColor, alpha, yOffset, null, null, null);
	}
/** @return the font used for the tooltip title. */
	private static Font tipTitleFont()
	{
		return FontManager.getRunescapeBoldFont();
	}
/** @return the font used for tooltip detail/action rows. */
	private static Font tipRowFont()
	{
		return FontManager.getRunescapeSmallFont();
	}
/** Truncates {@code text} with a trailing ellipsis so it fits within {@code maxWidth} pixels under {@code fm}. */
	private static String ellipsize(String text, FontMetrics fm, int maxWidth)
	{
		String value = text == null ? "" : text;
		if (fm.stringWidth(value) <= maxWidth)
		{
			return value;
		}
		String ellipsis = "…";
		int ellipsisW = fm.stringWidth(ellipsis);
		if (ellipsisW >= maxWidth)
		{
			return ellipsis;
		}
		int lo = 0;
		int hi = Math.min(value.length(), MAX_TITLE_CHARS_FALLBACK);
		while (lo < hi)
		{
			int mid = (lo + hi + 1) / 2;
			if (fm.stringWidth(value.substring(0, mid)) + ellipsisW <= maxWidth)
			{
				lo = mid;
			}
			else
			{
				hi = mid - 1;
			}
		}
		return value.substring(0, lo) + ellipsis;
	}
}

package com.osrstcg.ui;

import com.google.inject.ImplementedBy;
/**
 * Sidebar refresh callbacks exposed by {@link TcgPanel} to callers (e.g. {@code PackOpenCoordinator})
 * that need to update the panel without depending on it directly. All methods mutate Swing state and
 * must be called on the EDT.
 */
@ImplementedBy(TcgPanel.class)
public interface SidebarRefresh
{
/** Rebuilds/refreshes the currently visible tab's content. */
	void refresh();
/** Refreshes just the displayed credits balance. */
	void refreshCredits();
/** Freezes sidebar interaction while a pack reveal is in progress. */
	void beginPackRevealSidebarFreeze();
/** Lifts the freeze applied by {@link #beginPackRevealSidebarFreeze()}. */
	void clearPackRevealSidebarFreeze();
/** Refreshes the sidebar after a pack reveal overlay closes. */
	void refreshAfterPackRevealClose();
}

package com.osrstcg.ui.collection;

import com.osrstcg.catalog.BoosterPackDefinition;
import com.osrstcg.catalog.CardDefinition;
import com.osrstcg.state.CardCollectionKey;
import com.osrstcg.state.CollectionState;
import com.osrstcg.state.OwnedCardInstance;
import com.osrstcg.catalog.RarityMath;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
/** Builds and sorts the filtered {@link Row} list shown by the Collection tab's card list, off the EDT. */
public final class CollectionListModel
{
/** Ordering applied to the collection row list; the trailing label is also the combo box display text. */
	public enum SortMode
	{
		SCORE_DESC("Score (high → low)"),
		SCORE_ASC("Score (low → high)"),
		NAME_AZ("Name (A → Z)"),
		NAME_ZA("Name (Z → A)"),
		PULLED_DESC("Pulled at (newest)"),
		PULLED_ASC("Pulled at (oldest)");

		private final String label;
/** Stores the combo box display label. */
		SortMode(String label)
		{
			this.label = label;
		}
/** The combo box display label. */
		public String getLabel()
		{
			return label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}
/** Whether the list includes owned cards, unowned catalog names, or both. */
	public enum OwnedFilter
	{
		OBTAINED("Obtained"),
		ALL("All"),
		UNOBTAINED("Unobtained");

		private final String label;

		OwnedFilter(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}
/** One card/foil entry ready for display: display fields plus the values sort modes compare on. */
	public static final class Row
	{
		private final String name;
		private final boolean foil;
		private final RarityMath.Tier tier;
		private final long score;
		private final long pulledAtEpochMs;
		private final boolean owned;
/** Normalizes nulls/negatives (blank name, {@link RarityMath.Tier#COMMON} default, clamped score/timestamp). */
		public Row(String name, boolean foil, RarityMath.Tier tier, long score, long pulledAtEpochMs, boolean owned)
		{
			this.name = name == null ? "" : name;
			this.foil = foil;
			this.tier = tier == null ? RarityMath.Tier.COMMON : tier;
			this.score = Math.max(0L, score);
			this.pulledAtEpochMs = Math.max(0L, pulledAtEpochMs);
			this.owned = owned;
		}

		public String getName()
		{
			return name;
		}

		public boolean isFoil()
		{
			return foil;
		}

		public RarityMath.Tier getTier()
		{
			return tier;
		}

		public long getScore()
		{
			return score;
		}
/** Most recent pull timestamp across owned copies of this name/foil combination; 0 if unknown/unowned. */
		public long getPulledAtEpochMs()
		{
			return pulledAtEpochMs;
		}

		public boolean isOwned()
		{
			return owned;
		}
	}

	private CollectionListModel()
	{
	}
/**
	 * Builds filtered/sorted rows: owned name+foil keys and/or unowned catalog names per {@code ownedFilter}.
	 * Pulled-at sorts force {@link OwnedFilter#OBTAINED}. Safe to call off the EDT.
	 */
	public static List<Row> buildRows(
		CollectionState collection,
		Map<String, CardDefinition> cardsByLowerName,
		Set<String> packEligibleNamesOrNull,
		RarityMath.Tier rarityFilterOrNull,
		String nameQueryOrNull,
		SortMode sortMode,
		OwnedFilter ownedFilter)
	{
		Map<CardCollectionKey, Long> maxPulledAt = new HashMap<>();
		aggregateOwned(collection, maxPulledAt);

		SortMode mode = sortMode == null ? SortMode.SCORE_DESC : sortMode;
		OwnedFilter effective = mode == SortMode.PULLED_DESC || mode == SortMode.PULLED_ASC
			? OwnedFilter.OBTAINED
			: (ownedFilter == null ? OwnedFilter.OBTAINED : ownedFilter);
		String query = nameQueryOrNull == null ? "" : nameQueryOrNull.trim().toLowerCase(Locale.ROOT);

		Set<String> ownedNames = new HashSet<>();
		for (CardCollectionKey key : maxPulledAt.keySet())
		{
			if (key != null && key.getCardName() != null && !key.getCardName().isBlank())
			{
				ownedNames.add(key.getCardName().trim());
			}
		}

		List<Row> rows = new ArrayList<>();
		if (effective != OwnedFilter.UNOBTAINED)
		{
			for (Map.Entry<CardCollectionKey, Long> entry : maxPulledAt.entrySet())
			{
				CardCollectionKey key = entry.getKey();
				if (key == null || key.getCardName() == null || key.getCardName().isBlank())
				{
					continue;
				}
				String name = key.getCardName().trim();
				CardDefinition def = cardsByLowerName == null
					? null
					: cardsByLowerName.get(name.toLowerCase(Locale.ROOT));
				RarityMath.Tier tier = tierIfMatch(name, def, packEligibleNamesOrNull, rarityFilterOrNull, query);
				if (tier == null)
				{
					continue;
				}
				long score = def == null ? 0L : def.displayScore(key.isFoil());
				rows.add(new Row(name, key.isFoil(), tier, score, entry.getValue(), true));
			}
		}
		if (effective != OwnedFilter.OBTAINED && cardsByLowerName != null)
		{
			for (CardDefinition def : cardsByLowerName.values())
			{
				if (def == null || def.getName() == null || def.getName().isBlank())
				{
					continue;
				}
				String name = def.getName().trim();
				if (ownedNames.contains(name))
				{
					continue;
				}
				RarityMath.Tier tier = tierIfMatch(name, def, packEligibleNamesOrNull, rarityFilterOrNull, query);
				if (tier != null)
				{
					rows.add(new Row(name, false, tier, def.displayScore(false), 0L, false));
				}
			}
		}

		rows.sort(comparatorFor(mode));
		return rows;
	}
/** Returns tier when {@code name}/{@code def} pass pack, rarity, and search filters; otherwise null. */
	private static RarityMath.Tier tierIfMatch(
		String name,
		CardDefinition def,
		Set<String> packEligibleNamesOrNull,
		RarityMath.Tier rarityFilterOrNull,
		String queryLower)
	{
		if (packEligibleNamesOrNull != null && !packEligibleNamesOrNull.contains(name))
		{
			return null;
		}
		RarityMath.Tier tier = def == null
			? RarityMath.Tier.COMMON
			: RarityMath.tierFromLabel(def.getTierLabel());
		if (rarityFilterOrNull != null && tier != rarityFilterOrNull)
		{
			return null;
		}
		if (!queryLower.isEmpty() && !nameMatchesQuery(name, def, queryLower))
		{
			return null;
		}
		return tier;
	}
/** Whether the card's key name or catalog display name contains {@code queryLower} (already lowercased). */
	private static boolean nameMatchesQuery(String cardName, CardDefinition def, String queryLower)
	{
		if (cardName != null && cardName.toLowerCase(Locale.ROOT).contains(queryLower))
		{
			return true;
		}
		if (def != null && def.getDisplayName() != null
			&& def.getDisplayName().toLowerCase(Locale.ROOT).contains(queryLower))
		{
			return true;
		}
		return false;
	}
/**
	 * Names eligible for a booster's set-completion tracking: cards matching its category filters, or the
	 * whole roll pool when it has none.
	 */
	public static Set<String> eligibleNamesForPack(
		BoosterPackDefinition booster,
		List<CardDefinition> allCards,
		List<CardDefinition> rollPool)
	{
		Set<String> eligible = new HashSet<>();
		if (booster == null)
		{
			return eligible;
		}
		List<String> filters = booster.getCategoryFilters();
		List<CardDefinition> source = filters.isEmpty() ? rollPool : allCards;
		if (source == null)
		{
			return eligible;
		}
		for (CardDefinition c : source)
		{
			if (c == null || c.getName() == null || c.getName().trim().isEmpty())
			{
				continue;
			}
			if (filters.isEmpty() || BoosterPackDefinition.cardMatchesRegion(c, filters))
			{
				eligible.add(c.getName().trim());
			}
		}
		return eligible;
	}
/** Indexes card definitions by trimmed, lowercased name for case-insensitive lookup; first match wins on duplicates. */
	public static Map<String, CardDefinition> indexByLowerName(List<CardDefinition> cards)
	{
		Map<String, CardDefinition> map = new HashMap<>();
		if (cards == null)
		{
			return map;
		}
		for (CardDefinition c : cards)
		{
			if (c == null || c.getName() == null || c.getName().isBlank())
			{
				continue;
			}
			map.putIfAbsent(c.getName().trim().toLowerCase(Locale.ROOT), c);
		}
		return map;
	}
/** Fills {@code maxPulledAtOut} with the latest pull timestamp per name/foil key. */
	private static void aggregateOwned(
		CollectionState collection,
		Map<CardCollectionKey, Long> maxPulledAtOut)
	{
		if (collection == null)
		{
			return;
		}
		for (OwnedCardInstance i : collection.getOwnedInstances())
		{
			if (i == null || i.getCardName() == null || i.getCardName().isBlank())
			{
				continue;
			}
			CardCollectionKey key = new CardCollectionKey(i.getCardName().trim(), i.isFoil());
			maxPulledAtOut.merge(key, i.getPulledAtEpochMs(), Math::max);
		}
	}
/** Row comparator for {@code mode}; every mode uses name and foil status as tiebreakers. */
	private static Comparator<Row> comparatorFor(SortMode mode)
	{
		Comparator<Row> byName = Comparator.comparing(r -> r.getName().toLowerCase(Locale.ROOT));
		Comparator<Row> byScore = Comparator.comparingLong(Row::getScore);
		Comparator<Row> byPulled = Comparator.comparingLong(Row::getPulledAtEpochMs);
		Comparator<Row> foilLast = Comparator.comparing(Row::isFoil);
		switch (mode)
		{
			case SCORE_ASC:
				return byScore.thenComparing(byName).thenComparing(foilLast);
			case NAME_AZ:
				return byName.thenComparing(foilLast).thenComparing(byScore.reversed());
			case NAME_ZA:
				return byName.reversed().thenComparing(foilLast).thenComparing(byScore.reversed());
			case PULLED_DESC:
				return byPulled.reversed().thenComparing(byName).thenComparing(foilLast);
			case PULLED_ASC:
				return byPulled.thenComparing(byName).thenComparing(foilLast);
			case SCORE_DESC:
			default:
				return byScore.reversed().thenComparing(byName).thenComparing(foilLast);
		}
	}
}

