		this.shopTab = new ShopTab(
			cardDatabase, packRevealService,
			packOpenCoordinator, packCatalogService, imageCacheService, cloudSessionService,
			overviewTab,
			this::liveShopPacksContentWidth, this::capturePackCloseSnapshot,
